window.ALGORITMOS = [{"id": "DP-Algorithms-BitmaskDP", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/BitmaskDP.cpp", "nombre": "BitmaskDP", "algoritmo": "DP sobre subconjuntos (bitmask)", "problema": "CSES 1653 - Elevator Rides (https://cses.fi/problemset/task/1653)", "cses": "https://cses.fi/problemset/task/1653", "py_lento": false, "entrada": "n x, luego n pesos", "salida": "mínimo de viajes del ascensor (capacidad x) para llevar a todos", "complejidad": "tiempo O(2^n · n), memoria O(2^n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DP sobre subconjuntos (bitmask)\n * Problema  : CSES 1653 - Elevator Rides (https://cses.fi/problemset/task/1653)\n * Entrada   : n x, luego n pesos\n * Salida    : mínimo de viajes del ascensor (capacidad x) para llevar a todos\n * Complejidad: tiempo O(2^n · n), memoria O(2^n)\n */\n\nint main() {\n    fastio;\n    int n;\n    ll x;\n    cin >> n >> x;\n    vector<ll> w(n);\n    for (auto &v : w) cin >> v;\n\n    // dp[mask] = {viajes, peso en el último viaje} mínimo para llevar a las personas de mask\n    // dp[mask] = {viajes, peso en el último viaje} mínimo para llevar a las personas de mask\n    vector<pair<int, ll>> dp(1 << n, {n + 1, 0});\n    // se parte con un viaje vacío\n    dp[0] = {1, 0};\n    // se prueba cuál fue la última persona en subir\n    for (int mask = 1; mask < (1 << n); mask++) {\n        for (int i = 0; i < n; i++) {\n            if (!(mask >> i & 1)) continue;\n            auto [rides, last] = dp[mask ^ (1 << i)];\n            // cabe en el viaje actual o hay que abrir otro\n            if (last + w[i] <= x) last += w[i];\n            else rides++, last = w[i];\n            dp[mask] = min(dp[mask], {rides, last});\n        }\n    }\n    cout << dp[(1 << n) - 1].first << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP sobre subconjuntos (bitmask)\n * Problema  : CSES 1653 - Elevator Rides (https://cses.fi/problemset/task/1653)\n * Entrada   : n x, luego n pesos\n * Salida    : mínimo de viajes del ascensor (capacidad x) para llevar a todos\n * Complejidad: tiempo O(2^n · n), memoria O(2^n)\n\"\"\"\ndef main():\n    n, x = map(int, input().split())\n    w = list(map(int, input().split()))\n\n    # dp[mask] = (viajes, peso en el último viaje) mínimo para llevar a las personas de mask\n    full = 1 << n\n    rides = [n + 1] * full\n    last = [0] * full\n    # se parte con un viaje vacío\n    rides[0], last[0] = 1, 0\n    for mask in range(1, full):\n        br, bl = n + 1, 0\n        # se prueba cuál fue la última persona en subir\n        for i in range(n):\n            if mask >> i & 1:\n                p = mask ^ (1 << i)\n                r, l = rides[p], last[p]\n                # cabe en el viaje actual o hay que abrir otro\n                if l + w[i] <= x:\n                    l += w[i]\n                else:\n                    r += 1\n                    l = w[i]\n                if r < br or (r == br and l < bl):\n                    br, bl = r, l\n        rides[mask], last[mask] = br, bl\n    print(rides[full - 1])\n\n\nmain()\n"}, {"id": "DP-Algorithms-CoinChange", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/CoinChange.cpp", "nombre": "CoinChange", "algoritmo": "DP de monedas (mínimo número de monedas)", "problema": "CSES 1634 - Minimizing Coins (https://cses.fi/problemset/task/1634)", "cses": "https://cses.fi/problemset/task/1634", "py_lento": false, "entrada": "n x, luego n monedas", "salida": "mínimo de monedas para sumar x, o -1", "complejidad": "tiempo O(n·x), memoria O(x)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DP de monedas (mínimo número de monedas)\n * Problema  : CSES 1634 - Minimizing Coins (https://cses.fi/problemset/task/1634)\n * Entrada   : n x, luego n monedas\n * Salida    : mínimo de monedas para sumar x, o -1\n * Complejidad: tiempo O(n·x), memoria O(x)\n */\n\nint main() {\n    fastio;\n    int n, target;\n    cin >> n >> target;\n    vector<int> coins(n);\n    for (int i = 0; i < n; i++) cin >> coins[i];\n\n    // dp[x] = mínimo número de monedas para sumar x\n    vector<int> dp(target+1, INT_MAX);\n    dp[0] = 0;\n    // cada moneda se puede usar muchas veces (mochila no acotada)\n    for (int c : coins) {\n        for (int x = c; x <= target; x++) {\n            // solo se usa dp[x-c] si ya era alcanzable\n            if (dp[x-c] != INT_MAX)\n                dp[x] = min(dp[x], dp[x-c] + 1);\n        }\n    }\n\n    // si dp[target] sigue en INT_MAX no hay forma de formarlo\n    int ans = dp[target];\n    cout << (ans == INT_MAX ? -1 : ans) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de monedas (mínimo número de monedas)\n * Problema  : CSES 1634 - Minimizing Coins (https://cses.fi/problemset/task/1634)\n * Entrada   : n x, luego n monedas\n * Salida    : mínimo de monedas para sumar x, o -1\n * Complejidad: tiempo O(n·x), memoria O(x)\n\"\"\"\n\n\ndef main():\n    n, x = map(int, input().split())\n    coins = list(map(int, input().split()))\n\n    # dp[s] = mínimo de monedas para sumar s (x + 1 hace de infinito)\n    BIG = x + 1\n    dp = [BIG] * (x + 1)\n    dp[0] = 0\n    for c in coins:\n        # cada moneda se puede usar muchas veces (mochila no acotada)\n        for s in range(c, x + 1):\n            t = dp[s - c] + 1\n            if t < dp[s]:\n                dp[s] = t\n\n    # si dp[x] sigue en BIG no hay forma de formarlo\n    print(-1 if dp[x] == BIG else dp[x])\n\n\nmain()\n"}, {"id": "DP-Algorithms-CoinCombinations", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/CoinCombinations.cpp", "nombre": "CoinCombinations", "algoritmo": "Conteo de formas con monedas (combinaciones y permutaciones)", "problema": "CSES 1636 - Coin Combinations II (https://cses.fi/problemset/task/1636)", "cses": "https://cses.fi/problemset/task/1636", "py_lento": false, "entrada": "n x, luego n valores de monedas", "salida": "cantidad de combinaciones (sin importar el orden) que suman x, módulo 10^9+7", "complejidad": "tiempo O(n·x), memoria O(x)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Conteo de formas con monedas (combinaciones y permutaciones)\n * Problema  : CSES 1636 - Coin Combinations II (https://cses.fi/problemset/task/1636)\n * Entrada   : n x, luego n valores de monedas\n * Salida    : cantidad de combinaciones (sin importar el orden) que suman x, módulo 10^9+7\n * Complejidad: tiempo O(n·x), memoria O(x)\n */\n\nconst int MODC = 1000000007;  // este problema pide módulo 10^9+7\n\nint main() {\n    fastio;\n    int n, x;\n    cin >> n >> x;\n    vector<int> coin(n);\n    for (auto &c : coin) cin >> c;\n\n    // combinaciones: la moneda va en el bucle externo (el orden no importa)\n    // dp[s] = formas de sumar s\n    vector<int> dp(x + 1, 0);\n    // hay una forma de sumar 0: no usar monedas\n    dp[0] = 1;\n    for (int c : coin)\n        for (int s = c; s <= x; s++)\n            dp[s] = (dp[s] + dp[s - c]) % MODC;\n    // Para contar permutaciones (Coin Combinations I, CSES 1635) se invierten los bucles:\n    // for s in 1..x: for c in coin: dp[s] += dp[s - c]\n    cout << dp[x] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Conteo de formas con monedas (combinaciones y permutaciones)\n * Problema  : CSES 1636 - Coin Combinations II (https://cses.fi/problemset/task/1636)\n * Entrada   : n x, luego n valores de monedas\n * Salida    : cantidad de combinaciones (sin importar el orden) que suman x, módulo 10^9+7\n * Complejidad: tiempo O(n·x), memoria O(x)\n\"\"\"\nMODC = 1000000007  # este problema pide módulo 10^9+7\n\n\ndef main():\n    n, x = map(int, input().split())\n    coin = list(map(int, input().split()))\n\n    # dp[s] = formas de sumar s\n    dp = [0] * (x + 1)\n    # hay una forma de sumar 0: no usar monedas\n    dp[0] = 1\n    # combinaciones: la moneda va en el bucle externo (el orden no importa)\n    for c in coin:\n        for s in range(c, x + 1):\n            dp[s] = (dp[s] + dp[s - c]) % MODC\n    # Para contar permutaciones (Coin Combinations I, CSES 1635) se invierten los bucles:\n    # for s in 1..x: for c in coin: dp[s] += dp[s - c]\n    print(dp[x])\n\n\nmain()\n"}, {"id": "DP-Algorithms-EditDistance", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/EditDistance.cpp", "nombre": "EditDistance", "algoritmo": "Distancia de edición (Levenshtein)", "problema": "CSES 1639 - Edit Distance (https://cses.fi/problemset/task/1639)", "cses": "https://cses.fi/problemset/task/1639", "py_lento": false, "entrada": "dos cadenas a y b", "salida": "mínimo de operaciones (insertar, borrar, reemplazar) para convertir a en b", "complejidad": "tiempo O(n·m), memoria O(n·m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Distancia de edición (Levenshtein)\n * Problema  : CSES 1639 - Edit Distance (https://cses.fi/problemset/task/1639)\n * Entrada   : dos cadenas a y b\n * Salida    : mínimo de operaciones (insertar, borrar, reemplazar) para convertir a en b\n * Complejidad: tiempo O(n·m), memoria O(n·m)\n */\n\nint main() {\n    fastio;\n    string a, b;\n    cin >> a >> b;\n    int n = a.size(), m = b.size();\n\n    // dp[i][j] = distancia entre a[0..i) y b[0..j)\n    // dp[i][j] = distancia entre a[0..i) y b[0..j)\n    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));\n    // convertir un prefijo en vacío cuesta borrar todo (y al revés insertar)\n    for (int i = 0; i <= n; i++) dp[i][0] = i;\n    for (int j = 0; j <= m; j++) dp[0][j] = j;\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++)\n            // borrar, insertar o reemplazar (cuesta 0 si los caracteres coinciden)\n            dp[i][j] = min({dp[i - 1][j] + 1, dp[i][j - 1] + 1,\n                            dp[i - 1][j - 1] + (a[i - 1] != b[j - 1])});\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Distancia de edición (Levenshtein)\n * Problema  : CSES 1639 - Edit Distance (https://cses.fi/problemset/task/1639)\n * Entrada   : dos cadenas a y b\n * Salida    : mínimo de operaciones (insertar, borrar, reemplazar) para convertir a en b\n * Complejidad: tiempo O(n·m), memoria O(n·m)\n\"\"\"\ndef main():\n    a = input().strip()\n    b = input().strip()\n    n, m = len(a), len(b)\n\n    # dp[i][j] = distancia entre a[0..i) y b[0..j); se guardan solo dos filas\n    # convertir un prefijo en vacío cuesta borrar todo (y al revés insertar)\n    prev = list(range(m + 1))\n    for i in range(1, n + 1):\n        cur = [i] + [0] * m\n        ai = a[i - 1]\n        for j in range(1, m + 1):\n            # borrar, insertar o reemplazar (cuesta 0 si los caracteres coinciden)\n            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ai != b[j - 1]))\n        prev = cur\n    print(prev[m])\n\n\nmain()\n"}, {"id": "DP-Algorithms-Kadane1D", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/Kadane1D.cpp", "nombre": "Kadane1D", "algoritmo": "Kadane (subarreglo de suma máxima)", "problema": "CSES 1643 - Maximum Subarray Sum (https://cses.fi/problemset/task/1643)", "cses": "https://cses.fi/problemset/task/1643", "py_lento": false, "entrada": "n, luego n enteros", "salida": "máxima suma de un subarreglo no vacío", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Kadane (subarreglo de suma máxima)\n * Problema  : CSES 1643 - Maximum Subarray Sum (https://cses.fi/problemset/task/1643)\n * Entrada   : n, luego n enteros\n * Salida    : máxima suma de un subarreglo no vacío\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<ll> a(n);\n    for (int i = 0; i < n; i++) {\n        cin >> a[i];\n    }\n    // best = mejor suma encontrada, curr = mejor suma de un subarreglo que termina en i\n    ll best = a[0], curr = a[0];\n    for (int i = 1; i < n; i++) {\n        // o se empieza un subarreglo nuevo en a[i] o se extiende el anterior\n        curr = max(a[i], curr + a[i]);\n        // se guarda el mejor resultado global\n        best = max(best, curr);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Kadane (subarreglo de suma máxima)\n * Problema  : CSES 1643 - Maximum Subarray Sum (https://cses.fi/problemset/task/1643)\n * Entrada   : n, luego n enteros\n * Salida    : máxima suma de un subarreglo no vacío\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\ndef main():\n    n = int(input())\n    a = list(map(int, input().split()))\n\n    # best = mejor suma encontrada, curr = mejor suma de un subarreglo que termina en i\n    best = curr = a[0]\n    for i in range(1, n):\n        # o se empieza un subarreglo nuevo en a[i] o se extiende el anterior\n        curr = max(a[i], curr + a[i])\n        # se guarda el mejor resultado global\n        best = max(best, curr)\n    print(best)\n\n\nmain()\n"}, {"id": "DP-Algorithms-Kadane2D", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/Kadane2D.cpp", "nombre": "Kadane2D", "algoritmo": "Kadane 2D (submatriz de suma máxima)", "problema": "Clásico, sin problema equivalente en CSES", "cses": "", "py_lento": false, "entrada": "R C, luego la matriz de R filas y C columnas", "salida": "máxima suma de una submatriz no vacía", "complejidad": "tiempo O(R^2 · C), memoria O(R · C)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Kadane 2D (submatriz de suma máxima)\n * Problema  : Clásico, sin problema equivalente en CSES\n * Entrada   : R C, luego la matriz de R filas y C columnas\n * Salida    : máxima suma de una submatriz no vacía\n * Complejidad: tiempo O(R^2 · C), memoria O(R · C)\n */\n\nint main() {\n    fastio;\n    int R, C;\n    cin >> R >> C;\n    vector<vector<ll>> mat(R, vector<ll>(C));\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++)\n            cin >> mat[i][j];\n\n    // se parte de -INF porque todos los valores pueden ser negativos\n    ll best = -INF;\n    // fijar fila superior y fila inferior\n    for (int top = 0; top < R; top++) {\n        // colSum[j] = suma de la columna j entre las filas top y bot\n        vector<ll> colSum(C, 0);\n        for (int bot = top; bot < R; bot++) {\n            for (int j = 0; j < C; j++)\n                // al bajar bot se suma una fila más a cada columna\n                colSum[j] += mat[bot][j];\n            // aplicar Kadane 1D sobre colSum\n            ll curr = colSum[0];\n            best = max(best, curr);\n            for (int j = 1; j < C; j++) {\n                curr = max(colSum[j], curr + colSum[j]);\n                best = max(best, curr);\n            }\n        }\n    }\n    cout << best << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Kadane 2D (submatriz de suma máxima)\n * Problema  : Clásico, sin problema equivalente en CSES\n * Entrada   : R C, luego la matriz de R filas y C columnas\n * Salida    : máxima suma de una submatriz no vacía\n * Complejidad: tiempo O(R^2 · C), memoria O(R · C)\n\"\"\"\ndef main():\n    R, C = map(int, input().split())\n    mat = [list(map(int, input().split())) for _ in range(R)]\n\n    # se parte de -INF porque todos los valores pueden ser negativos\n    best = -INF\n    for top in range(R):\n        # colSum[j] = suma de la columna j entre las filas top y bot\n        colSum = [0] * C\n        for bot in range(top, R):\n            # al bajar bot se suma una fila más a cada columna\n            row = mat[bot]\n            for j in range(C):\n                colSum[j] += row[j]\n            # Kadane sobre colSum\n            curr = colSum[0]\n            best = max(best, curr)\n            for j in range(1, C):\n                curr = max(colSum[j], curr + colSum[j])\n                best = max(best, curr)\n    print(best)\n\n\nmain()\n"}, {"id": "DP-Algorithms-Knapsack", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/Knapsack.cpp", "nombre": "Knapsack", "algoritmo": "Mochila 0/1 (DP unidimensional)", "problema": "CSES 1158 - Book Shop (https://cses.fi/problemset/task/1158)", "cses": "https://cses.fi/problemset/task/1158", "py_lento": false, "entrada": "n x, luego n precios y luego n cantidades de páginas", "salida": "máximo de páginas que se pueden comprar con presupuesto x", "complejidad": "tiempo O(n·x), memoria O(x)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Mochila 0/1 (DP unidimensional)\n * Problema  : CSES 1158 - Book Shop (https://cses.fi/problemset/task/1158)\n * Entrada   : n x, luego n precios y luego n cantidades de páginas\n * Salida    : máximo de páginas que se pueden comprar con presupuesto x\n * Complejidad: tiempo O(n·x), memoria O(x)\n */\n\nint main() {\n    fastio;\n    int n, x;\n    cin >> n >> x;\n    vector<int> price(n), pages(n);\n    for (auto &p : price) cin >> p;\n    for (auto &p : pages) cin >> p;\n\n    // dp[w] = máximo de páginas con presupuesto w\n    vector<ll> dp(x + 1, 0);\n    // cada libro se usa una sola vez (mochila 0/1)\n    for (int i = 0; i < n; i++) {\n        // el presupuesto se recorre de mayor a menor para no reusar el mismo libro\n        for (int w = x; w >= price[i]; w--) {\n            // o no se compra el libro i, o se compra y se suma sus páginas\n            dp[w] = max(dp[w], dp[w - price[i]] + pages[i]);\n        }\n    }\n    cout << dp[x] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Mochila 0/1 (DP unidimensional)\n * Problema  : CSES 1158 - Book Shop (https://cses.fi/problemset/task/1158)\n * Entrada   : n x, luego n precios y luego n cantidades de páginas\n * Salida    : máximo de páginas que se pueden comprar con presupuesto x\n * Complejidad: tiempo O(n·x), memoria O(x)\n\"\"\"\ndef main():\n    n, x = map(int, input().split())\n    price = list(map(int, input().split()))\n    pages = list(map(int, input().split()))\n\n    # dp[w] = máximo de páginas con presupuesto w\n    dp = [0] * (x + 1)\n    # cada libro se usa una sola vez (mochila 0/1)\n    for i in range(n):\n        p, v = price[i], pages[i]\n        # el presupuesto se recorre de mayor a menor para no reusar el mismo libro\n        for w in range(x, p - 1, -1):\n            # o no se compra el libro i, o se compra y se suma sus páginas\n            if dp[w - p] + v > dp[w]:\n                dp[w] = dp[w - p] + v\n    print(dp[x])\n\n\nmain()\n"}, {"id": "DP-Algorithms-LCS", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/LCS.cpp", "nombre": "LCS", "algoritmo": "Subsecuencia común más larga (LCS) con reconstrucción", "problema": "CSES 3403 - Longest Common Subsequence (https://cses.fi/problemset/task/3403)", "cses": "https://cses.fi/problemset/task/3403", "py_lento": false, "entrada": "n m, luego los n enteros de a y los m enteros de b", "salida": "longitud de la LCS y una LCS", "complejidad": "tiempo O(n·m), memoria O(n·m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Subsecuencia común más larga (LCS) con reconstrucción\n * Problema  : CSES 3403 - Longest Common Subsequence (https://cses.fi/problemset/task/3403)\n * Entrada   : n m, luego los n enteros de a y los m enteros de b\n * Salida    : longitud de la LCS y una LCS\n * Complejidad: tiempo O(n·m), memoria O(n·m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<int> a(n), b(m);\n    for (auto &x : a) cin >> x;\n    for (auto &x : b) cin >> x;\n\n    // LCS[i][j] = longitud de la LCS de a[0..i) y b[0..j)\n    vector<vector<int>> LCS(n + 1, vector<int>(m + 1, 0));\n    // si los últimos coinciden se extiende la LCS; si no, se descarta uno de los dos\n    for (int i = 1; i <= n; ++i)\n        for (int j = 1; j <= m; ++j)\n            if (a[i - 1] == b[j - 1])\n                LCS[i][j] = LCS[i - 1][j - 1] + 1;\n            else\n                LCS[i][j] = max(LCS[i - 1][j], LCS[i][j - 1]);\n\n    // reconstrucción desde el final\n    // se camina desde (n, m) hacia atrás para recuperar una LCS\n    vector<int> res;\n    int i = n, j = m;\n    while (i > 0 && j > 0) {\n        if (a[i - 1] == b[j - 1]) {\n            res.push_back(a[i - 1]);\n            i--, j--;\n        }\n        else if (LCS[i - 1][j] >= LCS[i][j - 1]) i--;\n        else j--;\n    }\n    // se construyó al revés\n    reverse(all(res));\n\n    cout << LCS[n][m] << \"\\n\";\n    for (int x : res) cout << x << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Subsecuencia común más larga (LCS) con reconstrucción\n * Problema  : CSES 3403 - Longest Common Subsequence (https://cses.fi/problemset/task/3403)\n * Entrada   : n m, luego los n enteros de a y los m enteros de b\n * Salida    : longitud de la LCS y una LCS\n * Complejidad: tiempo O(n·m), memoria O(n·m)\n\"\"\"\ndef main():\n    n, m = map(int, input().split())\n    a = list(map(int, input().split()))\n    b = list(map(int, input().split()))\n\n    # LCS[i][j] = longitud de la LCS de a[0..i) y b[0..j)\n    LCS = [[0] * (m + 1) for _ in range(n + 1)]\n    for i in range(1, n + 1):\n        prev, cur, ai = LCS[i - 1], LCS[i], a[i - 1]\n        for j in range(1, m + 1):\n            # si los últimos coinciden se extiende la LCS; si no, se descarta uno de los dos\n            if ai == b[j - 1]:\n                cur[j] = prev[j - 1] + 1\n            else:\n                cur[j] = prev[j] if prev[j] >= cur[j - 1] else cur[j - 1]\n\n    # se camina desde (n, m) hacia atrás para recuperar una LCS\n    res = []\n    i, j = n, m\n    while i > 0 and j > 0:\n        if a[i - 1] == b[j - 1]:\n            res.append(a[i - 1])\n            i -= 1\n            j -= 1\n        elif LCS[i - 1][j] >= LCS[i][j - 1]:\n            i -= 1\n        else:\n            j -= 1\n    # se construyó al revés\n    res.reverse()\n\n    print(LCS[n][m])\n    print(*res)\n\n\nmain()\n"}, {"id": "DP-Algorithms-LIS-I", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/LIS-I.cpp", "nombre": "LIS-I", "algoritmo": "LIS con DP cuadrática", "problema": "CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145) (da TLE con n = 2·10^5; sirve para n <= 5000)", "cses": "https://cses.fi/problemset/task/1145", "py_lento": true, "entrada": "n, luego n enteros", "salida": "longitud de la subsecuencia creciente más larga", "complejidad": "tiempo O(n^2), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : LIS con DP cuadrática\n * Problema  : CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145) (da TLE con n = 2·10^5; sirve para n <= 5000)\n * Entrada   : n, luego n enteros\n * Salida    : longitud de la subsecuencia creciente más larga\n * Complejidad: tiempo O(n^2), memoria O(n)\n */\n\nint main(){\n    fastio;\n    \n    ll n; cin >> n;\n    vector<ll> a(n); for(auto &x: a) cin >> x;\n\n\n    // DP[i] = longitud de la LIS que termina en a[i]\n    vector<ll> DP(n, 1);\n    for(int i = 1; i < n; i++){\n        // se prueba extender cada subsecuencia anterior más pequeña\n        for(int j = 0; j < i; j++){\n            if(a[j] < a[i]){\n                // a[i] se agrega al final de la LIS que termina en a[j]\n                DP[i] = max(DP[i], 1 + DP[j]);\n            }\n        }\n    }\n\n    // la respuesta es el mejor DP[i] (O(n^2), lento para n grande)\n    cout << *max_element(all(DP)) << \"\\n\";\n    \n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : LIS con DP cuadrática\n * Problema  : CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145) (da TLE con n = 2·10^5; sirve para n <= 5000)\n * Entrada   : n, luego n enteros\n * Salida    : longitud de la subsecuencia creciente más larga\n * Complejidad: tiempo O(n^2), memoria O(n)\n\"\"\"\ndef main():\n    n = int(input())\n    a = list(map(int, input().split()))\n\n    # DP[i] = longitud de la LIS que termina en a[i]\n    DP = [1] * n\n    for i in range(n):\n        # se prueba extender cada subsecuencia anterior más pequeña\n        for j in range(i):\n            if a[j] < a[i] and DP[j] + 1 > DP[i]:\n                # a[i] se agrega al final de la LIS que termina en a[j]\n                DP[i] = DP[j] + 1\n    # la respuesta es el mejor DP[i] (O(n^2), lento para n grande)\n    print(max(DP))\n\n\nmain()\n"}, {"id": "DP-Algorithms-LIS-II", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/LIS-II.cpp", "nombre": "LIS-II", "algoritmo": "LIS con búsqueda binaria", "problema": "CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145)", "cses": "https://cses.fi/problemset/task/1145", "py_lento": false, "entrada": "n, luego n enteros", "salida": "longitud de la subsecuencia creciente más larga", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : LIS con búsqueda binaria\n * Problema  : CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145)\n * Entrada   : n, luego n enteros\n * Salida    : longitud de la subsecuencia creciente más larga\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main(){\n    fastio;\n    \n    ll n; cin >> n;\n    vector<ll> a(n); for(auto &x: a) cin >> x;\n\n\n    // R[k] = menor valor final posible de una LIS de longitud k+1 (siempre ordenado)\n    vector<ll> R;\n    // M[k] = índice del elemento que está en R[k]\n    vector<ll> M;\n\n    for(int i = 0; i < n; ++i) {\n        // primer lugar de R con valor >= a[i] (búsqueda binaria)\n        auto it = lower_bound(all(R), a[i]);\n        ll ind = it - R.begin();\n\n        // a[i] es mayor que todos: la LIS crece\n        if (ind == R.size()) {\n            R.push_back(a[i]);\n            M.push_back(i);\n        } \n        else {\n            // a[i] reemplaza un final más grande para dejar más espacio a futuro\n            R[ind] = a[i];\n            M[ind] = i;\n        }\n    }\n\n    // el tamaño de R es la longitud de la LIS\n    cout << R.size() << \"\\n\";\n    \n}\n", "python": "import sys\nfrom bisect import bisect_left\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : LIS con búsqueda binaria\n * Problema  : CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145)\n * Entrada   : n, luego n enteros\n * Salida    : longitud de la subsecuencia creciente más larga\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\ndef main():\n    n = int(input())\n    a = list(map(int, input().split()))\n\n    # R[k] = menor valor final posible de una LIS de longitud k+1 (siempre ordenado)\n    R = []\n    for v in a:\n        # primer lugar de R con valor >= v (búsqueda binaria)\n        ind = bisect_left(R, v)\n        if ind == len(R):\n            # v es mayor que todos: la LIS crece\n            R.append(v)\n        else:\n            # v reemplaza un final más grande para dejar más espacio a futuro\n            R[ind] = v\n    # el tamaño de R es la longitud de la LIS\n    print(len(R))\n\n\nmain()\n"}, {"id": "DP-Classic-Problems-Campeonato", "carpeta": "DP", "area": "Programación dinámica", "sub": "Classic Problems", "archivo": "DP/Classic Problems/Campeonato.cpp", "nombre": "Campeonato", "algoritmo": "DP de probabilidades (serie al primero en llegar a n victorias)", "problema": "Clásico \"Campeonato\"/World Series, sin problema equivalente en CSES", "cses": "", "py_lento": false, "entrada": "n p: victorias que necesita cada equipo y probabilidad p de que gane el equipo A un partido", "salida": "probabilidad de que A gane la serie (10 decimales)", "complejidad": "tiempo O(n^2), memoria O(n^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DP de probabilidades (serie al primero en llegar a n victorias)\n * Problema  : Clásico \"Campeonato\"/World Series, sin problema equivalente en CSES\n * Entrada   : n p: victorias que necesita cada equipo y probabilidad p de que gane el equipo A un partido\n * Salida    : probabilidad de que A gane la serie (10 decimales)\n * Complejidad: tiempo O(n^2), memoria O(n^2)\n */\n\nint main() {\n    fastio;\n    int n;\n    double p;\n    cin >> n >> p;\n    // q = probabilidad de que gane B\n    double q = 1 - p;\n\n    // P[i][j] = probabilidad de que A gane si le faltan i victorias y a B le faltan j\n    vector<vector<double>> P(n + 1, vector<double>(n + 1, 0.0));\n    // casos base: si A ya ganó la serie la probabilidad es 1\n    for (int i = 1; i <= n; i++) P[0][i] = 1.0;  // A ya ganó\n    // si B ya ganó, es 0\n    for (int j = 1; j <= n; j++) P[j][0] = 0.0;  // B ya ganó\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= n; j++)\n            // se juega un partido: gana A (falta una victoria menos) o gana B\n            P[i][j] = p * P[i - 1][j] + q * P[i][j - 1];\n\n    precision(10);\n    cout << P[n][n] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de probabilidades (serie al primero en llegar a n victorias)\n * Problema  : Clásico \"Campeonato\"/World Series, sin problema equivalente en CSES\n * Entrada   : n p: victorias que necesita cada equipo y probabilidad p de que gane el equipo A un partido\n * Salida    : probabilidad de que A gane la serie (10 decimales)\n * Complejidad: tiempo O(n^2), memoria O(n^2)\n\"\"\"\ndef main():\n    n, p = input().split()\n    n, p = int(n), float(p)\n    # q = probabilidad de que gane B\n    q = 1 - p\n\n    # P[i][j] = probabilidad de que A gane si le faltan i victorias y a B le faltan j\n    P = [[0.0] * (n + 1) for _ in range(n + 1)]\n    # casos base: si A ya ganó la serie la probabilidad es 1 (si B ya ganó, es 0)\n    for i in range(1, n + 1):\n        P[0][i] = 1.0\n    for i in range(1, n + 1):\n        for j in range(1, n + 1):\n            # se juega un partido: gana A (falta una victoria menos) o gana B\n            P[i][j] = p * P[i - 1][j] + q * P[i][j - 1]\n\n    print(f\"{P[n][n]:.10f}\")\n\n\nmain()\n"}, {"id": "DP-Classic-Problems-Counting-Numbers", "carpeta": "DP", "area": "Programación dinámica", "sub": "Classic Problems", "archivo": "DP/Classic Problems/Counting Numbers.cpp", "nombre": "Counting Numbers", "algoritmo": "DP de dígitos (contar números con una propiedad hasta un límite)", "problema": "CSES 2220 - Counting Numbers (https://cses.fi/problemset/task/2220)", "cses": "https://cses.fi/problemset/task/2220", "py_lento": false, "entrada": "dos enteros a y b", "salida": "cantidad de enteros en [a, b] sin dos dígitos vecinos iguales", "complejidad": "tiempo O(10 · dígitos), memoria O(dígitos)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP de dígitos (contar números con una propiedad hasta un límite)\n * Problema  : CSES 2220 - Counting Numbers (https://cses.fi/problemset/task/2220)\n * Entrada   : dos enteros a y b\n * Salida    : cantidad de enteros en [a, b] sin dos dígitos vecinos iguales\n * Complejidad: tiempo O(10 · dígitos), memoria O(dígitos)\n */\n\n// cuenta los enteros en [0, x] sin dos dígitos vecinos iguales\nll contar(ll x) {\n    if (x < 0) return 0;\n    if (x == 0) return 1;\n    string s = to_string(x);\n    int n = s.size();\n    vector<ll> p9(n + 1, 1);\n    for (int i = 1; i <= n; i++) p9[i] = p9[i - 1] * 9;\n    ll res = 1;  // el número 0\n    // números con menos dígitos: primer dígito 1..9 y cada siguiente distinto al anterior (9 opciones)\n    for (int len = 1; len < n; len++) res += p9[len];\n    // números con n dígitos menores que x: se copia un prefijo de x y en la posición i se pone un dígito menor\n    for (int i = 0; i < n; i++) {\n        int lim = s[i] - '0';\n        for (int d = (i == 0 ? 1 : 0); d < lim; d++)\n            if (i == 0 || d != s[i - 1] - '0') res += p9[n - 1 - i];\n        // si x ya tiene dos dígitos vecinos iguales, ningún número con este prefijo sirve\n        if (i > 0 && s[i] == s[i - 1]) return res;\n    }\n    return res + 1;  // x mismo es válido\n}\n\nint main() {\n    fastio;\n    ll a, b;\n    cin >> a >> b;\n    cout << contar(b) - contar(a - 1) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de dígitos (contar números con una propiedad hasta un límite)\n * Problema  : CSES 2220 - Counting Numbers (https://cses.fi/problemset/task/2220)\n * Entrada   : dos enteros a y b\n * Salida    : cantidad de enteros en [a, b] sin dos dígitos vecinos iguales\n * Complejidad: tiempo O(10 · dígitos), memoria O(dígitos)\n\"\"\"\n\n\ndef contar(x):\n    \"\"\"Cuenta los enteros en [0, x] sin dos dígitos vecinos iguales.\"\"\"\n    if x < 0:\n        return 0\n    if x == 0:\n        return 1\n    s = str(x)\n    n = len(s)\n    res = 1  # el número 0\n    # números con menos dígitos: primer dígito 1..9 y cada siguiente distinto al anterior\n    for length in range(1, n):\n        res += 9 ** length\n    # números con n dígitos menores que x: prefijo igual a x y en la posición i un dígito menor\n    for i in range(n):\n        for d in range(1 if i == 0 else 0, int(s[i])):\n            if i == 0 or d != int(s[i - 1]):\n                res += 9 ** (n - 1 - i)\n        # si x tiene dos dígitos vecinos iguales, ningún número con este prefijo sirve\n        if i > 0 and s[i] == s[i - 1]:\n            return res\n    return res + 1  # x mismo es válido\n\n\ndef main():\n    a, b = map(int, input().split())\n    print(contar(b) - contar(a - 1))\n\n\nmain()\n"}, {"id": "DP-Classic-Problems-Dice-Combinations", "carpeta": "DP", "area": "Programación dinámica", "sub": "Classic Problems", "archivo": "DP/Classic Problems/Dice Combinations.cpp", "nombre": "Dice Combinations", "algoritmo": "DP de conteo (formas de formar una suma)", "problema": "CSES 1633 - Dice Combinations (https://cses.fi/problemset/task/1633)", "cses": "https://cses.fi/problemset/task/1633", "py_lento": false, "entrada": "un entero n", "salida": "número de formas de sumar n lanzando un dado una o más veces, módulo 10^9+7", "complejidad": "tiempo O(6n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP de conteo (formas de formar una suma)\n * Problema  : CSES 1633 - Dice Combinations (https://cses.fi/problemset/task/1633)\n * Entrada   : un entero n\n * Salida    : número de formas de sumar n lanzando un dado una o más veces, módulo 10^9+7\n * Complejidad: tiempo O(6n), memoria O(n)\n */\n\nconst ll M = 1e9 + 7;\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    // dp[s] = formas de llegar exactamente a la suma s\n    vector<ll> dp(n + 1, 0);\n    dp[0] = 1;  // la suma 0 se forma de una sola forma: sin lanzar\n    for (int s = 1; s <= n; s++)\n        // el último lanzamiento fue una cara k entre 1 y 6\n        for (int k = 1; k <= 6 && k <= s; k++)\n            dp[s] = (dp[s] + dp[s - k]) % M;\n    cout << dp[n] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de conteo (formas de formar una suma)\n * Problema  : CSES 1633 - Dice Combinations (https://cses.fi/problemset/task/1633)\n * Entrada   : un entero n\n * Salida    : número de formas de sumar n lanzando un dado una o más veces, módulo 10^9+7\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\nM = 10**9 + 7\n\n\ndef main():\n    n = int(input())\n    # dp[s] = formas de llegar exactamente a la suma s; dp[0] = 1 (no lanzar)\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    # ventana = dp[s-1] + ... + dp[s-6], se actualiza en O(1) por paso\n    window = 0\n    for s in range(1, n + 1):\n        window += dp[s - 1]\n        if s > 6:\n            window -= dp[s - 7]\n        window %= M\n        dp[s] = window\n    print(dp[n])\n\n\nmain()\n"}, {"id": "DP-Classic-Problems-Grid-Paths-I", "carpeta": "DP", "area": "Programación dinámica", "sub": "Classic Problems", "archivo": "DP/Classic Problems/Grid Paths I.cpp", "nombre": "Grid Paths I", "algoritmo": "DP en cuadrícula (caminos con obstáculos)", "problema": "CSES 1638 - Grid Paths I (https://cses.fi/problemset/task/1638)", "cses": "https://cses.fi/problemset/task/1638", "py_lento": false, "entrada": "n, luego n filas de n caracteres ('.' libre, '*' trampa)", "salida": "caminos de la esquina superior izquierda a la inferior derecha (solo derecha/abajo), módulo 10^9+7", "complejidad": "tiempo O(n^2), memoria O(n^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP en cuadrícula (caminos con obstáculos)\n * Problema  : CSES 1638 - Grid Paths I (https://cses.fi/problemset/task/1638)\n * Entrada   : n, luego n filas de n caracteres ('.' libre, '*' trampa)\n * Salida    : caminos de la esquina superior izquierda a la inferior derecha (solo derecha/abajo), módulo 10^9+7\n * Complejidad: tiempo O(n^2), memoria O(n^2)\n */\n\nconst ll M = 1e9 + 7;\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<string> g(n);\n    for (auto &row : g) cin >> row;\n    // dp[i][j] = caminos que llegan a (i, j)\n    vector<vector<ll>> dp(n, vector<ll>(n, 0));\n    for (int i = 0; i < n; i++)\n        for (int j = 0; j < n; j++) {\n            if (g[i][j] == '*') continue;           // a una trampa no se llega\n            if (i == 0 && j == 0) { dp[i][j] = 1; continue; }\n            if (i > 0) dp[i][j] += dp[i - 1][j];    // llega desde arriba\n            if (j > 0) dp[i][j] += dp[i][j - 1];    // llega desde la izquierda\n            dp[i][j] %= M;\n        }\n    cout << dp[n - 1][n - 1] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP en cuadrícula (caminos con obstáculos)\n * Problema  : CSES 1638 - Grid Paths I (https://cses.fi/problemset/task/1638)\n * Entrada   : n, luego n filas de n caracteres ('.' libre, '*' trampa)\n * Salida    : caminos de la esquina superior izquierda a la inferior derecha (solo derecha/abajo), módulo 10^9+7\n * Complejidad: tiempo O(n^2), memoria O(n)\n\"\"\"\n\nM = 10**9 + 7\n\n\ndef main():\n    n = int(input())\n    # se guarda solo la fila anterior: row[j] = caminos que llegan a (i, j)\n    row = [0] * n\n    for i in range(n):\n        line = input().strip()\n        left = 0\n        for j in range(n):\n            if line[j] == '*':\n                left = 0                      # a una trampa no se llega\n            elif i == 0 and j == 0:\n                left = 1\n            else:\n                left = (left + row[j]) % M    # desde la izquierda + desde arriba\n            row[j] = left\n    print(row[n - 1])\n\n\nmain()\n"}, {"id": "DP-Classic-Problems-Money-Sums", "carpeta": "DP", "area": "Programación dinámica", "sub": "Classic Problems", "archivo": "DP/Classic Problems/Money Sums.cpp", "nombre": "Money Sums", "algoritmo": "DP de subconjuntos con bitset (sumas alcanzables)", "problema": "CSES 1745 - Money Sums (https://cses.fi/problemset/task/1745)", "cses": "https://cses.fi/problemset/task/1745", "py_lento": false, "entrada": "n, luego n valores de monedas", "salida": "cantidad de sumas distintas que se pueden formar y la lista ordenada", "complejidad": "tiempo O(n · S / 64) con S = suma total, memoria O(S)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP de subconjuntos con bitset (sumas alcanzables)\n * Problema  : CSES 1745 - Money Sums (https://cses.fi/problemset/task/1745)\n * Entrada   : n, luego n valores de monedas\n * Salida    : cantidad de sumas distintas que se pueden formar y la lista ordenada\n * Complejidad: tiempo O(n · S / 64) con S = suma total, memoria O(S)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    // bit s encendido = la suma s se puede formar con las monedas vistas\n    bitset<100001> can;\n    can[0] = 1;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        // cada suma vieja s genera s + x (usar o no la moneda)\n        can |= can << x;\n    }\n    vector<int> res;\n    for (int s = 1; s <= 100000; s++)\n        if (can[s]) res.push_back(s);\n    cout << res.size() << \"\\n\";\n    for (int s : res) cout << s << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de subconjuntos con bitset (sumas alcanzables)\n * Problema  : CSES 1745 - Money Sums (https://cses.fi/problemset/task/1745)\n * Entrada   : n, luego n valores de monedas\n * Salida    : cantidad de sumas distintas que se pueden formar y la lista ordenada\n * Complejidad: tiempo O(n · S / 64) con S = suma total, memoria O(S)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    xs = list(map(int, input().split()))\n    # un entero de Python funciona como bitset: bit s = la suma s se puede formar\n    can = 1\n    for x in xs:\n        can |= can << x\n    bits = bin(can)[:1:-1]  # bits[s] = '1' si la suma s es alcanzable\n    res = [s for s in range(1, len(bits)) if bits[s] == '1']\n    print(len(res))\n    print(*res)\n\n\nmain()\n"}, {"id": "DP-Classic-Problems-Removal-Game", "carpeta": "DP", "area": "Programación dinámica", "sub": "Classic Problems", "archivo": "DP/Classic Problems/Removal Game.cpp", "nombre": "Removal Game", "algoritmo": "DP de intervalos (juego de dos jugadores, minimax)", "problema": "CSES 1097 - Removal Game (https://cses.fi/problemset/task/1097)", "cses": "https://cses.fi/problemset/task/1097", "py_lento": true, "entrada": "n, luego n enteros", "salida": "puntaje máximo del primer jugador si ambos juegan óptimamente", "complejidad": "tiempo O(n^2), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP de intervalos (juego de dos jugadores, minimax)\n * Problema  : CSES 1097 - Removal Game (https://cses.fi/problemset/task/1097)\n * Entrada   : n, luego n enteros\n * Salida    : puntaje máximo del primer jugador si ambos juegan óptimamente\n * Complejidad: tiempo O(n^2), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<ll> x(n);\n    ll total = 0;\n    for (auto &v : x) cin >> v, total += v;\n    // d[l] (para el largo actual) = (mi puntaje - puntaje del rival) jugando primero en x[l..l+len-1]\n    vector<ll> d(x);  // largo 1: tomo el único número\n    for (int len = 2; len <= n; len++)\n        for (int l = 0; l + len <= n; l++) {\n            int r = l + len - 1;\n            // tomo x[l] y el rival juega en [l+1, r], o tomo x[r] y el rival juega en [l, r-1]\n            d[l] = max(x[l] - d[l + 1], x[r] - d[l]);\n        }\n    // mío + rival = total y mío - rival = d[0]\n    cout << (total + d[0]) / 2 << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de intervalos (juego de dos jugadores, minimax)\n * Problema  : CSES 1097 - Removal Game (https://cses.fi/problemset/task/1097)\n * Entrada   : n, luego n enteros\n * Salida    : puntaje máximo del primer jugador si ambos juegan óptimamente\n * Complejidad: tiempo O(n^2), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    x = list(map(int, input().split()))\n    # d[l] = (mi puntaje - puntaje del rival) jugando primero en un tramo que empieza en l\n    d = x[:]  # tramos de largo 1\n    for length in range(2, n + 1):\n        # tomo x[l] y el rival juega en [l+1, r], o tomo x[r] y el rival juega en [l, r-1]\n        d = [max(a - b, c - e) for a, b, c, e in zip(x, d[1:], x[length - 1:], d)]\n    # mío + rival = total y mío - rival = d[0]\n    print((sum(x) + d[0]) // 2)\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-Deque", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/Deque.cpp", "nombre": "Deque", "algoritmo": "Deque monótona (mínimo de ventana deslizante)", "problema": "CSES 3221 - Sliding Window Minimum (https://cses.fi/problemset/task/3221)", "cses": "https://cses.fi/problemset/task/3221", "py_lento": false, "entrada": "n k, luego x a b c con x_i = (a·x_{i-1} + b) mod c", "salida": "XOR de los mínimos de todas las ventanas de tamaño k", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Deque monótona (mínimo de ventana deslizante)\n * Problema  : CSES 3221 - Sliding Window Minimum (https://cses.fi/problemset/task/3221)\n * Entrada   : n k, luego x a b c con x_i = (a·x_{i-1} + b) mod c\n * Salida    : XOR de los mínimos de todas las ventanas de tamaño k\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    ll n, k, x, a, b, c;\n    cin >> n >> k >> x >> a >> b >> c;\n    vector<ll> v(n);\n    v[0] = x;\n    for (int i = 1; i < n; i++) v[i] = (a * v[i - 1] + b) % c;\n\n    // la deque guarda índices con valores crecientes; el frente es el mínimo de la ventana\n    // la deque guarda índices con valores crecientes; el frente es el mínimo de la ventana\n    deque<int> d;\n    ll res = 0;\n    for (int i = 0; i < n; i++) {\n        // se descartan los mayores o iguales a v[i]: nunca serán mínimo\n        while (!d.empty() && v[d.back()] >= v[i]) d.pop_back();\n        d.push_back(i);\n        // el frente salió de la ventana\n        if (d.front() <= i - k) d.pop_front();\n        // la ventana ya tiene k elementos\n        if (i >= k - 1) res ^= v[d.front()];\n    }\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Deque monótona (mínimo de ventana deslizante)\n * Problema  : CSES 3221 - Sliding Window Minimum (https://cses.fi/problemset/task/3221)\n * Entrada   : n k, luego x a b c con x_i = (a·x_{i-1} + b) mod c\n * Salida    : XOR de los mínimos de todas las ventanas de tamaño k\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n, k = map(int, input().split())\n    x, a, b, c = map(int, input().split())\n\n    # la deque (lista + índice de frente) guarda índices con valores crecientes;\n    # el frente es el mínimo de la ventana\n    idx = [0] * n\n    val = [0] * n\n    head = tail = 0\n    res = 0\n    v = x\n    for i in range(n):\n        if i:\n            v = (a * v + b) % c\n        # se descartan los mayores o iguales a v: nunca serán mínimo\n        while tail > head and val[tail - 1] >= v:\n            tail -= 1\n        idx[tail] = i\n        val[tail] = v\n        tail += 1\n        # el frente salió de la ventana\n        if idx[head] <= i - k:\n            head += 1\n        # la ventana ya tiene k elementos\n        if i >= k - 1:\n            res ^= val[head]\n    print(res)\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-FenwickTree", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/FenwickTree.cpp", "nombre": "FenwickTree", "algoritmo": "Fenwick Tree (BIT)", "problema": "CSES 1648 - Dynamic Range Sum Queries (https://cses.fi/problemset/task/1648)", "cses": "https://cses.fi/problemset/task/1648", "py_lento": false, "entrada": "n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (suma)", "salida": "la suma de cada consulta de tipo 2", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Fenwick Tree (BIT)\n * Problema  : CSES 1648 - Dynamic Range Sum Queries (https://cses.fi/problemset/task/1648)\n * Entrada   : n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (suma)\n * Salida    : la suma de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\n// Fenwick Tree (BIT): bit[i] guarda la suma de un bloque de tamaño (i & -i) que termina en i\nstruct Fenwick {\n    int n;\n    vector<ll> bit;\n\n    Fenwick(int n): n(n), bit(n + 1, 0) {}\n\n    // suma v a la posicion i (1-indexado)\n    void add(int i, ll v) {\n        for (; i <= n; i += i & -i) bit[i] += v;\n    }\n\n    // suma del prefijo [1..i]\n    ll query(int i) {\n        ll res = 0;\n        for (; i > 0; i -= i & -i) res += bit[i];\n        return res;\n    }\n\n    // suma del rango [l..r]\n    ll query(int l, int r) {\n        return query(r) - query(l - 1);\n    }\n};\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<ll> a(n + 1, 0);\n    // a[] se guarda aparte para saber cuánto cambiar al actualizar\n    Fenwick fw(n);\n    for (int i = 1; i <= n; i++) {\n        cin >> a[i];\n        fw.add(i, a[i]);\n    }\n\n    while (q--) {\n        int type; cin >> type;\n        if (type == 1) {\n            // a[k] = u\n            int k; ll u; cin >> k >> u;\n            // una asignación es sumar la diferencia\n            fw.add(k, u - a[k]);\n            a[k] = u;\n        } else {\n            int l, r; cin >> l >> r;\n            cout << fw.query(l, r) << \"\\n\";\n        }\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Fenwick Tree (BIT)\n * Problema  : CSES 1648 - Dynamic Range Sum Queries (https://cses.fi/problemset/task/1648)\n * Entrada   : n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (suma)\n * Salida    : la suma de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n\"\"\"\n\n\n# Fenwick Tree (BIT): bit[i] guarda la suma de un bloque de tamaño (i & -i) que termina en i\nclass Fenwick:\n    def __init__(self, n):\n        self.n = n\n        self.bit = [0] * (n + 1)\n\n    # suma v a la posición i (base 1)\n    def add(self, i, v):\n        while i <= self.n:\n            self.bit[i] += v\n            i += i & -i\n\n    # suma del prefijo [1..i]\n    def query(self, i):\n        res = 0\n        while i > 0:\n            res += self.bit[i]\n            i -= i & -i\n        return res\n\n\ndef main():\n    n, q = map(int, input().split())\n    # a[] se guarda aparte para saber cuánto cambiar al actualizar\n    a = [0] + list(map(int, input().split()))\n    fw = Fenwick(n)\n    for i in range(1, n + 1):\n        fw.add(i, a[i])\n\n    out = []\n    for _ in range(q):\n        t, x, y = map(int, input().split())\n        if t == 1:\n            # una asignación es sumar la diferencia\n            fw.add(x, y - a[x])\n            a[x] = y\n        else:\n            out.append(fw.query(y) - fw.query(x - 1))\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-Heap", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/Heap.cpp", "nombre": "Heap", "algoritmo": "Cola de prioridad (min-heap) para asignar recursos", "problema": "CSES 1164 - Room Allocation (https://cses.fi/problemset/task/1164)", "cses": "https://cses.fi/problemset/task/1164", "py_lento": false, "entrada": "n, luego n pares \"llegada salida\"", "salida": "mínimo de habitaciones y la habitación de cada cliente", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Cola de prioridad (min-heap) para asignar recursos\n * Problema  : CSES 1164 - Room Allocation (https://cses.fi/problemset/task/1164)\n * Entrada   : n, luego n pares \"llegada salida\"\n * Salida    : mínimo de habitaciones y la habitación de cada cliente\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<array<int, 3>> c(n);  // {llegada, salida, índice}\n    for (int i = 0; i < n; i++) {\n        cin >> c[i][0] >> c[i][1];\n        c[i][2] = i;\n    }\n    sort(all(c));\n\n    // min-heap de {salida, habitación}\n    // min-heap de {salida, habitación}: la habitación que se libera primero\n    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> heap;\n    vector<int> room(n);\n    int rooms = 0;\n    for (auto &cl : c) {\n        int r;\n        // si la habitación más pronta ya se liberó, se reutiliza\n        if (!heap.empty() && heap.top().first < cl[0]) {\n            r = heap.top().second;\n            heap.pop();\n        }\n        // si no, se abre una habitación nueva\n        else r = ++rooms;\n        room[cl[2]] = r;\n        heap.push({cl[1], r});\n    }\n\n    cout << rooms << \"\\n\";\n    for (int x : room) cout << x << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport heapq\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Cola de prioridad (min-heap) para asignar recursos\n * Problema  : CSES 1164 - Room Allocation (https://cses.fi/problemset/task/1164)\n * Entrada   : n, luego n pares \"llegada salida\"\n * Salida    : mínimo de habitaciones y la habitación de cada cliente\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:2 * n + 1:2]))\n    dep = list(map(int, data[2:2 * n + 2:2]))\n    # se ordenan los clientes por hora de llegada\n    order = sorted(range(n), key=arr.__getitem__)\n\n    # min-heap de salida * 2^18 + habitación: la habitación que se libera primero\n    SHIFT = 1 << 18\n    heap = []\n    room = [0] * n\n    rooms = 0\n    for i in order:\n        # si la habitación más pronta ya se liberó, se reutiliza\n        if heap and heap[0] // SHIFT < arr[i]:\n            r = heapq.heappop(heap) % SHIFT\n        else:\n            # si no, se abre una habitación nueva\n            rooms += 1\n            r = rooms\n        room[i] = r\n        heapq.heappush(heap, dep[i] * SHIFT + r)\n\n    print(rooms)\n    print(\" \".join(map(str, room)))\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-LazySegmentTree", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/LazySegmentTree.cpp", "nombre": "LazySegmentTree", "algoritmo": "Lazy Segment Tree, propagación perezosa (sumar a un rango, asignar a un rango y suma de rango)", "problema": "CSES 1735 - Range Updates and Sums (https://cses.fi/problemset/task/1735)", "cses": "https://cses.fi/problemset/task/1735", "py_lento": true, "entrada": "n q, n enteros, luego q consultas: \"1 a b x\" (suma x), \"2 a b x\" (asigna x) o \"3 a b\" (consulta suma)", "salida": "la suma de cada consulta de tipo 3", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Lazy Segment Tree, propagación perezosa (sumar a un rango, asignar a un rango y suma de rango)\n * Problema  : CSES 1735 - Range Updates and Sums (https://cses.fi/problemset/task/1735)\n * Entrada   : n q, n enteros, luego q consultas: \"1 a b x\" (suma x), \"2 a b x\" (asigna x) o \"3 a b\" (consulta suma)\n * Salida    : la suma de cada consulta de tipo 3\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\n// Data: información que guarda cada nodo (suma del rango y su tamaño)\nstruct Data {\n    ll suma, size;\n    Data(): suma(0), size(0) {}\n    Data(ll s): suma(s), size(1) {}\n\n    Data(const Data &left, const Data &right) {\n        suma = left.suma + right.suma;\n        size = left.size + right.size;\n    }\n};\n\n// Primero se asigna \"value\" (si set) y luego se suma \"add\"\n// Lazy: actualización pendiente que se aplica a los hijos cuando hace falta\nstruct Lazy {\n    bool set;\n    ll value, add;\n    Lazy(): set(false), value(0), add(0) {}\n\n    static Lazy Add(ll v) { Lazy l; l.add = v; return l; }\n    static Lazy Set(ll v) { Lazy l; l.set = true; l.value = v; return l; }\n\n    bool empty() const { return !set && add == 0; }\n\n    void updateData(Data &data) const {\n        if (set) data.suma = value * data.size;\n        data.suma += add * data.size;\n    }\n\n    // compone: aplica \"other\" después de this\n    void updateLazy(const Lazy &other) {\n        if (other.set) *this = other;\n        else add += other.add;\n    }\n};\n\n// Segment Tree con propagación perezosa\nstruct SegmentTree {\n    int n;\n    vector<Data> data;\n    vector<Lazy> lazy;\n\n    SegmentTree(const vector<ll> &A) {\n        n = A.size();\n        data.assign(4 * n, Data());\n        lazy.assign(4 * n, Lazy());\n        build(A, 1, 0, n - 1);\n    }\n\n    // construye el árbol recursivamente\n    void build(const vector<ll> &A, int index, int left, int right) {\n        if (left == right) { data[index] = Data(A[left]); return; }\n        int mid = (left + right) / 2;\n        build(A, 2 * index, left, mid);\n        build(A, 2 * index + 1, mid + 1, right);\n        data[index] = Data(data[2 * index], data[2 * index + 1]);\n    }\n\n    // aplica una actualización a un nodo y la deja pendiente para sus hijos\n    void apply(int index, const Lazy &l) {\n        l.updateData(data[index]);\n        lazy[index].updateLazy(l);\n    }\n\n    // empuja la actualización pendiente a los hijos\n    void propagate(int index) {\n        if (lazy[index].empty()) return;\n        apply(2 * index, lazy[index]);\n        apply(2 * index + 1, lazy[index]);\n        lazy[index] = Lazy();\n    }\n\n    // actualiza el rango [lower, upper]\n    void update(int index, int left, int right, int lower, int upper, const Lazy &value) {\n        if (left > upper || right < lower) return;\n        if (lower <= left && right <= upper) { apply(index, value); return; }\n        propagate(index);\n        int mid = (left + right) / 2;\n        update(2 * index, left, mid, lower, upper, value);\n        update(2 * index + 1, mid + 1, right, lower, upper, value);\n        data[index] = Data(data[2 * index], data[2 * index + 1]);\n    }\n\n    // suma en el rango [lower, upper]\n    ll query(int index, int left, int right, int lower, int upper) {\n        if (left > upper || right < lower) return 0;\n        if (lower <= left && right <= upper) return data[index].suma;\n        propagate(index);\n        int mid = (left + right) / 2;\n        return query(2 * index, left, mid, lower, upper) + query(2 * index + 1, mid + 1, right, lower, upper);\n    }\n};\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<ll> a(n);\n    for (auto &x : a) cin >> x;\n\n    SegmentTree Tree(a);\n    while (q--) {\n        int type, l, r;\n        cin >> type >> l >> r;\n        l--, r--;\n        if (type == 1) { ll x; cin >> x; Tree.update(1, 0, n - 1, l, r, Lazy::Add(x)); }\n        else if (type == 2) { ll x; cin >> x; Tree.update(1, 0, n - 1, l, r, Lazy::Set(x)); }\n        else cout << Tree.query(1, 0, n - 1, l, r) << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nsys.setrecursionlimit(1 << 25)\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Lazy Segment Tree, propagación perezosa (sumar a un rango, asignar a un rango y suma de rango)\n * Problema  : CSES 1735 - Range Updates and Sums (https://cses.fi/problemset/task/1735)\n * Entrada   : n q, n enteros, luego q consultas: \"1 a b x\" (suma x), \"2 a b x\" (asigna x) o \"3 a b\" (consulta suma)\n * Salida    : la suma de cada consulta de tipo 3\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n\"\"\"\n\n\n# Segment Tree con propagación perezosa: suma[] guarda la suma de cada nodo\n# y cada nodo puede tener pendiente \"asignar setv\" (si has_set) y luego \"sumar add\"\nclass SegmentTree:\n    def __init__(self, a):\n        self.n = n = len(a)\n        self.suma = [0] * (4 * n)\n        self.size = [0] * (4 * n)\n        self.has_set = [False] * (4 * n)\n        self.setv = [0] * (4 * n)\n        self.add = [0] * (4 * n)\n        self.build(a, 1, 0, n - 1)\n\n    # construye el árbol recursivamente\n    def build(self, a, i, l, r):\n        self.size[i] = r - l + 1\n        if l == r:\n            self.suma[i] = a[l]\n            return\n        m = (l + r) // 2\n        self.build(a, 2 * i, l, m)\n        self.build(a, 2 * i + 1, m + 1, r)\n        self.suma[i] = self.suma[2 * i] + self.suma[2 * i + 1]\n\n    # aplica una actualización a un nodo y la deja pendiente para sus hijos\n    def apply(self, i, is_set, value, add):\n        if is_set:\n            self.suma[i] = value * self.size[i]\n            self.has_set[i], self.setv[i], self.add[i] = True, value, 0\n        self.suma[i] += add * self.size[i]\n        self.add[i] += add\n\n    # empuja la actualización pendiente a los hijos\n    def propagate(self, i):\n        if self.has_set[i] or self.add[i]:\n            for c in (2 * i, 2 * i + 1):\n                self.apply(c, self.has_set[i], self.setv[i], self.add[i])\n            self.has_set[i], self.add[i] = False, 0\n\n    # actualiza el rango [lo, hi]\n    def update(self, i, l, r, lo, hi, is_set, value, add):\n        if r < lo or l > hi:\n            return\n        if lo <= l and r <= hi:\n            self.apply(i, is_set, value, add)\n            return\n        self.propagate(i)\n        m = (l + r) // 2\n        self.update(2 * i, l, m, lo, hi, is_set, value, add)\n        self.update(2 * i + 1, m + 1, r, lo, hi, is_set, value, add)\n        self.suma[i] = self.suma[2 * i] + self.suma[2 * i + 1]\n\n    # suma en el rango [lo, hi]\n    def query(self, i, l, r, lo, hi):\n        if r < lo or l > hi:\n            return 0\n        if lo <= l and r <= hi:\n            return self.suma[i]\n        self.propagate(i)\n        m = (l + r) // 2\n        return self.query(2 * i, l, m, lo, hi) + self.query(2 * i + 1, m + 1, r, lo, hi)\n\n\ndef main():\n    n, q = map(int, input().split())\n    a = list(map(int, input().split()))\n    tree = SegmentTree(a)\n    out = []\n    for _ in range(q):\n        t = list(map(int, input().split()))\n        l, r = t[1] - 1, t[2] - 1\n        if t[0] == 1:\n            tree.update(1, 0, n - 1, l, r, False, 0, t[3])\n        elif t[0] == 2:\n            tree.update(1, 0, n - 1, l, r, True, t[3], 0)\n        else:\n            out.append(tree.query(1, 0, n - 1, l, r))\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-MoAlgorithm", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/MoAlgorithm.cpp", "nombre": "MoAlgorithm", "algoritmo": "Algoritmo de Mo (consultas offline con raíz cuadrada)", "problema": "CSES 1734 - Distinct Values Queries (https://cses.fi/problemset/task/1734)", "cses": "https://cses.fi/problemset/task/1734", "py_lento": true, "entrada": "n q, n enteros, luego q consultas \"a b\"", "salida": "cantidad de valores distintos en cada rango [a, b]", "complejidad": "tiempo O((n + q) √n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Algoritmo de Mo (consultas offline con raíz cuadrada)\n * Problema  : CSES 1734 - Distinct Values Queries (https://cses.fi/problemset/task/1734)\n * Entrada   : n q, n enteros, luego q consultas \"a b\"\n * Salida    : cantidad de valores distintos en cada rango [a, b]\n * Complejidad: tiempo O((n + q) √n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<int> a(n);\n    for (auto &x : a) cin >> x;\n    // comprimir valores\n    // se comprimen los valores a 0..k-1\n    vector<int> vals = a;\n    sort(all(vals));\n    vals.erase(unique(all(vals)), vals.end());\n    for (auto &x : a) x = lower_bound(all(vals), x) - vals.begin();\n\n    // tamaño de bloque ≈ √n\n    int block = max(1, (int)sqrt(n));\n    vector<array<int, 3>> queries(q);  // {l, r, índice}\n    for (int i = 0; i < q; i++) {\n        cin >> queries[i][0] >> queries[i][1];\n        queries[i][0]--, queries[i][1]--;\n        queries[i][2] = i;\n    }\n    // se ordenan las consultas por bloque del extremo izquierdo (y alternando el derecho)\n    sort(all(queries), [&](const array<int, 3> &x, const array<int, 3> &y) {\n        int bx = x[0] / block, by = y[0] / block;\n        if (bx != by) return bx < by;\n        return (bx & 1) ? x[1] > y[1] : x[1] < y[1];\n    });\n\n    // cnt[v] = apariciones de v en la ventana actual, distinct = valores distintos\n    vector<int> cnt(vals.size(), 0), ans(q);\n    int distinct = 0, L = 0, R = -1;\n    auto add = [&](int i) { if (cnt[a[i]]++ == 0) distinct++; };\n    auto del = [&](int i) { if (--cnt[a[i]] == 0) distinct--; };\n    // se mueven los extremos de la ventana de una consulta a la siguiente\n    for (auto &[l, r, id] : queries) {\n        while (L > l) add(--L);\n        while (R < r) add(++R);\n        while (L < l) del(L++);\n        while (R > r) del(R--);\n        ans[id] = distinct;\n    }\n    for (int x : ans) cout << x << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Algoritmo de Mo (consultas offline con raíz cuadrada)\n * Problema  : CSES 1734 - Distinct Values Queries (https://cses.fi/problemset/task/1734)\n * Entrada   : n q, n enteros, luego q consultas \"a b\"\n * Salida    : cantidad de valores distintos en cada rango [a, b]\n * Complejidad: tiempo O((n + q) √n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, q = int(data[0]), int(data[1])\n    a = data[2:n + 2]\n    # se comprimen los valores a 0..k-1\n    comp = {}\n    a = [comp.setdefault(v, len(comp)) for v in a]\n\n    # tamaño de bloque ≈ √n\n    block = max(1, int(n ** 0.5))\n    L_ = [int(x) - 1 for x in data[n + 2::2]]\n    R_ = [int(x) - 1 for x in data[n + 3::2]]\n\n    # se ordenan las consultas por bloque del extremo izquierdo (y alternando el derecho)\n    def key(i):\n        b = L_[i] // block\n        return b * 10 ** 6 + (R_[i] if b % 2 == 0 else n - R_[i])\n\n    order = sorted(range(q), key=key)\n\n    # cnt[v] = apariciones de v en la ventana actual, distinct = valores distintos\n    cnt = [0] * len(comp)\n    ans = [0] * q\n    distinct, L, R = 0, 0, -1\n    # se mueven los extremos de la ventana de una consulta a la siguiente\n    for i in order:\n        l, r = L_[i], R_[i]\n        while L > l:\n            L -= 1\n            v = a[L]\n            if cnt[v] == 0:\n                distinct += 1\n            cnt[v] += 1\n        while R < r:\n            R += 1\n            v = a[R]\n            if cnt[v] == 0:\n                distinct += 1\n            cnt[v] += 1\n        while L < l:\n            v = a[L]\n            cnt[v] -= 1\n            if cnt[v] == 0:\n                distinct -= 1\n            L += 1\n        while R > r:\n            v = a[R]\n            cnt[v] -= 1\n            if cnt[v] == 0:\n                distinct -= 1\n            R -= 1\n        ans[i] = distinct\n    print(\"\\n\".join(map(str, ans)))\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-SegmentTree", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/SegmentTree.cpp", "nombre": "SegmentTree", "algoritmo": "Segment Tree (cualquier operación asociativa; aquí: mínimo de rango y actualización puntual)", "problema": "CSES 1649 - Dynamic Range Minimum Queries (https://cses.fi/problemset/task/1649)", "cses": "https://cses.fi/problemset/task/1649", "py_lento": false, "entrada": "n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (mínimo en [a, b])", "salida": "el mínimo de cada consulta de tipo 2", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Segment Tree (cualquier operación asociativa; aquí: mínimo de rango y actualización puntual)\n * Problema  : CSES 1649 - Dynamic Range Minimum Queries (https://cses.fi/problemset/task/1649)\n * Entrada   : n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (mínimo en [a, b])\n * Salida    : el mínimo de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\n// árbol iterativo: las hojas están en t[n..2n) y cada padre guarda el mínimo de sus hijos\nstruct SegmentTree {\n    int n;\n    vector<ll> t;\n\n    SegmentTree(const vector<ll> &a) {\n        n = a.size();\n        t.assign(2 * n, INF);\n        for (int i = 0; i < n; i++) t[n + i] = a[i];\n        for (int i = n - 1; i > 0; i--) t[i] = min(t[2 * i], t[2 * i + 1]);\n    }\n\n    // se cambia la hoja y se recalcula hacia la raíz\n    void update(int p, ll value) {\n        for (t[p += n] = value; p > 1; p >>= 1) t[p >> 1] = min(t[p], t[p ^ 1]);\n    }\n\n    // mínimo en [l, r)\n    // mínimo en [l, r): se sube juntando los nodos que cubren el rango\n    ll query(int l, int r) {\n        ll res = INF;\n        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {\n            if (l & 1) res = min(res, t[l++]);\n            if (r & 1) res = min(res, t[--r]);\n        }\n        return res;\n    }\n};\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<ll> a(n);\n    for (auto &x : a) cin >> x;\n    SegmentTree Tree(a);\n    while (q--) {\n        int type;\n        cin >> type;\n        if (type == 1) {\n            int k;\n            ll u;\n            cin >> k >> u;\n            Tree.update(k - 1, u);\n        }\n        else {\n            int l, r;\n            cin >> l >> r;\n            cout << Tree.query(l - 1, r) << \"\\n\";\n        }\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Segment Tree (cualquier operación asociativa; aquí: mínimo de rango y actualización puntual)\n * Problema  : CSES 1649 - Dynamic Range Minimum Queries (https://cses.fi/problemset/task/1649)\n * Entrada   : n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (mínimo en [a, b])\n * Salida    : el mínimo de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n\"\"\"\n\n\n# árbol iterativo: las hojas están en t[n..2n) y cada padre guarda el mínimo de sus hijos\nclass SegmentTree:\n    def __init__(self, a):\n        self.n = n = len(a)\n        self.t = [INF] * n + a\n        for i in range(n - 1, 0, -1):\n            self.t[i] = min(self.t[2 * i], self.t[2 * i + 1])\n\n    # se cambia la hoja y se recalcula hacia la raíz\n    def update(self, p, value):\n        t = self.t\n        p += self.n\n        t[p] = value\n        while p > 1:\n            p >>= 1\n            t[p] = min(t[2 * p], t[2 * p + 1])\n\n    # mínimo en [l, r): se sube juntando los nodos que cubren el rango\n    def query(self, l, r):\n        t = self.t\n        res = INF\n        l += self.n\n        r += self.n\n        while l < r:\n            if l & 1:\n                res = min(res, t[l])\n                l += 1\n            if r & 1:\n                r -= 1\n                res = min(res, t[r])\n            l >>= 1\n            r >>= 1\n        return res\n\n\ndef main():\n    n, q = map(int, input().split())\n    a = list(map(int, input().split()))\n    tree = SegmentTree(a)\n    out = []\n    for _ in range(q):\n        t, x, y = map(int, input().split())\n        if t == 1:\n            tree.update(x - 1, y)\n        else:\n            out.append(tree.query(x - 1, y))\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-SparseTable", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/SparseTable.cpp", "nombre": "SparseTable", "algoritmo": "Sparse Table (mínimo de rango en O(1))", "problema": "CSES 1647 - Static Range Minimum Queries (https://cses.fi/problemset/task/1647)", "cses": "https://cses.fi/problemset/task/1647", "py_lento": false, "entrada": "n q, n enteros, luego q consultas \"a b\"", "salida": "el mínimo de cada rango", "complejidad": "tiempo O(n log n + q), memoria O(n log n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Sparse Table (mínimo de rango en O(1))\n * Problema  : CSES 1647 - Static Range Minimum Queries (https://cses.fi/problemset/task/1647)\n * Entrada   : n q, n enteros, luego q consultas \"a b\"\n * Salida    : el mínimo de cada rango\n * Complejidad: tiempo O(n log n + q), memoria O(n log n)\n */\n\n// st[j][i] = mínimo del rango que empieza en i con longitud 2^j\nstruct SparseTable {\n    int n, LOG;\n    vector<vector<ll>> st;\n\n    SparseTable(const vector<ll> &a) {\n        n = a.size();\n        // cantidad de niveles necesarios\n        LOG = 32 - __builtin_clz(n);\n        st.assign(LOG, vector<ll>(n));\n        st[0] = a;\n        // cada nivel combina dos rangos del nivel anterior\n        for (int j = 1; j < LOG; j++)\n            for (int i = 0; i + (1 << j) <= n; i++)\n                st[j][i] = min(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);\n    }\n\n    // minimo en el rango [l..r] (0-indexado), O(1)\n    ll query(int l, int r) {\n        // se cubre [l..r] con dos rangos de longitud 2^j que se pueden solapar (válido para el mínimo)\n        int j = 31 - __builtin_clz(r - l + 1);\n        return min(st[j][l], st[j][r - (1 << j) + 1]);\n    }\n};\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<ll> a(n);\n    for (auto &x : a) cin >> x;\n\n    SparseTable table(a);\n    while (q--) {\n        int l, r; cin >> l >> r;\n        l--; r--;\n        cout << table.query(l, r) << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Sparse Table (mínimo de rango en O(1))\n * Problema  : CSES 1647 - Static Range Minimum Queries (https://cses.fi/problemset/task/1647)\n * Entrada   : n q, n enteros, luego q consultas \"a b\"\n * Salida    : el mínimo de cada rango\n * Complejidad: tiempo O(n log n + q), memoria O(n log n)\n\"\"\"\n\n\ndef main():\n    n, q = map(int, input().split())\n    a = list(map(int, input().split()))\n\n    # st[j][i] = mínimo del rango que empieza en i con longitud 2^j\n    st = [a]\n    j = 1\n    # cada nivel combina dos rangos del nivel anterior\n    while (1 << j) <= n:\n        prev, half = st[-1], 1 << (j - 1)\n        st.append([min(prev[i], prev[i + half]) for i in range(n - (1 << j) + 1)])\n        j += 1\n\n    out = []\n    for _ in range(q):\n        l, r = map(int, input().split())\n        l -= 1\n        # se cubre [l..r] con dos rangos de longitud 2^k que se pueden solapar (válido para el mínimo)\n        k = (r - l).bit_length() - 1\n        out.append(min(st[k][l], st[k][r - (1 << k)]))\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-Stack", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/Stack.cpp", "nombre": "Stack", "algoritmo": "Pila monótona (menor valor anterior)", "problema": "CSES 1645 - Nearest Smaller Values (https://cses.fi/problemset/task/1645)", "cses": "https://cses.fi/problemset/task/1645", "py_lento": false, "entrada": "n, luego n enteros", "salida": "para cada posición, el índice (base 1) del elemento menor más cercano a la izquierda, o 0", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Pila monótona (menor valor anterior)\n * Problema  : CSES 1645 - Nearest Smaller Values (https://cses.fi/problemset/task/1645)\n * Entrada   : n, luego n enteros\n * Salida    : para cada posición, el índice (base 1) del elemento menor más cercano a la izquierda, o 0\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<ll> a(n);\n    for (auto &x : a) cin >> x;\n\n    // la pila guarda índices con valores estrictamente crecientes\n    // se mantienen los candidatos a \"menor más cercano\"\n    stack<int> st;\n    for (int i = 0; i < n; i++) {\n        // los mayores o iguales a a[i] ya no sirven para elementos futuros\n        while (!st.empty() && a[st.top()] >= a[i]) st.pop();\n        // el tope es el menor más cercano a la izquierda (o 0 si no hay)\n        cout << (st.empty() ? 0 : st.top() + 1) << ' ';\n        // a[i] es candidato para los siguientes\n        st.push(i);\n    }\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Pila monótona (menor valor anterior)\n * Problema  : CSES 1645 - Nearest Smaller Values (https://cses.fi/problemset/task/1645)\n * Entrada   : n, luego n enteros\n * Salida    : para cada posición, el índice (base 1) del elemento menor más cercano a la izquierda, o 0\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    a = list(map(int, input().split()))\n\n    # se mantienen los candidatos a \"menor más cercano\"\n    st = []\n    res = []\n    for i in range(n):\n        # los mayores o iguales a a[i] ya no sirven para elementos futuros\n        while st and a[st[-1]] >= a[i]:\n            st.pop()\n        # el tope es el menor más cercano a la izquierda (o 0 si no hay)\n        res.append(st[-1] + 1 if st else 0)\n        # a[i] es candidato para los siguientes\n        st.append(i)\n    print(*res)\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-SweepLine", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/SweepLine.cpp", "nombre": "SweepLine", "algoritmo": "Sweep line (eventos ordenados)", "problema": "CSES 1619 - Restaurant Customers (https://cses.fi/problemset/task/1619)", "cses": "https://cses.fi/problemset/task/1619", "py_lento": false, "entrada": "n, luego n pares \"llegada salida\"", "salida": "máxima cantidad de clientes simultáneos", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Sweep line (eventos ordenados)\n * Problema  : CSES 1619 - Restaurant Customers (https://cses.fi/problemset/task/1619)\n * Entrada   : n, luego n pares \"llegada salida\"\n * Salida    : máxima cantidad de clientes simultáneos\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    // eventos: +1 al llegar y -1 al salir\n    vector<pair<int, int>> events;  // {tiempo, +1 llega / -1 sale}\n    for (int i = 0; i < n; i++) {\n        int a, b;\n        cin >> a >> b;\n        events.push_back({a, 1});\n        events.push_back({b, -1});\n    }\n    // a igual tiempo, las salidas (-1) van antes que las llegadas\n    sort(all(events));\n\n    int cur = 0, best = 0;\n    for (auto [t, d] : events) {\n        // cur = clientes presentes en este momento\n        cur += d;\n        best = max(best, cur);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Sweep line (eventos ordenados)\n * Problema  : CSES 1619 - Restaurant Customers (https://cses.fi/problemset/task/1619)\n * Entrada   : n, luego n pares \"llegada salida\"\n * Salida    : máxima cantidad de clientes simultáneos\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    # eventos: llegadas y salidas, cada lista ordenada por tiempo\n    arr = sorted(map(int, data[1:2 * n + 1:2]))\n    dep = sorted(map(int, data[2:2 * n + 2:2]))\n\n    # se recorren los eventos en orden; a igual tiempo, las salidas van antes que las llegadas\n    cur = best = 0\n    j = 0\n    for t in arr:\n        while dep[j] <= t:\n            cur -= 1\n            j += 1\n        # cur = clientes presentes en este momento\n        cur += 1\n        if cur > best:\n            best = cur\n    print(best)\n\n\nmain()\n"}, {"id": "Data-Structures-Algorithms-TwoPointers", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/TwoPointers.cpp", "nombre": "TwoPointers", "algoritmo": "Dos punteros sobre arreglo ordenado (suma de dos valores)", "problema": "CSES 1640 - Sum of Two Values (https://cses.fi/problemset/task/1640)", "cses": "https://cses.fi/problemset/task/1640", "py_lento": false, "entrada": "n x, luego n enteros", "salida": "dos posiciones (base 1) cuyos valores suman x, o IMPOSSIBLE", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Dos punteros sobre arreglo ordenado (suma de dos valores)\n * Problema  : CSES 1640 - Sum of Two Values (https://cses.fi/problemset/task/1640)\n * Entrada   : n x, luego n enteros\n * Salida    : dos posiciones (base 1) cuyos valores suman x, o IMPOSSIBLE\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    ll x;\n    cin >> n >> x;\n    // se guarda el índice original junto al valor\n    vector<pair<ll, int>> a(n);\n    for (int i = 0; i < n; i++) {\n        cin >> a[i].first;\n        a[i].second = i + 1;\n    }\n    sort(all(a));\n\n    // dos punteros en los extremos del arreglo ordenado\n    int l = 0, r = n - 1;\n    while (l < r) {\n        ll s = a[l].first + a[r].first;\n        if (s == x) {\n            cout << a[l].second << ' ' << a[r].second << \"\\n\";\n            return 0;\n        }\n        // suma pequeña: se sube el menor; suma grande: se baja el mayor\n        if (s < x) l++;\n        else r--;\n    }\n    cout << \"IMPOSSIBLE\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Dos punteros sobre arreglo ordenado (suma de dos valores)\n * Problema  : CSES 1640 - Sum of Two Values (https://cses.fi/problemset/task/1640)\n * Entrada   : n x, luego n enteros\n * Salida    : dos posiciones (base 1) cuyos valores suman x, o IMPOSSIBLE\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n, x = map(int, input().split())\n    # se guarda el índice original junto al valor\n    a = sorted((v, i + 1) for i, v in enumerate(map(int, input().split())))\n\n    # dos punteros en los extremos del arreglo ordenado\n    l, r = 0, n - 1\n    while l < r:\n        s = a[l][0] + a[r][0]\n        if s == x:\n            print(a[l][1], a[r][1])\n            return\n        # suma pequeña: se sube el menor; suma grande: se baja el mayor\n        if s < x:\n            l += 1\n        else:\n            r -= 1\n    print(\"IMPOSSIBLE\")\n\n\nmain()\n"}, {"id": "Data-Structures-Classic-Problems-Forest-Queries", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/Forest Queries.cpp", "nombre": "Forest Queries", "algoritmo": "Sumas de prefijos en 2D", "problema": "CSES 1652 - Forest Queries (https://cses.fi/problemset/task/1652)", "cses": "https://cses.fi/problemset/task/1652", "py_lento": false, "entrada": "n q, n filas con '.' (vacío) y '*' (árbol), luego q consultas \"y1 x1 y2 x2\"", "salida": "cantidad de árboles en cada rectángulo", "complejidad": "tiempo O(n^2 + q), memoria O(n^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Sumas de prefijos en 2D\n * Problema  : CSES 1652 - Forest Queries (https://cses.fi/problemset/task/1652)\n * Entrada   : n q, n filas con '.' (vacío) y '*' (árbol), luego q consultas \"y1 x1 y2 x2\"\n * Salida    : cantidad de árboles en cada rectángulo\n * Complejidad: tiempo O(n^2 + q), memoria O(n^2)\n */\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    // p[i][j] = árboles en el rectángulo (1,1)-(i,j)\n    vector<vector<int>> p(n + 1, vector<int>(n + 1, 0));\n    for (int i = 1; i <= n; i++) {\n        string row;\n        cin >> row;\n        for (int j = 1; j <= n; j++)\n            // inclusión-exclusión: arriba + izquierda - esquina repetida + la celda\n            p[i][j] = p[i - 1][j] + p[i][j - 1] - p[i - 1][j - 1] + (row[j - 1] == '*');\n    }\n    while (q--) {\n        int y1, x1, y2, x2;\n        cin >> y1 >> x1 >> y2 >> x2;\n        cout << p[y2][x2] - p[y1 - 1][x2] - p[y2][x1 - 1] + p[y1 - 1][x1 - 1] << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\nfrom itertools import accumulate\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Sumas de prefijos en 2D\n * Problema  : CSES 1652 - Forest Queries (https://cses.fi/problemset/task/1652)\n * Entrada   : n q, n filas con '.' (vacío) y '*' (árbol), luego q consultas \"y1 x1 y2 x2\"\n * Salida    : cantidad de árboles en cada rectángulo\n * Complejidad: tiempo O(n^2 + q), memoria O(n^2)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, q = int(data[0]), int(data[1])\n    # p[i][j] = árboles en el rectángulo (1,1)-(i,j); se arma fila por fila\n    p = [[0] * (n + 1)]\n    for i in range(n):\n        row = data[2 + i]\n        # prefijo de la fila (42 es el código de '*') sumado a la fila de arriba\n        acc = accumulate(c == 42 for c in row)\n        p.append([0] + [a + b for a, b in zip(acc, p[-1][1:])])\n    qs = list(map(int, data[2 + n:]))\n    out = []\n    for k in range(0, 4 * q, 4):\n        y1, x1, y2, x2 = qs[k], qs[k + 1], qs[k + 2], qs[k + 3]\n        out.append(p[y2][x2] - p[y1 - 1][x2] - p[y2][x1 - 1] + p[y1 - 1][x1 - 1])\n    print('\\n'.join(map(str, out)))\n\n\nmain()\n"}, {"id": "Data-Structures-Classic-Problems-Hotel-Queries", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/Hotel Queries.cpp", "nombre": "Hotel Queries", "algoritmo": "Segment Tree de máximos con descenso (primer elemento ≥ x)", "problema": "CSES 1143 - Hotel Queries (https://cses.fi/problemset/task/1143)", "cses": "https://cses.fi/problemset/task/1143", "py_lento": true, "entrada": "n m, cuartos libres de cada hotel, luego los cuartos que pide cada grupo", "salida": "el primer hotel con espacio suficiente para cada grupo (o 0)", "complejidad": "tiempo O((n + m) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Segment Tree de máximos con descenso (primer elemento ≥ x)\n * Problema  : CSES 1143 - Hotel Queries (https://cses.fi/problemset/task/1143)\n * Entrada   : n m, cuartos libres de cada hotel, luego los cuartos que pide cada grupo\n * Salida    : el primer hotel con espacio suficiente para cada grupo (o 0)\n * Complejidad: tiempo O((n + m) log n), memoria O(n)\n */\n\nint sz;\nvector<ll> t;  // t[v] = máximo de cuartos libres en el tramo del nodo v\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    sz = 1;\n    while (sz < n) sz <<= 1;\n    t.assign(2 * sz, 0);\n    for (int i = 0; i < n; i++) cin >> t[sz + i];\n    for (int v = sz - 1; v >= 1; v--) t[v] = max(t[2 * v], t[2 * v + 1]);\n    while (m--) {\n        ll r;\n        cin >> r;\n        // si ni el máximo alcanza, ningún hotel sirve\n        if (t[1] < r) { cout << 0 << ' '; continue; }\n        // se baja siempre por el hijo izquierdo si alcanza: así se encuentra el primero\n        int v = 1;\n        while (v < sz) v = (t[2 * v] >= r) ? 2 * v : 2 * v + 1;\n        cout << v - sz + 1 << ' ';\n        // se ocupan los cuartos y se recalcula el camino a la raíz\n        t[v] -= r;\n        for (v >>= 1; v >= 1; v >>= 1) t[v] = max(t[2 * v], t[2 * v + 1]);\n    }\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Segment Tree de máximos con descenso (primer elemento ≥ x)\n * Problema  : CSES 1143 - Hotel Queries (https://cses.fi/problemset/task/1143)\n * Entrada   : n m, cuartos libres de cada hotel, luego los cuartos que pide cada grupo\n * Salida    : el primer hotel con espacio suficiente para cada grupo (o 0)\n * Complejidad: tiempo O((n + m) log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, m = int(data[0]), int(data[1])\n    sz = 1\n    while sz < n:\n        sz <<= 1\n    # t[v] = máximo de cuartos libres en el tramo del nodo v\n    t = [0] * (2 * sz)\n    t[sz:sz + n] = map(int, data[2:2 + n])\n    for v in range(sz - 1, 0, -1):\n        a, b = t[2 * v], t[2 * v + 1]\n        t[v] = a if a > b else b\n    out = []\n    for r in map(int, data[2 + n:2 + n + m]):\n        # si ni el máximo alcanza, ningún hotel sirve\n        if t[1] < r:\n            out.append(0)\n            continue\n        # se baja por el hijo izquierdo si alcanza: así se encuentra el primero\n        v = 1\n        while v < sz:\n            v <<= 1\n            if t[v] < r:\n                v += 1\n        out.append(v - sz + 1)\n        # se ocupan los cuartos y se recalcula el camino a la raíz\n        t[v] -= r\n        v >>= 1\n        while v:\n            a, b = t[2 * v], t[2 * v + 1]\n            t[v] = a if a > b else b\n            v >>= 1\n    print(*out)\n\n\nmain()\n"}, {"id": "Data-Structures-Classic-Problems-K-Smallest-Sums", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/K-Smallest Sums.cpp", "nombre": "K-Smallest Sums", "algoritmo": "K menores sumas con heap (fusión de dos listas ordenadas)", "problema": "UVa 11997 - K Smallest Sums", "cses": "", "py_lento": false, "entrada": "varios casos: k, luego k filas de k enteros", "salida": "las k menores sumas posibles (una por columna), por caso", "complejidad": "tiempo O(k^2 log k), memoria O(k)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : K menores sumas con heap (fusión de dos listas ordenadas)\n * Problema  : UVa 11997 - K Smallest Sums\n * Entrada   : varios casos: k, luego k filas de k enteros\n * Salida    : las k menores sumas posibles (una por columna), por caso\n * Complejidad: tiempo O(k^2 log k), memoria O(k)\n */\n\n// comparador para que el heap sea un min-heap por la suma\nclass comp{\n\tpublic:\n\t\tbool operator()(tuple<ll, ll, ll>& a, tuple<ll, ll, ll>&b){\n\t\t\treturn get<0>(a) > get<0>(b);\n\t\t}\n};\n\n// mezcla dos listas ordenadas y devuelve las k menores sumas a[i] + b[j]\nvector<ll> merge(vector<ll> &a, vector<ll> &b, int k){\n\tvector<ll> res(k);\n\n\tpriority_queue<tuple<ll, ll, ll>, vector<tuple<ll, ll, ll>>, comp> heap;\n\tll suma, ii, j;\n\tset<tuple<ll, ll>> vis;\n\t// la menor suma posible es a[0] + b[0]\n\theap.push({a[0] + b[0], 0, 0});\n\tfor(int i = 0; i < k; i++){\n\t\t// se saca la menor suma pendiente\n\t\tauto [suma, ii, j] = heap.top(); heap.pop();\n\t\tres[i] = suma;\n\t\t\n\t\t// se agregan los dos vecinos (i+1, j) y (i, j+1); vis evita repetirlos\n\t\tif(ii+1 < k && vis.find({ii+1, j}) == vis.end()){\n\t\t\ttuple<ll, ll, ll> first = {a[ii+1] + b[j], ii+1, j};\n\t\t\theap.push(first);\n\t\t\tvis.insert({ii+1, j});\n\t\t}\n\t\tif(j+1 < k && vis.find({ii, j+1}) == vis.end()){\n\t\t\ttuple<ll, ll, ll> second = {a[ii] + b[j+1], ii, j+1};\n\t\t\theap.push(second);\n\t\t\tvis.insert({ii, j+1});\n\t\t}\n\n\t}\n\treturn res;\n}\n \nint main(){\n\tfastio;\n\tint k; \n\twhile(cin >> k){\n\t\tvector<ll> res(k); for(auto&x:res){cin >> x;}\n\t\tsort(res.begin(), res.end());\n\t\tfor(int i = 1; i < k; i++){\n\t\t\tvector<ll> a(k); for(auto&x:a){cin >> x;} sort(a.begin(), a.end());\n\t\t\tres = merge(res, a, k); sort(res.begin(), res.end());\n\t\t}\n\t\tfor(int i = 0; i < k-1; i++) cout << res[i] << \" \";\n\t\tcout << res.back() << \"\\n\";\n\t}\n}\n", "python": "import sys\nimport heapq\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : K menores sumas con heap (fusión de dos listas ordenadas)\n * Problema  : UVa 11997 - K Smallest Sums\n * Entrada   : varios casos: k, luego k filas de k enteros\n * Salida    : las k menores sumas posibles (una por columna), por caso\n * Complejidad: tiempo O(k^2 log k), memoria O(k)\n\"\"\"\n\n\n# mezcla dos listas ordenadas y devuelve las k menores sumas a[i] + b[j]\ndef merge(a, b, k):\n    # la menor suma posible es a[0] + b[0]\n    heap = [(a[0] + b[0], 0, 0)]\n    vis = {(0, 0)}\n    res = []\n    while len(res) < k:\n        # se saca la menor suma pendiente\n        s, i, j = heapq.heappop(heap)\n        res.append(s)\n        # se agregan los dos vecinos (i+1, j) y (i, j+1); vis evita repetirlos\n        if i + 1 < k and (i + 1, j) not in vis:\n            vis.add((i + 1, j))\n            heapq.heappush(heap, (a[i + 1] + b[j], i + 1, j))\n        if j + 1 < k and (i, j + 1) not in vis:\n            vis.add((i, j + 1))\n            heapq.heappush(heap, (a[i] + b[j + 1], i, j + 1))\n    return res\n\n\ndef main():\n    data = sys.stdin.read().split()\n    pos = 0\n    out = []\n    # varios casos: se mezcla fila por fila quedándose siempre con las k menores\n    while pos < len(data):\n        k = int(data[pos])\n        pos += 1\n        rows = []\n        for _ in range(k):\n            rows.append(sorted(map(int, data[pos:pos + k])))\n            pos += k\n        cur = rows[0]\n        for i in range(1, k):\n            cur = merge(cur, rows[i], k)\n        out.append(\" \".join(map(str, cur)))\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Data-Structures-Classic-Problems-Prefix-Sum-Queries", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/Prefix Sum Queries.cpp", "nombre": "Prefix Sum Queries", "algoritmo": "Segment Tree con nodos compuestos (suma y mejor prefijo)", "problema": "CSES 2166 - Prefix Sum Queries (https://cses.fi/problemset/task/2166)", "cses": "https://cses.fi/problemset/task/2166", "py_lento": true, "entrada": "n q, n enteros, luego q consultas \"1 k u\" (x_k = u) o \"2 a b\"", "salida": "para cada consulta de tipo 2, la máxima suma de un prefijo de [a, b] (el prefijo vacío vale 0)", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Segment Tree con nodos compuestos (suma y mejor prefijo)\n * Problema  : CSES 2166 - Prefix Sum Queries (https://cses.fi/problemset/task/2166)\n * Entrada   : n q, n enteros, luego q consultas \"1 k u\" (x_k = u) o \"2 a b\"\n * Salida    : para cada consulta de tipo 2, la máxima suma de un prefijo de [a, b] (el prefijo vacío vale 0)\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\n// cada nodo guarda la suma de su tramo y su mejor prefijo (≥ 0 porque se permite el vacío)\nstruct Node { ll sum, pre; };\n// combinar: el mejor prefijo es el de la izquierda, o toda la izquierda más un prefijo de la derecha\nNode comb(const Node &a, const Node &b) { return {a.sum + b.sum, max(a.pre, a.sum + b.pre)}; }\nconst Node NEUTRO = {0, 0};\n\nint sz;\nvector<Node> t;\n\nvoid update(int i, ll v) {\n    i += sz;\n    t[i] = {v, max(0LL, v)};\n    for (i >>= 1; i >= 1; i >>= 1) t[i] = comb(t[2 * i], t[2 * i + 1]);\n}\n\n// consulta [l, r) iterativa; el orden importa (comb no es conmutativa), así que se junta por los dos lados\nll query(int l, int r) {\n    Node L = NEUTRO, R = NEUTRO;\n    for (l += sz, r += sz; l < r; l >>= 1, r >>= 1) {\n        if (l & 1) L = comb(L, t[l++]);\n        if (r & 1) R = comb(t[--r], R);\n    }\n    return comb(L, R).pre;\n}\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    sz = n;\n    t.assign(2 * n, NEUTRO);\n    for (int i = 0; i < n; i++) { ll x; cin >> x; t[sz + i] = {x, max(0LL, x)}; }\n    for (int i = sz - 1; i >= 1; i--) t[i] = comb(t[2 * i], t[2 * i + 1]);\n    while (q--) {\n        int ty; ll a, b;\n        cin >> ty >> a >> b;\n        if (ty == 1) update(a - 1, b);\n        else cout << query(a - 1, b) << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Segment Tree con nodos compuestos (suma y mejor prefijo)\n * Problema  : CSES 2166 - Prefix Sum Queries (https://cses.fi/problemset/task/2166)\n * Entrada   : n q, n enteros, luego q consultas \"1 k u\" (x_k = u) o \"2 a b\"\n * Salida    : para cada consulta de tipo 2, la máxima suma de un prefijo de [a, b] (el prefijo vacío vale 0)\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, q = int(data[0]), int(data[1])\n    sz = 1\n    while sz < n:\n        sz <<= 1\n    # cada nodo: S = suma del tramo, P = mejor prefijo (≥ 0, se permite el vacío)\n    S = [0] * (2 * sz)\n    P = [0] * (2 * sz)\n    for i in range(n):\n        x = int(data[2 + i])\n        S[sz + i] = x\n        P[sz + i] = x if x > 0 else 0\n    for v in range(sz - 1, 0, -1):\n        l, r = 2 * v, 2 * v + 1\n        S[v] = S[l] + S[r]\n        # mejor prefijo: el de la izquierda, o toda la izquierda más un prefijo de la derecha\n        P[v] = max(P[l], S[l] + P[r])\n    out = []\n    pos = 2 + n\n    for _ in range(q):\n        ty, a, b = data[pos], int(data[pos + 1]), int(data[pos + 2])\n        pos += 3\n        if ty == b'1':\n            v = sz + a - 1\n            S[v] = b\n            P[v] = b if b > 0 else 0\n            v >>= 1\n            while v:\n                l = 2 * v\n                S[v] = S[l] + S[l + 1]\n                P[v] = max(P[l], S[l] + P[l + 1])\n                v >>= 1\n        else:\n            # se juntan los nodos de izquierda a derecha (el orden importa)\n            l, r = a - 1 + sz, b + sz\n            ls, lp = 0, 0\n            right = []\n            while l < r:\n                if l & 1:\n                    lp = max(lp, ls + P[l])\n                    ls += S[l]\n                    l += 1\n                if r & 1:\n                    r -= 1\n                    right.append(r)\n                l >>= 1\n                r >>= 1\n            for v in reversed(right):\n                lp = max(lp, ls + P[v])\n                ls += S[v]\n            out.append(lp)\n    print('\\n'.join(map(str, out)))\n\n\nmain()\n"}, {"id": "Data-Structures-Classic-Problems-Range-Update-Queries", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/Range Update Queries.cpp", "nombre": "Range Update Queries", "algoritmo": "Fenwick Tree sobre el arreglo de diferencias (suma en rango, consulta puntual)", "problema": "CSES 1651 - Range Update Queries (https://cses.fi/problemset/task/1651)", "cses": "https://cses.fi/problemset/task/1651", "py_lento": false, "entrada": "n q, n enteros, luego q consultas \"1 a b u\" (sumar u a [a, b]) o \"2 k\" (valor en k)", "salida": "el valor pedido en cada consulta de tipo 2", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Fenwick Tree sobre el arreglo de diferencias (suma en rango, consulta puntual)\n * Problema  : CSES 1651 - Range Update Queries (https://cses.fi/problemset/task/1651)\n * Entrada   : n q, n enteros, luego q consultas \"1 a b u\" (sumar u a [a, b]) o \"2 k\" (valor en k)\n * Salida    : el valor pedido en cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\nint n;\nvector<ll> bit;\nvoid add(int i, ll v) { for (; i <= n; i += i & -i) bit[i] += v; }\nll sum(int i) { ll s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }\n\nint main() {\n    fastio;\n    int q;\n    cin >> n >> q;\n    vector<ll> x(n + 1);\n    for (int i = 1; i <= n; i++) cin >> x[i];\n    // bit guarda diferencias: sumar u a [a, b] es +u en a y -u en b+1\n    bit.assign(n + 2, 0);\n    while (q--) {\n        int t;\n        cin >> t;\n        if (t == 1) {\n            int a, b; ll u;\n            cin >> a >> b >> u;\n            add(a, u);\n            if (b + 1 <= n) add(b + 1, -u);\n        } else {\n            int k;\n            cin >> k;\n            // el valor actual es el original más todo lo acumulado hasta k\n            cout << x[k] + sum(k) << \"\\n\";\n        }\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Fenwick Tree sobre el arreglo de diferencias (suma en rango, consulta puntual)\n * Problema  : CSES 1651 - Range Update Queries (https://cses.fi/problemset/task/1651)\n * Entrada   : n q, n enteros, luego q consultas \"1 a b u\" (sumar u a [a, b]) o \"2 k\" (valor en k)\n * Salida    : el valor pedido en cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, q = int(data[0]), int(data[1])\n    x = [0] + list(map(int, data[2:2 + n]))\n    # bit guarda diferencias: sumar u a [a, b] es +u en a y -u en b+1\n    bit = [0] * (n + 1)\n    pos = 2 + n\n    out = []\n    for _ in range(q):\n        if data[pos] == b'1':\n            a, b, u = int(data[pos + 1]), int(data[pos + 2]), int(data[pos + 3])\n            pos += 4\n            i = a\n            while i <= n:\n                bit[i] += u\n                i += i & -i\n            i = b + 1\n            while i <= n:\n                bit[i] -= u\n                i += i & -i\n        else:\n            k = int(data[pos + 1])\n            pos += 2\n            # el valor actual es el original más todo lo acumulado hasta k\n            s = x[k]\n            while k > 0:\n                s += bit[k]\n                k -= k & -k\n            out.append(s)\n    print('\\n'.join(map(str, out)))\n\n\nmain()\n"}, {"id": "Data-Structures-Classic-Problems-Static-Range-Sum-Queries", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/Static Range Sum Queries.cpp", "nombre": "Static Range Sum Queries", "algoritmo": "Sumas de prefijos", "problema": "CSES 1646 - Static Range Sum Queries (https://cses.fi/problemset/task/1646)", "cses": "https://cses.fi/problemset/task/1646", "py_lento": false, "entrada": "n q, n enteros, luego q consultas \"a b\"", "salida": "la suma de cada rango [a, b]", "complejidad": "tiempo O(n + q), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Sumas de prefijos\n * Problema  : CSES 1646 - Static Range Sum Queries (https://cses.fi/problemset/task/1646)\n * Entrada   : n q, n enteros, luego q consultas \"a b\"\n * Salida    : la suma de cada rango [a, b]\n * Complejidad: tiempo O(n + q), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    // p[i] = x_1 + ... + x_i, con p[0] = 0\n    vector<ll> p(n + 1, 0);\n    for (int i = 1; i <= n; i++) {\n        ll x;\n        cin >> x;\n        p[i] = p[i - 1] + x;\n    }\n    while (q--) {\n        int a, b;\n        cin >> a >> b;\n        // la suma de [a, b] es lo que se acumula entre a-1 y b\n        cout << p[b] - p[a - 1] << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\nfrom itertools import accumulate\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Sumas de prefijos\n * Problema  : CSES 1646 - Static Range Sum Queries (https://cses.fi/problemset/task/1646)\n * Entrada   : n q, n enteros, luego q consultas \"a b\"\n * Salida    : la suma de cada rango [a, b]\n * Complejidad: tiempo O(n + q), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, q = int(data[0]), int(data[1])\n    # p[i] = x_1 + ... + x_i, con p[0] = 0\n    p = [0] + list(accumulate(map(int, data[2:2 + n])))\n    qs = data[2 + n:]\n    # la suma de [a, b] es p[b] - p[a-1]\n    out = [p[int(qs[2 * i + 1])] - p[int(qs[2 * i]) - 1] for i in range(q)]\n    print('\\n'.join(map(str, out)))\n\n\nmain()\n"}, {"id": "Data-Structures-Classic-Problems-Team-Queue", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/Team Queue.cpp", "nombre": "Team Queue", "algoritmo": "Cola de equipos (cola de colas)", "problema": "UVa 540 - Team Queue", "cses": "", "py_lento": false, "entrada": "varios casos: n equipos con sus miembros y órdenes ENQUEUE x / DEQUEUE / STOP, terminando con n = 0", "salida": "cada elemento desencolado, bajo \"Scenario #t\"", "complejidad": "tiempo O(1) por operación, memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Cola de equipos (cola de colas)\n * Problema  : UVa 540 - Team Queue\n * Entrada   : varios casos: n equipos con sus miembros y órdenes ENQUEUE x / DEQUEUE / STOP, terminando con n = 0\n * Salida    : cada elemento desencolado, bajo \"Scenario #t\"\n * Complejidad: tiempo O(1) por operación, memoria O(n)\n */\n\nint main(){\n\tfastio;\n\tint tt = 1;\n\twhile(true){\n\t\tll n; cin >> n;\n\t\tif(n == 0) break;\n\t\t\n\t\t// TeamQueue[x] = cola del equipo al que pertenece x\n\t\tmap<ll, queue<ll>*> TeamQueue;\n\t\t// cola de equipos que tienen alguien esperando\n\t\tqueue<queue<ll>*> Queue;\n\n\t\tfor(int i = 0; i < n; i++){\n\t\t\tll k; cin >> k;\n\t\t\tqueue<ll>* team = new queue<ll>();\n\t\t\tfor(int j = 0; j < k; j++){\n\t\t\t\tll x; cin >> x;\n\t\t\t\tTeamQueue[x] = team;\n\t\t\t}\n\t\t}\n\n\t\tcout << \"Scenario #\" << tt << \"\\n\";\n\t\twhile (true)\n\t\t{\n\t\t\tstring s; cin >> s;\n\t\t\t// fin del caso\n\t\t\tif(s == \"STOP\") break;\n\t\t\t// el nuevo entra a la cola de su equipo; si el equipo estaba vacío, el equipo entra al final\n\t\t\telse if(s == \"ENQUEUE\"){\n\t\t\t\tll x; cin >> x;\n\t\t\t\tTeamQueue[x]->push(x);\n\t\t\t\tif(TeamQueue[x]->size() == 1){\n\t\t\t\t\tQueue.push(TeamQueue[x]);\n\t\t\t\t}\n\t\t\t}\n\t\t\telse{\n\t\t\t\t// DEQUEUE: sale el primero del equipo que está al frente\n\t\t\t\tll x = Queue.front()->front();\n\t\t\t\tcout << x << \"\\n\";\n\t\t\t\tQueue.front()->pop();\n\n\t\t\t\t// si el equipo se vacía, deja la cola de equipos\n\t\t\t\tif(Queue.front()->size() == 0) Queue.pop();\n\t\t\t}\n\t\t}\n\t\ttt++; cout << \"\\n\";\n\t}\n}\n", "python": "import sys\nfrom collections import deque\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Cola de equipos (cola de colas)\n * Problema  : UVa 540 - Team Queue\n * Entrada   : varios casos: n equipos con sus miembros y órdenes ENQUEUE x / DEQUEUE / STOP, terminando con n = 0\n * Salida    : cada elemento desencolado, bajo \"Scenario #t\"\n * Complejidad: tiempo O(1) por operación, memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.read().split()\n    pos = 0\n    out = []\n    scenario = 0\n    while True:\n        t = int(data[pos])\n        pos += 1\n        if t == 0:\n            break\n        scenario += 1\n        out.append(\"Scenario #%d\" % scenario)\n\n        # team_of[x] = equipo al que pertenece x\n        team_of = {}\n        for team in range(t):\n            m = int(data[pos])\n            pos += 1\n            for x in data[pos:pos + m]:\n                team_of[x] = team\n            pos += m\n\n        # cola de cada equipo y cola de equipos que tienen alguien esperando\n        team_queue = [deque() for _ in range(t)]\n        queue = deque()\n        while True:\n            cmd = data[pos]\n            pos += 1\n            # fin del caso\n            if cmd == \"STOP\":\n                break\n            if cmd == \"ENQUEUE\":\n                x = data[pos]\n                pos += 1\n                tm = team_of[x]\n                # el nuevo entra a la cola de su equipo; si el equipo estaba vacío, el equipo entra al final\n                if not team_queue[tm]:\n                    queue.append(tm)\n                team_queue[tm].append(x)\n            else:\n                # DEQUEUE: sale el primero del equipo que está al frente\n                tm = queue[0]\n                out.append(team_queue[tm].popleft())\n                # si el equipo se vacía, deja la cola de equipos\n                if not team_queue[tm]:\n                    queue.popleft()\n        out.append(\"\")\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-BipartiteMatching", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/BipartiteMatching.cpp", "nombre": "BipartiteMatching", "algoritmo": "Emparejamiento bipartito máximo (algoritmo de Kuhn)", "problema": "CSES 1696 - School Dance (https://cses.fi/problemset/task/1696)", "cses": "https://cses.fi/problemset/task/1696", "py_lento": false, "entrada": "n m k, luego k pares \"chico chica\"", "salida": "cantidad máxima de parejas y las parejas", "complejidad": "tiempo O(V · E), memoria O(V + E)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Emparejamiento bipartito máximo (algoritmo de Kuhn)\n * Problema  : CSES 1696 - School Dance (https://cses.fi/problemset/task/1696)\n * Entrada   : n m k, luego k pares \"chico chica\"\n * Salida    : cantidad máxima de parejas y las parejas\n * Complejidad: tiempo O(V · E), memoria O(V + E)\n */\n\nint n, m;\nvector<vector<int>> G;\n// match[v] = nodo de la izquierda emparejado con v (0 si ninguno)\nvector<int> match;  // match[chica] = chico emparejado (0 si ninguno)\nvector<bool> used;\n\n// busca un camino aumentante desde u\nbool kuhn(int u) {\n    for (int v : G[u]) {\n        if (used[v]) continue;\n        used[v] = true;\n        // v está libre, o se puede reubicar a quien lo ocupa\n        if (match[v] == 0 || kuhn(match[v])) {\n            match[v] = u;\n            return true;\n        }\n    }\n    return false;\n}\n\nint main() {\n    fastio;\n    int k;\n    cin >> n >> m >> k;\n    G.assign(n + 1, {});\n    match.assign(m + 1, 0);\n    for (int i = 0; i < k; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n    }\n\n    int total = 0;\n    // se intenta emparejar a cada nodo de la izquierda\n    for (int u = 1; u <= n; u++) {\n        // used evita visitar un nodo dos veces en la misma búsqueda\n        used.assign(m + 1, false);\n        if (kuhn(u)) total++;\n    }\n\n    cout << total << \"\\n\";\n    for (int v = 1; v <= m; v++)\n        if (match[v]) cout << match[v] << ' ' << v << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Emparejamiento bipartito máximo (algoritmo de Kuhn)\n * Problema  : CSES 1696 - School Dance (https://cses.fi/problemset/task/1696)\n * Entrada   : n m k, luego k pares \"chico chica\"\n * Salida    : cantidad máxima de parejas y las parejas\n * Complejidad: tiempo O(V · E), memoria O(V + E)\n\"\"\"\n\n\ndef main():\n    n, m, k = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(k):\n        a, b = map(int, input().split())\n        G[a].append(b)\n\n    # match[v] = nodo de la izquierda emparejado con v (0 si ninguno)\n    match = [0] * (m + 1)\n\n    # busca un camino aumentante desde s (DFS iterativo de Kuhn)\n    def kuhn(s, used):\n        st = [(s, 0)]\n        path = []\n        while st:\n            u, i = st[-1]\n            if i == len(G[u]):\n                st.pop()\n                if path:\n                    path.pop()\n                continue\n            st[-1] = (u, i + 1)\n            v = G[u][i]\n            if used[v]:\n                continue\n            # used evita visitar un nodo dos veces en la misma búsqueda\n            used[v] = True\n            path.append((u, v))\n            # v está libre: se aplica toda la cadena de reasignaciones\n            if match[v] == 0:\n                for a, b in path:\n                    match[b] = a\n                return True\n            # v está ocupado: se intenta reubicar a quien lo ocupa\n            st.append((match[v], 0))\n        return False\n\n    total = 0\n    # se intenta emparejar a cada nodo de la izquierda\n    for u in range(1, n + 1):\n        if kuhn(u, [False] * (m + 1)):\n            total += 1\n\n    out = [str(total)]\n    for v in range(1, m + 1):\n        if match[v]:\n            out.append(\"%d %d\" % (match[v], v))\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-Dinic", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/Dinic.cpp", "nombre": "Dinic", "algoritmo": "Dinic (flujo máximo)", "problema": "CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)", "cses": "https://cses.fi/problemset/task/1694", "py_lento": false, "entrada": "n m, luego m aristas dirigidas \"a b c\" (capacidad c)", "salida": "el flujo máximo de 1 a n", "complejidad": "tiempo O(V^2 · E), memoria O(V + E)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Dinic (flujo máximo)\n * Problema  : CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (capacidad c)\n * Salida    : el flujo máximo de 1 a n\n * Complejidad: tiempo O(V^2 · E), memoria O(V + E)\n */\n\n// Dinic: cada fase arma un grafo por niveles (BFS) y envía flujo bloqueante (DFS)\nstruct Dinic {\n    struct Edge {\n        int to;\n        ll cap;\n    };\n    int n;\n    vector<Edge> edges;\n    vector<vector<int>> G;\n    vector<int> level, it;\n\n    Dinic(int n): n(n), G(n + 1), level(n + 1), it(n + 1) {}\n\n    // arista y su inversa (capacidad 0) en posiciones consecutivas: id ^ 1 es la inversa\n    void addEdge(int u, int v, ll cap) {\n        G[u].push_back(edges.size());\n        edges.push_back({v, cap});\n        G[v].push_back(edges.size());\n        edges.push_back({u, 0});\n    }\n\n    // niveles desde s; devuelve si t es alcanzable\n    bool bfs(int s, int t) {\n        fill(all(level), -1);\n        queue<int> q;\n        level[s] = 0;\n        q.push(s);\n        while (!q.empty()) {\n            int u = q.front();\n            q.pop();\n            for (int id : G[u]) {\n                if (edges[id].cap > 0 && level[edges[id].to] == -1) {\n                    level[edges[id].to] = level[u] + 1;\n                    q.push(edges[id].to);\n                }\n            }\n        }\n        return level[t] != -1;\n    }\n\n    // empuja flujo solo por aristas que suben un nivel; it[v] recuerda por dónde seguir\n    ll dfs(int v, int t, ll pushed) {\n        if (v == t || pushed == 0) return pushed;\n        for (int &i = it[v]; i < (int)G[v].size(); i++) {\n            int id = G[v][i];\n            int u = edges[id].to;\n            if (level[u] != level[v] + 1 || edges[id].cap == 0) continue;\n            ll f = dfs(u, t, min(pushed, edges[id].cap));\n            if (f > 0) {\n                edges[id].cap -= f;\n                edges[id ^ 1].cap += f;\n                return f;\n            }\n        }\n        return 0;\n    }\n\n    // mientras exista camino, se repiten fases\n    ll maxflow(int s, int t) {\n        ll flow = 0;\n        while (bfs(s, t)) {\n            fill(all(it), 0);\n            while (ll f = dfs(s, t, INF)) flow += f;\n        }\n        return flow;\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    Dinic flow(n);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        flow.addEdge(a, b, c);\n    }\n    cout << flow.maxflow(1, n) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nfrom collections import deque\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Dinic (flujo máximo)\n * Problema  : CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (capacidad c)\n * Salida    : el flujo máximo de 1 a n\n * Complejidad: tiempo O(V^2 · E), memoria O(V + E)\n\"\"\"\n\n\n# Dinic: cada fase arma un grafo por niveles (BFS) y envía flujo bloqueante (DFS)\nclass Dinic:\n    def __init__(self, n):\n        self.n = n\n        self.G = [[] for _ in range(n + 1)]\n        # aristas en listas paralelas: to[e], cap[e]; e ^ 1 es la inversa\n        self.to, self.cap = [], []\n\n    # arista y su inversa (capacidad 0) en posiciones consecutivas\n    def add_edge(self, u, v, c):\n        self.G[u].append(len(self.to))\n        self.to.append(v)\n        self.cap.append(c)\n        self.G[v].append(len(self.to))\n        self.to.append(u)\n        self.cap.append(0)\n\n    # niveles desde s; devuelve si t es alcanzable\n    def bfs(self, s, t):\n        self.level = level = [-1] * (self.n + 1)\n        level[s] = 0\n        q = deque([s])\n        while q:\n            u = q.popleft()\n            for e in self.G[u]:\n                v = self.to[e]\n                if self.cap[e] > 0 and level[v] == -1:\n                    level[v] = level[u] + 1\n                    q.append(v)\n        return level[t] != -1\n\n    # empuja flujo solo por aristas que suben un nivel; it[v] recuerda por dónde seguir (iterativo)\n    def dfs(self, s, t):\n        G, to, cap, level, it = self.G, self.to, self.cap, self.level, self.it\n        path = []\n        v = s\n        while True:\n            if v == t:\n                f = min(cap[e] for e in path)\n                for e in path:\n                    cap[e] -= f\n                    cap[e ^ 1] += f\n                return f\n            advanced = False\n            while it[v] < len(G[v]):\n                e = G[v][it[v]]\n                u = to[e]\n                if cap[e] > 0 and level[u] == level[v] + 1:\n                    path.append(e)\n                    v = u\n                    advanced = True\n                    break\n                it[v] += 1\n            if not advanced:\n                if v == s:\n                    return 0\n                # callejón sin salida: se retrocede y se descarta esa arista\n                level[v] = -1\n                e = path.pop()\n                v = to[e ^ 1]\n                it[v] += 1\n\n    # mientras exista camino, se repiten fases\n    def maxflow(self, s, t):\n        flow = 0\n        while self.bfs(s, t):\n            self.it = [0] * (self.n + 1)\n            while True:\n                f = self.dfs(s, t)\n                if f == 0:\n                    break\n                flow += f\n        return flow\n\n\ndef main():\n    n, m = map(int, input().split())\n    flow = Dinic(n)\n    for _ in range(m):\n        a, b, c = map(int, input().split())\n        flow.add_edge(a, b, c)\n    print(flow.maxflow(1, n))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-EdmonsKarp", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/EdmonsKarp.cpp", "nombre": "EdmonsKarp", "algoritmo": "Edmonds-Karp (flujo máximo con BFS)", "problema": "CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)", "cses": "https://cses.fi/problemset/task/1694", "py_lento": true, "entrada": "n m, luego m aristas dirigidas \"a b c\" (capacidad c)", "salida": "el flujo máximo de 1 a n", "complejidad": "tiempo O(V · E^2), memoria O(V^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Edmonds-Karp (flujo máximo con BFS)\n * Problema  : CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (capacidad c)\n * Salida    : el flujo máximo de 1 a n\n * Complejidad: tiempo O(V · E^2), memoria O(V^2)\n */\n\nint n;\n// capacity[u][v] = capacidad residual; adj solo para recorrer vecinos\nvector<vector<ll>> capacity;\nvector<vector<int>> adj;\n\n// BFS que busca un camino aumentante; devuelve el cuello de botella\n// BFS que busca un camino aumentante; devuelve el cuello de botella\nll bfs(int s, int t, vector<int> &parent) {\n    fill(all(parent), -1);\n    parent[s] = -2;\n    queue<pair<int, ll>> q;\n    q.push({s, INF});\n    while (!q.empty()) {\n        auto [u, flow] = q.front();\n        q.pop();\n        for (int v : adj[u]) {\n            if (parent[v] == -1 && capacity[u][v] > 0) {\n                parent[v] = u;\n                ll new_flow = min(flow, capacity[u][v]);\n                if (v == t) return new_flow;\n                q.push({v, new_flow});\n            }\n        }\n    }\n    return 0;\n}\n\n// se aumenta el flujo mientras haya camino\nll maxflow(int s, int t) {\n    ll flow = 0;\n    vector<int> parent(n + 1);\n    while (ll new_flow = bfs(s, t, parent)) {\n        flow += new_flow;\n        int cur = t;\n        while (cur != s) {\n            int prev = parent[cur];\n            // se resta en la arista y se suma en la inversa\n            capacity[prev][cur] -= new_flow;\n            capacity[cur][prev] += new_flow;\n            cur = prev;\n        }\n    }\n    return flow;\n}\n\nint main() {\n    fastio;\n    int m;\n    cin >> n >> m;\n    capacity.assign(n + 1, vector<ll>(n + 1, 0));\n    adj.assign(n + 1, {});\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        if (capacity[a][b] == 0 && capacity[b][a] == 0) {\n            adj[a].push_back(b);\n            adj[b].push_back(a);\n        }\n        // se suman capacidades si hay aristas repetidas\n        capacity[a][b] += c;\n    }\n    cout << maxflow(1, n) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nfrom collections import deque\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Edmonds-Karp (flujo máximo con BFS)\n * Problema  : CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (capacidad c)\n * Salida    : el flujo máximo de 1 a n\n * Complejidad: tiempo O(V · E^2), memoria O(V^2)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    # capacity[u][v] = capacidad residual; adj solo para recorrer vecinos\n    capacity = [[0] * (n + 1) for _ in range(n + 1)]\n    adj = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b, c = map(int, input().split())\n        if capacity[a][b] == 0 and capacity[b][a] == 0:\n            adj[a].append(b)\n            adj[b].append(a)\n        # se suman capacidades si hay aristas repetidas\n        capacity[a][b] += c\n\n    s, t = 1, n\n    flow = 0\n    # se aumenta el flujo mientras haya camino\n    while True:\n        # BFS que busca un camino aumentante; guarda el cuello de botella\n        parent = [-1] * (n + 1)\n        parent[s] = -2\n        bottleneck = [0] * (n + 1)\n        bottleneck[s] = INF\n        q = deque([s])\n        while q and parent[t] == -1:\n            u = q.popleft()\n            for v in adj[u]:\n                if parent[v] == -1 and capacity[u][v] > 0:\n                    parent[v] = u\n                    bottleneck[v] = min(bottleneck[u], capacity[u][v])\n                    q.append(v)\n        if parent[t] == -1:\n            break\n        f = bottleneck[t]\n        flow += f\n        # se resta en la arista y se suma en la inversa\n        v = t\n        while v != s:\n            u = parent[v]\n            capacity[u][v] -= f\n            capacity[v][u] += f\n            v = u\n    print(flow)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-MinCostAnyFlow", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/MinCostAnyFlow.cpp", "nombre": "MinCostAnyFlow", "algoritmo": "Flujo de costo mínimo con exactamente K unidades (Successive Shortest Paths)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "n m K, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)", "salida": "IMPOSSIBLE si no se pueden enviar K unidades; si no, el costo mínimo", "complejidad": "tiempo O(K · E log V), memoria O(V + E)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Flujo de costo mínimo con exactamente K unidades (Successive Shortest Paths)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n m K, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)\n * Salida    : IMPOSSIBLE si no se pueden enviar K unidades; si no, el costo mínimo\n * Complejidad: tiempo O(K · E log V), memoria O(V + E)\n */\n\n// cada arista guarda destino, índice de su inversa, capacidad y costo\nstruct MinCostFlow {\n    struct Edge { ll to, rev, cap, cost; };\n    \n    ll n;\n    vector<vector<Edge>> adj;\n    \n    MinCostFlow(ll n=0): n(n), adj(n) {}\n\n    // agrega la arista y su inversa (capacidad 0 y costo negativo)\n    ll add_edge(ll u, ll v, ll cap, ll cost){\n        ll iu = adj[u].size();\n        ll iv = adj[v].size();\n        adj[u].push_back({v, iv, cap, cost});\n        adj[v].push_back({u, iu, 0, -cost});\n        return iu;\n    }\n\n    // try to send exactly K flow from s to t; returns {flow_sent, total_cost}\n    pair<ll,ll> min_cost_flow_k(ll s, ll t, ll K){\n        ll flow = 0, cost = 0;\n        vector<ll> potential(n, 0), dist(n);\n        vector<ll> parent_vertex(n), parent_edge(n);\n\n        // init potentials with Bellman-Ford if negative edges exist (safe)\n        for(int it = 0; it < n; ++it){\n            bool any = false;\n            for(int v = 0; v < n; ++v){\n                if(potential[v] == INF) continue;\n                for(auto &edge : adj[v]){\n                    if(edge.cap > 0 && potential[edge.to] > potential[v] + edge.cost){\n                        potential[edge.to] = potential[v] + edge.cost;\n                        any = true;\n                    }\n                }\n            }\n            if(!any) break;\n        }\n\n        // cada vuelta envía flujo por el camino más barato del grafo residual (Dijkstra con potenciales)\n        while(flow < K){\n            fill(all(dist), INF); dist[s] = 0;\n\n            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;\n            pq.push({0, s});\n            \n            while(!pq.empty()){\n                auto [dis, v] = pq.top(); pq.pop();\n                if(dis != dist[v]) continue;\n                for(int i = 0; i < (int)adj[v].size(); ++i){\n                    auto &edge = adj[v][i];\n                    if(edge.cap <= 0) continue;\n                    ll new_dis = dis + edge.cost + potential[v] - potential[edge.to];\n                    if(new_dis < dist[edge.to]){\n                        dist[edge.to] = new_dis;\n                        parent_vertex[edge.to] = v;\n                        parent_edge[edge.to] = i;\n                        pq.push({new_dis, edge.to});\n                    }\n                }\n            }\n            if(dist[t] == INF) break; // cannot send more\n\n            for(int v = 0; v < n; ++v)\n                if(dist[v] < INF) potential[v] += dist[v];\n\n            // cuello de botella del camino encontrado\n            ll add = K - flow;\n            int v = t;\n            while(v != s){\n                auto &edge = adj[parent_vertex[v]][parent_edge[v]];\n                add = min(add, edge.cap);\n                v = parent_vertex[v];\n            }\n\n            v = t;\n            while(v != s){\n                auto &edge = adj[parent_vertex[v]][parent_edge[v]];\n                edge.cap -= add;\n                adj[v][edge.rev].cap += add;\n                v = parent_vertex[v];\n            }\n\n            // potential[t] es el costo real del camino más corto\n            flow += add;\n            cost += add * potential[t]; // potential[t] equals actual shortest path cost\n        }\n\n        return {flow, cost};\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    ll K;\n    cin >> n >> m >> K;\n    MinCostFlow mcf(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        ll cap, cost;\n        cin >> u >> v >> cap >> cost;\n        mcf.add_edge(u, v, cap, cost);\n    }\n\n    auto [flow, cost] = mcf.min_cost_flow_k(1, n, K);\n    if (flow < K) cout << \"IMPOSSIBLE\\n\";\n    else cout << cost << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport heapq\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Flujo de costo mínimo con exactamente K unidades (Successive Shortest Paths)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n m K, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)\n * Salida    : IMPOSSIBLE si no se pueden enviar K unidades; si no, el costo mínimo\n * Complejidad: tiempo O(K · E log V), memoria O(V + E)\n\"\"\"\n\n\n# cada arista guarda destino, capacidad y costo en listas paralelas; e ^ 1 es la inversa\nclass MinCostFlow:\n    def __init__(self, n):\n        self.n = n\n        self.G = [[] for _ in range(n)]\n        self.to, self.cap, self.cost = [], [], []\n\n    # agrega la arista y su inversa (capacidad 0 y costo negativo)\n    def add_edge(self, u, v, c, w):\n        self.G[u].append(len(self.to))\n        self.to.append(v); self.cap.append(c); self.cost.append(w)\n        self.G[v].append(len(self.to))\n        self.to.append(u); self.cap.append(0); self.cost.append(-w)\n\n    def min_cost_flow_k(self, s, t, K):\n        n, G, to, cap, cost = self.n, self.G, self.to, self.cap, self.cost\n        # potenciales iniciales con Bellman-Ford (por si hay costos negativos)\n        pot = [INF] * n\n        pot[s] = 0\n        for _ in range(n):\n            changed = False\n            for u in range(n):\n                if pot[u] == INF:\n                    continue\n                for e in G[u]:\n                    if cap[e] > 0 and pot[u] + cost[e] < pot[to[e]]:\n                        pot[to[e]] = pot[u] + cost[e]\n                        changed = True\n            if not changed:\n                break\n        pot = [p if p != INF else 0 for p in pot]\n\n        flow = total = 0\n        # cada vuelta envía flujo por el camino más barato del grafo residual (Dijkstra con potenciales)\n        while flow < K:\n            dist = [INF] * n\n            pe = [-1] * n\n            dist[s] = 0\n            pq = [(0, s)]\n            while pq:\n                d, u = heapq.heappop(pq)\n                if d > dist[u]:\n                    continue\n                for e in G[u]:\n                    v = to[e]\n                    nd = d + cost[e] + pot[u] - pot[v]\n                    if cap[e] > 0 and nd < dist[v]:\n                        dist[v] = nd\n                        pe[v] = e\n                        heapq.heappush(pq, (nd, v))\n            if dist[t] == INF:\n                break\n            for v in range(n):\n                if dist[v] < INF:\n                    pot[v] += dist[v]\n            # cuello de botella del camino encontrado\n            add = K - flow\n            v = t\n            while v != s:\n                e = pe[v]\n                add = min(add, cap[e])\n                v = to[e ^ 1]\n            v = t\n            while v != s:\n                e = pe[v]\n                cap[e] -= add\n                cap[e ^ 1] += add\n                v = to[e ^ 1]\n            flow += add\n            # pot[t] - pot[s] es el costo real del camino más corto\n            total += add * (pot[t] - pot[s])\n        return flow, total\n\n\ndef main():\n    n, m, K = map(int, input().split())\n    mcf = MinCostFlow(n + 1)\n    for _ in range(m):\n        u, v, c, w = map(int, input().split())\n        mcf.add_edge(u, v, c, w)\n    flow, cost = mcf.min_cost_flow_k(1, n, K)\n    print(\"IMPOSSIBLE\" if flow < K else cost)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-MinCostMaxFlow", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/MinCostMaxFlow.cpp", "nombre": "MinCostMaxFlow", "algoritmo": "Flujo máximo de costo mínimo (Successive Shortest Paths con potenciales)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "n m, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)", "salida": "cantidad de flujo máximo enviado y su costo mínimo total", "complejidad": "tiempo O(F · E log V), F = flujo total, memoria O(V + E)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Flujo máximo de costo mínimo (Successive Shortest Paths con potenciales)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n m, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)\n * Salida    : cantidad de flujo máximo enviado y su costo mínimo total\n * Complejidad: tiempo O(F · E log V), F = flujo total, memoria O(V + E)\n */\n\n// cada arista guarda destino, índice de su inversa, capacidad y costo\nstruct MinCostFlow {\n    struct Edge { ll to, rev, cap, cost; };\n    \n    ll n;\n    vector<vector<Edge>> adj;\n    \n    MinCostFlow(ll n=0): n(n), adj(n) {}\n\n    // agrega la arista y su inversa (capacidad 0 y costo negativo)\n    ll add_edge(ll u, ll v, ll cap, ll cost){\n        ll iu = adj[u].size();\n        ll iv = adj[v].size();\n        adj[u].push_back({v, iv, cap, cost});\n        adj[v].push_back({u, iu, 0, -cost});\n        return iu;\n    }\n\n    // try to send exactly K flow from s to t; returns {flow_sent, total_cost}\n    pair<ll,ll> min_cost_flow_k(ll s, ll t, ll K){\n        ll flow = 0, cost = 0;\n        vector<ll> potential(n, 0), dist(n);\n        vector<ll> parent_vertex(n), parent_edge(n);\n\n        // init potentials with Bellman-Ford if negative edges exist (safe)\n        for(int it = 0; it < n; ++it){\n            bool any = false;\n            for(int v = 0; v < n; ++v){\n                if(potential[v] == INF) continue;\n                for(auto &edge : adj[v]){\n                    if(edge.cap > 0 && potential[edge.to] > potential[v] + edge.cost){\n                        potential[edge.to] = potential[v] + edge.cost;\n                        any = true;\n                    }\n                }\n            }\n            if(!any) break;\n        }\n\n        // cada vuelta envía flujo por el camino más barato del grafo residual (Dijkstra con potenciales)\n        while(flow < K){\n            fill(all(dist), INF); dist[s] = 0;\n\n            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;\n            pq.push({0, s});\n            \n            while(!pq.empty()){\n                auto [dis, v] = pq.top(); pq.pop();\n                if(dis != dist[v]) continue;\n                for(int i = 0; i < (int)adj[v].size(); ++i){\n                    auto &edge = adj[v][i];\n                    if(edge.cap <= 0) continue;\n                    ll new_dis = dis + edge.cost + potential[v] - potential[edge.to];\n                    if(new_dis < dist[edge.to]){\n                        dist[edge.to] = new_dis;\n                        parent_vertex[edge.to] = v;\n                        parent_edge[edge.to] = i;\n                        pq.push({new_dis, edge.to});\n                    }\n                }\n            }\n            if(dist[t] == INF) break; // cannot send more\n\n            for(int v = 0; v < n; ++v)\n                if(dist[v] < INF) potential[v] += dist[v];\n\n            // cuello de botella del camino encontrado\n            ll add = K - flow;\n            int v = t;\n            while(v != s){\n                auto &edge = adj[parent_vertex[v]][parent_edge[v]];\n                add = min(add, edge.cap);\n                v = parent_vertex[v];\n            }\n\n            v = t;\n            while(v != s){\n                auto &edge = adj[parent_vertex[v]][parent_edge[v]];\n                edge.cap -= add;\n                adj[v][edge.rev].cap += add;\n                v = parent_vertex[v];\n            }\n\n            // potential[t] es el costo real del camino más corto\n            flow += add;\n            cost += add * potential[t]; // potential[t] equals actual shortest path cost\n        }\n\n        return {flow, cost};\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    MinCostFlow mcf(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        ll cap, cost;\n        cin >> u >> v >> cap >> cost;\n        mcf.add_edge(u, v, cap, cost);\n    }\n\n    // K = INF: se envía todo el flujo posible\n    auto [flow, cost] = mcf.min_cost_flow_k(1, n, INF);\n    cout << flow << ' ' << cost << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport heapq\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Flujo máximo de costo mínimo (Successive Shortest Paths con potenciales)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n m, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)\n * Salida    : cantidad de flujo máximo enviado y su costo mínimo total\n * Complejidad: tiempo O(F · E log V), F = flujo total, memoria O(V + E)\n\"\"\"\n\n\n# cada arista guarda destino, capacidad y costo en listas paralelas; e ^ 1 es la inversa\nclass MinCostFlow:\n    def __init__(self, n):\n        self.n = n\n        self.G = [[] for _ in range(n)]\n        self.to, self.cap, self.cost = [], [], []\n\n    # agrega la arista y su inversa (capacidad 0 y costo negativo)\n    def add_edge(self, u, v, c, w):\n        self.G[u].append(len(self.to))\n        self.to.append(v); self.cap.append(c); self.cost.append(w)\n        self.G[v].append(len(self.to))\n        self.to.append(u); self.cap.append(0); self.cost.append(-w)\n\n    def min_cost_flow_k(self, s, t, K):\n        n, G, to, cap, cost = self.n, self.G, self.to, self.cap, self.cost\n        # potenciales iniciales con Bellman-Ford (por si hay costos negativos)\n        pot = [INF] * n\n        pot[s] = 0\n        for _ in range(n):\n            changed = False\n            for u in range(n):\n                if pot[u] == INF:\n                    continue\n                for e in G[u]:\n                    if cap[e] > 0 and pot[u] + cost[e] < pot[to[e]]:\n                        pot[to[e]] = pot[u] + cost[e]\n                        changed = True\n            if not changed:\n                break\n        pot = [p if p != INF else 0 for p in pot]\n\n        flow = total = 0\n        # cada vuelta envía flujo por el camino más barato del grafo residual (Dijkstra con potenciales)\n        while flow < K:\n            dist = [INF] * n\n            pe = [-1] * n\n            dist[s] = 0\n            pq = [(0, s)]\n            while pq:\n                d, u = heapq.heappop(pq)\n                if d > dist[u]:\n                    continue\n                for e in G[u]:\n                    v = to[e]\n                    nd = d + cost[e] + pot[u] - pot[v]\n                    if cap[e] > 0 and nd < dist[v]:\n                        dist[v] = nd\n                        pe[v] = e\n                        heapq.heappush(pq, (nd, v))\n            if dist[t] == INF:\n                break\n            for v in range(n):\n                if dist[v] < INF:\n                    pot[v] += dist[v]\n            # cuello de botella del camino encontrado\n            add = K - flow\n            v = t\n            while v != s:\n                e = pe[v]\n                add = min(add, cap[e])\n                v = to[e ^ 1]\n            v = t\n            while v != s:\n                e = pe[v]\n                cap[e] -= add\n                cap[e ^ 1] += add\n                v = to[e ^ 1]\n            flow += add\n            # pot[t] - pot[s] es el costo real del camino más corto\n            total += add * (pot[t] - pot[s])\n        return flow, total\n\n\ndef main():\n    n, m = map(int, input().split())\n    # nodos numerados de 1 a n\n    mcf = MinCostFlow(n + 1)\n    for _ in range(m):\n        u, v, c, w = map(int, input().split())\n        mcf.add_edge(u, v, c, w)\n    # K = INF: se envía todo el flujo posible\n    flow, cost = mcf.min_cost_flow_k(1, n, INF)\n    print(flow, cost)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-BFS", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/BFS.cpp", "nombre": "BFS", "algoritmo": "BFS (camino más corto en grafo no ponderado)", "problema": "CSES 1667 - Message Route (https://cses.fi/problemset/task/1667)", "cses": "https://cses.fi/problemset/task/1667", "py_lento": false, "entrada": "n m, luego m aristas \"a b\"", "salida": "IMPOSSIBLE, o la cantidad de nodos y un camino mínimo de 1 a n", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : BFS (camino más corto en grafo no ponderado)\n * Problema  : CSES 1667 - Message Route (https://cses.fi/problemset/task/1667)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : IMPOSSIBLE, o la cantidad de nodos y un camino mínimo de 1 a n\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> G(n + 1);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // dist[v] = aristas desde 1, parent[v] = nodo anterior en el camino mínimo\n    vector<int> dist(n + 1, -1), parent(n + 1, 0);\n    queue<int> q;\n    dist[1] = 0;\n    q.push(1);\n    // BFS: visita por capas, así la primera vez que se llega a un nodo es por el camino más corto\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        for (int v : G[u]) {\n            if (dist[v] != -1) continue;\n            dist[v] = dist[u] + 1;\n            parent[v] = u;\n            q.push(v);\n        }\n    }\n\n    if (dist[n] == -1) {\n        cout << \"IMPOSSIBLE\\n\";\n        return 0;\n    }\n    // se reconstruye el camino desde n hasta 1 con parent[]\n    vector<int> path;\n    for (int v = n; v != 0; v = parent[v]) path.push_back(v);\n    reverse(all(path));\n    cout << path.size() << \"\\n\";\n    for (int v : path) cout << v << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nfrom collections import deque\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : BFS (camino más corto en grafo no ponderado)\n * Problema  : CSES 1667 - Message Route (https://cses.fi/problemset/task/1667)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : IMPOSSIBLE, o la cantidad de nodos y un camino mínimo de 1 a n\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        G[b].append(a)\n\n    # dist[v] = aristas desde 1, parent[v] = nodo anterior en el camino mínimo\n    dist = [-1] * (n + 1)\n    parent = [0] * (n + 1)\n    # BFS: visita por capas, así la primera vez que se llega a un nodo es por el camino más corto\n    dist[1] = 0\n    q = deque([1])\n    while q:\n        u = q.popleft()\n        for v in G[u]:\n            if dist[v] == -1:\n                dist[v] = dist[u] + 1\n                parent[v] = u\n                q.append(v)\n\n    if dist[n] == -1:\n        print(\"IMPOSSIBLE\")\n        return\n    # se reconstruye el camino desde n hasta 1 con parent[]\n    path = []\n    v = n\n    while v != 0:\n        path.append(v)\n        v = parent[v]\n    path.reverse()\n    print(len(path))\n    print(*path)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-BellmanFord", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/BellmanFord.cpp", "nombre": "BellmanFord", "algoritmo": "Bellman-Ford (detección de ciclo negativo)", "problema": "CSES 1197 - Cycle Finding (https://cses.fi/problemset/task/1197)", "cses": "https://cses.fi/problemset/task/1197", "py_lento": false, "entrada": "n m, luego m aristas dirigidas \"a b c\" (peso c)", "salida": "NO, o YES y un ciclo de peso negativo", "complejidad": "tiempo O(n·m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Bellman-Ford (detección de ciclo negativo)\n * Problema  : CSES 1197 - Cycle Finding (https://cses.fi/problemset/task/1197)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (peso c)\n * Salida    : NO, o YES y un ciclo de peso negativo\n * Complejidad: tiempo O(n·m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    // aristas {a, b, c}\n    vector<array<ll, 3>> edges(m);\n    for (auto &e : edges) cin >> e[0] >> e[1] >> e[2];\n\n    // dist = 0 para todos: equivale a un nodo fuente virtual conectado a todos\n    // dist = 0 para todos: equivale a un nodo fuente virtual conectado a todos\n    vector<ll> dist(n + 1, 0);\n    vector<int> parent(n + 1, 0);\n    int last = -1;\n    // n rondas de relajación; si en la n-ésima aún mejora, hay ciclo negativo\n    for (int i = 0; i < n; i++) {\n        last = -1;\n        for (auto &[a, b, c] : edges) {\n            if (dist[a] + c < dist[b]) {\n                dist[b] = dist[a] + c;\n                parent[b] = a;\n                last = b;\n            }\n        }\n        if (last == -1) break;\n    }\n\n    if (last == -1) {\n        cout << \"NO\\n\";\n        return 0;\n    }\n    // retroceder n veces para asegurar estar dentro del ciclo\n    // retroceder n veces para asegurar estar dentro del ciclo\n    for (int i = 0; i < n; i++) last = parent[last];\n    // se recorre el ciclo siguiendo parent[] hasta volver a last\n    vector<int> cycle;\n    for (int v = last;; v = parent[v]) {\n        cycle.push_back(v);\n        if (v == last && cycle.size() > 1) break;\n    }\n    reverse(all(cycle));\n    cout << \"YES\\n\";\n    for (int v : cycle) cout << v << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Bellman-Ford (detección de ciclo negativo)\n * Problema  : CSES 1197 - Cycle Finding (https://cses.fi/problemset/task/1197)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (peso c)\n * Salida    : NO, o YES y un ciclo de peso negativo\n * Complejidad: tiempo O(n·m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    # aristas (a, b, c)\n    edges = [tuple(map(int, input().split())) for _ in range(m)]\n\n    # dist = 0 para todos: equivale a un nodo fuente virtual conectado a todos\n    dist = [0] * (n + 1)\n    parent = [0] * (n + 1)\n    last = -1\n    # n rondas de relajación; si en la n-ésima aún mejora, hay ciclo negativo\n    for _ in range(n):\n        last = -1\n        for a, b, c in edges:\n            if dist[a] + c < dist[b]:\n                dist[b] = dist[a] + c\n                parent[b] = a\n                last = b\n        if last == -1:\n            break\n\n    if last == -1:\n        print(\"NO\")\n        return\n    # retroceder n veces para asegurar estar dentro del ciclo\n    for _ in range(n):\n        last = parent[last]\n    # se recorre el ciclo siguiendo parent[] hasta volver a last\n    cycle = [last]\n    v = parent[last]\n    while v != last:\n        cycle.append(v)\n        v = parent[v]\n    cycle.append(last)\n    cycle.reverse()\n    print(\"YES\")\n    print(*cycle)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Bipartite", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Bipartite.cpp", "nombre": "Bipartite", "algoritmo": "Grafo bipartito (coloreo con BFS)", "problema": "CSES 1668 - Building Teams (https://cses.fi/problemset/task/1668)", "cses": "https://cses.fi/problemset/task/1668", "py_lento": false, "entrada": "n m, luego m aristas \"a b\"", "salida": "IMPOSSIBLE, o el equipo (1 o 2) de cada nodo", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Grafo bipartito (coloreo con BFS)\n * Problema  : CSES 1668 - Building Teams (https://cses.fi/problemset/task/1668)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : IMPOSSIBLE, o el equipo (1 o 2) de cada nodo\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> G(n + 1);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // color 1 o 2 por nodo (0 = aún sin color)\n    vector<int> color(n + 1, 0);  // 0 = sin color\n    for (int s = 1; s <= n; s++) {\n        if (color[s]) continue;\n        // cada componente se colorea desde un nodo cualquiera\n        color[s] = 1;\n        queue<int> q;\n        q.push(s);\n        while (!q.empty()) {\n            int u = q.front();\n            q.pop();\n            for (int v : G[u]) {\n                if (color[v] == 0) {\n                    // los vecinos reciben el color opuesto\n                    color[v] = 3 - color[u];\n                    q.push(v);\n                }\n                // dos vecinos del mismo color: hay un ciclo impar, no es bipartito\n                else if (color[v] == color[u]) {\n                    cout << \"IMPOSSIBLE\\n\";\n                    return 0;\n                }\n            }\n        }\n    }\n\n    for (int i = 1; i <= n; i++) cout << color[i] << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nfrom collections import deque\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Grafo bipartito (coloreo con BFS)\n * Problema  : CSES 1668 - Building Teams (https://cses.fi/problemset/task/1668)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : IMPOSSIBLE, o el equipo (1 o 2) de cada nodo\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        G[b].append(a)\n\n    # color 1 o 2 por nodo (0 = aún sin color)\n    color = [0] * (n + 1)\n    for s in range(1, n + 1):\n        if color[s]:\n            continue\n        # cada componente se colorea desde un nodo cualquiera\n        color[s] = 1\n        q = deque([s])\n        while q:\n            u = q.popleft()\n            for v in G[u]:\n                if color[v] == 0:\n                    # los vecinos reciben el color opuesto\n                    color[v] = 3 - color[u]\n                    q.append(v)\n                elif color[v] == color[u]:\n                    # dos vecinos del mismo color: hay un ciclo impar, no es bipartito\n                    print(\"IMPOSSIBLE\")\n                    return\n    print(*color[1:])\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-DFS", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/DFS.cpp", "nombre": "DFS", "algoritmo": "DFS (componentes conexas)", "problema": "CSES 1666 - Building Roads (https://cses.fi/problemset/task/1666)", "cses": "https://cses.fi/problemset/task/1666", "py_lento": false, "entrada": "n m, luego m aristas \"a b\"", "salida": "cantidad mínima de caminos a construir y las aristas que conectan las componentes", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DFS (componentes conexas)\n * Problema  : CSES 1666 - Building Roads (https://cses.fi/problemset/task/1666)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : cantidad mínima de caminos a construir y las aristas que conectan las componentes\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// visited[u] indica si u ya fue explorado\nvector<vector<int>> G;\nvector<bool> visited;\n\n// explora toda la componente de u\nvoid dfs(int u) {\n    visited[u] = true;\n    for (int v : G[u])\n        if (!visited[v]) dfs(v);\n}\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    G.assign(n + 1, {});\n    visited.assign(n + 1, false);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // un representante por componente; se unen en cadena\n    // un representante por cada componente conexa\n    vector<int> reps;\n    for (int i = 1; i <= n; i++) {\n        if (!visited[i]) {\n            reps.push_back(i);\n            dfs(i);\n        }\n    }\n\n    // se necesitan (componentes - 1) caminos para unirlas\n    cout << reps.size() - 1 << \"\\n\";\n    for (int i = 1; i < (int)reps.size(); i++)\n        cout << reps[i - 1] << ' ' << reps[i] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DFS (componentes conexas)\n * Problema  : CSES 1666 - Building Roads (https://cses.fi/problemset/task/1666)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : cantidad mínima de caminos a construir y las aristas que conectan las componentes\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        G[b].append(a)\n\n    # visited[u] indica si u ya fue explorado\n    visited = [False] * (n + 1)\n    # un representante por cada componente conexa\n    reps = []\n    for s in range(1, n + 1):\n        if visited[s]:\n            continue\n        reps.append(s)\n        # DFS iterativo con pila: explora toda la componente de s\n        visited[s] = True\n        st = [s]\n        while st:\n            u = st.pop()\n            for v in G[u]:\n                if not visited[v]:\n                    visited[v] = True\n                    st.append(v)\n\n    # se necesitan (componentes - 1) caminos para unirlas\n    out = [str(len(reps) - 1)]\n    for i in range(1, len(reps)):\n        out.append(\"%d %d\" % (reps[i - 1], reps[i]))\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-DSU", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/DSU.cpp", "nombre": "DSU", "algoritmo": "DSU (Union-Find con compresión de caminos y unión por tamaño)", "problema": "CSES 1676 - Road Construction (https://cses.fi/problemset/task/1676)", "cses": "https://cses.fi/problemset/task/1676", "py_lento": false, "entrada": "n m, luego m aristas \"a b\"", "salida": "tras cada arista: cantidad de componentes y tamaño de la componente más grande", "complejidad": "tiempo O(m α(n)), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DSU (Union-Find con compresión de caminos y unión por tamaño)\n * Problema  : CSES 1676 - Road Construction (https://cses.fi/problemset/task/1676)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : tras cada arista: cantidad de componentes y tamaño de la componente más grande\n * Complejidad: tiempo O(m α(n)), memoria O(n)\n */\n\n// Union-Find: parent[x] es el padre en el bosque y size el tamaño de cada conjunto\nstruct DSU {\n    vector<int> parent, size;\n\n    DSU(int n) {\n        parent.resize(n + 1);\n        size.assign(n + 1, 1);\n        iota(all(parent), 0);\n    }\n\n    // compresión de caminos\n    int find(int x) {\n        return parent[x] == x ? x : parent[x] = find(parent[x]);\n    }\n\n    // unión por tamaño: el conjunto pequeño se cuelga del grande\n    bool unite(int a, int b) {\n        a = find(a), b = find(b);\n        if (a == b) return false;\n        if (size[a] < size[b]) swap(a, b);\n        parent[b] = a;\n        size[a] += size[b];\n        return true;\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    DSU dsu(n);\n    // comps = componentes actuales, biggest = tamaño de la mayor\n    int comps = n, biggest = 1;\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        if (dsu.unite(a, b)) {\n            comps--;\n            biggest = max(biggest, dsu.size[dsu.find(a)]);\n        }\n        cout << comps << ' ' << biggest << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DSU (Union-Find con compresión de caminos y unión por tamaño)\n * Problema  : CSES 1676 - Road Construction (https://cses.fi/problemset/task/1676)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : tras cada arista: cantidad de componentes y tamaño de la componente más grande\n * Complejidad: tiempo O(m α(n)), memoria O(n)\n\"\"\"\n\n\n# Union-Find: parent[x] es el padre en el bosque y size el tamaño de cada conjunto\nclass DSU:\n    def __init__(self, n):\n        self.parent = list(range(n + 1))\n        self.size = [1] * (n + 1)\n\n    # compresión de caminos (iterativa)\n    def find(self, x):\n        root = x\n        while self.parent[root] != root:\n            root = self.parent[root]\n        while self.parent[x] != root:\n            self.parent[x], x = root, self.parent[x]\n        return root\n\n    # unión por tamaño: el conjunto pequeño se cuelga del grande\n    def unite(self, a, b):\n        a, b = self.find(a), self.find(b)\n        if a == b:\n            return False\n        if self.size[a] < self.size[b]:\n            a, b = b, a\n        self.parent[b] = a\n        self.size[a] += self.size[b]\n        return True\n\n\ndef main():\n    n, m = map(int, input().split())\n    dsu = DSU(n)\n    # comps = componentes actuales, biggest = tamaño de la mayor\n    comps, biggest = n, 1\n    out = []\n    for _ in range(m):\n        a, b = map(int, input().split())\n        if dsu.unite(a, b):\n            comps -= 1\n            biggest = max(biggest, dsu.size[dsu.find(a)])\n        out.append(\"%d %d\" % (comps, biggest))\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Diameter", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Diameter.cpp", "nombre": "Diameter", "algoritmo": "Diámetro de un árbol (dos DFS)", "problema": "CSES 1131 - Tree Diameter (https://cses.fi/problemset/task/1131)", "cses": "https://cses.fi/problemset/task/1131", "py_lento": false, "entrada": "n, luego n-1 aristas \"a b\"", "salida": "longitud del diámetro (en aristas)", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Diámetro de un árbol (dos DFS)\n * Problema  : CSES 1131 - Tree Diameter (https://cses.fi/problemset/task/1131)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : longitud del diámetro (en aristas)\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\n// árbol como lista de adyacencia; dist_dfs[v] = distancia desde la raíz de la DFS actual\nvector<vector<int>> g;\nvector<int> dist_dfs;\n\n// DFS que devuelve el nodo más lejano y su distancia\npair<int,int> dfs_far(int u, int p) {\n    // retorna {nodo más lejano, distancia a él}\n    pair<int,int> best = {u, dist_dfs[u]};\n    for (int v : g[u]) if (v != p) {\n        dist_dfs[v] = dist_dfs[u] + 1;\n        auto cand = dfs_far(v, u);\n        if (cand.second > best.second) best = cand;\n    }\n    return best;\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    g.assign(n+1, {});\n    for (int i = 0; i < n-1; ++i) {\n        int u, v;\n        cin >> u >> v;\n        g[u].push_back(v);\n        g[v].push_back(u);\n    }\n\n    dist_dfs.assign(n+1, 0);\n    // 1ª DFS: desde 1 para hallar vértice A más lejano\n    // el nodo más lejano de cualquier nodo es un extremo del diámetro\n    auto a = dfs_far(1, 0).first;\n\n    // 2ª DFS: desde A para hallar distancia máxima (diámetro)\n    dist_dfs.assign(n+1, 0);\n    // la mayor distancia desde ese extremo es el diámetro\n    auto b = dfs_far(a, 0);\n    cout << b.second << \"\\n\";\n\n    return 0;\n}\n", "python": "import sys\nfrom collections import deque\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Diámetro de un árbol (dos DFS)\n * Problema  : CSES 1131 - Tree Diameter (https://cses.fi/problemset/task/1131)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : longitud del diámetro (en aristas)\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\n# BFS desde s: devuelve el nodo más lejano y su distancia\ndef far(G, s):\n    n = len(G)\n    dist = [-1] * n\n    dist[s] = 0\n    q = deque([s])\n    while q:\n        u = q.popleft()\n        for v in G[u]:\n            if dist[v] == -1:\n                dist[v] = dist[u] + 1\n                q.append(v)\n    best = max(range(n), key=lambda v: dist[v])\n    return best, dist[best]\n\n\ndef main():\n    n = int(input())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        G[b].append(a)\n\n    # el nodo más lejano de cualquier nodo es un extremo del diámetro\n    a, _ = far(G, 1)\n    # la mayor distancia desde ese extremo es el diámetro\n    _, d = far(G, a)\n    print(d)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Djikstra", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Djikstra.cpp", "nombre": "Djikstra", "algoritmo": "Dijkstra con cola de prioridad", "problema": "CSES 1671 - Shortest Routes I (https://cses.fi/problemset/task/1671)", "cses": "https://cses.fi/problemset/task/1671", "py_lento": false, "entrada": "n m, luego m aristas dirigidas \"a b c\" (peso c)", "salida": "la distancia mínima de 1 a cada nodo", "complejidad": "tiempo O((n + m) log n), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Dijkstra con cola de prioridad\n * Problema  : CSES 1671 - Shortest Routes I (https://cses.fi/problemset/task/1671)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (peso c)\n * Salida    : la distancia mínima de 1 a cada nodo\n * Complejidad: tiempo O((n + m) log n), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int, ll>>> G(n + 1);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        G[a].push_back({b, c});\n    }\n\n    // dist[v] = mejor distancia conocida desde 1\n    vector<ll> dist(n + 1, INF);\n    // min-heap de {distancia, nodo}\n    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;\n    dist[1] = 0;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top();\n        pq.pop();\n        // entrada vieja del heap: ya hay una distancia mejor\n        if (d > dist[u]) continue;\n        for (auto [v, w] : G[u]) {\n            // relajación de la arista u -> v\n            if (dist[u] + w < dist[v]) {\n                dist[v] = dist[u] + w;\n                pq.push({dist[v], v});\n            }\n        }\n    }\n\n    for (int i = 1; i <= n; i++) cout << dist[i] << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport heapq\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Dijkstra con cola de prioridad\n * Problema  : CSES 1671 - Shortest Routes I (https://cses.fi/problemset/task/1671)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (peso c)\n * Salida    : la distancia mínima de 1 a cada nodo\n * Complejidad: tiempo O((n + m) log n), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b, c = map(int, input().split())\n        G[a].append((b, c))\n\n    # dist[v] = mejor distancia conocida desde 1\n    dist = [INF] * (n + 1)\n    dist[1] = 0\n    # min-heap de (distancia, nodo)\n    pq = [(0, 1)]\n    while pq:\n        d, u = heapq.heappop(pq)\n        # entrada vieja del heap: ya hay una distancia mejor\n        if d > dist[u]:\n            continue\n        for v, w in G[u]:\n            # relajación de la arista u -> v\n            if d + w < dist[v]:\n                dist[v] = d + w\n                heapq.heappush(pq, (dist[v], v))\n    print(*dist[1:])\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-EulerianCycle", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/EulerianCycle.cpp", "nombre": "EulerianCycle", "algoritmo": "Ciclo euleriano (Hierholzer, grafo no dirigido)", "problema": "CSES 1691 - Mail Delivery (https://cses.fi/problemset/task/1691)", "cses": "https://cses.fi/problemset/task/1691", "py_lento": false, "entrada": "n m, luego m aristas \"a b\"", "salida": "un ciclo euleriano desde el nodo 1, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Ciclo euleriano (Hierholzer, grafo no dirigido)\n * Problema  : CSES 1691 - Mail Delivery (https://cses.fi/problemset/task/1691)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : un ciclo euleriano desde el nodo 1, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// cada arista guarda su destino y un id para marcarla como usada\nstruct Edge{\n    ll to, id;\n};\n\nint main(){\n    fastio;\n\n    ll n, m; cin >> n >> m;\n    // lista de adyacencia; used[id] indica si la arista ya se recorrió\n    vector<vector<Edge>> ady(n, vector<Edge>());\n    vector<bool> used(m, false);\n\n    for(int i = 0; i < m; i++){\n        ll u, v; cin >> u >> v;\n        u--; v--;\n        ady[u].push_back({v, i});\n        ady[v].push_back({u, i});\n    }\n\n    // cycle = circuito resultante (se arma al desapilar)\n    vector<ll> cycle;\n    vector<bool> vis(n, false);\n    // primero se verifica que todos los nodos con aristas sean alcanzables desde 0\n    stack<ll> ss; ss.push(0);\n\n    while (!ss.empty())\n    {\n        ll v = ss.top(); ss.pop();\n        for(auto [u, i]: ady[v]){\n            if(!vis[u]) ss.push(u);\n        }\n        vis[v] = true;\n    }\n\n    // condición de Euler: todos los grados pares y un solo componente conexo\n    bool agg = true;\n    for(int i = 0; i < n; i++){\n        if(ady[i].size() == 0) vis[i] = true;\n        else if(ady[i].size() & 1) agg = false;\n\n        if(vis[i] == false) agg = false;\n    }\n    \n    // si no se cumple la condición no existe el ciclo\n    if(!agg){\n        cout << \"IMPOSSIBLE\" << \"\\n\";\n        return 0;\n    }\n\n    ss.push(0);\n    // Hierholzer iterativo: se avanza por aristas libres y se desapila al quedar sin salida\n    while (!ss.empty()){\n        ll v = ss.top();\n        // se descartan aristas ya usadas desde el otro extremo\n        while (!ady[v].empty() && used[ady[v].back().id]) ady[v].pop_back();\n        \n        if(!ady[v].empty()){\n            auto edge = ady[v].back(); ady[v].pop_back();\n            used[edge.id] = true;\n            ss.push(edge.to);\n        }\n        else{\n            // nodo sin salidas: entra al circuito (queda en orden inverso, válido por ser un ciclo)\n            cycle.push_back(v);\n            ss.pop();\n        }\n    }\n    \n    for(auto &x: cycle) cout << x+1 << \" \";\n    cout << \"\\n\";\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Ciclo euleriano (Hierholzer, grafo no dirigido)\n * Problema  : CSES 1691 - Mail Delivery (https://cses.fi/problemset/task/1691)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : un ciclo euleriano desde el nodo 1, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    # cada arista guarda su destino y un id para marcarla como usada\n    adj = [[] for _ in range(n + 1)]\n    deg = [0] * (n + 1)\n    for i in range(m):\n        a, b = map(int, input().split())\n        adj[a].append((b, i))\n        adj[b].append((a, i))\n        deg[a] += 1\n        deg[b] += 1\n\n    # condición de Euler: todos los grados pares\n    if any(d % 2 for d in deg):\n        print(\"IMPOSSIBLE\")\n        return\n\n    # Hierholzer iterativo: se avanza por aristas libres y se desapila al quedar sin salida\n    used = [False] * m\n    ptr = [0] * (n + 1)\n    st = [1]\n    cycle = []\n    while st:\n        v = st[-1]\n        # se descartan aristas ya usadas desde el otro extremo\n        while ptr[v] < len(adj[v]) and used[adj[v][ptr[v]][1]]:\n            ptr[v] += 1\n        if ptr[v] == len(adj[v]):\n            # nodo sin salidas: entra al circuito\n            cycle.append(v)\n            st.pop()\n        else:\n            u, i = adj[v][ptr[v]]\n            used[i] = True\n            st.append(u)\n\n    # si no se usaron las m aristas, el grafo no es conexo\n    if len(cycle) != m + 1:\n        print(\"IMPOSSIBLE\")\n    else:\n        print(*cycle)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-FloydWarshall", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/FloydWarshall.cpp", "nombre": "FloydWarshall", "algoritmo": "Floyd-Warshall (distancias entre todos los pares)", "problema": "CSES 1672 - Shortest Routes II (https://cses.fi/problemset/task/1672)", "cses": "https://cses.fi/problemset/task/1672", "py_lento": true, "entrada": "n m q, luego m aristas no dirigidas \"a b c\" y q consultas \"a b\"", "salida": "la distancia mínima de cada consulta, o -1 si no hay camino", "complejidad": "tiempo O(n^3 + q), memoria O(n^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Floyd-Warshall (distancias entre todos los pares)\n * Problema  : CSES 1672 - Shortest Routes II (https://cses.fi/problemset/task/1672)\n * Entrada   : n m q, luego m aristas no dirigidas \"a b c\" y q consultas \"a b\"\n * Salida    : la distancia mínima de cada consulta, o -1 si no hay camino\n * Complejidad: tiempo O(n^3 + q), memoria O(n^2)\n */\n\nint main() {\n    fastio;\n    int n, m, q;\n    cin >> n >> m >> q;\n    // inf = INF / 4 para que dist[i][k] + dist[k][j] no desborde\n    const ll inf = INF / 4;  // evita overflow al sumar\n    vector<vector<ll>> dist(n + 1, vector<ll>(n + 1, inf));\n    for (int i = 1; i <= n; i++) dist[i][i] = 0;\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        dist[a][b] = min(dist[a][b], c);\n        dist[b][a] = min(dist[b][a], c);\n    }\n\n    // k = nodo intermedio permitido: se prueba pasar por k para cada par (i, j)\n    for (int k = 1; k <= n; k++)\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= n; j++)\n                if (dist[i][k] + dist[k][j] < dist[i][j])\n                    dist[i][j] = dist[i][k] + dist[k][j];\n\n    while (q--) {\n        int a, b;\n        cin >> a >> b;\n        cout << (dist[a][b] >= inf ? -1 : dist[a][b]) << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Floyd-Warshall (distancias entre todos los pares)\n * Problema  : CSES 1672 - Shortest Routes II (https://cses.fi/problemset/task/1672)\n * Entrada   : n m q, luego m aristas no dirigidas \"a b c\" y q consultas \"a b\"\n * Salida    : la distancia mínima de cada consulta, o -1 si no hay camino\n * Complejidad: tiempo O(n^3 + q), memoria O(n^2)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, m, q = int(data[0]), int(data[1]), int(data[2])\n    # BIG hace de infinito sin desbordar al sumar\n    BIG = 10 ** 18\n    dist = [[BIG] * n for _ in range(n)]\n    for i in range(n):\n        dist[i][i] = 0\n    pos = 3\n    for _ in range(m):\n        a, b, c = int(data[pos]) - 1, int(data[pos + 1]) - 1, int(data[pos + 2])\n        pos += 3\n        if c < dist[a][b]:\n            dist[a][b] = dist[b][a] = c\n\n    # k = nodo intermedio permitido: se prueba pasar por k para cada par (i, j)\n    for k in range(n):\n        dk = dist[k]\n        for i in range(n):\n            di = dist[i]\n            dik = di[k]\n            if dik == BIG:\n                continue\n            # una fila completa a la vez: di[j] = min(di[j], dik + dk[j])\n            dist[i] = [x if x < dik + y else dik + y for x, y in zip(di, dk)]\n\n    out = []\n    for _ in range(q):\n        a, b = int(data[pos]) - 1, int(data[pos + 1]) - 1\n        pos += 2\n        out.append(-1 if dist[a][b] == BIG else dist[a][b])\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-HierholzerDirected", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/HierholzerDirected.cpp", "nombre": "HierholzerDirected", "algoritmo": "Camino euleriano en grafo dirigido (Hierholzer)", "problema": "CSES 1693 - Teleporters Path (https://cses.fi/problemset/task/1693)", "cses": "https://cses.fi/problemset/task/1693", "py_lento": false, "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "un camino de 1 a n que usa cada arista exactamente una vez, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Camino euleriano en grafo dirigido (Hierholzer)\n * Problema  : CSES 1693 - Teleporters Path (https://cses.fi/problemset/task/1693)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : un camino de 1 a n que usa cada arista exactamente una vez, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> G(n + 1);\n    // grados de entrada y salida de cada nodo\n    vector<int> in(n + 1, 0), out(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        out[a]++, in[b]++;\n    }\n\n    // condiciones del camino de 1 a n\n    // el camino de 1 a n existe si out(1) = in(1) + 1, in(n) = out(n) + 1 y los demás grados coinciden\n    bool ok = out[1] - in[1] == 1 && in[n] - out[n] == 1;\n    for (int i = 2; i < n; i++) ok &= in[i] == out[i];\n    if (!ok) {\n        cout << \"IMPOSSIBLE\\n\";\n        return 0;\n    }\n\n    // Hierholzer iterativo\n    vector<int> path, st = {1};\n    while (!st.empty()) {\n        int u = st.back();\n        if (G[u].empty()) {\n            path.push_back(u);\n            st.pop_back();\n        }\n        else {\n            int v = G[u].back();\n            G[u].pop_back();\n            st.push_back(v);\n        }\n    }\n    reverse(all(path));\n\n    // si no se usaron las m aristas, el grafo no es conexo\n    if ((int)path.size() != m + 1 || path[0] != 1 || path.back() != n) {\n        cout << \"IMPOSSIBLE\\n\";\n        return 0;\n    }\n    for (int v : path) cout << v << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Camino euleriano en grafo dirigido (Hierholzer)\n * Problema  : CSES 1693 - Teleporters Path (https://cses.fi/problemset/task/1693)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : un camino de 1 a n que usa cada arista exactamente una vez, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    # grados de entrada y salida de cada nodo\n    indeg = [0] * (n + 1)\n    outdeg = [0] * (n + 1)\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        outdeg[a] += 1\n        indeg[b] += 1\n\n    # el camino de 1 a n existe si out(1) = in(1) + 1, in(n) = out(n) + 1 y los demás grados coinciden\n    ok = outdeg[1] - indeg[1] == 1 and indeg[n] - outdeg[n] == 1\n    ok = ok and all(indeg[i] == outdeg[i] for i in range(2, n))\n    if not ok:\n        print(\"IMPOSSIBLE\")\n        return\n\n    # Hierholzer iterativo\n    path = []\n    st = [1]\n    while st:\n        u = st[-1]\n        if G[u]:\n            st.append(G[u].pop())\n        else:\n            path.append(u)\n            st.pop()\n    path.reverse()\n\n    # si no se usaron las m aristas, el grafo no es conexo\n    if len(path) != m + 1 or path[0] != 1 or path[-1] != n:\n        print(\"IMPOSSIBLE\")\n    else:\n        print(*path)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Kosaraju", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Kosaraju.cpp", "nombre": "Kosaraju", "algoritmo": "Kosaraju (componentes fuertemente conexas)", "problema": "CSES 1683 - Planets and Kingdoms (https://cses.fi/problemset/task/1683)", "cses": "https://cses.fi/problemset/task/1683", "py_lento": false, "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "cantidad de reinos (SCC) y el reino de cada nodo", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Kosaraju (componentes fuertemente conexas)\n * Problema  : CSES 1683 - Planets and Kingdoms (https://cses.fi/problemset/task/1683)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : cantidad de reinos (SCC) y el reino de cada nodo\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// G = grafo y GT = grafo con las aristas invertidas\nvector<vector<int>> G, GT;\nvector<int> order, comp;\nvector<bool> visited;\n\n// primera pasada: se guarda el orden de salida de cada nodo\nvoid dfs1(int u) {\n    visited[u] = true;\n    for (int v : G[u])\n        if (!visited[v]) dfs1(v);\n    order.push_back(u);  // orden de salida\n}\n\n// segunda pasada sobre GT: todo lo alcanzado forma una SCC\nvoid dfs2(int u, int c) {\n    comp[u] = c;\n    for (int v : GT[u])\n        if (comp[v] == 0) dfs2(v, c);\n}\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    G.assign(n + 1, {});\n    GT.assign(n + 1, {});\n    visited.assign(n + 1, false);\n    comp.assign(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        GT[b].push_back(a);\n    }\n\n    for (int i = 1; i <= n; i++)\n        if (!visited[i]) dfs1(i);\n\n    // segunda pasada sobre el grafo transpuesto en orden de salida inverso\n    int c = 0;\n    // se procesan los nodos en orden de salida decreciente\n    for (int i = n - 1; i >= 0; i--)\n        if (comp[order[i]] == 0) dfs2(order[i], ++c);\n\n    cout << c << \"\\n\";\n    for (int i = 1; i <= n; i++) cout << comp[i] << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Kosaraju (componentes fuertemente conexas)\n * Problema  : CSES 1683 - Planets and Kingdoms (https://cses.fi/problemset/task/1683)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : cantidad de reinos (SCC) y el reino de cada nodo\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    # G = grafo y GT = grafo con las aristas invertidas\n    G = [[] for _ in range(n + 1)]\n    GT = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        GT[b].append(a)\n\n    # primera pasada (DFS iterativo): se guarda el orden de salida de cada nodo\n    visited = [False] * (n + 1)\n    order = []\n    for s in range(1, n + 1):\n        if visited[s]:\n            continue\n        visited[s] = True\n        st = [(s, 0)]\n        while st:\n            u, i = st[-1]\n            if i < len(G[u]):\n                st[-1] = (u, i + 1)\n                v = G[u][i]\n                if not visited[v]:\n                    visited[v] = True\n                    st.append((v, 0))\n            else:\n                order.append(u)\n                st.pop()\n\n    # segunda pasada sobre GT en orden de salida decreciente: todo lo alcanzado forma una SCC\n    comp = [0] * (n + 1)\n    c = 0\n    for s in reversed(order):\n        if comp[s]:\n            continue\n        c += 1\n        comp[s] = c\n        st = [s]\n        while st:\n            u = st.pop()\n            for v in GT[u]:\n                if not comp[v]:\n                    comp[v] = c\n                    st.append(v)\n\n    print(c)\n    print(*comp[1:])\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Tarjan", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Tarjan.cpp", "nombre": "Tarjan", "algoritmo": "Componentes fuertemente conexas (Tarjan)", "problema": "CSES 1682 - Flight Routes Check (https://cses.fi/problemset/task/1682)", "cses": "https://cses.fi/problemset/task/1682", "py_lento": false, "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "YES si todo nodo llega a todo nodo; si no, NO y un par \"a b\" sin camino de a hacia b", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Componentes fuertemente conexas (Tarjan)\n * Problema  : CSES 1682 - Flight Routes Check (https://cses.fi/problemset/task/1682)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : YES si todo nodo llega a todo nodo; si no, NO y un par \"a b\" sin camino de a hacia b\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// Tarjan: componentes fuertemente conexas (SCC) con una sola DFS\nstruct Tarjan{\n    // tempo = contador de descubrimiento\n    ll tempo = 0;\n    vector<vector<ll>> ady;\n    // discovered[v] = momento en que se visitó v, low[v] = menor tiempo alcanzable desde su subárbol\n    vector<ll> discovered;\n    vector<ll> low;\n    // pila de nodos de la SCC actual; in_stack evita usar aristas hacia SCC ya cerradas\n    stack<ll> ss;\n    vector<bool> in_stack;\n    // SCC = lista de componentes, SCC_index[v] = componente de v\n    vector<vector<ll>> SCC;\n    vector<ll> SCC_index;\n \n    Tarjan(ll n){\n        ady.assign(n, vector<ll>());\n        discovered.assign(n, -1);\n        low.assign(n, -1);\n        in_stack.assign(n, false);\n        SCC_index.assign(n, -1);\n    }\n \n    void add_edge(ll u, ll v){\n        ady[u].push_back(v);\n    }\n \n    // DFS de Tarjan\n    void DFS(ll v){\n        discovered[v] = tempo;\n        low[v] = tempo;\n        tempo++;\n \n        ss.push(v);\n        in_stack[v] = true;\n \n        for(auto u: ady[v]){\n            // arista de árbol: se baja y se actualiza low con el hijo\n            if(discovered[u] == -1){\n                DFS(u);\n                low[v] = min(low[v], low[u]);\n            }\n            // arista hacia atrás dentro de la misma componente\n            else if(in_stack[u]){\n                low[v] = min(low[v], discovered[u]);\n            }\n        }\n \n        // v es la raíz de una SCC: se desapila hasta v\n        if(low[v] == discovered[v]){\n            vector<ll> newSCC;\n            ll w;\n            do {\n                w = ss.top(); ss.pop();\n                SCC_index[w] = SCC.size();\n                newSCC.push_back(w);\n                in_stack[w] = false;\n            } while (w != v);\n            SCC.push_back(newSCC);\n        }\n    }\n};\n \nint main(){\n    fastio;\n    \n    ll n, m; cin >> n >> m;\n    Tarjan tarjan(n);\n \n    for(int i = 0; i < m; i++){\n        ll u, v; cin >> u >> v;\n        u--; v--;\n        tarjan.add_edge(u, v);\n    }\n \n    for(int i = 0; i < n; i++){\n        if(tarjan.discovered[i] == -1){\n            tarjan.DFS(i);\n        }\n    }\n \n    // una sola SCC = fuertemente conexo\n    if(tarjan.SCC.size() == 1){\n        cout << \"YES\" << \"\\n\";\n    }\n    else{\n        // hay que mostrar un par (a, b) tal que no se pueda ir de a a b\n        cout << \"NO\" << \"\\n\";\n        for(int i = 0; i < n; i++){\n            for(auto j: tarjan.ady[i]){\n                // una arista i->j entre componentes distintas: no existe camino de j a i\n                if(tarjan.SCC_index[i] != tarjan.SCC_index[j]){\n                    cout << j+1 << \" \" << i+1 << \"\\n\";\n                    return 0;\n                }\n            }\n        }\n \n        for(int i = 0; i < n; i++){\n            // si no, algún nodo no está en la componente 0: no se llega a ella desde ahí\n            if(tarjan.SCC_index[i] != 0){\n                cout << i+1 << \" \" << tarjan.SCC.front().front()+1 << \"\\n\";\n                return 0; \n            }\n        }\n    }\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Componentes fuertemente conexas (Tarjan)\n * Problema  : CSES 1682 - Flight Routes Check (https://cses.fi/problemset/task/1682)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : YES si todo nodo llega a todo nodo; si no, NO y un par \"a b\" sin camino de a hacia b\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\n# Tarjan: componentes fuertemente conexas (SCC) con una sola DFS (iterativa)\ndef tarjan(G, n):\n    # discovered[v] = momento en que se visitó v, low[v] = menor tiempo alcanzable desde su subárbol\n    discovered = [-1] * (n + 1)\n    low = [0] * (n + 1)\n    # pila de nodos de la SCC actual; in_stack evita usar aristas hacia SCC ya cerradas\n    in_stack = [False] * (n + 1)\n    ss = []\n    # scc_index[v] = componente de v\n    scc_index = [-1] * (n + 1)\n    tempo = 0\n    count = 0\n    for s in range(1, n + 1):\n        if discovered[s] != -1:\n            continue\n        discovered[s] = low[s] = tempo\n        tempo += 1\n        ss.append(s)\n        in_stack[s] = True\n        call = [(s, 0)]\n        while call:\n            v, i = call[-1]\n            if i < len(G[v]):\n                call[-1] = (v, i + 1)\n                u = G[v][i]\n                if discovered[u] == -1:\n                    # arista de árbol: se baja\n                    discovered[u] = low[u] = tempo\n                    tempo += 1\n                    ss.append(u)\n                    in_stack[u] = True\n                    call.append((u, 0))\n                elif in_stack[u]:\n                    # arista hacia atrás dentro de la misma componente\n                    low[v] = min(low[v], discovered[u])\n            else:\n                call.pop()\n                if call:\n                    p = call[-1][0]\n                    low[p] = min(low[p], low[v])\n                # v es la raíz de una SCC: se desapila hasta v\n                if low[v] == discovered[v]:\n                    while True:\n                        x = ss.pop()\n                        in_stack[x] = False\n                        scc_index[x] = count\n                        if x == v:\n                            break\n                    count += 1\n    return count, scc_index\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    edges = []\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        edges.append((a, b))\n\n    count, idx = tarjan(G, n)\n    # una sola SCC = fuertemente conexo\n    if count == 1:\n        print(\"YES\")\n        return\n    # hay que mostrar un par (a, b) tal que no se pueda ir de a a b\n    print(\"NO\")\n    # una arista i->j entre componentes distintas: no existe camino de j a i\n    for a, b in edges:\n        if idx[a] != idx[b]:\n            print(b, a)\n            return\n    # si no hay aristas entre componentes, dos nodos de componentes distintas sirven\n    for v in range(2, n + 1):\n        if idx[v] != idx[1]:\n            print(1, v)\n            return\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-TopologicalSort", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/TopologicalSort.cpp", "nombre": "TopologicalSort", "algoritmo": "Orden topológico (Kahn)", "problema": "CSES 1679 - Course Schedule (https://cses.fi/problemset/task/1679)", "cses": "https://cses.fi/problemset/task/1679", "py_lento": false, "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "un orden topológico, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Orden topológico (Kahn)\n * Problema  : CSES 1679 - Course Schedule (https://cses.fi/problemset/task/1679)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : un orden topológico, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    ll n, m;\n    cin >> n >> m;\n\n    vector<vector<ll>> G(n);\n    // indeg[v] = aristas que entran a v\n    vector<ll> indeg(n, 0);\n    for (ll i = 0; i < m; ++i) {\n        ll u, v;\n        cin >> u >> v;\n        u--, v--;\n        G[u].push_back(v);\n        indeg[v]++;\n    }\n\n    // Kahn: se procesan primero los nodos sin aristas entrantes\n    // nodos sin dependencias pendientes\n    queue<ll> q;\n    for (ll i = 0; i < n; ++i)\n        if (indeg[i] == 0) q.push(i);\n\n    vector<ll> order;\n    while (!q.empty()) {\n        ll v = q.front(); q.pop();\n        order.push_back(v);\n        for (ll u : G[v]) {\n            // al sacar v se \"borran\" sus aristas; u queda libre al llegar a 0\n            if (--indeg[u] == 0) q.push(u);\n        }\n    }\n\n    // si no entraron todos los nodos hay un ciclo\n    if ((ll)order.size() < n) {\n        cout << \"IMPOSSIBLE\\n\";\n    } else {\n        for (ll v : order) cout << v + 1 << ' ';\n        cout << '\\n';\n    }\n    return 0;\n}\n", "python": "import sys\nfrom collections import deque\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Orden topológico (Kahn)\n * Problema  : CSES 1679 - Course Schedule (https://cses.fi/problemset/task/1679)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : un orden topológico, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    # indeg[v] = aristas que entran a v\n    indeg = [0] * (n + 1)\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        indeg[b] += 1\n\n    # nodos sin dependencias pendientes\n    q = deque(v for v in range(1, n + 1) if indeg[v] == 0)\n    order = []\n    while q:\n        v = q.popleft()\n        order.append(v)\n        for u in G[v]:\n            # al sacar v se \"borran\" sus aristas; u queda libre al llegar a 0\n            indeg[u] -= 1\n            if indeg[u] == 0:\n                q.append(u)\n\n    # si no salieron todos, hay un ciclo\n    print(*order) if len(order) == n else print(\"IMPOSSIBLE\")\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-MST-Kruskal", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/MST", "archivo": "Graphs/Algorithms/MST/Kruskal.cpp", "nombre": "Kruskal", "algoritmo": "Kruskal (árbol de expansión mínima con DSU)", "problema": "CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)", "cses": "https://cses.fi/problemset/task/1675", "py_lento": false, "entrada": "n m, luego m aristas \"a b c\" (costo c)", "salida": "el costo mínimo para conectar todo, o IMPOSSIBLE", "complejidad": "tiempo O(m log m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Kruskal (árbol de expansión mínima con DSU)\n * Problema  : CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)\n * Entrada   : n m, luego m aristas \"a b c\" (costo c)\n * Salida    : el costo mínimo para conectar todo, o IMPOSSIBLE\n * Complejidad: tiempo O(m log m), memoria O(n + m)\n */\n\n// DSU para detectar si una arista une componentes distintas\nstruct DSU {\n    vector<int> parent, size;\n\n    DSU(int n) {\n        parent.resize(n + 1);\n        size.assign(n + 1, 1);\n        iota(all(parent), 0);\n    }\n\n    int find(int x) {\n        return parent[x] == x ? x : parent[x] = find(parent[x]);\n    }\n\n    bool unite(int a, int b) {\n        a = find(a), b = find(b);\n        if (a == b) return false;\n        if (size[a] < size[b]) swap(a, b);\n        parent[b] = a;\n        size[a] += size[b];\n        return true;\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<array<ll, 3>> edges(m);  // {peso, a, b}\n    for (auto &e : edges) cin >> e[1] >> e[2] >> e[0];\n    // se procesan las aristas de menor a mayor peso\n    sort(all(edges));\n\n    DSU dsu(n);\n    ll total = 0;\n    int used = 0;\n    for (auto &[w, a, b] : edges) {\n        // la arista se usa solo si no forma ciclo\n        if (dsu.unite(a, b)) {\n            total += w;\n            used++;\n        }\n    }\n\n    // un árbol de expansión tiene n-1 aristas; si faltan, el grafo no es conexo\n    if (used != n - 1) cout << \"IMPOSSIBLE\\n\";\n    else cout << total << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Kruskal (árbol de expansión mínima con DSU)\n * Problema  : CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)\n * Entrada   : n m, luego m aristas \"a b c\" (costo c)\n * Salida    : el costo mínimo para conectar todo, o IMPOSSIBLE\n * Complejidad: tiempo O(m log m), memoria O(n + m)\n\"\"\"\n\n\n# DSU para detectar si una arista une componentes distintas\nclass DSU:\n    def __init__(self, n):\n        self.parent = list(range(n + 1))\n        self.size = [1] * (n + 1)\n\n    def find(self, x):\n        root = x\n        while self.parent[root] != root:\n            root = self.parent[root]\n        while self.parent[x] != root:\n            self.parent[x], x = root, self.parent[x]\n        return root\n\n    def unite(self, a, b):\n        a, b = self.find(a), self.find(b)\n        if a == b:\n            return False\n        if self.size[a] < self.size[b]:\n            a, b = b, a\n        self.parent[b] = a\n        self.size[a] += self.size[b]\n        return True\n\n\ndef main():\n    n, m = map(int, input().split())\n    edges = []\n    for _ in range(m):\n        a, b, c = map(int, input().split())\n        edges.append((c, a, b))\n    # se procesan las aristas de menor a mayor peso\n    edges.sort()\n\n    dsu = DSU(n)\n    total = used = 0\n    for w, a, b in edges:\n        # la arista se usa solo si no forma ciclo\n        if dsu.unite(a, b):\n            total += w\n            used += 1\n    # un árbol de expansión tiene n-1 aristas; si faltan, el grafo no es conexo\n    print(total if used == n - 1 else \"IMPOSSIBLE\")\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-MST-Prim", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/MST", "archivo": "Graphs/Algorithms/MST/Prim.cpp", "nombre": "Prim", "algoritmo": "Prim (árbol de expansión mínima con cola de prioridad)", "problema": "CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)", "cses": "https://cses.fi/problemset/task/1675", "py_lento": false, "entrada": "n m, luego m aristas \"a b c\" (costo c)", "salida": "el costo mínimo para conectar todo, o IMPOSSIBLE", "complejidad": "tiempo O(m log n), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Prim (árbol de expansión mínima con cola de prioridad)\n * Problema  : CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)\n * Entrada   : n m, luego m aristas \"a b c\" (costo c)\n * Salida    : el costo mínimo para conectar todo, o IMPOSSIBLE\n * Complejidad: tiempo O(m log n), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int, ll>>> G(n + 1);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        G[a].push_back({b, c});\n        G[b].push_back({a, c});\n    }\n\n    vector<bool> inTree(n + 1, false);\n    // min-heap de {peso de la arista, nodo} para crecer el árbol desde el nodo 1\n    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;\n    pq.push({0, 1});\n    ll total = 0;\n    int used = 0;\n    while (!pq.empty()) {\n        auto [w, u] = pq.top();\n        pq.pop();\n        // el nodo ya está en el árbol\n        if (inTree[u]) continue;\n        inTree[u] = true;\n        // se agrega el nodo con la arista más barata que lo conecta\n        total += w;\n        used++;\n        for (auto [v, c] : G[u])\n            if (!inTree[v]) pq.push({c, v});\n    }\n\n    // si no entraron todos, el grafo no es conexo\n    if (used != n) cout << \"IMPOSSIBLE\\n\";\n    else cout << total << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport heapq\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Prim (árbol de expansión mínima con cola de prioridad)\n * Problema  : CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)\n * Entrada   : n m, luego m aristas \"a b c\" (costo c)\n * Salida    : el costo mínimo para conectar todo, o IMPOSSIBLE\n * Complejidad: tiempo O(m log n), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b, c = map(int, input().split())\n        G[a].append((b, c))\n        G[b].append((a, c))\n\n    # min-heap de (peso de la arista, nodo) para crecer el árbol desde el nodo 1\n    in_tree = [False] * (n + 1)\n    pq = [(0, 1)]\n    total = used = 0\n    while pq:\n        w, u = heapq.heappop(pq)\n        # el nodo ya está en el árbol\n        if in_tree[u]:\n            continue\n        # se agrega el nodo con la arista más barata que lo conecta\n        in_tree[u] = True\n        total += w\n        used += 1\n        for v, c in G[u]:\n            if not in_tree[v]:\n                heapq.heappush(pq, (c, v))\n    # si no entraron todos, el grafo no es conexo\n    print(total if used == n else \"IMPOSSIBLE\")\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Miscellaneous-2-SAT", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Miscellaneous", "archivo": "Graphs/Algorithms/Miscellaneous/2-SAT.cpp", "nombre": "2-SAT", "algoritmo": "2-SAT con componentes fuertemente conexas (Tarjan)", "problema": "CSES 1684 - Giant Pizza (https://cses.fi/problemset/task/1684)", "cses": "https://cses.fi/problemset/task/1684", "py_lento": false, "entrada": "n m, luego n líneas \"+ a - b\" (deseos de cada persona sobre m ingredientes)", "salida": "una asignación \"+/-\" por ingrediente, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : 2-SAT con componentes fuertemente conexas (Tarjan)\n * Problema  : CSES 1684 - Giant Pizza (https://cses.fi/problemset/task/1684)\n * Entrada   : n m, luego n líneas \"+ a - b\" (deseos de cada persona sobre m ingredientes)\n * Salida    : una asignación \"+/-\" por ingrediente, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// Tarjan: componentes fuertemente conexas (SCC) con una sola DFS\nstruct Tarjan{\n    // tempo = contador de descubrimiento\n    ll tempo = 0;\n    vector<vector<ll>> ady;\n    // discovered[v] = momento en que se visitó v, low[v] = menor tiempo alcanzable desde su subárbol\n    vector<ll> discovered;\n    vector<ll> low;\n    // pila de nodos de la SCC actual; in_stack evita usar aristas hacia SCC ya cerradas\n    stack<ll> ss;\n    vector<bool> in_stack;\n    // SCC = lista de componentes, SCC_index[v] = componente de v\n    vector<vector<ll>> SCC;\n    vector<ll> SCC_index;\n \n    Tarjan(ll n){\n        ady.assign(n, vector<ll>());\n        discovered.assign(n, -1);\n        low.assign(n, -1);\n        in_stack.assign(n, false);\n        SCC_index.assign(n, -1);\n    }\n \n    void add_edge(ll u, ll v){\n        ady[u].push_back(v);\n    }\n \n    // DFS de Tarjan\n    void DFS(ll v){\n        discovered[v] = tempo;\n        low[v] = tempo;\n        tempo++;\n \n        ss.push(v);\n        in_stack[v] = true;\n \n        for(auto u: ady[v]){\n            // arista de árbol: se baja y se actualiza low con el hijo\n            if(discovered[u] == -1){\n                DFS(u);\n                low[v] = min(low[v], low[u]);\n            }\n            // arista hacia atrás dentro de la misma componente\n            else if(in_stack[u]){\n                low[v] = min(low[v], discovered[u]);\n            }\n        }\n \n        // v es la raíz de una SCC: se desapila hasta v\n        if(low[v] == discovered[v]){\n            vector<ll> newSCC;\n            ll w;\n            do {\n                w = ss.top(); ss.pop();\n                SCC_index[w] = SCC.size();\n                newSCC.push_back(w);\n                in_stack[w] = false;\n            } while (w != v);\n            SCC.push_back(newSCC);\n        }\n    }\n};\n \nint main(){\n    fastio;\n    \n    ll n, m; cin >> n >> m;\n    // 2-SAT: n cláusulas y m variables; el nodo x es \"x verdadero\" y x+m es su negación\n    Tarjan tarjan(2*m+1);\n \n    // negación de un literal\n    auto negation = [&](ll u){\n        if(u > m) return u - m;\n        else return u + m;\n    };\n \n    for(int i = 0; i < n; i++){\n        // cada cláusula (a ∨ b) agrega las implicaciones ¬a → b y ¬b → a\n        char type1, type2; ll u, v; \n        cin >> type1 >> u >> type2  >> v;\n        // se lee \"+ x\" como literal x; se guarda su negación para armar las implicaciones\n        if(type1 == '+') u = negation(u);\n        if(type2 == '+') v = negation(v);\n \n        tarjan.add_edge(negation(u), v);\n        tarjan.add_edge(negation(v), u);\n    }\n \n    // SCC sobre el grafo de implicaciones\n    for(int i = 1; i < 2*m+1; i++){\n        if(tarjan.discovered[i] == -1){\n            tarjan.DFS(i);\n        }\n    }\n \n    // si x y ¬x están en la misma SCC no hay solución\n    bool agg = true;\n    for(int i = 1; i <= m; i++){\n        if(tarjan.SCC_index[i] == tarjan.SCC_index[negation(i)]){\n            agg = false;\n            break;\n        }\n    }\n \n    if(!agg){\n        cout << \"IMPOSSIBLE\" << \"\\n\";\n    }\n    else{\n        // x es verdadera si su SCC sale después que la de ¬x en el orden topológico (Tarjan numera al revés)\n        string res = \"\";\n        for(int i = 1; i <= m; i++){\n            if(tarjan.SCC_index[i] < tarjan.SCC_index[negation(i)]) res += '-';\n            else res += '+';\n        }\n \n        for(auto c: res) cout << c << \" \";\n        cout << \"\\n\";\n    }\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : 2-SAT con componentes fuertemente conexas (Tarjan)\n * Problema  : CSES 1684 - Giant Pizza (https://cses.fi/problemset/task/1684)\n * Entrada   : n m, luego n líneas \"+ a - b\" (deseos de cada persona sobre m ingredientes)\n * Salida    : una asignación \"+/-\" por ingrediente, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\n# Tarjan: componentes fuertemente conexas (SCC) con una sola DFS (iterativa)\ndef tarjan(G, n):\n    # discovered[v] = momento en que se visitó v, low[v] = menor tiempo alcanzable desde su subárbol\n    discovered = [-1] * (n + 1)\n    low = [0] * (n + 1)\n    # pila de nodos de la SCC actual; in_stack evita usar aristas hacia SCC ya cerradas\n    in_stack = [False] * (n + 1)\n    ss = []\n    # scc_index[v] = componente de v\n    scc_index = [-1] * (n + 1)\n    tempo = 0\n    count = 0\n    for s in range(1, n + 1):\n        if discovered[s] != -1:\n            continue\n        discovered[s] = low[s] = tempo\n        tempo += 1\n        ss.append(s)\n        in_stack[s] = True\n        call = [(s, 0)]\n        while call:\n            v, i = call[-1]\n            if i < len(G[v]):\n                call[-1] = (v, i + 1)\n                u = G[v][i]\n                if discovered[u] == -1:\n                    # arista de árbol: se baja\n                    discovered[u] = low[u] = tempo\n                    tempo += 1\n                    ss.append(u)\n                    in_stack[u] = True\n                    call.append((u, 0))\n                elif in_stack[u]:\n                    # arista hacia atrás dentro de la misma componente\n                    low[v] = min(low[v], discovered[u])\n            else:\n                call.pop()\n                if call:\n                    p = call[-1][0]\n                    low[p] = min(low[p], low[v])\n                # v es la raíz de una SCC: se desapila hasta v\n                if low[v] == discovered[v]:\n                    while True:\n                        x = ss.pop()\n                        in_stack[x] = False\n                        scc_index[x] = count\n                        if x == v:\n                            break\n                    count += 1\n    return count, scc_index\n\n\ndef main():\n    n, m = map(int, input().split())\n    # 2-SAT: el nodo x es \"x verdadero\" y x+m es su negación\n    neg = lambda u: u - m if u > m else u + m\n    G = [[] for _ in range(2 * m + 1)]\n    for _ in range(n):\n        s1, u, s2, v = input().split()\n        u = int(u) if s1 == '+' else int(u) + m\n        v = int(v) if s2 == '+' else int(v) + m\n        # cada cláusula (u ∨ v) agrega las implicaciones ¬u → v y ¬v → u\n        G[neg(u)].append(v)\n        G[neg(v)].append(u)\n\n    # SCC sobre el grafo de implicaciones\n    _, idx = tarjan(G, 2 * m)\n    res = []\n    for x in range(1, m + 1):\n        # si x y ¬x están en la misma SCC no hay solución\n        if idx[x] == idx[x + m]:\n            print(\"IMPOSSIBLE\")\n            return\n        # x es verdadera si su SCC va después en el orden topológico (Tarjan numera al revés)\n        res.append('+' if idx[x] < idx[x + m] else '-')\n    print(*res)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Miscellaneous-CycleFindingDirected", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Miscellaneous", "archivo": "Graphs/Algorithms/Miscellaneous/CycleFindingDirected.cpp", "nombre": "CycleFindingDirected", "algoritmo": "Ciclo en grafo dirigido (DFS con pila de recursión)", "problema": "CSES 1678 - Round Trip II (https://cses.fi/problemset/task/1678)", "cses": "https://cses.fi/problemset/task/1678", "py_lento": false, "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "longitud del ciclo y sus nodos, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Ciclo en grafo dirigido (DFS con pila de recursión)\n * Problema  : CSES 1678 - Round Trip II (https://cses.fi/problemset/task/1678)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : longitud del ciclo y sus nodos, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// on_stack = nodos en el camino actual de la DFS, parent[] sirve para reconstruir el ciclo\nvector<bool> on_stack;\nvector<bool> vis;\nvector<vector<ll>> ady;\nvector<ll> cycle;\nvector<ll> parent;\n \n// devuelve true apenas encuentra un ciclo\nbool DFS(ll v){\n    vis[v] = true;\n    on_stack[v] = true;\n \n    for (auto u : ady[v]) {\n        if (!vis[u]) {\n            parent[u] = v;\n            if (DFS(u)) return true;\n        // arista hacia un nodo del camino actual: ciclo dirigido\n        } else if (on_stack[u]) {\n            cycle.clear();\n            cycle.push_back(u);\n            // se retrocede por los padres desde v hasta u\n            for (ll x = v; x != u; x = parent[x]) {\n                cycle.push_back(x);\n            }\n            cycle.push_back(u);\n            // se invierte para imprimirlo en el sentido de las aristas\n            reverse(all(cycle));\n            return true;\n        }\n    }\n \n    // v ya no está en el camino actual\n    on_stack[v] = false;\n    return false;\n}\n \nint main(){\n    fastio;\n \n    ll n, m; cin >> n >> m;\n    ady.assign(n, {});\n    for (int i = 0; i < m; i++){\n        ll u, v; cin >> u >> v; u--; v--;\n        ady[u].push_back(v);\n    }\n \n    on_stack.assign(n, false);\n    vis.assign(n, false);\n    parent.assign(n, -1);\n \n    for (int i = 0; i < n; i++){\n        if (!vis[i]) {\n            // se prueba cada componente\n            if (DFS(i)) {\n                cout << cycle.size() << \"\\n\";\n                for (auto node : cycle) cout << node + 1 << \" \";\n                cout << \"\\n\";\n                return 0;\n            }\n        }\n    }\n \n    cout << \"IMPOSSIBLE\\n\";\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Ciclo en grafo dirigido (DFS con pila de recursión)\n * Problema  : CSES 1678 - Round Trip II (https://cses.fi/problemset/task/1678)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : longitud del ciclo y sus nodos, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n\n    # on_stack = nodos en el camino actual de la DFS, parent[] sirve para reconstruir el ciclo\n    visited = [False] * (n + 1)\n    on_stack = [False] * (n + 1)\n    parent = [0] * (n + 1)\n    for s in range(1, n + 1):\n        if visited[s]:\n            continue\n        visited[s] = on_stack[s] = True\n        st = [(s, 0)]\n        while st:\n            v, i = st[-1]\n            if i < len(G[v]):\n                st[-1] = (v, i + 1)\n                u = G[v][i]\n                if not visited[u]:\n                    visited[u] = on_stack[u] = True\n                    parent[u] = v\n                    st.append((u, 0))\n                elif on_stack[u]:\n                    # arista hacia un nodo del camino actual: ciclo dirigido\n                    cycle = [u]\n                    x = v\n                    while x != u:\n                        cycle.append(x)\n                        x = parent[x]\n                    cycle.append(u)\n                    # se invierte para imprimirlo en el sentido de las aristas\n                    cycle.reverse()\n                    print(len(cycle))\n                    print(*cycle)\n                    return\n            else:\n                # v ya no está en el camino actual\n                on_stack[v] = False\n                st.pop()\n    print(\"IMPOSSIBLE\")\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Miscellaneous-CycleFindingUndirected", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Miscellaneous", "archivo": "Graphs/Algorithms/Miscellaneous/CycleFindingUndirected.cpp", "nombre": "CycleFindingUndirected", "algoritmo": "Ciclo en grafo no dirigido (DFS)", "problema": "CSES 1669 - Round Trip (https://cses.fi/problemset/task/1669)", "cses": "https://cses.fi/problemset/task/1669", "py_lento": false, "entrada": "n m, luego m aristas \"a b\"", "salida": "longitud del ciclo y sus nodos, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Ciclo en grafo no dirigido (DFS)\n * Problema  : CSES 1669 - Round Trip (https://cses.fi/problemset/task/1669)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : longitud del ciclo y sus nodos, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// on_stack = nodos en el camino actual de la DFS, parent[] sirve para reconstruir el ciclo\nvector<bool> on_stack;\nvector<bool> vis;\nvector<vector<ll>> ady;\nvector<ll> cycle;\nvector<ll> parent;\n \n// devuelve true apenas encuentra un ciclo\nbool DFS(ll v, ll p){\n    parent[v] = p;\n    vis[v] = true;\n    on_stack[v] = true;\n \n    for (auto u : ady[v]) {\n        // no se cuenta la arista por la que se llegó (padre)\n        if(u == p) continue;\n \n        if (!vis[u]) {\n            if (DFS(u, v)) return true;\n        // se llegó a un ancestro: hay un ciclo\n        } else if (on_stack[u]) {\n            cycle.clear();\n            cycle.push_back(u);\n            // se retrocede por los padres desde v hasta u\n            for (ll x = v; x != u; x = parent[x]) {\n                cycle.push_back(x);\n            }\n            cycle.push_back(u); \n            return true;\n        }\n    }\n \n    // v ya no está en el camino actual\n    on_stack[v] = false;\n    return false;\n}\n \nint main(){\n    fastio;\n \n    ll n, m; cin >> n >> m;\n    ady.assign(n, {});\n    for (int i = 0; i < m; i++){\n        ll u, v; cin >> u >> v; u--; v--;\n        ady[u].push_back(v);\n        ady[v].push_back(u);\n    }\n \n    on_stack.assign(n, false);\n    vis.assign(n, false);\n    parent.assign(n, -1);\n \n    for (int i = 0; i < n; i++){\n        if (!vis[i]) {\n            // se prueba cada componente conexa\n            if (DFS(i, -1)) {\n                cout << cycle.size() << \"\\n\";\n                for (auto node : cycle) cout << node + 1 << \" \";\n                cout << \"\\n\";\n                return 0;\n            }\n        }\n    }\n \n    cout << \"IMPOSSIBLE\\n\";\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Ciclo en grafo no dirigido (DFS)\n * Problema  : CSES 1669 - Round Trip (https://cses.fi/problemset/task/1669)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : longitud del ciclo y sus nodos, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    n, m = map(int, input().split())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(m):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        G[b].append(a)\n\n    # on_stack = nodos en el camino actual de la DFS, parent[] sirve para reconstruir el ciclo\n    visited = [False] * (n + 1)\n    on_stack = [False] * (n + 1)\n    parent = [0] * (n + 1)\n    for s in range(1, n + 1):\n        if visited[s]:\n            continue\n        visited[s] = on_stack[s] = True\n        parent[s] = -1\n        st = [(s, 0)]\n        while st:\n            v, i = st[-1]\n            if i < len(G[v]):\n                st[-1] = (v, i + 1)\n                u = G[v][i]\n                # no se cuenta la arista por la que se llegó (padre)\n                if u == parent[v]:\n                    continue\n                if not visited[u]:\n                    visited[u] = on_stack[u] = True\n                    parent[u] = v\n                    st.append((u, 0))\n                elif on_stack[u]:\n                    # se llegó a un ancestro: hay un ciclo; se retrocede por los padres desde v hasta u\n                    cycle = [u]\n                    x = v\n                    while x != u:\n                        cycle.append(x)\n                        x = parent[x]\n                    cycle.append(u)\n                    print(len(cycle))\n                    print(*cycle)\n                    return\n            else:\n                # v ya no está en el camino actual\n                on_stack[v] = False\n                st.pop()\n    print(\"IMPOSSIBLE\")\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Trees-BinaryLifting", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/BinaryLifting.cpp", "nombre": "BinaryLifting", "algoritmo": "Binary Lifting (ancestro a distancia k)", "problema": "CSES 1750 - Planets Queries I (https://cses.fi/problemset/task/1750)", "cses": "https://cses.fi/problemset/task/1750", "py_lento": false, "entrada": "n q, luego t_1..t_n (destino de cada planeta) y q consultas \"x k\"", "salida": "el planeta al que se llega desde x tras k teletransportes", "complejidad": "tiempo O((n + q) log k), memoria O(n log k)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Binary Lifting (ancestro a distancia k)\n * Problema  : CSES 1750 - Planets Queries I (https://cses.fi/problemset/task/1750)\n * Entrada   : n q, luego t_1..t_n (destino de cada planeta) y q consultas \"x k\"\n * Salida    : el planeta al que se llega desde x tras k teletransportes\n * Complejidad: tiempo O((n + q) log k), memoria O(n log k)\n */\n\n// 2^30 > 10^9, suficiente para k hasta 10^9\nconst int LOG = 30;\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    // up[j][v] = nodo al que se llega desde v tras 2^j pasos\n    // up[j][v] = nodo al que se llega desde v tras 2^j pasos\n    vector<vector<int>> up(LOG, vector<int>(n + 1));\n    for (int v = 1; v <= n; v++) cin >> up[0][v];\n    // cada nivel sale de duplicar el anterior\n    for (int j = 1; j < LOG; j++)\n        for (int v = 1; v <= n; v++)\n            up[j][v] = up[j - 1][up[j - 1][v]];\n\n    while (q--) {\n        int x, k;\n        cin >> x >> k;\n        for (int j = 0; j < LOG; j++)\n            // se descompone k en binario y se salta por cada bit encendido\n            if (k >> j & 1) x = up[j][x];\n        cout << x << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Binary Lifting (ancestro a distancia k)\n * Problema  : CSES 1750 - Planets Queries I (https://cses.fi/problemset/task/1750)\n * Entrada   : n q, luego t_1..t_n (destino de cada planeta) y q consultas \"x k\"\n * Salida    : el planeta al que se llega desde x tras k teletransportes\n * Complejidad: tiempo O((n + q) log k), memoria O(n log k)\n\"\"\"\n\n\n# 2^30 > 10^9, suficiente para k hasta 10^9\nLOG = 30\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, q = int(data[0]), int(data[1])\n    # up[j][v] = nodo al que se llega desde v tras 2^j pasos\n    up = [[0] + [int(x) for x in data[2:n + 2]]]\n    # cada nivel sale de duplicar el anterior\n    for j in range(1, LOG):\n        prev = up[-1]\n        up.append([prev[prev[v]] for v in range(n + 1)])\n\n    out = []\n    pos = n + 2\n    for _ in range(q):\n        x, k = int(data[pos]), int(data[pos + 1])\n        pos += 2\n        # se descompone k en binario y se salta por cada bit encendido\n        j = 0\n        while k:\n            if k & 1:\n                x = up[j][x]\n            k >>= 1\n            j += 1\n        out.append(x)\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Trees-Centroid", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/Centroid.cpp", "nombre": "Centroid", "algoritmo": "Centroide de un árbol (tamaños de subárbol)", "problema": "CSES 2079 - Finding a Centroid (https://cses.fi/problemset/task/2079)", "cses": "https://cses.fi/problemset/task/2079", "py_lento": false, "entrada": "n, luego n-1 aristas \"a b\"", "salida": "un centroide", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Centroide de un árbol (tamaños de subárbol)\n * Problema  : CSES 2079 - Finding a Centroid (https://cses.fi/problemset/task/2079)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : un centroide\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n\n    int n;\n    cin >> n;\n    vector<vector<int>> adj(n+1);\n    for (int i = 0; i < n-1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n\n    // DFS iterativo: order guarda los nodos en preorden y parent su padre\n    vector<int> parent(n+1, 0), order;\n    order.reserve(n);\n    stack<pair<int, int>> st;\n    st.emplace(1, 0);\n\n    while (!st.empty()) {\n        auto [u, p] = st.top(); st.pop();\n        parent[u] = p;\n        order.push_back(u);\n        for (int v : adj[u]) {\n            if (v == p) continue;\n            st.emplace(v, u);\n        }\n    }\n\n    // dp[u] = tamaño del subárbol de u (se llena de las hojas hacia la raíz)\n    vector<int> dp(n+1, 1);\n    for (int i = n-1; i >= 0; --i) {\n        int u = order[i];\n        for (int v : adj[u]) {\n            if (v == parent[u]) continue;\n            dp[u] += dp[v];\n        }\n    }\n\n    // centroide: ningún subárbol puede tener más de n/2 nodos\n    int limit = n / 2;\n    int u = 1;\n    // se baja siempre hacia el hijo con subárbol demasiado grande\n    while (true) {\n        bool moved = false;\n        for (int v : adj[u]) {\n            if (v != parent[u] && dp[v] > limit) {\n                parent[u] = u;\n                u = v;\n                moved = true;\n                break;\n            }\n        }\n        if (moved) continue;\n\n        // si tampoco la parte \"de arriba\" es grande, u es el centroide\n        if (n - dp[u] <= limit) {\n            cout << u << '\\n';\n            break;\n        }\n\n        u = parent[u];\n    }\n\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Centroide de un árbol (tamaños de subárbol)\n * Problema  : CSES 2079 - Finding a Centroid (https://cses.fi/problemset/task/2079)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : un centroide\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        G[b].append(a)\n\n    # recorrido iterativo: order guarda los nodos en preorden y parent su padre\n    parent = [0] * (n + 1)\n    order = [1]\n    for u in order:\n        for v in G[u]:\n            if v != parent[u]:\n                parent[v] = u\n                order.append(v)\n\n    # dp[u] = tamaño del subárbol de u (se llena de las hojas hacia la raíz)\n    dp = [1] * (n + 1)\n    for u in reversed(order):\n        if u != 1:\n            dp[parent[u]] += dp[u]\n\n    # centroide: ningún subárbol puede tener más de n/2 nodos\n    limit = n // 2\n    u = 1\n    # se baja siempre hacia el hijo con subárbol demasiado grande\n    while True:\n        nxt = 0\n        for v in G[u]:\n            if v != parent[u] and dp[v] > limit:\n                nxt = v\n                break\n        if nxt == 0:\n            break\n        u = nxt\n    print(u)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Trees-CentroidDecomposition", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/CentroidDecomposition.cpp", "nombre": "CentroidDecomposition", "algoritmo": "Descomposición por centroides (caminos de longitud fija)", "problema": "CSES 2080 - Fixed-Length Paths I (https://cses.fi/problemset/task/2080)", "cses": "https://cses.fi/problemset/task/2080", "py_lento": true, "entrada": "n k, luego n-1 aristas \"a b\"", "salida": "cantidad de caminos con exactamente k aristas", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Descomposición por centroides (caminos de longitud fija)\n * Problema  : CSES 2080 - Fixed-Length Paths I (https://cses.fi/problemset/task/2080)\n * Entrada   : n k, luego n-1 aristas \"a b\"\n * Salida    : cantidad de caminos con exactamente k aristas\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint n, k;\nvector<vector<int>> G;\nvector<int> sz, cnt;\nvector<bool> removed;\nll answer = 0;\nint maxDepth;\n\n// tamaño de cada subárbol (ignorando centroides ya removidos)\nint calcSize(int u, int p) {\n    sz[u] = 1;\n    for (int v : G[u])\n        if (v != p && !removed[v]) sz[u] += calcSize(v, u);\n    return sz[u];\n}\n\n// baja hacia el hijo con más de la mitad de los nodos\nint findCentroid(int u, int p, int total) {\n    for (int v : G[u])\n        if (v != p && !removed[v] && sz[v] * 2 > total) return findCentroid(v, u, total);\n    return u;\n}\n\n// cuenta caminos que pasan por el centroide usando cnt[d] = nodos a profundidad d ya vistos\n// recorre un subárbol: con fill se registra la profundidad, sin fill se cuentan caminos de longitud k\nvoid collect(int u, int p, int depth, bool fill) {\n    if (depth > k) return;\n    if (fill) cnt[depth]++;\n    else answer += cnt[k - depth];\n    maxDepth = max(maxDepth, depth);\n    for (int v : G[u])\n        if (v != p && !removed[v]) collect(v, u, depth + 1, fill);\n}\n\n// 1) se halla el centroide, 2) se cuentan los caminos que pasan por él, 3) se repite en cada parte\nvoid decompose(int root) {\n    int total = calcSize(root, 0);\n    int c = findCentroid(root, 0, total);\n    removed[c] = true;\n\n    cnt[0] = 1;\n    int used = 0;\n    for (int v : G[c]) {\n        if (removed[v]) continue;\n        maxDepth = 0;\n        // primero se consulta contra los subárboles anteriores\n        collect(v, c, 1, false);  // primero se consulta contra los subárboles anteriores\n        collect(v, c, 1, true);   // luego se agrega este subárbol\n        used = max(used, maxDepth);\n    }\n    // se limpia cnt para el siguiente centroide\n    for (int d = 0; d <= min(used, k); d++) cnt[d] = 0;\n\n    for (int v : G[c])\n        if (!removed[v]) decompose(v);\n}\n\nint main() {\n    fastio;\n    cin >> n >> k;\n    G.assign(n + 1, {});\n    sz.assign(n + 1, 0);\n    cnt.assign(n + 2, 0);\n    removed.assign(n + 1, false);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n    decompose(1);\n    cout << answer << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Descomposición por centroides (caminos de longitud fija)\n * Problema  : CSES 2080 - Fixed-Length Paths I (https://cses.fi/problemset/task/2080)\n * Entrada   : n k, luego n-1 aristas \"a b\"\n * Salida    : cantidad de caminos con exactamente k aristas\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, k = int(data[0]), int(data[1])\n    G = [[] for _ in range(n + 1)]\n    for i in range(n - 1):\n        a, b = int(data[2 + 2 * i]), int(data[3 + 2 * i])\n        G[a].append(b)\n        G[b].append(a)\n\n    removed = [False] * (n + 1)\n    sz = [0] * (n + 1)\n    par = [0] * (n + 1)\n    dep = [0] * (n + 1)\n    # cnt[d] = nodos a profundidad d ya vistos alrededor del centroide actual\n    cnt = [0] * (n + 2)\n    answer = 0\n\n    # 1) se halla el centroide, 2) se cuentan los caminos que pasan por él, 3) se repite en cada parte\n    stack = [1]\n    while stack:\n        root = stack.pop()\n        # tamaño de cada subárbol (ignorando centroides ya removidos)\n        par[root] = 0\n        order = [root]\n        for u in order:\n            for v in G[u]:\n                if v != par[u] and not removed[v]:\n                    par[v] = u\n                    order.append(v)\n        for u in reversed(order):\n            sz[u] = 1\n        for u in reversed(order):\n            if u != root:\n                sz[par[u]] += sz[u]\n        total = len(order)\n        # baja hacia el hijo con más de la mitad de los nodos\n        c = root\n        while True:\n            nxt = 0\n            for v in G[c]:\n                if v != par[c] and not removed[v] and sz[v] * 2 > total:\n                    nxt = v\n                    break\n            if nxt == 0:\n                break\n            c = nxt\n        removed[c] = True\n\n        cnt[0] = 1\n        maxd = 0\n        for v in G[c]:\n            if removed[v]:\n                continue\n            # profundidades del subárbol de v (BFS desde v, sin pasar de k)\n            par[v] = c\n            dep[v] = 1\n            q = [v]\n            for u in q:\n                du = dep[u]\n                if du == k:\n                    continue\n                for w in G[u]:\n                    if w != par[u] and not removed[w]:\n                        par[w] = u\n                        dep[w] = du + 1\n                        q.append(w)\n            # primero se consulta contra los subárboles anteriores, luego se agrega este\n            for u in q:\n                answer += cnt[k - dep[u]]\n            for u in q:\n                cnt[dep[u]] += 1\n            if dep[q[-1]] > maxd:\n                maxd = dep[q[-1]]\n        # se limpia cnt para el siguiente centroide\n        for d in range(1, maxd + 1):\n            cnt[d] = 0\n\n        for v in G[c]:\n            if not removed[v]:\n                stack.append(v)\n    print(answer)\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Trees-EulerTour", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/EulerTour.cpp", "nombre": "EulerTour", "algoritmo": "Euler Tour + Fenwick Tree (consultas sobre subárboles)", "problema": "CSES 1137 - Subtree Queries (https://cses.fi/problemset/task/1137)", "cses": "https://cses.fi/problemset/task/1137", "py_lento": false, "entrada": "n q, n valores, n-1 aristas y q consultas: \"1 s x\" (valor del nodo s = x) o \"2 s\" (suma del subárbol de s)", "salida": "la suma de cada consulta de tipo 2", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Euler Tour + Fenwick Tree (consultas sobre subárboles)\n * Problema  : CSES 1137 - Subtree Queries (https://cses.fi/problemset/task/1137)\n * Entrada   : n q, n valores, n-1 aristas y q consultas: \"1 s x\" (valor del nodo s = x) o \"2 s\" (suma del subárbol de s)\n * Salida    : la suma de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\nint n;\nvector<vector<int>> G;\n// tin[u]/tout[u] = intervalo del subárbol de u en el recorrido\nvector<int> tin, tout;\n// Fenwick Tree sobre las posiciones del recorrido\nvector<ll> bit;\n\n// suma v en la posición i\nvoid add(int i, ll v) {\n    for (; i <= n; i += i & -i) bit[i] += v;\n}\n\n// suma del prefijo [1..i]\nll sum(int i) {\n    ll s = 0;\n    for (; i > 0; i -= i & -i) s += bit[i];\n    return s;\n}\n\nint main() {\n    fastio;\n    int q;\n    cin >> n >> q;\n    vector<ll> val(n + 1);\n    for (int i = 1; i <= n; i++) cin >> val[i];\n    G.assign(n + 1, {});\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // DFS iterativo: tin/tout marcan el intervalo del subárbol\n    tin.assign(n + 1, 0), tout.assign(n + 1, 0);\n    vector<int> parent(n + 1, 0), idx(n + 1, 0), st = {1};\n    int timer = 0;\n    tin[1] = ++timer;\n    while (!st.empty()) {\n        int u = st.back();\n        if (idx[u] < (int)G[u].size()) {\n            int v = G[u][idx[u]++];\n            if (v == parent[u]) continue;\n            parent[v] = u;\n            tin[v] = ++timer;\n            st.push_back(v);\n        }\n        else {\n            tout[u] = timer;\n            st.pop_back();\n        }\n    }\n\n    bit.assign(n + 2, 0);\n    // cada nodo ocupa la posición tin[i]\n    for (int i = 1; i <= n; i++) add(tin[i], val[i]);\n\n    while (q--) {\n        int type, s;\n        cin >> type >> s;\n        // actualizar un nodo = sumar la diferencia en su posición; consultar = suma del intervalo del subárbol\n        if (type == 1) {\n            ll x;\n            cin >> x;\n            add(tin[s], x - val[s]);\n            val[s] = x;\n        }\n        else cout << sum(tout[s]) - sum(tin[s] - 1) << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Euler Tour + Fenwick Tree (consultas sobre subárboles)\n * Problema  : CSES 1137 - Subtree Queries (https://cses.fi/problemset/task/1137)\n * Entrada   : n q, n valores, n-1 aristas y q consultas: \"1 s x\" (valor del nodo s = x) o \"2 s\" (suma del subárbol de s)\n * Salida    : la suma de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, q = int(data[0]), int(data[1])\n    val = [0] + [int(x) for x in data[2:n + 2]]\n    G = [[] for _ in range(n + 1)]\n    pos = n + 2\n    for _ in range(n - 1):\n        a, b = int(data[pos]), int(data[pos + 1])\n        pos += 2\n        G[a].append(b)\n        G[b].append(a)\n\n    # tin[u]/tout[u] = intervalo del subárbol de u en el recorrido (DFS iterativo)\n    tin = [0] * (n + 1)\n    tout = [0] * (n + 1)\n    parent = [0] * (n + 1)\n    timer = 1\n    tin[1] = 1\n    st = [(1, 0)]\n    while st:\n        u, i = st[-1]\n        if i < len(G[u]):\n            st[-1] = (u, i + 1)\n            v = G[u][i]\n            if v != parent[u]:\n                parent[v] = u\n                timer += 1\n                tin[v] = timer\n                st.append((v, 0))\n        else:\n            tout[u] = timer\n            st.pop()\n\n    # Fenwick Tree sobre las posiciones del recorrido\n    bit = [0] * (n + 1)\n\n    def add(i, v):\n        while i <= n:\n            bit[i] += v\n            i += i & -i\n\n    def prefix(i):\n        s = 0\n        while i > 0:\n            s += bit[i]\n            i -= i & -i\n        return s\n\n    # cada nodo ocupa la posición tin[i]\n    for v in range(1, n + 1):\n        add(tin[v], val[v])\n\n    out = []\n    for _ in range(q):\n        t = int(data[pos])\n        s = int(data[pos + 1])\n        if t == 1:\n            # actualizar un nodo = sumar la diferencia en su posición\n            x = int(data[pos + 2])\n            pos += 3\n            add(tin[s], x - val[s])\n            val[s] = x\n        else:\n            # consultar = suma del intervalo del subárbol\n            pos += 2\n            out.append(prefix(tout[s]) - prefix(tin[s] - 1))\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Trees-LCA", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/LCA.cpp", "nombre": "LCA", "algoritmo": "LCA con binary lifting", "problema": "CSES 1688 - Company Queries II (https://cses.fi/problemset/task/1688)", "cses": "https://cses.fi/problemset/task/1688", "py_lento": false, "entrada": "n q, luego los jefes de 2..n y q consultas \"a b\"", "salida": "el ancestro común más bajo de cada consulta", "complejidad": "tiempo O((n + q) log n), memoria O(n log n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : LCA con binary lifting\n * Problema  : CSES 1688 - Company Queries II (https://cses.fi/problemset/task/1688)\n * Entrada   : n q, luego los jefes de 2..n y q consultas \"a b\"\n * Salida    : el ancestro común más bajo de cada consulta\n * Complejidad: tiempo O((n + q) log n), memoria O(n log n)\n */\n\nint main() {\n    fastio;\n\n    ll n, q;\n    cin >> n >> q;\n\n    vector<vector<ll>> children(n + 1);\n    // read bosses e[2..n]\n    for (ll i = 2; i <= n; ++i) {\n        ll b;\n        cin >> b;\n        children[b].push_back(i);\n    }\n\n    // compute depth and immediate parent\n    vector<ll> depth(n + 1), parent(n + 1);\n    queue<ll> bfs;\n    depth[1] = 0;\n    parent[1] = 1;\n    bfs.push(1);\n    while (!bfs.empty()) {\n        ll u = bfs.front(); bfs.pop();\n        for (ll v : children[u]) {\n            depth[v] = depth[u] + 1;\n            parent[v] = u;\n            bfs.push(v);\n        }\n    }\n\n    // binary lifting table\n    // up[i][j] = ancestro 2^j veces arriba de i\n    const int LOG = 19; // since 2^18 > 2e5\n    vector<array<ll, LOG>> up(n + 1);\n    for (ll i = 1; i <= n; ++i) {\n        up[i][0] = parent[i];\n    }\n    for (int j = 1; j < LOG; ++j) {\n        for (ll i = 1; i <= n; ++i) {\n            up[i][j] = up[ up[i][j - 1] ][j - 1];\n        }\n    }\n\n    // LCA: se igualan profundidades y luego se sube a la vez mientras los ancestros difieran\n    auto lca = [&](ll a, ll b) {\n        if (depth[a] < depth[b]) swap(a, b);\n        ll diff = depth[a] - depth[b];\n        for (int j = 0; j < LOG; ++j) {\n            if (diff & (1LL << j)) {\n                a = up[a][j];\n            }\n        }\n        if (a == b) return a;\n        for (int j = LOG - 1; j >= 0; --j) {\n            if (up[a][j] != up[b][j]) {\n                a = up[a][j];\n                b = up[b][j];\n            }\n        }\n        return parent[a];\n    };\n\n    while (q--) {\n        ll a, b;\n        cin >> a >> b;\n        cout << lca(a, b) << '\\n';\n    }\n\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : LCA con binary lifting\n * Problema  : CSES 1688 - Company Queries II (https://cses.fi/problemset/task/1688)\n * Entrada   : n q, luego los jefes de 2..n y q consultas \"a b\"\n * Salida    : el ancestro común más bajo de cada consulta\n * Complejidad: tiempo O((n + q) log n), memoria O(n log n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, q = int(data[0]), int(data[1])\n    parent = [0, 1] + [int(x) for x in data[2:n + 1]]\n\n    # profundidad con BFS desde la raíz (los jefes forman el árbol)\n    children = [[] for _ in range(n + 1)]\n    for v in range(2, n + 1):\n        children[parent[v]].append(v)\n    depth = [0] * (n + 1)\n    order = [1]\n    for u in order:\n        for v in children[u]:\n            depth[v] = depth[u] + 1\n            order.append(v)\n\n    # up[j][v] = ancestro 2^j veces arriba de v\n    LOG = max(1, n.bit_length())\n    up = [parent]\n    for j in range(1, LOG):\n        prev = up[-1]\n        up.append([prev[prev[v]] for v in range(n + 1)])\n\n    # LCA: se igualan profundidades y luego se sube a la vez mientras los ancestros difieran\n    def lca(a, b):\n        if depth[a] < depth[b]:\n            a, b = b, a\n        diff = depth[a] - depth[b]\n        j = 0\n        while diff:\n            if diff & 1:\n                a = up[j][a]\n            diff >>= 1\n            j += 1\n        if a == b:\n            return a\n        for j in range(LOG - 1, -1, -1):\n            if up[j][a] != up[j][b]:\n                a, b = up[j][a], up[j][b]\n        return parent[a]\n\n    out = []\n    pos = n + 1\n    for _ in range(q):\n        a, b = int(data[pos]), int(data[pos + 1])\n        pos += 2\n        out.append(lca(a, b))\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Trees-TreeDistances", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/TreeDistances.cpp", "nombre": "TreeDistances", "algoritmo": "Distancia máxima desde cada nodo (extremos del diámetro)", "problema": "CSES 1132 - Tree Distances I (https://cses.fi/problemset/task/1132)", "cses": "https://cses.fi/problemset/task/1132", "py_lento": false, "entrada": "n, luego n-1 aristas \"a b\"", "salida": "para cada nodo, la distancia al nodo más lejano", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Distancia máxima desde cada nodo (extremos del diámetro)\n * Problema  : CSES 1132 - Tree Distances I (https://cses.fi/problemset/task/1132)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : para cada nodo, la distancia al nodo más lejano\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nvector<vector<int>> G;\n\n// BFS: distancias desde s\n// BFS: distancias desde s\nvector<int> bfs(int s) {\n    vector<int> dist(G.size(), -1);\n    queue<int> q;\n    dist[s] = 0;\n    q.push(s);\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        for (int v : G[u])\n            if (dist[v] == -1) {\n                dist[v] = dist[u] + 1;\n                q.push(v);\n            }\n    }\n    return dist;\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    G.assign(n + 1, {});\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // el más lejano de cualquier nodo es un extremo A del diámetro; el más lejano de A es B\n    // el nodo más lejano de cualquier nodo es un extremo A del diámetro\n    auto d0 = bfs(1);\n    int A = max_element(d0.begin() + 1, d0.end()) - d0.begin();\n    auto dA = bfs(A);\n    int B = max_element(dA.begin() + 1, dA.end()) - dA.begin();\n    auto dB = bfs(B);\n\n    // la distancia máxima desde v es max(dist a A, dist a B)\n    // la distancia máxima desde v es max(dist a A, dist a B)\n    for (int v = 1; v <= n; v++) cout << max(dA[v], dB[v]) << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nfrom collections import deque\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Distancia máxima desde cada nodo (extremos del diámetro)\n * Problema  : CSES 1132 - Tree Distances I (https://cses.fi/problemset/task/1132)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : para cada nodo, la distancia al nodo más lejano\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\n# BFS: distancias desde s\ndef bfs(G, s):\n    dist = [-1] * len(G)\n    dist[s] = 0\n    q = deque([s])\n    while q:\n        u = q.popleft()\n        for v in G[u]:\n            if dist[v] == -1:\n                dist[v] = dist[u] + 1\n                q.append(v)\n    return dist\n\n\ndef main():\n    n = int(input())\n    G = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = map(int, input().split())\n        G[a].append(b)\n        G[b].append(a)\n\n    # el nodo más lejano de cualquier nodo es un extremo A del diámetro; el más lejano de A es B\n    d0 = bfs(G, 1)\n    A = max(range(1, n + 1), key=lambda v: d0[v])\n    dA = bfs(G, A)\n    B = max(range(1, n + 1), key=lambda v: dA[v])\n    dB = bfs(G, B)\n\n    # la distancia máxima desde v es max(dist a A, dist a B)\n    print(*(max(dA[v], dB[v]) for v in range(1, n + 1)))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Trees-TreeIsomorfism", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/TreeIsomorfism.cpp", "nombre": "TreeIsomorfism", "algoritmo": "Isomorfismo de árboles sin raíz (centroides + IDs canónicos)", "problema": "CSES 1701 - Tree Isomorphism II (https://cses.fi/problemset/task/1701)", "cses": "https://cses.fi/problemset/task/1701", "py_lento": false, "entrada": "t casos; cada uno: n, aristas del primer árbol y aristas del segundo", "salida": "YES o NO por caso", "complejidad": "tiempo O(n log n) por caso, memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Isomorfismo de árboles sin raíz (centroides + IDs canónicos)\n * Problema  : CSES 1701 - Tree Isomorphism II (https://cses.fi/problemset/task/1701)\n * Entrada   : t casos; cada uno: n, aristas del primer árbol y aristas del segundo\n * Salida    : YES o NO por caso\n * Complejidad: tiempo O(n log n) por caso, memoria O(n)\n */\n\nconst int MAXN = 100000 + 1;\n\nint n, cidCounter;\n// adj[t][u] = lista de vecinos del nodo u en el árbol t (t=0,1)\nvector<int> adj[2][MAXN];\n// sizeSub[t][u] = tamaño del subárbol en u en el árbol t\nint sizeSub[2][MAXN];\n// canonId[t][u] = identificador canónico del subárbol en u\nint canonId[2][MAXN];\n// posibles centroides de cada árbol\nvector<int> centers[2];\n// mapa de vectores de hijos ordenados → nuevo ID\nmap<vector<int>, int> idmap;\n\n// Restaurar estructuras entre casos\nvoid reset() {\n    idmap.clear();\n    cidCounter = 0;\n    for (int t = 0; t < 2; t++) {\n        centers[t].clear();\n        for (int i = 1; i <= n; i++) {\n            adj[t][i].clear();\n            sizeSub[t][i] = canonId[t][i] = 0;\n        }\n    }\n}\n\n// DFS para hallar centroides: marca u si ningún subárbol > n/2\nvoid dfs_centroid(int t, int u, int p) {\n    sizeSub[t][u] = 1;\n    bool ok = true;\n    for (int v : adj[t][u]) if (v != p) {\n        dfs_centroid(t, v, u);\n        sizeSub[t][u] += sizeSub[t][v];\n        if (sizeSub[t][v] > n/2) ok = false;\n    }\n    if (n - sizeSub[t][u] > n/2) ok = false;\n    if (ok) centers[t].push_back(u);\n}\n\n// DFS para asignar IDs canónicos basados en multiconjuntos de hijos\nvoid dfs_canonical(int t, int u, int p) {\n    vector<int> childIds;\n    for (int v : adj[t][u]) if (v != p) {\n        dfs_canonical(t, v, u);\n        childIds.push_back(canonId[t][v]);\n    }\n    sort(all(childIds));                   // ordenamos para multiconjunto\n    if (!idmap[childIds])                  // si no existe el patrón\n        idmap[childIds] = ++cidCounter;    // creamos uno nuevo\n    canonId[t][u] = idmap[childIds];       // asignamos al nodo\n}\n\n// Resolver un caso: leer, hallar centroides y comparar isomorfismos\nvoid solve_case() {\n    cin >> n;\n    reset();\n    for (int t = 0; t < 2; t++) {\n        for (int i = 0, u, v; i < n-1; i++) {\n            cin >> u >> v;\n            adj[t][u].push_back(v);\n            adj[t][v].push_back(u);\n        }\n        dfs_centroid(t, 1, -1);\n    }\n    // probamos cada par de centroides\n    for (int c0 : centers[0]) {\n        for (int c1 : centers[1]) {\n            idmap.clear();\n            dfs_canonical(0, c0, -1);\n            dfs_canonical(1, c1, -1);\n            if (canonId[0][c0] == canonId[1][c1]) {\n                cout << \"YES\\n\";\n                return;\n            }\n        }\n    }\n    cout << \"NO\\n\";\n}\n\nint main() {\n    fastio;\n    int T;\n    cin >> T;\n    while (T--) solve_case();\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Isomorfismo de árboles sin raíz (centroides + IDs canónicos)\n * Problema  : CSES 1701 - Tree Isomorphism II (https://cses.fi/problemset/task/1701)\n * Entrada   : t casos; cada uno: n, aristas del primer árbol y aristas del segundo\n * Salida    : YES o NO por caso\n * Complejidad: tiempo O(n log n) por caso, memoria O(n)\n\"\"\"\n\n\n# id canónico de la raíz: depende de los ids ordenados de los hijos (de las hojas hacia la raíz)\ndef canonical(G, root, ids):\n    n = len(G) - 1\n    parent = [0] * (n + 1)\n    parent[root] = -1\n    order = [root]\n    for u in order:\n        for v in G[u]:\n            if v != parent[u]:\n                parent[v] = u\n                order.append(v)\n    children = [[] for _ in range(n + 1)]\n    cid = [0] * (n + 1)\n    for u in reversed(order):\n        key = tuple(sorted(children[u]))\n        # cada lista ordenada de ids de hijos recibe un id único\n        if key not in ids:\n            ids[key] = len(ids)\n        cid[u] = ids[key]\n        if parent[u] > 0:\n            children[parent[u]].append(cid[u])\n    return cid[root]\n\n\ndef read_tree(data, pos, n):\n    G = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = int(data[pos]), int(data[pos + 1])\n        pos += 2\n        G[a].append(b)\n        G[b].append(a)\n    return G, pos\n\n\n# centroides: nodos donde ningún pedazo al quitarlos tiene más de n/2 nodos\ndef centroids(G):\n    n = len(G) - 1\n    parent = [0] * (n + 1)\n    order = [1]\n    for u in order:\n        for v in G[u]:\n            if v != parent[u]:\n                parent[v] = u\n                order.append(v)\n    size = [1] * (n + 1)\n    res = []\n    for u in reversed(order):\n        biggest = n - size[u]\n        for v in G[u]:\n            if v != parent[u]:\n                biggest = max(biggest, size[v])\n        if parent[u]:\n            size[parent[u]] += size[u]\n        if biggest <= n // 2:\n            res.append(u)\n    return res\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    t = int(data[0])\n    pos = 1\n    out = []\n    # se resuelve cada caso de prueba por separado\n    for _ in range(t):\n        n = int(data[pos])\n        pos += 1\n        A, pos = read_tree(data, pos, n)\n        B, pos = read_tree(data, pos, n)\n        # ids compartido: el id de B se calcula una vez desde su primer centroide\n        # y se compara contra cada centroide de A\n        ids = {}\n        target = canonical(B, centroids(B)[0], ids)\n        ans = \"NO\"\n        for ca in centroids(A):\n            if canonical(A, ca, ids) == target:\n                ans = \"YES\"\n                break\n        out.append(ans)\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Graphs-Algorithms-Trees-TreeIsomorfismRooted", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/TreeIsomorfismRooted.cpp", "nombre": "TreeIsomorfismRooted", "algoritmo": "Isomorfismo de árboles con raíz (ids canónicos compartidos)", "problema": "CSES 1700 - Tree Isomorphism I (https://cses.fi/problemset/task/1700)", "cses": "https://cses.fi/problemset/task/1700", "py_lento": false, "entrada": "t casos: n, luego n-1 aristas del primer árbol y n-1 del segundo (ambos con raíz 1)", "salida": "YES si los árboles con raíz son isomorfos, NO si no", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Isomorfismo de árboles con raíz (ids canónicos compartidos)\n * Problema  : CSES 1700 - Tree Isomorphism I (https://cses.fi/problemset/task/1700)\n * Entrada   : t casos: n, luego n-1 aristas del primer árbol y n-1 del segundo (ambos con raíz 1)\n * Salida    : YES si los árboles con raíz son isomorfos, NO si no\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\n// cada lista ordenada de ids de hijos recibe un id único\nmap<vector<int>, int> ids;  // compartido entre los dos árboles de cada caso\n\n// id canónico de cada nodo: depende de los ids ordenados de sus hijos\n// calcula el id canónico de la raíz del árbol\nint canonical(const vector<vector<int>> &G) {\n    int n = G.size() - 1;\n    // BFS para obtener un orden y el padre de cada nodo\n    vector<int> parent(n + 1, 0), order;\n    order.push_back(1);\n    for (int i = 0; i < (int)order.size(); i++) {\n        int u = order[i];\n        for (int v : G[u])\n            if (v != parent[u]) {\n                parent[v] = u;\n                order.push_back(v);\n            }\n    }\n\n    vector<int> id(n + 1);\n    vector<vector<int>> children(n + 1);\n    // se procesa de las hojas hacia la raíz\n    for (int i = n - 1; i >= 0; i--) {  // de las hojas hacia la raíz\n        int u = order[i];\n        sort(all(children[u]));\n        auto it = ids.find(children[u]);\n        if (it == ids.end()) it = ids.insert({children[u], (int)ids.size()}).first;\n        id[u] = it->second;\n        if (parent[u]) children[parent[u]].push_back(id[u]);\n    }\n    return id[1];\n}\n\nint main() {\n    fastio;\n    int t;\n    cin >> t;\n    while (t--) {\n        int n;\n        cin >> n;\n        vector<vector<int>> A(n + 1), B(n + 1);\n        for (int i = 0; i < n - 1; i++) {\n            int a, b;\n            cin >> a >> b;\n            A[a].push_back(b);\n            A[b].push_back(a);\n        }\n        for (int i = 0; i < n - 1; i++) {\n            int a, b;\n            cin >> a >> b;\n            B[a].push_back(b);\n            B[b].push_back(a);\n        }\n        // árboles con raíz isomorfos si las raíces tienen el mismo id\n        cout << (canonical(A) == canonical(B) ? \"YES\" : \"NO\") << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Isomorfismo de árboles con raíz (ids canónicos compartidos)\n * Problema  : CSES 1700 - Tree Isomorphism I (https://cses.fi/problemset/task/1700)\n * Entrada   : t casos: n, luego n-1 aristas del primer árbol y n-1 del segundo (ambos con raíz 1)\n * Salida    : YES si los árboles con raíz son isomorfos, NO si no\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\n# id canónico de la raíz: depende de los ids ordenados de los hijos (de las hojas hacia la raíz)\ndef canonical(G, root, ids):\n    n = len(G) - 1\n    parent = [0] * (n + 1)\n    parent[root] = -1\n    order = [root]\n    for u in order:\n        for v in G[u]:\n            if v != parent[u]:\n                parent[v] = u\n                order.append(v)\n    children = [[] for _ in range(n + 1)]\n    cid = [0] * (n + 1)\n    for u in reversed(order):\n        key = tuple(sorted(children[u]))\n        # cada lista ordenada de ids de hijos recibe un id único\n        if key not in ids:\n            ids[key] = len(ids)\n        cid[u] = ids[key]\n        if parent[u] > 0:\n            children[parent[u]].append(cid[u])\n    return cid[root]\n\n\ndef read_tree(data, pos, n):\n    G = [[] for _ in range(n + 1)]\n    for _ in range(n - 1):\n        a, b = int(data[pos]), int(data[pos + 1])\n        pos += 2\n        G[a].append(b)\n        G[b].append(a)\n    return G, pos\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    t = int(data[0])\n    pos = 1\n    out = []\n    for _ in range(t):\n        n = int(data[pos])\n        pos += 1\n        A, pos = read_tree(data, pos, n)\n        B, pos = read_tree(data, pos, n)\n        # ids compartido entre los dos árboles de cada caso\n        ids = {}\n        # árboles con raíz isomorfos si las raíces tienen el mismo id\n        out.append(\"YES\" if canonical(A, 1, ids) == canonical(B, 1, ids) else \"NO\")\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Graphs-Classic-Problems-Counting-Rooms", "carpeta": "Graphs", "area": "Grafos", "sub": "Classic Problems", "archivo": "Graphs/Classic Problems/Counting Rooms.cpp", "nombre": "Counting Rooms", "algoritmo": "Componentes conexas en una cuadrícula (flood fill con BFS)", "problema": "CSES 1192 - Counting Rooms (https://cses.fi/problemset/task/1192)", "cses": "https://cses.fi/problemset/task/1192", "py_lento": false, "entrada": "n m, luego n filas de m caracteres ('.' piso, '#' pared)", "salida": "cantidad de cuartos (regiones de piso conectadas)", "complejidad": "tiempo O(n · m), memoria O(n · m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Componentes conexas en una cuadrícula (flood fill con BFS)\n * Problema  : CSES 1192 - Counting Rooms (https://cses.fi/problemset/task/1192)\n * Entrada   : n m, luego n filas de m caracteres ('.' piso, '#' pared)\n * Salida    : cantidad de cuartos (regiones de piso conectadas)\n * Complejidad: tiempo O(n · m), memoria O(n · m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<string> g(n);\n    for (auto &row : g) cin >> row;\n    int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};\n    int rooms = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = 0; j < m; j++) {\n            if (g[i][j] != '.') continue;\n            // piso sin visitar: es un cuarto nuevo; se pinta entero con BFS\n            rooms++;\n            queue<pair<int, int>> q;\n            q.push({i, j});\n            g[i][j] = '#';  // marcar como visitado\n            while (!q.empty()) {\n                auto [x, y] = q.front();\n                q.pop();\n                for (int d = 0; d < 4; d++) {\n                    int a = x + dx[d], b = y + dy[d];\n                    if (a < 0 || b < 0 || a >= n || b >= m || g[a][b] != '.') continue;\n                    g[a][b] = '#';\n                    q.push({a, b});\n                }\n            }\n        }\n    cout << rooms << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Componentes conexas en una cuadrícula (flood fill)\n * Problema  : CSES 1192 - Counting Rooms (https://cses.fi/problemset/task/1192)\n * Entrada   : n m, luego n filas de m caracteres ('.' piso, '#' pared)\n * Salida    : cantidad de cuartos (regiones de piso conectadas)\n * Complejidad: tiempo O(n · m), memoria O(n · m)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, m = int(data[0]), int(data[1])\n    # cuadrícula aplanada con un borde de pared alrededor: así no hay que revisar límites\n    W = m + 2\n    free = bytearray(W * (n + 2))\n    for i in range(n):\n        row = data[2 + i]\n        base = (i + 1) * W + 1\n        free[base:base + m] = row.replace(b'.', b'\\x01').replace(b'#', b'\\x00')\n    rooms = 0\n    moves = (1, -1, W, -W)\n    for start in range(W, W * (n + 1)):\n        if not free[start]:\n            continue\n        # piso sin visitar: es un cuarto nuevo; se pinta entero con una pila\n        rooms += 1\n        free[start] = 0\n        stack = [start]\n        while stack:\n            v = stack.pop()\n            for d in moves:\n                u = v + d\n                if free[u]:\n                    free[u] = 0\n                    stack.append(u)\n    print(rooms)\n\n\nmain()\n"}, {"id": "Graphs-Classic-Problems-Flight-Discount", "carpeta": "Graphs", "area": "Grafos", "sub": "Classic Problems", "archivo": "Graphs/Classic Problems/Flight Discount.cpp", "nombre": "Flight Discount", "algoritmo": "Dijkstra desde el origen y desde el destino (grafo invertido) para usar un cupón", "problema": "CSES 1195 - Flight Discount (https://cses.fi/problemset/task/1195)", "cses": "https://cses.fi/problemset/task/1195", "py_lento": false, "entrada": "n m, luego m vuelos dirigidos \"a b c\"", "salida": "el precio mínimo de 1 a n pudiendo pagar la mitad (redondeada abajo) de un solo vuelo", "complejidad": "tiempo O((n + m) log n), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Dijkstra desde el origen y desde el destino (grafo invertido) para usar un cupón\n * Problema  : CSES 1195 - Flight Discount (https://cses.fi/problemset/task/1195)\n * Entrada   : n m, luego m vuelos dirigidos \"a b c\"\n * Salida    : el precio mínimo de 1 a n pudiendo pagar la mitad (redondeada abajo) de un solo vuelo\n * Complejidad: tiempo O((n + m) log n), memoria O(n + m)\n */\n\ntypedef vector<vector<pair<int, ll>>> Graph;\n\nvector<ll> dijkstra(const Graph &g, int s) {\n    vector<ll> d(g.size(), INF);\n    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;\n    d[s] = 0;\n    pq.push({0, s});\n    while (!pq.empty()) {\n        auto [du, u] = pq.top();\n        pq.pop();\n        if (du != d[u]) continue;  // entrada vieja\n        for (auto [v, c] : g[u])\n            if (du + c < d[v]) d[v] = du + c, pq.push({d[v], v});\n    }\n    return d;\n}\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    Graph g(n + 1), rg(n + 1);\n    vector<array<ll, 3>> e(m);\n    for (auto &[a, b, c] : e) {\n        cin >> a >> b >> c;\n        g[a].push_back({(int)b, c});\n        rg[b].push_back({(int)a, c});  // grafo al revés: distancias hacia n\n    }\n    vector<ll> from1 = dijkstra(g, 1), toN = dijkstra(rg, n);\n    // el cupón se usa en algún vuelo a -> b: ir de 1 a a, pagar c/2, ir de b a n\n    ll best = INF;\n    for (auto [a, b, c] : e)\n        if (from1[a] < INF && toN[b] < INF) best = min(best, from1[a] + c / 2 + toN[b]);\n    cout << best << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport heapq\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Dijkstra desde el origen y desde el destino (grafo invertido) para usar un cupón\n * Problema  : CSES 1195 - Flight Discount (https://cses.fi/problemset/task/1195)\n * Entrada   : n m, luego m vuelos dirigidos \"a b c\"\n * Salida    : el precio mínimo de 1 a n pudiendo pagar la mitad (redondeada abajo) de un solo vuelo\n * Complejidad: tiempo O((n + m) log n), memoria O(n + m)\n\"\"\"\n\n\ndef dijkstra(g, s, n):\n    d = [INF] * (n + 1)\n    d[s] = 0\n    pq = [(0, s)]\n    while pq:\n        du, u = heapq.heappop(pq)\n        if du != d[u]:\n            continue  # entrada vieja\n        for v, c in g[u]:\n            nd = du + c\n            if nd < d[v]:\n                d[v] = nd\n                heapq.heappush(pq, (nd, v))\n    return d\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, m = int(data[0]), int(data[1])\n    e = list(map(int, data[2:2 + 3 * m]))\n    g = [[] for _ in range(n + 1)]\n    rg = [[] for _ in range(n + 1)]  # grafo al revés: distancias hacia n\n    for i in range(0, 3 * m, 3):\n        a, b, c = e[i], e[i + 1], e[i + 2]\n        g[a].append((b, c))\n        rg[b].append((a, c))\n    from1 = dijkstra(g, 1, n)\n    to_n = dijkstra(rg, n, n)\n    # el cupón se usa en algún vuelo a -> b: ir de 1 a a, pagar c // 2, ir de b a n\n    best = min(from1[e[i]] + e[i + 2] // 2 + to_n[e[i + 1]] for i in range(0, 3 * m, 3))\n    print(best)\n\n\nmain()\n"}, {"id": "Graphs-Classic-Problems-Labyrinth", "carpeta": "Graphs", "area": "Grafos", "sub": "Classic Problems", "archivo": "Graphs/Classic Problems/Labyrinth.cpp", "nombre": "Labyrinth", "algoritmo": "BFS en cuadrícula con reconstrucción del camino", "problema": "CSES 1193 - Labyrinth (https://cses.fi/problemset/task/1193)", "cses": "https://cses.fi/problemset/task/1193", "py_lento": false, "entrada": "n m, luego n filas con '.', '#', 'A' (inicio) y 'B' (fin)", "salida": "YES, el largo y las direcciones (L, R, U, D) de un camino más corto; o NO", "complejidad": "tiempo O(n · m), memoria O(n · m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : BFS en cuadrícula con reconstrucción del camino\n * Problema  : CSES 1193 - Labyrinth (https://cses.fi/problemset/task/1193)\n * Entrada   : n m, luego n filas con '.', '#', 'A' (inicio) y 'B' (fin)\n * Salida    : YES, el largo y las direcciones (L, R, U, D) de un camino más corto; o NO\n * Complejidad: tiempo O(n · m), memoria O(n · m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<string> g(n);\n    for (auto &row : g) cin >> row;\n    int dx[] = {0, 0, -1, 1}, dy[] = {-1, 1, 0, 0};\n    const char *name = \"LRUD\";\n    // from[i][j] = dirección con la que se llegó a (i, j), -1 si no se ha visitado\n    vector<vector<int>> from(n, vector<int>(m, -1));\n    queue<pair<int, int>> q;\n    int ex = 0, ey = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = 0; j < m; j++) {\n            if (g[i][j] == 'A') { q.push({i, j}); from[i][j] = 4; }\n            if (g[i][j] == 'B') ex = i, ey = j;\n        }\n    // BFS: la primera vez que se llega a una celda es por un camino más corto\n    while (!q.empty()) {\n        auto [x, y] = q.front();\n        q.pop();\n        for (int d = 0; d < 4; d++) {\n            int a = x + dx[d], b = y + dy[d];\n            if (a < 0 || b < 0 || a >= n || b >= m || g[a][b] == '#' || from[a][b] != -1) continue;\n            from[a][b] = d;\n            q.push({a, b});\n        }\n    }\n    if (from[ex][ey] == -1) { cout << \"NO\\n\"; return 0; }\n    // se reconstruye desde B hacia A siguiendo las direcciones al revés\n    string path;\n    for (int x = ex, y = ey; from[x][y] != 4;) {\n        int d = from[x][y];\n        path += name[d];\n        x -= dx[d], y -= dy[d];\n    }\n    reverse(all(path));\n    cout << \"YES\\n\" << path.size() << \"\\n\" << path << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : BFS en cuadrícula con reconstrucción del camino\n * Problema  : CSES 1193 - Labyrinth (https://cses.fi/problemset/task/1193)\n * Entrada   : n m, luego n filas con '.', '#', 'A' (inicio) y 'B' (fin)\n * Salida    : YES, el largo y las direcciones (L, R, U, D) de un camino más corto; o NO\n * Complejidad: tiempo O(n · m), memoria O(n · m)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, m = int(data[0]), int(data[1])\n    # cuadrícula aplanada con un borde de pared alrededor\n    W = m + 2\n    grid = bytearray(b'#' * (W * (n + 2)))\n    for i in range(n):\n        base = (i + 1) * W + 1\n        grid[base:base + m] = data[2 + i]\n    s, e = grid.index(b'A'), grid.index(b'B')\n    moves = ((-1, 'L'), (1, 'R'), (-W, 'U'), (W, 'D'))\n    # frm[v] = índice de la dirección con la que se llegó a v (4 = inicio, 255 = sin visitar)\n    frm = bytearray(b'\\xff' * len(grid))\n    frm[s] = 4\n    q = [s]\n    # BFS por niveles: la primera vez que se llega a una celda es por un camino más corto\n    for v in q:\n        if v == e:\n            break\n        for k in range(4):\n            u = v + moves[k][0]\n            if frm[u] == 255 and grid[u] != 35:  # 35 = '#'\n                frm[u] = k\n                q.append(u)\n    if frm[e] == 255:\n        print('NO')\n        return\n    # reconstruir desde B hacia A siguiendo las direcciones al revés\n    path = []\n    v = e\n    while frm[v] != 4:\n        d, c = moves[frm[v]]\n        path.append(c)\n        v -= d\n    path.reverse()\n    print('YES')\n    print(len(path))\n    print(''.join(path))\n\n\nmain()\n"}, {"id": "Graphs-Classic-Problems-Longest-Flight-Route", "carpeta": "Graphs", "area": "Grafos", "sub": "Classic Problems", "archivo": "Graphs/Classic Problems/Longest Flight Route.cpp", "nombre": "Longest Flight Route", "algoritmo": "DP sobre un DAG en orden topológico (camino más largo)", "problema": "CSES 1680 - Longest Flight Route (https://cses.fi/problemset/task/1680)", "cses": "https://cses.fi/problemset/task/1680", "py_lento": false, "entrada": "n m, luego m vuelos dirigidos \"a b\" (no hay ciclos)", "salida": "la mayor cantidad de ciudades en una ruta de 1 a n y la ruta; o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP sobre un DAG en orden topológico (camino más largo)\n * Problema  : CSES 1680 - Longest Flight Route (https://cses.fi/problemset/task/1680)\n * Entrada   : n m, luego m vuelos dirigidos \"a b\" (no hay ciclos)\n * Salida    : la mayor cantidad de ciudades en una ruta de 1 a n y la ruta; o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> g(n + 1);\n    vector<int> indeg(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        g[a].push_back(b);\n        indeg[b]++;\n    }\n    // orden topológico con Kahn: cada ciudad sale cuando ya se procesaron todas las que llegan a ella\n    vector<int> order;\n    queue<int> q;\n    for (int v = 1; v <= n; v++) if (!indeg[v]) q.push(v);\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        order.push_back(u);\n        for (int v : g[u]) if (--indeg[v] == 0) q.push(v);\n    }\n    // best[v] = máximo de ciudades de 1 a v (-1 si no se puede llegar), par[v] = ciudad anterior\n    vector<int> best(n + 1, -1), par(n + 1, 0);\n    best[1] = 1;\n    for (int u : order) {\n        if (best[u] < 0) continue;\n        for (int v : g[u])\n            if (best[u] + 1 > best[v]) best[v] = best[u] + 1, par[v] = u;\n    }\n    if (best[n] < 0) { cout << \"IMPOSSIBLE\\n\"; return 0; }\n    vector<int> path;\n    for (int v = n; v != 1; v = par[v]) path.push_back(v);\n    path.push_back(1);\n    reverse(all(path));\n    cout << path.size() << \"\\n\";\n    for (int v : path) cout << v << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP sobre un DAG en orden topológico (camino más largo)\n * Problema  : CSES 1680 - Longest Flight Route (https://cses.fi/problemset/task/1680)\n * Entrada   : n m, luego m vuelos dirigidos \"a b\" (no hay ciclos)\n * Salida    : la mayor cantidad de ciudades en una ruta de 1 a n y la ruta; o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, m = int(data[0]), int(data[1])\n    g = [[] for _ in range(n + 1)]\n    indeg = [0] * (n + 1)\n    e = list(map(int, data[2:2 + 2 * m]))\n    for i in range(0, 2 * m, 2):\n        g[e[i]].append(e[i + 1])\n        indeg[e[i + 1]] += 1\n    # orden topológico con Kahn\n    order = [v for v in range(1, n + 1) if indeg[v] == 0]\n    for u in order:\n        for v in g[u]:\n            indeg[v] -= 1\n            if indeg[v] == 0:\n                order.append(v)\n    # best[v] = máximo de ciudades de 1 a v (-1 si no se puede llegar), par[v] = ciudad anterior\n    best = [-1] * (n + 1)\n    par = [0] * (n + 1)\n    best[1] = 1\n    for u in order:\n        bu = best[u]\n        if bu < 0:\n            continue\n        for v in g[u]:\n            if bu + 1 > best[v]:\n                best[v] = bu + 1\n                par[v] = u\n    if best[n] < 0:\n        print('IMPOSSIBLE')\n        return\n    path = [n]\n    while path[-1] != 1:\n        path.append(par[path[-1]])\n    path.reverse()\n    print(len(path))\n    print(*path)\n\n\nmain()\n"}, {"id": "Graphs-Classic-Problems-Subordinates", "carpeta": "Graphs", "area": "Grafos", "sub": "Classic Problems", "archivo": "Graphs/Classic Problems/Subordinates.cpp", "nombre": "Subordinates", "algoritmo": "Tamaños de subárbol en un árbol con raíz", "problema": "CSES 1674 - Subordinates (https://cses.fi/problemset/task/1674)", "cses": "https://cses.fi/problemset/task/1674", "py_lento": false, "entrada": "n, luego el jefe directo de cada empleado 2..n", "salida": "para cada empleado, la cantidad de subordinados (tamaño de su subárbol menos 1)", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Tamaños de subárbol en un árbol con raíz\n * Problema  : CSES 1674 - Subordinates (https://cses.fi/problemset/task/1674)\n * Entrada   : n, luego el jefe directo de cada empleado 2..n\n * Salida    : para cada empleado, la cantidad de subordinados (tamaño de su subárbol menos 1)\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<int> boss(n + 1, 0);\n    vector<vector<int>> kids(n + 1);\n    for (int i = 2; i <= n; i++) {\n        cin >> boss[i];\n        kids[boss[i]].push_back(i);\n    }\n    // orden BFS desde el director: todo jefe aparece antes que sus subordinados\n    vector<int> order = {1};\n    for (int k = 0; k < (int)order.size(); k++)\n        for (int v : kids[order[k]]) order.push_back(v);\n    // se recorre al revés: cuando se procesa a alguien, sus subordinados ya están contados\n    vector<int> sub(n + 1, 0);\n    for (int k = n - 1; k >= 1; k--) {\n        int v = order[k];\n        sub[boss[v]] += sub[v] + 1;\n    }\n    for (int v = 1; v <= n; v++) cout << sub[v] << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Tamaños de subárbol en un árbol con raíz\n * Problema  : CSES 1674 - Subordinates (https://cses.fi/problemset/task/1674)\n * Entrada   : n, luego el jefe directo de cada empleado 2..n\n * Salida    : para cada empleado, la cantidad de subordinados (tamaño de su subárbol menos 1)\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    boss = [0, 0] + list(map(int, data[1:n]))\n    kids = [[] for _ in range(n + 1)]\n    for v in range(2, n + 1):\n        kids[boss[v]].append(v)\n    # orden BFS desde el director: todo jefe aparece antes que sus subordinados\n    order = [1]\n    for u in order:\n        order.extend(kids[u])\n    # al revés: cuando se procesa a alguien, sus subordinados ya están contados\n    sub = [0] * (n + 1)\n    for v in reversed(order[1:]):\n        sub[boss[v]] += sub[v] + 1\n    print(*sub[1:])\n\n\nmain()\n"}, {"id": "Strings-Algorithms-KMP-I", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/KMP-I.cpp", "nombre": "KMP-I", "algoritmo": "KMP con prefix-function sobre patrón + '#' + texto", "problema": "CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)", "cses": "https://cses.fi/problemset/task/1753", "py_lento": false, "entrada": "texto s y luego patrón t", "salida": "cantidad de apariciones de t en s", "complejidad": "tiempo O(|s| + |t|), memoria O(|s| + |t|)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : KMP con prefix-function sobre patrón + '#' + texto\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|s| + |t|)\n */\n\n// LP[i] = longitud del mayor prefijo que también es sufijo de s[0..i]\nvector<int> KMP(const string &s) {\n    vector<int> LP(s.size(), 0);\n    for (int i = 1; i < (int)s.size(); i++) {\n        int j = LP[i - 1];\n        while (j > 0 && s[i] != s[j]) j = LP[j - 1];\n        if (s[i] == s[j]) j++;\n        LP[i] = j;\n    }\n    return LP;\n}\n\n// posiciones (base 0) de t dentro de s\n// se concatena t + \"#\" + s: un valor |t| en LP marca una aparición\nvector<int> PatternSearch(const string &s, const string &t) {\n    vector<int> pos;\n    string combined = t + '#' + s;\n    vector<int> lps = KMP(combined);\n    for (int i = t.size() + 1; i < (int)lps.size(); i++)\n        if (lps[i] == (int)t.size())\n            pos.push_back(i - 2 * t.size());\n    return pos;\n}\n\nint main() {\n    fastio;\n    string s, t;\n    cin >> s >> t;\n    cout << PatternSearch(s, t).size() << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : KMP con prefix-function sobre patrón + '#' + texto\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|s| + |t|)\n\"\"\"\n\n\n# LP[i] = longitud del mayor prefijo que también es sufijo de s[0..i]\ndef KMP(s):\n    LP = [0] * len(s)\n    for i in range(1, len(s)):\n        j = LP[i - 1]\n        while j > 0 and s[i] != s[j]:\n            j = LP[j - 1]\n        if s[i] == s[j]:\n            j += 1\n        LP[i] = j\n    return LP\n\n\n# se concatena t + \"#\" + s: un valor |t| en LP marca una aparición\ndef pattern_search(s, t):\n    lps = KMP(t + '#' + s)\n    m = len(t)\n    return [i - 2 * m for i in range(m + 1, len(lps)) if lps[i] == m]\n\n\ndef main():\n    s = input().strip()\n    t = input().strip()\n    print(len(pattern_search(s, t)))\n\n\nmain()\n"}, {"id": "Strings-Algorithms-KMP-II", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/KMP-II.cpp", "nombre": "KMP-II", "algoritmo": "KMP con prefix-function solo del patrón", "problema": "CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)", "cses": "https://cses.fi/problemset/task/1753", "py_lento": false, "entrada": "texto s y luego patrón t", "salida": "cantidad de apariciones de t en s", "complejidad": "tiempo O(|s| + |t|), memoria O(|t|)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : KMP con prefix-function solo del patrón\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|t|)\n */\n\n// LP[i] = longitud del mayor prefijo que también es sufijo de s[0..i]\nvector<int> KMP(const string &s) {\n    vector<int> LP(s.size(), 0);\n    for (int i = 1; i < (int)s.size(); i++) {\n        int j = LP[i - 1];\n        while (j > 0 && s[i] != s[j]) j = LP[j - 1];\n        if (s[i] == s[j]) j++;\n        LP[i] = j;\n    }\n    return LP;\n}\n\n// posiciones (base 0) de pattern dentro de text\n// recorre el texto reutilizando LP del patrón para no retroceder\nvector<int> PatternSearch(const string &text, const string &pattern) {\n    vector<int> lp = KMP(pattern);\n    vector<int> result;\n    int j = 0;\n    for (int i = 0; i < (int)text.size(); i++) {\n        while (j > 0 && text[i] != pattern[j]) j = lp[j - 1];\n        if (text[i] == pattern[j]) j++;\n        // coincidencia completa; se sigue con el borde más largo\n        if (j == (int)pattern.size()) {\n            result.push_back(i - pattern.size() + 1);\n            j = lp[j - 1];\n        }\n    }\n    return result;\n}\n\nint main() {\n    fastio;\n    string s, t;\n    cin >> s >> t;\n    cout << PatternSearch(s, t).size() << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : KMP con prefix-function solo del patrón\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|t|)\n\"\"\"\n\n\n# LP[i] = longitud del mayor prefijo que también es sufijo de s[0..i]\ndef KMP(s):\n    LP = [0] * len(s)\n    for i in range(1, len(s)):\n        j = LP[i - 1]\n        while j > 0 and s[i] != s[j]:\n            j = LP[j - 1]\n        if s[i] == s[j]:\n            j += 1\n        LP[i] = j\n    return LP\n\n\n# recorre el texto reutilizando LP del patrón para no retroceder\ndef pattern_search(text, pattern):\n    lp = KMP(pattern)\n    res = []\n    j = 0\n    for i, c in enumerate(text):\n        while j > 0 and c != pattern[j]:\n            j = lp[j - 1]\n        if c == pattern[j]:\n            j += 1\n        # coincidencia completa; se sigue con el borde más largo\n        if j == len(pattern):\n            res.append(i - len(pattern) + 1)\n            j = lp[j - 1]\n    return res\n\n\ndef main():\n    s = input().strip()\n    t = input().strip()\n    print(len(pattern_search(s, t)))\n\n\nmain()\n"}, {"id": "Strings-Algorithms-Manacher", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/Manacher.cpp", "nombre": "Manacher", "algoritmo": "Manacher (subcadena palíndroma más larga)", "problema": "CSES 1111 - Longest Palindrome (https://cses.fi/problemset/task/1111)", "cses": "https://cses.fi/problemset/task/1111", "py_lento": false, "entrada": "una cadena s", "salida": "la subcadena palíndroma más larga", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Manacher (subcadena palíndroma más larga)\n * Problema  : CSES 1111 - Longest Palindrome (https://cses.fi/problemset/task/1111)\n * Entrada   : una cadena s\n * Salida    : la subcadena palíndroma más larga\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\n// d1[i] = radio de palíndromos impares centrados en i, d2[i] = radio de los pares\nstring longestPalindrome(const string &s) {\n    int n = s.size();\n    // d1 = radios de palíndromos impares, d2 = radios de los pares (centro entre dos letras)\n    vector<int> d1(n), d2(n);\n    for (int i = 0, l = 0, r = -1; i < n; i++) {\n        // se reutiliza el palíndromo simétrico dentro de [l, r]\n        int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);\n        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) k++;\n        d1[i] = k--;\n        if (i + k > r) l = i - k, r = i + k;\n    }\n    for (int i = 0, l = 0, r = -1; i < n; i++) {\n        int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);\n        while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) k++;\n        d2[i] = k--;\n        if (i + k > r) l = i - k - 1, r = i + k;\n    }\n\n    // se elige el más largo entre impares y pares\n    int best = 0, start = 0;\n    for (int i = 0; i < n; i++) {\n        if (2 * d1[i] - 1 > best) best = 2 * d1[i] - 1, start = i - d1[i] + 1;\n        if (2 * d2[i] > best) best = 2 * d2[i], start = i - d2[i];\n    }\n    return s.substr(start, best);\n}\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    cout << longestPalindrome(s) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Manacher (subcadena palíndroma más larga)\n * Problema  : CSES 1111 - Longest Palindrome (https://cses.fi/problemset/task/1111)\n * Entrada   : una cadena s\n * Salida    : la subcadena palíndroma más larga\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\n# d1 = radios de palíndromos impares, d2 = radios de los pares (centro entre dos letras)\ndef longest_palindrome(s):\n    n = len(s)\n    d1, d2 = [0] * n, [0] * n\n    l, r = 0, -1\n    for i in range(n):\n        # se reutiliza el palíndromo simétrico dentro de [l, r]\n        k = 1 if i > r else min(d1[l + r - i], r - i + 1)\n        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:\n            k += 1\n        d1[i] = k\n        k -= 1\n        if i + k > r:\n            l, r = i - k, i + k\n    l, r = 0, -1\n    for i in range(n):\n        k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)\n        while i - k - 1 >= 0 and i + k < n and s[i - k - 1] == s[i + k]:\n            k += 1\n        d2[i] = k\n        k -= 1\n        if i + k > r:\n            l, r = i - k - 1, i + k\n\n    # se elige el más largo entre impares y pares\n    best = start = 0\n    for i in range(n):\n        if 2 * d1[i] - 1 > best:\n            best, start = 2 * d1[i] - 1, i - d1[i] + 1\n        if 2 * d2[i] > best:\n            best, start = 2 * d2[i], i - d2[i]\n    return s[start:start + best]\n\n\ndef main():\n    print(longest_palindrome(input().strip()))\n\n\nmain()\n"}, {"id": "Strings-Algorithms-MinimalRotation", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/MinimalRotation.cpp", "nombre": "MinimalRotation", "algoritmo": "Rotación lexicográficamente mínima (algoritmo de Booth/Duval)", "problema": "CSES 1110 - Minimal Rotation (https://cses.fi/problemset/task/1110)", "cses": "https://cses.fi/problemset/task/1110", "py_lento": false, "entrada": "una cadena s", "salida": "la rotación lexicográficamente mínima de s", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Rotación lexicográficamente mínima (algoritmo de Booth/Duval)\n * Problema  : CSES 1110 - Minimal Rotation (https://cses.fi/problemset/task/1110)\n * Entrada   : una cadena s\n * Salida    : la rotación lexicográficamente mínima de s\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\n// índice de inicio de la rotación mínima\nint minimalRotation(const string &s) {\n    // la rotación mínima es una subcadena de s + s\n    string t = s + s;\n    int n = s.size(), i = 0, j = 1, k = 0;\n    // se comparan dos candidatos i y j; el peor se descarta saltando k + 1 posiciones\n    while (i < n && j < n && k < n) {\n        char a = t[i + k], b = t[j + k];\n        if (a == b) { k++; continue; }\n        if (a > b) i += k + 1;\n        else j += k + 1;\n        if (i == j) j++;\n        k = 0;\n    }\n    // el candidato que sobrevive\n    return min(i, j);\n}\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    int p = minimalRotation(s);\n    cout << s.substr(p) + s.substr(0, p) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Rotación lexicográficamente mínima (algoritmo de Booth/Duval)\n * Problema  : CSES 1110 - Minimal Rotation (https://cses.fi/problemset/task/1110)\n * Entrada   : una cadena s\n * Salida    : la rotación lexicográficamente mínima de s\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\n# índice de inicio de la rotación mínima\ndef minimal_rotation(s):\n    # la rotación mínima es una subcadena de s + s\n    t = s + s\n    n = len(s)\n    i, j, k = 0, 1, 0\n    # se comparan dos candidatos i y j; el peor se descarta saltando k + 1 posiciones\n    while i < n and j < n and k < n:\n        a, b = t[i + k], t[j + k]\n        if a == b:\n            k += 1\n            continue\n        if a > b:\n            i += k + 1\n        else:\n            j += k + 1\n        if i == j:\n            j += 1\n        k = 0\n    # el candidato que sobrevive\n    return min(i, j)\n\n\ndef main():\n    s = input().strip()\n    p = minimal_rotation(s)\n    print(s[p:] + s[:p])\n\n\nmain()\n"}, {"id": "Strings-Algorithms-PrefixTrie", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/PrefixTrie.cpp", "nombre": "PrefixTrie", "algoritmo": "Trie (prefix tree) + DP de conteo de formas", "problema": "CSES 1731 - Word Combinations (https://cses.fi/problemset/task/1731)", "cses": "https://cses.fi/problemset/task/1731", "py_lento": false, "entrada": "cadena s, k, luego k palabras", "salida": "cantidad de formas de construir s con las palabras, módulo 10^9+7", "complejidad": "tiempo O(|s|^2 + suma de longitudes), memoria O(suma de longitudes)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Trie (prefix tree) + DP de conteo de formas\n * Problema  : CSES 1731 - Word Combinations (https://cses.fi/problemset/task/1731)\n * Entrada   : cadena s, k, luego k palabras\n * Salida    : cantidad de formas de construir s con las palabras, módulo 10^9+7\n * Complejidad: tiempo O(|s|^2 + suma de longitudes), memoria O(suma de longitudes)\n */\n\nconst int MODW = 1000000007;  // este problema pide módulo 10^9+7\n\n// cada nodo tiene un hijo por letra y marca si termina una palabra\nstruct Node {\n    int children[26];\n    bool flag = false;\n\n    Node() {\n        fill(begin(children), end(children), -1);\n    }\n};\n\n// árbol de prefijos\nstruct Trie {\n    vector<Node> Tree;\n    Trie() {\n        Tree.emplace_back();\n    }\n\n    // inserta una palabra letra por letra\n    void insert(const string &word) {\n        int v = 0;\n        for (char ch : word) {\n            int code = ch - 'a';\n            if (Tree[v].children[code] == -1) {\n                Tree[v].children[code] = Tree.size();\n                Tree.emplace_back();\n            }\n            v = Tree[v].children[code];\n        }\n        Tree[v].flag = true;\n    }\n\n    // la palabra existe si el camino existe y termina marcada\n    bool search(const string &word) {\n        int v = 0;\n        for (char ch : word) {\n            int code = ch - 'a';\n            if (Tree[v].children[code] == -1) return false;\n            v = Tree[v].children[code];\n        }\n        return Tree[v].flag;\n    }\n\n    // basta con que exista el camino del prefijo\n    bool startsWith(const string &prefix) {\n        int v = 0;\n        for (char ch : prefix) {\n            int code = ch - 'a';\n            if (Tree[v].children[code] == -1) return false;\n            v = Tree[v].children[code];\n        }\n        return true;\n    }\n};\n\nint main() {\n    fastio;\n    string s;\n    int k;\n    cin >> s >> k;\n    Trie PrefixTrie;\n    for (int i = 0; i < k; i++) {\n        string w;\n        cin >> w;\n        PrefixTrie.insert(w);\n    }\n\n    // dp[i] = formas de construir el sufijo s[i..]\n    int n = s.size();\n    // dp[i] = formas de construir el sufijo s[i..]\n    vector<ll> dp(n + 1, 0);\n    dp[n] = 1;\n    // desde cada posición se baja por el trie y cada palabra completa suma dp[j + 1]\n    for (int i = n - 1; i >= 0; i--) {\n        int v = 0;\n        for (int j = i; j < n; j++) {\n            int code = s[j] - 'a';\n            if (PrefixTrie.Tree[v].children[code] == -1) break;\n            v = PrefixTrie.Tree[v].children[code];\n            if (PrefixTrie.Tree[v].flag) dp[i] = (dp[i] + dp[j + 1]) % MODW;\n        }\n    }\n    cout << dp[0] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Trie (prefix tree) + DP de conteo de formas\n * Problema  : CSES 1731 - Word Combinations (https://cses.fi/problemset/task/1731)\n * Entrada   : cadena s, k, luego k palabras\n * Salida    : cantidad de formas de construir s con las palabras, módulo 10^9+7\n * Complejidad: tiempo O(|s|^2 + suma de longitudes), memoria O(suma de longitudes)\n\"\"\"\n\n\nMODW = 1000000007  # este problema pide módulo 10^9+7\n\n\n# árbol de prefijos: cada arista (nodo, letra) se guarda en un solo diccionario\n# con clave nodo * 32 + letra; flag marca los nodos donde termina una palabra\nclass Trie:\n    def __init__(self):\n        self.child = {}\n        self.flag = [False]\n\n    # inserta una palabra letra por letra\n    def insert(self, word):\n        v = 0\n        for ch in word:\n            key = v * 32 + ch - 96\n            nxt = self.child.get(key)\n            if nxt is None:\n                nxt = len(self.flag)\n                self.child[key] = nxt\n                self.flag.append(False)\n            v = nxt\n        self.flag[v] = True\n\n    # la palabra existe si el camino existe y termina marcada\n    def search(self, word):\n        v = 0\n        for ch in word:\n            v = self.child.get(v * 32 + ch - 96)\n            if v is None:\n                return False\n        return self.flag[v]\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    s = data[0]\n    k = int(data[1])\n    trie = Trie()\n    for w in data[2:2 + k]:\n        trie.insert(w)\n\n    # dp[i] = formas de construir el sufijo s[i..]\n    n = len(s)\n    dp = [0] * (n + 1)\n    dp[n] = 1\n    child, flag = trie.child, trie.flag\n    # desde cada posición se baja por el trie y cada palabra completa suma dp[j + 1]\n    for i in range(n - 1, -1, -1):\n        v = 0\n        total = 0\n        for j in range(i, n):\n            v = child.get(v * 32 + s[j] - 96)\n            if v is None:\n                break\n            if flag[v]:\n                total += dp[j + 1]\n        dp[i] = total % MODW\n    print(dp[0])\n\n\nmain()\n"}, {"id": "Strings-Algorithms-RabinKarp", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/RabinKarp.cpp", "nombre": "RabinKarp", "algoritmo": "Rabin-Karp con doble hash polinomial", "problema": "CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)", "cses": "https://cses.fi/problemset/task/1753", "py_lento": false, "entrada": "texto s y luego patrón t (letras minúsculas)", "salida": "cantidad de apariciones de t en s", "complejidad": "tiempo O(|s| + |t|) esperado, memoria O(|s|)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Rabin-Karp con doble hash polinomial\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t (letras minúsculas)\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|) esperado, memoria O(|s|)\n */\n\n// dos módulos y una base para reducir colisiones\nll P1 = 1000000007;\nll P2 = 998244353;\nll base = 60;\n\n// Pot[i] = base^i mod P\nvector<ll> Pot1(1000003, 1);\nvector<ll> Pot2(1000003, 1);\n\nll code(char a) {\n    return (ll)a - (ll)'a' + 1;\n}\n\nll mod(ll x, ll n) {\n    return (x % n + n) % n;\n}\n\n// hash polinomial de una cadena junto con su tamaño\nstruct Hash {\n    ll hash_1, hash_2, size;\n\n    Hash() { hash_1 = 0, hash_2 = 0, size = 0; }\n    Hash(ll h1, ll h2, ll s) { hash_1 = h1; hash_2 = h2; size = s; }\n    Hash(char s) { hash_1 = code(s), hash_2 = code(s), size = 1; }\n\n    // concatenación de dos hashes\n    Hash operator+(const Hash &other) const {\n        return Hash(mod(hash_1 * Pot1[other.size] + other.hash_1, P1),\n                    mod(hash_2 * Pot2[other.size] + other.hash_2, P2),\n                    size + other.size);\n    }\n\n    // quita un prefijo (hash del sufijo)\n    Hash operator-(const Hash &other) const {\n        return Hash(mod(hash_1 - other.hash_1 * Pot1[size - other.size], P1),\n                    mod(hash_2 - other.hash_2 * Pot2[size - other.size], P2),\n                    size - other.size);\n    }\n\n    bool operator==(const Hash &other) const {\n        return hash_1 == other.hash_1 && hash_2 == other.hash_2;\n    }\n};\n\nint main() {\n    fastio;\n    // potencias precalculadas\n    for (int i = 1; i < (int)Pot1.size(); i++) {\n        Pot1[i] = (base * Pot1[i - 1]) % P1;\n        Pot2[i] = (base * Pot2[i - 1]) % P2;\n    }\n\n    string s1, s2;\n    cin >> s1 >> s2;\n    if (s2.size() > s1.size()) {\n        cout << 0 << \"\\n\";\n        return 0;\n    }\n\n    // text[i] = hash del prefijo s1[0..i]\n    // text[i] = hash del prefijo s1[0..i]\n    vector<Hash> text;\n    text.push_back(Hash(s1.front()));\n    for (int i = 1; i < (int)s1.size(); i++)\n        text.push_back(text.back() + Hash(s1[i]));\n\n    Hash pattern;\n    for (auto c : s2) pattern = pattern + Hash(c);\n\n    int count = 0;\n    // se compara el hash de cada ventana con el del patrón\n    for (int i = 0; i + s2.size() <= s1.size(); i++) {\n        Hash search;\n        if (i == 0) search = text[s2.size() - 1];\n        else search = text[i + s2.size() - 1] - text[i - 1];\n        if (search == pattern) count++;\n    }\n    cout << count << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Rabin-Karp con doble hash polinomial\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t (letras minúsculas)\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|) esperado, memoria O(|s|)\n\"\"\"\n\n\n# dos módulos y una base para reducir colisiones\nP1, P2, BASE = 1000000007, 998244353, 60\n\n\ndef main():\n    s1 = input().strip()\n    s2 = input().strip()\n    n, m = len(s1), len(s2)\n    if m > n:\n        print(0)\n        return\n    code = lambda c: ord(c) - ord('a') + 1\n\n    # h[i] = hash del prefijo s1[0..i) y pw[i] = BASE^i, para los dos módulos\n    h1, h2 = [0] * (n + 1), [0] * (n + 1)\n    pw1, pw2 = [1] * (n + 1), [1] * (n + 1)\n    for i, c in enumerate(s1):\n        h1[i + 1] = (h1[i] * BASE + code(c)) % P1\n        h2[i + 1] = (h2[i] * BASE + code(c)) % P2\n        pw1[i + 1] = pw1[i] * BASE % P1\n        pw2[i + 1] = pw2[i] * BASE % P2\n\n    # hash del patrón\n    t1 = t2 = 0\n    for c in s2:\n        t1 = (t1 * BASE + code(c)) % P1\n        t2 = (t2 * BASE + code(c)) % P2\n\n    # se compara el hash de cada ventana con el del patrón (quitar un prefijo = restar su hash)\n    count = 0\n    for i in range(n - m + 1):\n        if (h1[i + m] - h1[i] * pw1[m]) % P1 == t1 and (h2[i + m] - h2[i] * pw2[m]) % P2 == t2:\n            count += 1\n    print(count)\n\n\nmain()\n"}, {"id": "Strings-Algorithms-SuffixArray", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/SuffixArray.cpp", "nombre": "SuffixArray", "algoritmo": "Suffix Array (duplicación de prefijos) + LCP de Kasai", "problema": "CSES 2105 - Distinct Substrings (https://cses.fi/problemset/task/2105)", "cses": "https://cses.fi/problemset/task/2105", "py_lento": false, "entrada": "una cadena s", "salida": "cantidad de subcadenas distintas de s", "complejidad": "tiempo O(n log^2 n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Suffix Array (duplicación de prefijos) + LCP de Kasai\n * Problema  : CSES 2105 - Distinct Substrings (https://cses.fi/problemset/task/2105)\n * Entrada   : una cadena s\n * Salida    : cantidad de subcadenas distintas de s\n * Complejidad: tiempo O(n log^2 n), memoria O(n)\n */\n\n// sa = sufijos ordenados; rnk[i] = posición del sufijo i en ese orden\nvector<int> suffixArray(const string &s) {\n    int n = s.size();\n    vector<int> sa(n), rnk(n), tmp(n);\n    iota(all(sa), 0);\n    for (int i = 0; i < n; i++) rnk[i] = s[i];\n    // duplicación de prefijos: se ordena por los primeros k y luego 2k caracteres\n    for (int k = 1;; k <<= 1) {\n        auto cmp = [&](int a, int b) {\n            if (rnk[a] != rnk[b]) return rnk[a] < rnk[b];\n            int ra = a + k < n ? rnk[a + k] : -1;\n            int rb = b + k < n ? rnk[b + k] : -1;\n            return ra < rb;\n        };\n        sort(all(sa), cmp);\n        tmp[sa[0]] = 0;\n        for (int i = 1; i < n; i++) tmp[sa[i]] = tmp[sa[i - 1]] + cmp(sa[i - 1], sa[i]);\n        rnk = tmp;\n        if (rnk[sa[n - 1]] == n - 1) break;\n    }\n    return sa;\n}\n\n// lcp[i] = prefijo común entre sa[i] y sa[i + 1]\n// lcp[i] = prefijo común entre sa[i] y sa[i + 1] (Kasai)\nvector<int> kasai(const string &s, const vector<int> &sa) {\n    int n = s.size();\n    vector<int> rnk(n), lcp(max(0, n - 1));\n    for (int i = 0; i < n; i++) rnk[sa[i]] = i;\n    for (int i = 0, h = 0; i < n; i++) {\n        if (rnk[i] + 1 < n) {\n            int j = sa[rnk[i] + 1];\n            while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;\n            lcp[rnk[i]] = h;\n            if (h > 0) h--;\n        }\n        else h = 0;\n    }\n    return lcp;\n}\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    ll n = s.size();\n    auto sa = suffixArray(s);\n    auto lcp = kasai(s, sa);\n\n    // subcadenas distintas = todas las subcadenas - prefijos repetidos\n    // cada sufijo aporta (largo) subcadenas; se restan las que ya aparecieron (lcp)\n    ll total = n * (n + 1) / 2;\n    for (int x : lcp) total -= x;\n    cout << total << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Suffix Array (duplicación de prefijos) + LCP de Kasai\n * Problema  : CSES 2105 - Distinct Substrings (https://cses.fi/problemset/task/2105)\n * Entrada   : una cadena s\n * Salida    : cantidad de subcadenas distintas de s\n * Complejidad: tiempo O(n log^2 n), memoria O(n)\n\"\"\"\n\n\n# sa = sufijos ordenados; rnk[i] = posición del sufijo i en ese orden\ndef suffix_array(s):\n    n = len(s)\n    sa = list(range(n))\n    rnk = [ord(c) for c in s]\n    k = 1\n    # duplicación de prefijos: se ordena por los primeros k y luego 2k caracteres\n    while True:\n        key = [rnk[i] * (n + 1) + (rnk[i + k] + 1 if i + k < n else 0) for i in range(n)]\n        sa.sort(key=key.__getitem__)\n        tmp = [0] * n\n        for idx in range(1, n):\n            tmp[sa[idx]] = tmp[sa[idx - 1]] + (key[sa[idx]] != key[sa[idx - 1]])\n        rnk = tmp\n        if rnk[sa[-1]] == n - 1:\n            break\n        k <<= 1\n    return sa\n\n\n# lcp[i] = prefijo común entre sa[i] y sa[i + 1] (Kasai)\ndef kasai(s, sa):\n    n = len(s)\n    rnk = [0] * n\n    for i, p in enumerate(sa):\n        rnk[p] = i\n    lcp = [0] * max(0, n - 1)\n    h = 0\n    for i in range(n):\n        if rnk[i] + 1 < n:\n            j = sa[rnk[i] + 1]\n            while i + h < n and j + h < n and s[i + h] == s[j + h]:\n                h += 1\n            lcp[rnk[i]] = h\n            if h > 0:\n                h -= 1\n        else:\n            h = 0\n    return lcp\n\n\ndef main():\n    s = input().strip()\n    n = len(s)\n    sa = suffix_array(s)\n    # cada sufijo aporta (largo) subcadenas; se restan las que ya aparecieron (lcp)\n    print(n * (n + 1) // 2 - sum(kasai(s, sa)))\n\n\nmain()\n"}, {"id": "Strings-Algorithms-ZFunction", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/ZFunction.cpp", "nombre": "ZFunction", "algoritmo": "Z-function", "problema": "CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)", "cses": "https://cses.fi/problemset/task/1753", "py_lento": false, "entrada": "dos líneas: el texto s y el patrón t", "salida": "número de apariciones de t en s", "complejidad": "tiempo O(|s| + |t|), memoria O(|s| + |t|)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Z-function\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : dos líneas: el texto s y el patrón t\n * Salida    : número de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|s| + |t|)\n */\n\n// z[i] = longitud del prefijo comun mas largo entre s y s[i..]\nvector<int> z_function(const string &s) {\n    int n = s.size();\n    vector<int> z(n, 0);\n    for (int i = 1, l = 0, r = 0; i < n; i++) {\n        // dentro del intervalo [l, r) ya hay información reutilizable\n        if (i < r) z[i] = min(r - i, z[i - l]);\n        // se extiende comparando caracter a caracter\n        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;\n        // se actualiza el intervalo más a la derecha\n        if (i + z[i] > r) l = i, r = i + z[i];\n    }\n    return z;\n}\n\nint main() {\n    fastio;\n    string s, t;\n    cin >> s >> t;\n\n    // ocurrencias de t en s: z sobre t + '#' + s\n    string combined = t + '#' + s;\n    vector<int> z = z_function(combined);\n\n    ll count = 0;\n    for (int i = t.size() + 1; i < (int)combined.size(); i++)\n        // coincidencia completa del patrón en esa posición\n        if (z[i] == (int)t.size()) count++;\n\n    cout << count << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Z-function\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : dos líneas: el texto s y el patrón t\n * Salida    : número de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|s| + |t|)\n\"\"\"\n\n\n# z[i] = longitud del prefijo común más largo entre s y s[i:]\ndef z_function(s):\n    n = len(s)\n    z = [0] * n\n    l = r = 0\n    for i in range(1, n):\n        # dentro del intervalo [l, r) ya hay información reutilizable\n        if i < r:\n            z[i] = min(r - i, z[i - l])\n        # se extiende comparando carácter a carácter\n        while i + z[i] < n and s[z[i]] == s[i + z[i]]:\n            z[i] += 1\n        # se actualiza el intervalo más a la derecha\n        if i + z[i] > r:\n            l, r = i, i + z[i]\n    return z\n\n\ndef main():\n    s = input().strip()\n    t = input().strip()\n    combined = t + '#' + s\n    z = z_function(combined)\n    # coincidencia completa del patrón en esa posición\n    print(sum(1 for i in range(len(t) + 1, len(combined)) if z[i] == len(t)))\n\n\nmain()\n"}, {"id": "Strings-Classic-Problems-Distinct-Subsequences", "carpeta": "Strings", "area": "Cadenas", "sub": "Classic Problems", "archivo": "Strings/Classic Problems/Distinct Subsequences.cpp", "nombre": "Distinct Subsequences", "algoritmo": "DP para contar subsecuencias distintas", "problema": "CSES 1149 - Distinct Subsequences (https://cses.fi/problemset/task/1149)", "cses": "https://cses.fi/problemset/task/1149", "py_lento": false, "entrada": "una cadena de largo n", "salida": "cantidad de subsecuencias distintas no vacías, módulo 10^9+7", "complejidad": "tiempo O(n), memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP para contar subsecuencias distintas\n * Problema  : CSES 1149 - Distinct Subsequences (https://cses.fi/problemset/task/1149)\n * Entrada   : una cadena de largo n\n * Salida    : cantidad de subsecuencias distintas no vacías, módulo 10^9+7\n * Complejidad: tiempo O(n), memoria O(1)\n */\n\nconst ll M = 1e9 + 7;\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    // total = subsecuencias distintas (incluida la vacía) del prefijo leído\n    // last[c] = valor de total justo antes de la última vez que apareció c\n    ll total = 1;\n    vector<ll> last(26, 0);\n    for (char ch : s) {\n        int c = ch - 'a';\n        // cada subsecuencia puede o no terminar con este caracter: se duplica el total,\n        // pero las que ya terminaban en c se habrían contado dos veces\n        ll nuevo = (2 * total - last[c] + M) % M;\n        last[c] = total;\n        total = nuevo;\n    }\n    cout << (total - 1 + M) % M << \"\\n\";  // se quita la subsecuencia vacía\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP para contar subsecuencias distintas\n * Problema  : CSES 1149 - Distinct Subsequences (https://cses.fi/problemset/task/1149)\n * Entrada   : una cadena de largo n\n * Salida    : cantidad de subsecuencias distintas no vacías, módulo 10^9+7\n * Complejidad: tiempo O(n), memoria O(1)\n\"\"\"\n\nM = 10**9 + 7\n\n\ndef main():\n    s = sys.stdin.buffer.readline().strip()\n    # total = subsecuencias distintas (incluida la vacía) del prefijo leído\n    # last[c] = valor de total justo antes de la última vez que apareció c\n    total = 1\n    last = [0] * 256\n    for c in s:\n        # se duplica el total, pero las que ya terminaban en c se habrían contado dos veces\n        nuevo = (2 * total - last[c]) % M\n        last[c] = total\n        total = nuevo\n    print((total - 1) % M)  # se quita la subsecuencia vacía\n\n\nmain()\n"}, {"id": "Strings-Classic-Problems-Finding-Borders", "carpeta": "Strings", "area": "Cadenas", "sub": "Classic Problems", "archivo": "Strings/Classic Problems/Finding Borders.cpp", "nombre": "Finding Borders", "algoritmo": "Función de prefijos (KMP) y cadena de bordes", "problema": "CSES 1732 - Finding Borders (https://cses.fi/problemset/task/1732)", "cses": "https://cses.fi/problemset/task/1732", "py_lento": true, "entrada": "una cadena de largo n", "salida": "todos los largos de bordes (prefijo que también es sufijo, sin ser toda la cadena) en orden creciente", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Función de prefijos (KMP) y cadena de bordes\n * Problema  : CSES 1732 - Finding Borders (https://cses.fi/problemset/task/1732)\n * Entrada   : una cadena de largo n\n * Salida    : todos los largos de bordes (prefijo que también es sufijo, sin ser toda la cadena) en orden creciente\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    int n = s.size();\n    // lps[i] = largo del mayor borde de s[0..i]\n    vector<int> lps(n, 0);\n    for (int i = 1; i < n; i++) {\n        int j = lps[i - 1];\n        while (j > 0 && s[i] != s[j]) j = lps[j - 1];\n        if (s[i] == s[j]) j++;\n        lps[i] = j;\n    }\n    // los bordes de s son: el mayor (lps[n-1]), el mayor borde de ese borde, y así sucesivamente\n    vector<int> res;\n    for (int b = lps[n - 1]; b > 0; b = lps[b - 1]) res.push_back(b);\n    reverse(all(res));\n    for (int b : res) cout << b << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Función de prefijos (KMP) y cadena de bordes\n * Problema  : CSES 1732 - Finding Borders (https://cses.fi/problemset/task/1732)\n * Entrada   : una cadena de largo n\n * Salida    : todos los largos de bordes (prefijo que también es sufijo, sin ser toda la cadena) en orden creciente\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    s = sys.stdin.buffer.readline().strip()\n    n = len(s)\n    # pi[i] = largo del mayor borde de s[0..i]\n    pi = [0] * n\n    j = 0\n    for i in range(1, n):\n        c = s[i]\n        while j and c != s[j]:\n            j = pi[j - 1]\n        if c == s[j]:\n            j += 1\n        pi[i] = j\n    # los bordes de s: el mayor (pi[n-1]), el mayor borde de ese borde, y así sucesivamente\n    res = []\n    b = pi[n - 1]\n    while b:\n        res.append(b)\n        b = pi[b - 1]\n    print(*reversed(res))\n\n\nmain()\n"}, {"id": "Strings-Classic-Problems-Finding-Periods", "carpeta": "Strings", "area": "Cadenas", "sub": "Classic Problems", "archivo": "Strings/Classic Problems/Finding Periods.cpp", "nombre": "Finding Periods", "algoritmo": "Función Z (periodos de una cadena)", "problema": "CSES 1733 - Finding Periods (https://cses.fi/problemset/task/1733)", "cses": "https://cses.fi/problemset/task/1733", "py_lento": true, "entrada": "una cadena de largo n", "salida": "todos los largos de periodo en orden creciente", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Función Z (periodos de una cadena)\n * Problema  : CSES 1733 - Finding Periods (https://cses.fi/problemset/task/1733)\n * Entrada   : una cadena de largo n\n * Salida    : todos los largos de periodo en orden creciente\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    int n = s.size();\n    // z[i] = largo del mayor prefijo de s que empieza también en la posición i\n    vector<int> z(n, 0);\n    for (int i = 1, l = 0, r = 0; i < n; i++) {\n        if (i < r) z[i] = min(r - i, z[i - l]);  // se reutiliza lo ya comparado en [l, r)\n        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;\n        if (i + z[i] > r) l = i, r = i + z[i];\n    }\n    // p es periodo si al correr la cadena p posiciones coincide con el prefijo hasta el final\n    for (int p = 1; p < n; p++)\n        if (z[p] == n - p) cout << p << ' ';\n    cout << n << \"\\n\";  // toda la cadena siempre es un periodo\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Función Z (periodos de una cadena)\n * Problema  : CSES 1733 - Finding Periods (https://cses.fi/problemset/task/1733)\n * Entrada   : una cadena de largo n\n * Salida    : todos los largos de periodo en orden creciente\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    s = sys.stdin.buffer.readline().strip()\n    n = len(s)\n    # z[i] = largo del mayor prefijo de s que empieza también en la posición i\n    z = [0] * n\n    l = r = 0\n    for i in range(1, n):\n        k = 0\n        if i < r:\n            k = min(r - i, z[i - l])  # se reutiliza lo ya comparado en [l, r)\n        while i + k < n and s[k] == s[i + k]:\n            k += 1\n        z[i] = k\n        if i + k > r:\n            l, r = i, i + k\n    # p es periodo si al correr la cadena p posiciones coincide con el prefijo hasta el final\n    res = [p for p in range(1, n) if z[p] == n - p]\n    res.append(n)  # toda la cadena siempre es un periodo\n    print(*res)\n\n\nmain()\n"}, {"id": "Strings-Classic-Problems-Repeating-Substring", "carpeta": "Strings", "area": "Cadenas", "sub": "Classic Problems", "archivo": "Strings/Classic Problems/Repeating Substring.cpp", "nombre": "Repeating Substring", "algoritmo": "Suffix Array + LCP (mayor subcadena que se repite)", "problema": "CSES 2106 - Repeating Substring (https://cses.fi/problemset/task/2106)", "cses": "https://cses.fi/problemset/task/2106", "py_lento": false, "entrada": "una cadena de largo n", "salida": "la subcadena más larga que aparece al menos dos veces, o -1", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Suffix Array + LCP (mayor subcadena que se repite)\n * Problema  : CSES 2106 - Repeating Substring (https://cses.fi/problemset/task/2106)\n * Entrada   : una cadena de largo n\n * Salida    : la subcadena más larga que aparece al menos dos veces, o -1\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    s += '$';  // centinela menor que todas las letras\n    int n = s.size();\n    // suffix array por duplicación: se ordenan los sufijos por sus primeros 2^k caracteres\n    vector<int> sa(n), rk(n), tmp(n);\n    for (int i = 0; i < n; i++) sa[i] = i, rk[i] = s[i];\n    for (int k = 1;; k <<= 1) {\n        auto cmp = [&](int a, int b) {\n            if (rk[a] != rk[b]) return rk[a] < rk[b];\n            return rk[(a + k) % n] < rk[(b + k) % n];\n        };\n        sort(all(sa), cmp);\n        tmp[sa[0]] = 0;\n        for (int i = 1; i < n; i++) tmp[sa[i]] = tmp[sa[i - 1]] + cmp(sa[i - 1], sa[i]);\n        rk = tmp;\n        if (rk[sa[n - 1]] == n - 1) break;\n    }\n    // LCP con Kasai: lcp[i] = prefijo común entre los sufijos sa[i] y sa[i-1]\n    // la subcadena repetida más larga es el mayor LCP entre sufijos vecinos\n    int best = 0, where = 0;\n    for (int i = 0, h = 0; i < n; i++) {\n        if (rk[i] == 0) { h = 0; continue; }\n        int j = sa[rk[i] - 1];\n        while (s[i + h] == s[j + h]) h++;\n        if (h > best) best = h, where = i;\n        if (h > 0) h--;\n    }\n    if (best == 0) cout << -1 << \"\\n\";\n    else cout << s.substr(where, best) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport random\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Búsqueda binaria sobre el largo + hashing polinomial (mayor subcadena que se repite)\n * Problema  : CSES 2106 - Repeating Substring (https://cses.fi/problemset/task/2106)\n * Entrada   : una cadena de largo n\n * Salida    : la subcadena más larga que aparece al menos dos veces, o -1\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\nP = (1 << 61) - 1  # primo grande: las colisiones son muy improbables\n\n\ndef main():\n    s = sys.stdin.buffer.readline().strip()\n    n = len(s)\n    B = random.randrange(10**6, P - 1)  # base al azar para que nadie arme un caso malo\n    # h[i] = hash del prefijo s[0..i), pw[i] = B^i\n    h = [0] * (n + 1)\n    pw = [1] * (n + 1)\n    for i in range(n):\n        h[i + 1] = (h[i] * B + s[i]) % P\n        pw[i + 1] = pw[i] * B % P\n\n    def repetida(L):\n        \"\"\"Devuelve el inicio de una subcadena de largo L que se repite, o -1.\"\"\"\n        p = pw[L]\n        seen = {}\n        for i in range(n - L + 1):\n            x = (h[i + L] - h[i] * p) % P\n            if x in seen:\n                return i\n            seen[x] = i\n        return -1\n\n    # si un largo L se repite, cualquier largo menor también: se busca el mayor con binaria\n    lo, hi, at = 0, n - 1, -1\n    while lo < hi:\n        mid = (lo + hi + 1) // 2\n        i = repetida(mid)\n        if i >= 0:\n            lo, at = mid, i\n        else:\n            hi = mid - 1\n    print(s[at:at + lo].decode() if lo else -1)\n\n\nmain()\n"}, {"id": "Strings-Classic-Problems-Required-Substring", "carpeta": "Strings", "area": "Cadenas", "sub": "Classic Problems", "archivo": "Strings/Classic Problems/Required Substring.cpp", "nombre": "Required Substring", "algoritmo": "DP sobre el autómata de KMP (contar cadenas que contienen un patrón)", "problema": "CSES 1112 - Required Substring (https://cses.fi/problemset/task/1112)", "cses": "https://cses.fi/problemset/task/1112", "py_lento": false, "entrada": "n, luego un patrón de largo m (letras A–Z)", "salida": "cantidad de cadenas de largo n que contienen el patrón, módulo 10^9+7", "complejidad": "tiempo O(n · m · 26), memoria O(m · 26)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP sobre el autómata de KMP (contar cadenas que contienen un patrón)\n * Problema  : CSES 1112 - Required Substring (https://cses.fi/problemset/task/1112)\n * Entrada   : n, luego un patrón de largo m (letras A–Z)\n * Salida    : cantidad de cadenas de largo n que contienen el patrón, módulo 10^9+7\n * Complejidad: tiempo O(n · m · 26), memoria O(m · 26)\n */\n\nconst ll M = 1e9 + 7;\n\nint main() {\n    fastio;\n    int n;\n    string p;\n    cin >> n >> p;\n    int m = p.size();\n    // función de prefijos del patrón\n    vector<int> lps(m, 0);\n    for (int i = 1; i < m; i++) {\n        int j = lps[i - 1];\n        while (j > 0 && p[i] != p[j]) j = lps[j - 1];\n        if (p[i] == p[j]) j++;\n        lps[i] = j;\n    }\n    // go[k][c] = cuántos caracteres del patrón llevo emparejados si tenía k y leo c\n    vector<array<int, 26>> go(m);\n    for (int k = 0; k < m; k++)\n        for (int c = 0; c < 26; c++) {\n            if (p[k] - 'A' == c) go[k][c] = k + 1;\n            else go[k][c] = k ? go[lps[k - 1]][c] : 0;\n        }\n    // dp[k] = cadenas del largo actual que todavía NO contienen el patrón y tienen k emparejados\n    vector<ll> dp(m, 0), nd(m);\n    dp[0] = 1;\n    ll total = 1;  // 26^largo\n    for (int len = 0; len < n; len++) {\n        fill(all(nd), 0);\n        for (int k = 0; k < m; k++) if (dp[k])\n            for (int c = 0; c < 26; c++) {\n                int t = go[k][c];\n                if (t < m) nd[t] = (nd[t] + dp[k]) % M;  // si t == m ya apareció: se descarta\n            }\n        dp = nd;\n        total = total * 26 % M;\n    }\n    // las que contienen el patrón = todas - las que nunca lo completaron\n    ll malas = 0;\n    for (ll x : dp) malas = (malas + x) % M;\n    cout << (total - malas + M) % M << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP sobre el autómata de KMP (contar cadenas que contienen un patrón)\n * Problema  : CSES 1112 - Required Substring (https://cses.fi/problemset/task/1112)\n * Entrada   : n, luego un patrón de largo m (letras A–Z)\n * Salida    : cantidad de cadenas de largo n que contienen el patrón, módulo 10^9+7\n * Complejidad: tiempo O(n · m · d) con d = destinos distintos por estado (pocos), memoria O(m · 26)\n\"\"\"\n\nM = 10**9 + 7\n\n\ndef main():\n    n = int(input())\n    p = input().strip()\n    m = len(p)\n    # función de prefijos del patrón\n    pi = [0] * m\n    for i in range(1, m):\n        j = pi[i - 1]\n        while j and p[i] != p[j]:\n            j = pi[j - 1]\n        if p[i] == p[j]:\n            j += 1\n        pi[i] = j\n    # go[k][c] = caracteres emparejados si tenía k y leo c\n    go = [[0] * 26 for _ in range(m)]\n    for k in range(m):\n        for c in range(26):\n            if ord(p[k]) - 65 == c:\n                go[k][c] = k + 1\n            else:\n                go[k][c] = go[pi[k - 1]][c] if k else 0\n    # se agrupan las 26 letras por destino: trans[k] = [(destino, cuántas letras llevan ahí)]\n    trans = []\n    for k in range(m):\n        cnt = {}\n        for t in go[k]:\n            if t < m:  # si t == m el patrón ya apareció: no se cuenta como \"mala\"\n                cnt[t] = cnt.get(t, 0) + 1\n        trans.append(list(cnt.items()))\n    # dp[k] = cadenas que todavía NO contienen el patrón y tienen k emparejados\n    dp = [0] * m\n    dp[0] = 1\n    for _ in range(n):\n        nd = [0] * m\n        for k in range(m):\n            v = dp[k]\n            if v:\n                for t, c in trans[k]:\n                    nd[t] += v * c\n        dp = [x % M for x in nd]\n    print((pow(26, n, M) - sum(dp)) % M)\n\n\nmain()\n"}, {"id": "Geometry-ClosestPair", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/ClosestPair.cpp", "nombre": "ClosestPair", "algoritmo": "Par de puntos más cercano (sweep line con set)", "problema": "CSES 2194 - Minimum Euclidean Distance (https://cses.fi/problemset/task/2194)", "cses": "https://cses.fi/problemset/task/2194", "py_lento": false, "entrada": "n, luego n puntos enteros \"x y\"", "salida": "el cuadrado de la mínima distancia euclidiana entre dos puntos", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Par de puntos más cercano (sweep line con set)\n * Problema  : CSES 2194 - Minimum Euclidean Distance (https://cses.fi/problemset/task/2194)\n * Entrada   : n, luego n puntos enteros \"x y\"\n * Salida    : el cuadrado de la mínima distancia euclidiana entre dos puntos\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<pair<ll, ll>> p(n);\n    for (auto &q : p) cin >> q.first >> q.second;\n    // se ordenan los puntos por x\n    sort(all(p));  // ordenados por x\n\n    auto dist2 = [](pair<ll, ll> a, pair<ll, ll> b) {\n        return (a.first - b.first) * (a.first - b.first) + (a.second - b.second) * (a.second - b.second);\n    };\n\n    // set ordenado por y con los puntos dentro de la franja de ancho sqrt(best)\n    // puntos cercanos en x, ordenados por y\n    set<pair<ll, ll>> active;  // {y, x}\n    ll best = INF;\n    int left = 0;\n    for (int i = 0; i < n; i++) {\n        ll d = (ll)ceil(sqrt((ld)best));\n        if (best == INF) d = 4e9;\n        // se sacan los puntos demasiado lejos en x\n        while (left < i && p[i].first - p[left].first >= d) {\n            active.erase({p[left].second, p[left].first});\n            left++;\n        }\n        // solo se revisan los puntos con y dentro de ±d (pocos por la franja)\n        auto lo = active.lower_bound({p[i].second - d, -INF});\n        for (auto it = lo; it != active.end() && it->first <= p[i].second + d; ++it)\n            best = min(best, dist2(p[i], {it->second, it->first}));\n        active.insert({p[i].second, p[i].first});\n    }\n    cout << best << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport math\nfrom bisect import bisect_left, insort\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Par de puntos más cercano (sweep line con set)\n * Problema  : CSES 2194 - Minimum Euclidean Distance (https://cses.fi/problemset/task/2194)\n * Entrada   : n, luego n puntos enteros \"x y\"\n * Salida    : el cuadrado de la mínima distancia euclidiana entre dos puntos\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    # se ordenan los puntos por x\n    p = sorted(zip(map(int, data[1:2 * n + 1:2]), map(int, data[2:2 * n + 2:2])))\n\n    # puntos cercanos en x, ordenados por y (lista ordenada con bisect)\n    active = []\n    best = INF\n    left = 0\n    for i in range(n):\n        x, y = p[i]\n        d = math.isqrt(best) + 1 if best != INF else 4 * 10 ** 9\n        # se sacan los puntos demasiado lejos en x\n        while left < i and x - p[left][0] >= d:\n            px, py = p[left]\n            active.pop(bisect_left(active, (py, px)))\n            left += 1\n        # solo se revisan los puntos con y dentro de ±d (pocos por la franja)\n        j = bisect_left(active, (y - d, -INF))\n        while j < len(active) and active[j][0] <= y + d:\n            qy, qx = active[j]\n            dist = (x - qx) ** 2 + (y - qy) ** 2\n            if dist < best:\n                best = dist\n            j += 1\n        insort(active, (y, x))\n    print(best)\n\n\nmain()\n"}, {"id": "Geometry-ConvexHull", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/ConvexHull.cpp", "nombre": "ConvexHull", "algoritmo": "Envolvente convexa (Graham scan, incluye puntos colineales del borde)", "problema": "CSES 2195 - Convex Hull (https://cses.fi/problemset/task/2195)", "cses": "https://cses.fi/problemset/task/2195", "py_lento": false, "entrada": "n, luego n puntos enteros \"x y\"", "salida": "cantidad de puntos de la envolvente (incluye los del borde) y sus coordenadas", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Envolvente convexa (Graham scan, incluye puntos colineales del borde)\n * Problema  : CSES 2195 - Convex Hull (https://cses.fi/problemset/task/2195)\n * Entrada   : n, luego n puntos enteros \"x y\"\n * Salida    : cantidad de puntos de la envolvente (incluye los del borde) y sus coordenadas\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\n// punto del plano con coordenadas enteras\nstruct pt {\n    ll x, y;  // Funcionan como parejas\n    bool operator==(pt const &t) const {\n        return x == t.x && y == t.y;\n    }\n};\n\n// signo del producto cruz (b - a) x (c - a)\nint orientation(pt a, pt b, pt c) {\n    ll v = a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y);  // Producto cruz\n    if (v < 0) return -1;  // a-b-c Horario\n    if (v > 0) return +1;  // a-b-c Antihorario\n    return 0;\n}\n\n// cw verifica si a-b-c va en sentido horario\nbool cw(pt a, pt b, pt c, bool include_collinear) {\n    int o = orientation(a, b, c);\n    return o < 0 || (include_collinear && o == 0);\n}\n\nbool collinear(pt a, pt b, pt c) { return orientation(a, b, c) == 0; }\n\n// Graham scan: se ordena por ángulo alrededor del punto más bajo\nvoid convex_hull(vector<pt> &a, bool include_collinear = false) {\n    pt p0 = *min_element(all(a), [](pt a, pt b) {\n        return make_pair(a.y, a.x) < make_pair(b.y, b.x);\n    });  // encuentra el punto más abajo a la izquierda\n    sort(all(a), [&p0](const pt &a, const pt &b) {\n        int o = orientation(p0, a, b);\n        if (o == 0)\n            return (p0.x - a.x) * (p0.x - a.x) + (p0.y - a.y) * (p0.y - a.y)\n                 < (p0.x - b.x) * (p0.x - b.x) + (p0.y - b.y) * (p0.y - b.y);\n        return o < 0;  // Criterio de comparacion para ordenar\n    });\n    // con puntos colineales en el borde final, se invierte esa última parte\n    if (include_collinear) {\n        int i = (int)a.size() - 1;\n        while (i >= 0 && collinear(p0, a[i], a.back())) i--;\n        reverse(a.begin() + i + 1, a.end());\n    }\n\n    // pila de la envolvente\n    vector<pt> st;\n    for (int i = 0; i < (int)a.size(); i++) {\n        // Verifica si los dos anteriores con el actual van en sentido horario\n        while (st.size() > 1 && !cw(st[st.size() - 2], st.back(), a[i], include_collinear))\n            st.pop_back();\n        st.push_back(a[i]);\n    }\n\n    // caso degenerado de puntos repetidos\n    if (include_collinear == false && st.size() == 2 && st[0] == st[1])\n        st.pop_back();\n\n    a = st;\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<pt> points(n);\n    for (auto &p : points) cin >> p.x >> p.y;\n\n    convex_hull(points, true);\n    cout << points.size() << \"\\n\";\n    for (auto &p : points) cout << p.x << ' ' << p.y << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Envolvente convexa (Graham scan, incluye puntos colineales del borde)\n * Problema  : CSES 2195 - Convex Hull (https://cses.fi/problemset/task/2195)\n * Entrada   : n, luego n puntos enteros \"x y\"\n * Salida    : cantidad de puntos de la envolvente (incluye los del borde) y sus coordenadas\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\n# producto cruz (a - o) x (b - o): > 0 antihorario, < 0 horario, 0 colineal\ndef cross(o, a, b):\n    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])\n\n\n# cadena monótona (Andrew): se ordenan los puntos y se arman la parte de abajo y la de arriba\n# (versión más rápida en Python que el Graham scan; con include_collinear se dejan los puntos del borde)\ndef convex_hull(pts, include_collinear=False):\n    pts = sorted(set(pts))\n    if len(pts) <= 2:\n        return pts\n\n    def half(points):\n        st = []\n        for p in points:\n            # se saca el último mientras el giro no sea antihorario (o colineal si se excluyen)\n            while len(st) > 1:\n                c = cross(st[-2], st[-1], p)\n                if c > 0 or (include_collinear and c == 0):\n                    break\n                st.pop()\n            st.append(p)\n        return st\n\n    lower = half(pts)\n    upper = half(reversed(pts))\n    hull = lower[:-1] + upper[:-1]\n    # si todos son colineales, cada punto quedó dos veces\n    if include_collinear and len(hull) > len(pts):\n        return pts\n    return hull\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    points = list(zip(map(int, data[1:2 * n + 1:2]), map(int, data[2:2 * n + 2:2])))\n    hull = convex_hull(points, True)\n    out = [str(len(hull))] + [\"%d %d\" % p for p in hull]\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Geometry-Point", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/Point.cpp", "nombre": "Point", "algoritmo": "Vectores 3D (suma, producto punto y cruz, norma, proyección, ángulo)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "seis reales: ax ay az bx by bz (para vectores en el plano, z = 0)", "salida": "a+b, a-b, a×b, a·b, |b| y la proyección de a sobre b (10 decimales)", "complejidad": "tiempo O(1) por operación, memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Vectores 3D (suma, producto punto y cruz, norma, proyección, ángulo)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : seis reales: ax ay az bx by bz (para vectores en el plano, z = 0)\n * Salida    : a+b, a-b, a×b, a·b, |b| y la proyección de a sobre b (10 decimales)\n * Complejidad: tiempo O(1) por operación, memoria O(1)\n */\n\nstruct Point3d {\n\tld x, y, z; //Son vectores y si lo necesita en el plano, pues fije z=0\n\tPoint3d() {}\n\tPoint3d(ld x, ld y, ld z): x(x), y(y), z(z) {}\n\tPoint3d& operator+=(const Point3d &t) {\n\t\tx += t.x;\n\t\ty += t.y;\n\t\tz += t.z;\n\t\treturn *this;\n\t}\n\tPoint3d& operator-=(const Point3d &t) {\n\t\tx -= t.x;\n\t\ty -= t.y;\n\t\tz -= t.z;\n\t\treturn *this;\n\t}\n\tPoint3d& operator*=(ld t) { //Aqui se opera a derecha!!\n\t\tx *= t;\n\t\ty *= t;\n\t\tz *= t;\n\t\treturn *this;\n\t}\n\tPoint3d& operator/=(ld t) { //Aqui se opera a derecha!!\n\t\tx /= t;\n\t\ty /= t;\n\t\tz /= t;\n\treturn *this;\n\t}\n\tPoint3d operator+(const Point3d &t) const {\n\t\treturn Point3d(*this) += t;\n\t}\n\tPoint3d operator-(const Point3d &t) const {\n\t\treturn Point3d(*this) -= t;\n\t}\n\tPoint3d operator*(ld t) const {\n\t\treturn Point3d(*this) *= t;\n\t}\n\tPoint3d operator/(ld t) const {\n\t\treturn Point3d(*this) /= t;\n\t}\n\t// producto punto\n\tstatic ld dot(Point3d a,Point3d b) {\n\t\treturn a.x * b.x + a.y * b.y + a.z * b.z;\n\t}\n\t// producto cruz\n\tstatic Point3d cross(Point3d a, Point3d b) {\n\t\treturn Point3d(a.y * b.z - a.z * b.y,\n\t\t\ta.z * b.x - a.x * b.z,\n\t\t\ta.x * b.y - a.y * b.x);\n\t}\n\tstatic ld norm(Point3d a) {//norma al cuadrado\n\t\treturn dot(a,a);\n\t}\n\tstatic ld abs(Point3d a) {//norma normal xd\n\t\treturn sqrt(norm(a));\n\t}\n\t// proyección de a sobre b: b * (a·b / |b|²)\n\tstatic Point3d proj(Point3d a, Point3d b) {// proyeccion de a en b\n\t\treturn b*(dot(a, b) / norm(b));\n\t}\n\t// ángulo entre dos vectores\n\tstatic ld angle(Point3d a, Point3d b) {\n\t\treturn acos(dot(a, b) / abs(a) / abs(b));\n\t}\n\t// igualdad con tolerancia EPS por ser reales\n\tbool operator==(const Point3d &other) const {\n    \t\tconst double EPS = 1e-6;\n\t\treturn fabs(x - other.x) < EPS && fabs(y - other.y) < EPS && fabs(z - other.z) < EPS;\n\t}\n};\nPoint3d operator*(ld a, Point3d b) {\n\treturn b * a;\n}\n\nint main() {\n    fastio;\n    precision(10);\n    ld ax, ay, az, bx, by, bz;\n    cin >> ax >> ay >> az >> bx >> by >> bz;\n    Point3d A(ax, ay, az), B(bx, by, bz);\n\n    Point3d sum = A + B, diff = A - B, cr = Point3d::cross(A, B), pr = Point3d::proj(A, B);\n    cout << \"A+B = \" << sum.x << ' ' << sum.y << ' ' << sum.z << \"\\n\";\n    cout << \"A-B = \" << diff.x << ' ' << diff.y << ' ' << diff.z << \"\\n\";\n    cout << \"AxB = \" << cr.x << ' ' << cr.y << ' ' << cr.z << \"\\n\";\n    cout << \"A.B = \" << Point3d::dot(A, B) << \"\\n\";\n    cout << \"|B| = \" << Point3d::abs(B) << \"\\n\";\n    cout << \"proj_B(A) = \" << pr.x << ' ' << pr.y << ' ' << pr.z << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport math\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Vectores 3D (suma, producto punto y cruz, norma, proyección, ángulo)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : seis reales: ax ay az bx by bz (para vectores en el plano, z = 0)\n * Salida    : a+b, a-b, a×b, a·b, |b| y la proyección de a sobre b (10 decimales)\n * Complejidad: tiempo O(1) por operación, memoria O(1)\n\"\"\"\n\n\n# vector en 3D (para vectores en el plano se fija z = 0)\nclass Point3d:\n    def __init__(self, x, y, z):\n        self.x, self.y, self.z = x, y, z\n\n    def __add__(self, t):\n        return Point3d(self.x + t.x, self.y + t.y, self.z + t.z)\n\n    def __sub__(self, t):\n        return Point3d(self.x - t.x, self.y - t.y, self.z - t.z)\n\n    def __mul__(self, t):\n        return Point3d(self.x * t, self.y * t, self.z * t)\n\n    def __truediv__(self, t):\n        return Point3d(self.x / t, self.y / t, self.z / t)\n\n    # igualdad con tolerancia EPS por ser reales\n    def __eq__(self, o):\n        EPS = 1e-6\n        return abs(self.x - o.x) < EPS and abs(self.y - o.y) < EPS and abs(self.z - o.z) < EPS\n\n\n# producto punto\ndef dot(a, b):\n    return a.x * b.x + a.y * b.y + a.z * b.z\n\n\n# producto cruz\ndef cross(a, b):\n    return Point3d(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x)\n\n\n# norma al cuadrado y norma\ndef norm(a):\n    return dot(a, a)\n\n\ndef length(a):\n    return math.sqrt(norm(a))\n\n\n# proyección de a sobre b: b * (a·b / |b|²)\ndef proj(a, b):\n    return b * (dot(a, b) / norm(b))\n\n\n# ángulo entre dos vectores\ndef angle(a, b):\n    return math.acos(dot(a, b) / length(a) / length(b))\n\n\ndef main():\n    ax, ay, az, bx, by, bz = map(float, sys.stdin.read().split()[:6])\n    A, B = Point3d(ax, ay, az), Point3d(bx, by, bz)\n    f = lambda v: \"%.10f\" % v\n    s, d, cr, pr = A + B, A - B, cross(A, B), proj(A, B)\n    print(\"A+B =\", f(s.x), f(s.y), f(s.z))\n    print(\"A-B =\", f(d.x), f(d.y), f(d.z))\n    print(\"AxB =\", f(cr.x), f(cr.y), f(cr.z))\n    print(\"A.B =\", f(dot(A, B)))\n    print(\"|B| =\", f(length(B)))\n    print(\"proj_B(A) =\", f(pr.x), f(pr.y), f(pr.z))\n\n\nmain()\n"}, {"id": "Geometry-PointInPolygon", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/PointInPolygon.cpp", "nombre": "PointInPolygon", "algoritmo": "Punto en polígono (ray casting con producto cruz)", "problema": "CSES 2192 - Point in Polygon (https://cses.fi/problemset/task/2192)", "cses": "https://cses.fi/problemset/task/2192", "py_lento": false, "entrada": "n m, luego n vértices del polígono y m puntos \"x y\"", "salida": "INSIDE, OUTSIDE o BOUNDARY para cada punto", "complejidad": "tiempo O(n · m), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Punto en polígono (ray casting con producto cruz)\n * Problema  : CSES 2192 - Point in Polygon (https://cses.fi/problemset/task/2192)\n * Entrada   : n m, luego n vértices del polígono y m puntos \"x y\"\n * Salida    : INSIDE, OUTSIDE o BOUNDARY para cada punto\n * Complejidad: tiempo O(n · m), memoria O(n)\n */\n\ntypedef pair<ll, ll> pt;\n\n// producto cruz (b - a) x (c - a)\nll cross(pt a, pt b, pt c) {  // (b - a) x (c - a)\n    return (b.first - a.first) * (c.second - a.second) - (b.second - a.second) * (c.first - a.first);\n}\n\n// p está en el segmento ab: colineal y dentro de su caja\nbool onSegment(pt a, pt b, pt p) {\n    return cross(a, b, p) == 0 &&\n           min(a.first, b.first) <= p.first && p.first <= max(a.first, b.first) &&\n           min(a.second, b.second) <= p.second && p.second <= max(a.second, b.second);\n}\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<pt> poly(n);\n    for (auto &p : poly) cin >> p.first >> p.second;\n\n    while (m--) {\n        pt p;\n        cin >> p.first >> p.second;\n        bool boundary = false;\n        int crossings = 0;\n        for (int i = 0; i < n; i++) {\n            pt a = poly[i], b = poly[(i + 1) % n];\n            // si está sobre una arista, es borde\n            if (onSegment(a, b, p)) { boundary = true; break; }\n            // rayo hacia la derecha: cuenta aristas que cruzan la altura de p\n            // rayo horizontal: se cuentan aristas que cruzan la altura de p a su derecha\n            if ((a.second > p.second) != (b.second > p.second)) {\n                ll c = cross(a, b, p);\n                if ((c > 0) == (b.second > a.second)) crossings++;\n            }\n        }\n        if (boundary) cout << \"BOUNDARY\\n\";\n        // cantidad impar de cruces = adentro\n        else cout << (crossings % 2 ? \"INSIDE\" : \"OUTSIDE\") << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Punto en polígono (ray casting con producto cruz)\n * Problema  : CSES 2192 - Point in Polygon (https://cses.fi/problemset/task/2192)\n * Entrada   : n m, luego n vértices del polígono y m puntos \"x y\"\n * Salida    : INSIDE, OUTSIDE o BOUNDARY para cada punto\n * Complejidad: tiempo O(n · m), memoria O(n)\n\"\"\"\n\n\n# producto cruz (b - a) x (c - a)\ndef cross(a, b, c):\n    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])\n\n\n# p está en el segmento ab: colineal y dentro de su caja\ndef on_segment(a, b, p):\n    return (cross(a, b, p) == 0 and min(a[0], b[0]) <= p[0] <= max(a[0], b[0])\n            and min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))\n\n\ndef main():\n    n, m = map(int, input().split())\n    poly = [tuple(map(int, input().split())) for _ in range(n)]\n    out = []\n    for _ in range(m):\n        p = tuple(map(int, input().split()))\n        boundary = False\n        crossings = 0\n        for i in range(n):\n            a, b = poly[i], poly[(i + 1) % n]\n            # si está sobre una arista, es borde\n            if on_segment(a, b, p):\n                boundary = True\n                break\n            # rayo horizontal: se cuentan aristas que cruzan la altura de p a su derecha\n            if (a[1] > p[1]) != (b[1] > p[1]):\n                if (cross(a, b, p) > 0) == (b[1] > a[1]):\n                    crossings += 1\n        # cantidad impar de cruces = adentro\n        out.append(\"BOUNDARY\" if boundary else (\"INSIDE\" if crossings % 2 else \"OUTSIDE\"))\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "Geometry-PolygonLatticePoints", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/PolygonLatticePoints.cpp", "nombre": "PolygonLatticePoints", "algoritmo": "Teorema de Pick (puntos enteros de un polígono)", "problema": "CSES 2193 - Polygon Lattice Points (https://cses.fi/problemset/task/2193)", "cses": "https://cses.fi/problemset/task/2193", "py_lento": false, "entrada": "n, luego n vértices enteros en orden", "salida": "puntos enteros interiores y puntos enteros en el borde", "complejidad": "tiempo O(n log C), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Teorema de Pick (puntos enteros de un polígono)\n * Problema  : CSES 2193 - Polygon Lattice Points (https://cses.fi/problemset/task/2193)\n * Entrada   : n, luego n vértices enteros en orden\n * Salida    : puntos enteros interiores y puntos enteros en el borde\n * Complejidad: tiempo O(n log C), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<pair<ll, ll>> p(n);\n    for (auto &q : p) cin >> q.first >> q.second;\n\n    ll area2 = 0, boundary = 0;  // area2 = 2 * área\n    for (int i = 0; i < n; i++) {\n        auto [x1, y1] = p[i];\n        auto [x2, y2] = p[(i + 1) % n];\n        // Shoelace: suma de x1*y2 - x2*y1\n        area2 += x1 * y2 - x2 * y1;\n        // puntos enteros en cada arista = gcd(|dx|, |dy|)\n        boundary += gcd(abs(x2 - x1), abs(y2 - y1));\n    }\n    area2 = abs(area2);\n\n    // Pick: A = I + B/2 - 1  =>  I = (2A - B + 2) / 2\n    // de Pick: A = I + B/2 - 1\n    ll inside = (area2 - boundary + 2) / 2;\n    cout << inside << ' ' << boundary << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nimport math\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Teorema de Pick (puntos enteros de un polígono)\n * Problema  : CSES 2193 - Polygon Lattice Points (https://cses.fi/problemset/task/2193)\n * Entrada   : n, luego n vértices enteros en orden\n * Salida    : puntos enteros interiores y puntos enteros en el borde\n * Complejidad: tiempo O(n log C), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    p = [tuple(map(int, input().split())) for _ in range(n)]\n\n    # area2 = 2 * área\n    area2 = boundary = 0\n    for i in range(n):\n        x1, y1 = p[i]\n        x2, y2 = p[(i + 1) % n]\n        # Shoelace: suma de x1*y2 - x2*y1\n        area2 += x1 * y2 - x2 * y1\n        # puntos enteros en cada arista = gcd(|dx|, |dy|)\n        boundary += math.gcd(abs(x2 - x1), abs(y2 - y1))\n    area2 = abs(area2)\n\n    # de Pick: A = I + B/2 - 1  =>  I = (2A - B + 2) / 2\n    print((area2 - boundary + 2) // 2, boundary)\n\n\nmain()\n"}, {"id": "Geometry-SegmentIntersection", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/SegmentIntersection.cpp", "nombre": "SegmentIntersection", "algoritmo": "Intersección de segmentos (orientaciones y cajas envolventes)", "problema": "CSES 2190 - Line Segment Intersection (https://cses.fi/problemset/task/2190)", "cses": "https://cses.fi/problemset/task/2190", "py_lento": true, "entrada": "t casos con \"x1 y1 x2 y2 x3 y3 x4 y4\"", "salida": "YES si los segmentos se intersectan (incluye tocarse), NO si no", "complejidad": "tiempo O(1) por caso, memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Intersección de segmentos (orientaciones y cajas envolventes)\n * Problema  : CSES 2190 - Line Segment Intersection (https://cses.fi/problemset/task/2190)\n * Entrada   : t casos con \"x1 y1 x2 y2 x3 y3 x4 y4\"\n * Salida    : YES si los segmentos se intersectan (incluye tocarse), NO si no\n * Complejidad: tiempo O(1) por caso, memoria O(1)\n */\n\ntypedef pair<ll, ll> pt;\n\nint sgn(ll v) { return (v > 0) - (v < 0); }\n\n// signo del producto cruz: 1 antihorario, -1 horario, 0 colineal\nint orient(pt a, pt b, pt c) {\n    return sgn((b.first - a.first) * (c.second - a.second) - (b.second - a.second) * (c.first - a.first));\n}\n\n// los rectángulos de los segmentos deben solaparse (caso colineal)\nbool inBox(pt a, pt b, pt c, pt d) {  // las cajas de ab y cd se solapan\n    return max(min(a.first, b.first), min(c.first, d.first)) <= min(max(a.first, b.first), max(c.first, d.first)) &&\n           max(min(a.second, b.second), min(c.second, d.second)) <= min(max(a.second, b.second), max(c.second, d.second));\n}\n\n// los extremos de cada segmento quedan a lados opuestos del otro (o tocan)\nbool intersect(pt a, pt b, pt c, pt d) {\n    return inBox(a, b, c, d) &&\n           orient(a, b, c) * orient(a, b, d) <= 0 &&\n           orient(c, d, a) * orient(c, d, b) <= 0;\n}\n\nint main() {\n    fastio;\n    int t;\n    cin >> t;\n    while (t--) {\n        pt a, b, c, d;\n        cin >> a.first >> a.second >> b.first >> b.second >> c.first >> c.second >> d.first >> d.second;\n        cout << (intersect(a, b, c, d) ? \"YES\" : \"NO\") << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Intersección de segmentos (orientaciones y cajas envolventes)\n * Problema  : CSES 2190 - Line Segment Intersection (https://cses.fi/problemset/task/2190)\n * Entrada   : t casos con \"x1 y1 x2 y2 x3 y3 x4 y4\"\n * Salida    : YES si los segmentos se intersectan (incluye tocarse), NO si no\n * Complejidad: tiempo O(1) por caso, memoria O(1)\n\"\"\"\n\n\ndef main():\n    data = list(map(int, sys.stdin.buffer.read().split()))\n    t = data[0]\n    out = []\n    i = 1\n    for _ in range(t):\n        x1, y1, x2, y2, x3, y3, x4, y4 = data[i], data[i + 1], data[i + 2], data[i + 3], data[i + 4], data[i + 5], data[i + 6], data[i + 7]\n        i += 8\n        # los rectángulos de los segmentos deben solaparse (caso colineal)\n        if (max(min(x1, x2), min(x3, x4)) > min(max(x1, x2), max(x3, x4))\n                or max(min(y1, y2), min(y3, y4)) > min(max(y1, y2), max(y3, y4))):\n            out.append(\"NO\")\n            continue\n        # orientaciones (productos cruz) de cada extremo respecto al otro segmento\n        d1 = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)\n        d2 = (x2 - x1) * (y4 - y1) - (y2 - y1) * (x4 - x1)\n        d3 = (x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)\n        d4 = (x4 - x3) * (y2 - y3) - (y4 - y3) * (x2 - x3)\n        # los extremos de cada segmento quedan a lados opuestos del otro (o tocan)\n        ok = ((d1 >= 0 and d2 <= 0) or (d1 <= 0 and d2 >= 0)) and ((d3 >= 0 and d4 <= 0) or (d3 <= 0 and d4 >= 0))\n        out.append(\"YES\" if ok else \"NO\")\n    sys.stdout.write(\"\\n\".join(out) + \"\\n\")\n\n\nmain()\n"}, {"id": "Geometry-Shoelace", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/Shoelace.cpp", "nombre": "Shoelace", "algoritmo": "Fórmula del Shoelace (área de un polígono)", "problema": "CSES 2191 - Polygon Area (https://cses.fi/problemset/task/2191)", "cses": "https://cses.fi/problemset/task/2191", "py_lento": false, "entrada": "n, luego n vértices \"x y\" en orden", "salida": "el doble del área del polígono (entero)", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Fórmula del Shoelace (área de un polígono)\n * Problema  : CSES 2191 - Polygon Area (https://cses.fi/problemset/task/2191)\n * Entrada   : n, luego n vértices \"x y\" en orden\n * Salida    : el doble del área del polígono (entero)\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\n// módulo no negativo para índices circulares\nll mod(ll x, ll n) {\n    return (x % n + n) % n;\n}\n\nint main() {\n    fastio;\n    ll n;\n    cin >> n;\n    vector<pair<ll, ll>> points(n);\n    for (auto &p : points) cin >> p.first >> p.second;\n\n    ll res = 0;\n    for (int i = 0; i < n; i++) {\n        // término x_i * (y_{i+1} - y_{i-1}) de la fórmula del Shoelace\n        res += points[i].first * (points[mod(i + 1, n)].second - points[mod(i - 1, n)].second);\n    }\n\n    res = abs(res);  // Esto me da 2 veces el area!!\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Fórmula del Shoelace (área de un polígono)\n * Problema  : CSES 2191 - Polygon Area (https://cses.fi/problemset/task/2191)\n * Entrada   : n, luego n vértices \"x y\" en orden\n * Salida    : el doble del área del polígono (entero)\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    points = [tuple(map(int, input().split())) for _ in range(n)]\n\n    res = 0\n    for i in range(n):\n        # término x_i * (y_{i+1} - y_{i-1}) de la fórmula del Shoelace (índices circulares)\n        res += points[i][0] * (points[(i + 1) % n][1] - points[i - 1][1])\n\n    # esto da 2 veces el área\n    print(abs(res))\n\n\nmain()\n"}, {"id": "Geometry-Classic-Problems-Area-of-Rectangles", "carpeta": "Geometry", "area": "Geometría", "sub": "Classic Problems", "archivo": "Geometry/Classic Problems/Area of Rectangles.cpp", "nombre": "Area of Rectangles", "algoritmo": "Línea de barrido + Segment Tree de cobertura (área de la unión de rectángulos)", "problema": "CSES 1741 - Area of Rectangles (https://cses.fi/problemset/task/1741)", "cses": "https://cses.fi/problemset/task/1741", "py_lento": true, "entrada": "n, luego n rectángulos \"x1 y1 x2 y2\"", "salida": "el área total cubierta por la unión", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Línea de barrido + Segment Tree de cobertura (área de la unión de rectángulos)\n * Problema  : CSES 1741 - Area of Rectangles (https://cses.fi/problemset/task/1741)\n * Entrada   : n, luego n rectángulos \"x1 y1 x2 y2\"\n * Salida    : el área total cubierta por la unión\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nvector<ll> ys;           // alturas comprimidas\nvector<int> cnt;          // cnt[v] = cuántos rectángulos cubren entero el tramo del nodo v\nvector<ll> len;           // len[v] = largo cubierto dentro del tramo del nodo v\n\n// el nodo v cubre los intervalos elementales [ys[l], ys[l+1]), ..., [ys[r], ys[r+1])\nvoid update(int v, int l, int r, int a, int b, int d) {\n    if (b < l || r < a) return;\n    if (a <= l && r <= b) cnt[v] += d;\n    else {\n        int m = (l + r) / 2;\n        update(2 * v, l, m, a, b, d);\n        update(2 * v + 1, m + 1, r, a, b, d);\n    }\n    // si algo lo cubre entero, todo su tramo cuenta; si no, lo que aporten sus hijos\n    if (cnt[v] > 0) len[v] = ys[r + 1] - ys[l];\n    else len[v] = (l == r) ? 0 : len[2 * v] + len[2 * v + 1];\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<array<ll, 4>> ev;  // (x, +1/-1, y1, y2)\n    for (int i = 0; i < n; i++) {\n        ll x1, y1, x2, y2;\n        cin >> x1 >> y1 >> x2 >> y2;\n        ev.push_back({x1, 1, y1, y2});\n        ev.push_back({x2, -1, y1, y2});\n        ys.push_back(y1), ys.push_back(y2);\n    }\n    sort(all(ys));\n    ys.erase(unique(all(ys)), ys.end());\n    int m = ys.size() - 1;  // intervalos elementales\n    cnt.assign(4 * m + 4, 0), len.assign(4 * m + 4, 0);\n    sort(all(ev));\n    ll area = 0;\n    for (int i = 0; i < (int)ev.size(); i++) {\n        // entre el evento anterior y este, el largo cubierto en y no cambia: se suma la franja\n        if (i > 0) area += len[1] * (ev[i][0] - ev[i - 1][0]);\n        int a = lower_bound(all(ys), ev[i][2]) - ys.begin();\n        int b = lower_bound(all(ys), ev[i][3]) - ys.begin() - 1;\n        update(1, 0, m - 1, a, b, (int)ev[i][1]);\n    }\n    cout << area << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Línea de barrido + Segment Tree de cobertura (área de la unión de rectángulos)\n * Problema  : CSES 1741 - Area of Rectangles (https://cses.fi/problemset/task/1741)\n * Entrada   : n, luego n rectángulos \"x1 y1 x2 y2\"\n * Salida    : el área total cubierta por la unión\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + 4 * n]))\n    ys = sorted(set(v[1::4]) | set(v[3::4]))  # alturas comprimidas\n    pos = {y: i for i, y in enumerate(ys)}\n    m = len(ys) - 1  # intervalos elementales [ys[i], ys[i+1])\n    sz = 1\n    while sz < m:\n        sz <<= 1\n    # W[v] = ancho del tramo del nodo, cnt[v] = rectángulos que lo cubren entero, L[v] = largo cubierto\n    W = [0] * (2 * sz)\n    for i in range(m):\n        W[sz + i] = ys[i + 1] - ys[i]\n    for u in range(sz - 1, 0, -1):\n        W[u] = W[2 * u] + W[2 * u + 1]\n    cnt = [0] * (2 * sz)\n    L = [0] * (2 * sz)\n\n    def pull(u):\n        if cnt[u]:\n            L[u] = W[u]          # cubierto entero\n        elif u < sz:\n            L[u] = L[2 * u] + L[2 * u + 1]\n        else:\n            L[u] = 0\n\n    # eventos: (x, delta, y1, y2), se suman las franjas entre x consecutivos\n    ev = sorted([(v[k], 1, v[k + 1], v[k + 3]) for k in range(0, 4 * n, 4)] +\n                [(v[k + 2], -1, v[k + 1], v[k + 3]) for k in range(0, 4 * n, 4)])\n    area = 0\n    prev = ev[0][0]\n    for x, d, y1, y2 in ev:\n        area += L[1] * (x - prev)\n        prev = x\n        # segment tree iterativo: se marcan los nodos que cubren [a, b) y se recalculan sus ancestros\n        l, r = pos[y1] + sz, pos[y2] + sz\n        l0, r0 = l, r - 1\n        while l < r:\n            if l & 1:\n                cnt[l] += d\n                pull(l)\n                l += 1\n            if r & 1:\n                r -= 1\n                cnt[r] += d\n                pull(r)\n            l >>= 1\n            r >>= 1\n        l0 >>= 1\n        while l0:\n            pull(l0)\n            l0 >>= 1\n        r0 >>= 1\n        while r0:\n            pull(r0)\n            r0 >>= 1\n    print(area)\n\n\nmain()\n"}, {"id": "Geometry-Classic-Problems-Intersection-Points", "carpeta": "Geometry", "area": "Geometría", "sub": "Classic Problems", "archivo": "Geometry/Classic Problems/Intersection Points.cpp", "nombre": "Intersection Points", "algoritmo": "Línea de barrido + Fenwick Tree (cruces entre segmentos horizontales y verticales)", "problema": "CSES 1740 - Intersection Points (https://cses.fi/problemset/task/1740)", "cses": "https://cses.fi/problemset/task/1740", "py_lento": false, "entrada": "n, luego n segmentos horizontales o verticales \"x1 y1 x2 y2\"", "salida": "cantidad de puntos de intersección", "complejidad": "tiempo O(n log C) con C = rango de coordenadas, memoria O(C)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Línea de barrido + Fenwick Tree (cruces entre segmentos horizontales y verticales)\n * Problema  : CSES 1740 - Intersection Points (https://cses.fi/problemset/task/1740)\n * Entrada   : n, luego n segmentos horizontales o verticales \"x1 y1 x2 y2\"\n * Salida    : cantidad de puntos de intersección\n * Complejidad: tiempo O(n log C) con C = rango de coordenadas, memoria O(C)\n */\n\nconst int OFF = 1000001, C = 2000003;  // y + OFF queda en [1, C)\nvector<ll> bit(C + 1, 0);\nvoid add(int i, ll v) { for (; i <= C; i += i & -i) bit[i] += v; }\nll sum(int i) { ll s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    // eventos por x: tipo 0 = empieza horizontal, 1 = vertical (consulta), 2 = termina horizontal\n    vector<array<int, 4>> ev;\n    for (int i = 0; i < n; i++) {\n        int x1, y1, x2, y2;\n        cin >> x1 >> y1 >> x2 >> y2;\n        if (y1 == y2) ev.push_back({x1, 0, y1, 0}), ev.push_back({x2, 2, y1, 0});\n        else ev.push_back({x1, 1, y1, y2});\n    }\n    // se barre de izquierda a derecha; el Fenwick cuenta las horizontales activas en cada altura y\n    sort(all(ev));\n    ll total = 0;\n    for (auto &[x, t, a, b] : ev) {\n        if (t == 0) add(a + OFF, 1);\n        else if (t == 2) add(a + OFF, -1);\n        else total += sum(b + OFF) - sum(a + OFF - 1);  // horizontales activas con y en [y1, y2]\n    }\n    cout << total << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Línea de barrido + Fenwick Tree (cruces entre segmentos horizontales y verticales)\n * Problema  : CSES 1740 - Intersection Points (https://cses.fi/problemset/task/1740)\n * Entrada   : n, luego n segmentos horizontales o verticales \"x1 y1 x2 y2\"\n * Salida    : cantidad de puntos de intersección\n * Complejidad: tiempo O(n log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + 4 * n]))\n    # se comprimen las alturas de las horizontales para que el Fenwick sea pequeño\n    ys = sorted({v[k + 1] for k in range(0, 4 * n, 4) if v[k + 1] == v[k + 3]})\n    from bisect import bisect_left, bisect_right\n    idx = {y: i + 1 for i, y in enumerate(ys)}\n    m = len(ys)\n    # eventos codificados en un entero para ordenar rápido: (x, tipo, índice del segmento)\n    # tipo 0 = empieza horizontal, 1 = vertical (consulta), 2 = termina horizontal\n    ev = []\n    for k in range(0, 4 * n, 4):\n        x1, y1, x2, y2 = v[k], v[k + 1], v[k + 2], v[k + 3]\n        if y1 == y2:\n            ev.append(((x1 + 1000000) * 3) * n + k // 4)\n            ev.append(((x2 + 1000000) * 3 + 2) * n + k // 4)\n        else:\n            ev.append(((x1 + 1000000) * 3 + 1) * n + k // 4)\n    ev.sort()\n    bit = [0] * (m + 1)\n    total = 0\n    for e in ev:\n        t = e // n % 3\n        k = 4 * (e % n)\n        if t == 1:\n            # horizontales activas con altura en [y1, y2]\n            hi = bisect_right(ys, v[k + 3])\n            lo = bisect_left(ys, v[k + 1])\n            s = 0\n            while hi > 0:\n                s += bit[hi]\n                hi -= hi & -hi\n            while lo > 0:\n                s -= bit[lo]\n                lo -= lo & -lo\n            total += s\n        else:\n            i, d = idx[v[k + 1]], (1 if t == 0 else -1)\n            while i <= m:\n                bit[i] += d\n                i += i & -i\n    print(total)\n\n\nmain()\n"}, {"id": "Geometry-Classic-Problems-Lines-and-Queries-I", "carpeta": "Geometry", "area": "Geometría", "sub": "Classic Problems", "archivo": "Geometry/Classic Problems/Lines and Queries I.cpp", "nombre": "Lines and Queries I", "algoritmo": "Li Chao Tree (máximo entre rectas en un punto)", "problema": "CSES 3429 - Lines and Queries I (https://cses.fi/problemset/task/3429)", "cses": "https://cses.fi/problemset/task/3429", "py_lento": false, "entrada": "n, luego n consultas \"1 a b\" (agregar la recta ax + b) o \"2 x\" (máximo en x)", "salida": "la respuesta de cada consulta de tipo 2", "complejidad": "tiempo O(n log X) con X = 10^5, memoria O(X)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Li Chao Tree (máximo entre rectas en un punto)\n * Problema  : CSES 3429 - Lines and Queries I (https://cses.fi/problemset/task/3429)\n * Entrada   : n, luego n consultas \"1 a b\" (agregar la recta ax + b) o \"2 x\" (máximo en x)\n * Salida    : la respuesta de cada consulta de tipo 2\n * Complejidad: tiempo O(n log X) con X = 10^5, memoria O(X)\n */\n\nconst int X = 100001;  // x va de 0 a 10^5\nstruct Line { ll a, b; ll f(ll x) const { return a * x + b; } };\nvector<Line> t(4 * X, {0, -INF});\nvector<bool> has(4 * X, false);\n\n// cada nodo guarda la recta que gana en el centro de su tramo; la perdedora baja al lado donde podría ganar\nvoid add(Line ln, int v = 1, int l = 0, int r = X - 1) {\n    if (!has[v]) { t[v] = ln; has[v] = true; return; }\n    int m = (l + r) / 2;\n    bool winL = ln.f(l) > t[v].f(l), winM = ln.f(m) > t[v].f(m);\n    if (winM) swap(ln, t[v]);           // el nodo se queda con la mejor en el centro\n    if (l == r) return;\n    // dos rectas se cruzan a lo sumo una vez: la perdedora solo puede ganar en una mitad\n    if (winL != winM) add(ln, 2 * v, l, m);\n    else add(ln, 2 * v + 1, m + 1, r);\n}\n\nll query(int x, int v = 1, int l = 0, int r = X - 1) {\n    if (!has[v]) return -INF;\n    ll res = t[v].f(x);\n    if (l == r) return res;\n    int m = (l + r) / 2;\n    return max(res, x <= m ? query(x, 2 * v, l, m) : query(x, 2 * v + 1, m + 1, r));\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    while (n--) {\n        int ty;\n        cin >> ty;\n        if (ty == 1) { ll a, b; cin >> a >> b; add({a, b}); }\n        else { int x; cin >> x; cout << query(x) << \"\\n\"; }\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Li Chao Tree (máximo entre rectas en un punto)\n * Problema  : CSES 3429 - Lines and Queries I (https://cses.fi/problemset/task/3429)\n * Entrada   : n, luego n consultas \"1 a b\" (agregar la recta ax + b) o \"2 x\" (máximo en x)\n * Salida    : la respuesta de cada consulta de tipo 2\n * Complejidad: tiempo O(n log X) con X = 10^5, memoria O(X)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    X = 1 << 17  # potencia de 2 mayor que 10^5 + 1: el árbol cubre x en [0, X)\n    # A[v], B[v] = recta del nodo v (None = vacío); gana en el centro del tramo del nodo\n    A = [0] * (2 * X)\n    B = [None] * (2 * X)\n    out = []\n    pos = 1\n    for _ in range(n):\n        if data[pos] == b'1':\n            a, b = int(data[pos + 1]), int(data[pos + 2])\n            pos += 3\n            v, l, r = 1, 0, X - 1\n            while True:\n                if B[v] is None:\n                    A[v], B[v] = a, b\n                    break\n                m = (l + r) >> 1\n                ca, cb = A[v], B[v]\n                win_l = a * l + b > ca * l + cb\n                win_m = a * m + b > ca * m + cb\n                if win_m:  # el nodo se queda con la mejor en el centro\n                    A[v], B[v], a, b = a, b, ca, cb\n                if l == r:\n                    break\n                # la perdedora solo puede ganar en una de las dos mitades\n                if win_l != win_m:\n                    v, r = 2 * v, m\n                else:\n                    v, l = 2 * v + 1, m + 1\n        else:\n            x = int(data[pos + 1])\n            pos += 2\n            # el máximo está en algún nodo del camino de la raíz a la hoja x\n            v = x + X\n            best = -INF\n            while v:\n                if B[v] is not None:\n                    y = A[v] * x + B[v]\n                    if y > best:\n                        best = y\n                v >>= 1\n            out.append(best)\n    print('\\n'.join(map(str, out)))\n\n\nmain()\n"}, {"id": "Geometry-Classic-Problems-Maximum-Manhattan-Distances", "carpeta": "Geometry", "area": "Geometría", "sub": "Classic Problems", "archivo": "Geometry/Classic Problems/Maximum Manhattan Distances.cpp", "nombre": "Maximum Manhattan Distances", "algoritmo": "Rotación de 45° (|dx| + |dy| = max(|du|, |dv|) con u = x + y, v = x - y)", "problema": "CSES 3410 - Maximum Manhattan Distances (https://cses.fi/problemset/task/3410)", "cses": "https://cses.fi/problemset/task/3410", "py_lento": false, "entrada": "n, luego n puntos \"x y\" que se agregan uno por uno", "salida": "después de cada punto, la mayor distancia Manhattan entre dos puntos del conjunto", "complejidad": "tiempo O(n), memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Rotación de 45° (|dx| + |dy| = max(|du|, |dv|) con u = x + y, v = x - y)\n * Problema  : CSES 3410 - Maximum Manhattan Distances (https://cses.fi/problemset/task/3410)\n * Entrada   : n, luego n puntos \"x y\" que se agregan uno por uno\n * Salida    : después de cada punto, la mayor distancia Manhattan entre dos puntos del conjunto\n * Complejidad: tiempo O(n), memoria O(1)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    // basta conocer el mínimo y el máximo de u = x + y y de v = x - y\n    ll minU = INF, maxU = -INF, minV = INF, maxV = -INF;\n    while (n--) {\n        ll x, y;\n        cin >> x >> y;\n        ll u = x + y, v = x - y;\n        minU = min(minU, u), maxU = max(maxU, u);\n        minV = min(minV, v), maxV = max(maxV, v);\n        cout << max(maxU - minU, maxV - minV) << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Rotación de 45° (|dx| + |dy| = max(|du|, |dv|) con u = x + y, v = x - y)\n * Problema  : CSES 3410 - Maximum Manhattan Distances (https://cses.fi/problemset/task/3410)\n * Entrada   : n, luego n puntos \"x y\" que se agregan uno por uno\n * Salida    : después de cada punto, la mayor distancia Manhattan entre dos puntos del conjunto\n * Complejidad: tiempo O(n), memoria O(1)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + 2 * n]))\n    # basta conocer el mínimo y el máximo de u = x + y y de w = x - y\n    lo_u = lo_w = INF\n    hi_u = hi_w = -INF\n    out = []\n    for k in range(0, 2 * n, 2):\n        x, y = v[k], v[k + 1]\n        u, w = x + y, x - y\n        if u < lo_u: lo_u = u\n        if u > hi_u: hi_u = u\n        if w < lo_w: lo_w = w\n        if w > hi_w: hi_w = w\n        out.append(max(hi_u - lo_u, hi_w - lo_w))\n    print('\\n'.join(map(str, out)))\n\n\nmain()\n"}, {"id": "Geometry-Classic-Problems-Point-Location-Test", "carpeta": "Geometry", "area": "Geometría", "sub": "Classic Problems", "archivo": "Geometry/Classic Problems/Point Location Test.cpp", "nombre": "Point Location Test", "algoritmo": "Producto cruz (orientación de tres puntos)", "problema": "CSES 2189 - Point Location Test (https://cses.fi/problemset/task/2189)", "cses": "https://cses.fi/problemset/task/2189", "py_lento": false, "entrada": "t, luego t líneas \"x1 y1 x2 y2 x3 y3\"", "salida": "LEFT, RIGHT o TOUCH según dónde queda p3 respecto a la recta p1 -> p2", "complejidad": "tiempo O(1) por caso, memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Producto cruz (orientación de tres puntos)\n * Problema  : CSES 2189 - Point Location Test (https://cses.fi/problemset/task/2189)\n * Entrada   : t, luego t líneas \"x1 y1 x2 y2 x3 y3\"\n * Salida    : LEFT, RIGHT o TOUCH según dónde queda p3 respecto a la recta p1 -> p2\n * Complejidad: tiempo O(1) por caso, memoria O(1)\n */\n\nint main() {\n    fastio;\n    int t;\n    cin >> t;\n    while (t--) {\n        ll x1, y1, x2, y2, x3, y3;\n        cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;\n        // cruz de (p2 - p1) con (p3 - p1): positivo = giro a la izquierda, negativo = a la derecha\n        // los valores llegan a ~8·10^18, que todavía cabe en long long\n        ll cr = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);\n        cout << (cr > 0 ? \"LEFT\" : cr < 0 ? \"RIGHT\" : \"TOUCH\") << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Producto cruz (orientación de tres puntos)\n * Problema  : CSES 2189 - Point Location Test (https://cses.fi/problemset/task/2189)\n * Entrada   : t, luego t líneas \"x1 y1 x2 y2 x3 y3\"\n * Salida    : LEFT, RIGHT o TOUCH según dónde queda p3 respecto a la recta p1 -> p2\n * Complejidad: tiempo O(1) por caso, memoria O(1)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    t = int(data[0])\n    v = list(map(int, data[1:1 + 6 * t]))\n    out = []\n    for k in range(0, 6 * t, 6):\n        x1, y1, x2, y2, x3, y3 = v[k:k + 6]\n        # cruz de (p2 - p1) con (p3 - p1): positivo = izquierda, negativo = derecha, 0 = sobre la recta\n        cr = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)\n        out.append('LEFT' if cr > 0 else 'RIGHT' if cr < 0 else 'TOUCH')\n    print('\\n'.join(out))\n\n\nmain()\n"}, {"id": "FunctionalTools-Classic-Problems-Array-Division", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Classic Problems", "archivo": "FunctionalTools/Classic Problems/Array Division.cpp", "nombre": "Array Division", "algoritmo": "Búsqueda binaria sobre la respuesta + verificación golosa", "problema": "CSES 1085 - Array Division (https://cses.fi/problemset/task/1085)", "cses": "https://cses.fi/problemset/task/1085", "py_lento": true, "entrada": "n k, luego n enteros positivos", "salida": "la menor suma máxima posible al partir el arreglo en k subarreglos", "complejidad": "tiempo O(n log S) con S = suma total, memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Búsqueda binaria sobre la respuesta + verificación golosa\n * Problema  : CSES 1085 - Array Division (https://cses.fi/problemset/task/1085)\n * Entrada   : n k, luego n enteros positivos\n * Salida    : la menor suma máxima posible al partir el arreglo en k subarreglos\n * Complejidad: tiempo O(n log S) con S = suma total, memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n, k;\n    cin >> n >> k;\n    vector<ll> x(n);\n    ll lo = 0, hi = 0;\n    for (auto &v : x) cin >> v, lo = max(lo, v), hi += v;\n    // ¿se puede con suma máxima L? Golosamente se llena cada parte hasta donde quepa\n    auto cabe = [&](ll L) {\n        int partes = 1;\n        ll s = 0;\n        for (ll v : x) {\n            if (s + v > L) partes++, s = 0;\n            s += v;\n        }\n        return partes <= k;\n    };\n    // si L sirve, cualquier L mayor también: se busca el menor que sirve\n    while (lo < hi) {\n        ll mid = (lo + hi) / 2;\n        if (cabe(mid)) hi = mid;\n        else lo = mid + 1;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nfrom itertools import accumulate\nfrom bisect import bisect_right\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Búsqueda binaria sobre la respuesta + verificación golosa\n * Problema  : CSES 1085 - Array Division (https://cses.fi/problemset/task/1085)\n * Entrada   : n k, luego n enteros positivos\n * Salida    : la menor suma máxima posible al partir el arreglo en k subarreglos\n * Complejidad: tiempo O(n log S) con S = suma total, memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n, k = int(data[0]), int(data[1])\n    x = list(map(int, data[2:2 + n]))\n    p = [0] + list(accumulate(x))  # p[i] = x_1 + ... + x_i\n\n    def cabe(L):\n        \"\"\"¿Se puede con suma máxima L? Cada parte se extiende lo más posible (salto con bisect).\"\"\"\n        i, partes = 0, 0\n        while i < n:\n            partes += 1\n            if partes > k:\n                return False\n            # la parte que empieza en i llega hasta el último j con p[j] - p[i] <= L\n            i = bisect_right(p, p[i] + L) - 1\n        return True\n\n    # si L sirve, cualquier L mayor también: se busca el menor que sirve\n    lo, hi = max(x), p[n]\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if cabe(mid):\n            hi = mid\n        else:\n            lo = mid + 1\n    print(lo)\n\n\nmain()\n"}, {"id": "FunctionalTools-Classic-Problems-Counting-Divisors", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Classic Problems", "archivo": "FunctionalTools/Classic Problems/Counting Divisors.cpp", "nombre": "Counting Divisors", "algoritmo": "Criba del menor factor primo + fórmula de cantidad de divisores", "problema": "CSES 1713 - Counting Divisors (https://cses.fi/problemset/task/1713)", "cses": "https://cses.fi/problemset/task/1713", "py_lento": false, "entrada": "n, luego n enteros x (x ≤ 10^6)", "salida": "la cantidad de divisores de cada x", "complejidad": "tiempo O(X log log X + n log x), memoria O(X)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Criba del menor factor primo + fórmula de cantidad de divisores\n * Problema  : CSES 1713 - Counting Divisors (https://cses.fi/problemset/task/1713)\n * Entrada   : n, luego n enteros x (x ≤ 10^6)\n * Salida    : la cantidad de divisores de cada x\n * Complejidad: tiempo O(X log log X + n log x), memoria O(X)\n */\n\nconst int X = 1000000;\n\nint main() {\n    fastio;\n    // spf[v] = menor factor primo de v\n    vector<int> spf(X + 1, 0);\n    for (int i = 2; i <= X; i++)\n        if (!spf[i])\n            for (int j = i; j <= X; j += i)\n                if (!spf[j]) spf[j] = i;\n    int n;\n    cin >> n;\n    while (n--) {\n        int x;\n        cin >> x;\n        // si x = p1^e1 · p2^e2 · ..., tiene (e1 + 1)(e2 + 1)... divisores\n        int res = 1;\n        while (x > 1) {\n            int p = spf[x], e = 0;\n            while (x % p == 0) x /= p, e++;\n            res *= e + 1;\n        }\n        cout << res << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Criba del menor factor primo + fórmula de cantidad de divisores\n * Problema  : CSES 1713 - Counting Divisors (https://cses.fi/problemset/task/1713)\n * Entrada   : n, luego n enteros x (x ≤ 10^6)\n * Salida    : la cantidad de divisores de cada x\n * Complejidad: tiempo O(X log log X + n log x), memoria O(X)\n\"\"\"\n\nX = 10**6\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    # spf[v] = menor factor primo de v. Se recorren los primos de mayor a menor hasta 1000:\n    # cada asignación por rebanadas pisa a las de primos mayores, así queda el menor.\n    spf = list(range(X + 1))\n    small = [p for p in range(2, 1001) if all(p % q for q in range(2, int(p**0.5) + 1))]\n    for p in reversed(small):\n        spf[p * p::p] = [p] * len(range(p * p, X + 1, p))\n    out = []\n    for x in map(int, data[1:1 + n]):\n        # si x = p1^e1 · p2^e2 · ..., tiene (e1 + 1)(e2 + 1)... divisores\n        res = 1\n        while x > 1:\n            p = spf[x]\n            e = 1\n            x //= p\n            while x % p == 0:\n                x //= p\n                e += 1\n            res *= e + 1\n        out.append(res)\n    print('\\n'.join(map(str, out)))\n\n\nmain()\n"}, {"id": "FunctionalTools-Classic-Problems-Distributing-Apples", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Classic Problems", "archivo": "FunctionalTools/Classic Problems/Distributing Apples.cpp", "nombre": "Distributing Apples", "algoritmo": "Combinatoria (estrellas y barras) con factoriales e inversos modulares", "problema": "CSES 1716 - Distributing Apples (https://cses.fi/problemset/task/1716)", "cses": "https://cses.fi/problemset/task/1716", "py_lento": false, "entrada": "n m (niños y manzanas)", "salida": "formas de repartir m manzanas entre n niños, módulo 10^9+7", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Combinatoria (estrellas y barras) con factoriales e inversos modulares\n * Problema  : CSES 1716 - Distributing Apples (https://cses.fi/problemset/task/1716)\n * Entrada   : n m (niños y manzanas)\n * Salida    : formas de repartir m manzanas entre n niños, módulo 10^9+7\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nconst ll M = 1e9 + 7;\n\nll power(ll b, ll e) { ll r = 1; b %= M; for (; e; e >>= 1, b = b * b % M) if (e & 1) r = r * b % M; return r; }\n\nint main() {\n    fastio;\n    ll n, m;\n    cin >> n >> m;\n    // m manzanas (estrellas) y n-1 separadores (barras): se elige dónde van las barras\n    // respuesta = C(m + n - 1, n - 1)\n    int N = n + m;\n    vector<ll> f(N + 1, 1);\n    for (int i = 1; i <= N; i++) f[i] = f[i - 1] * i % M;\n    // inverso con el pequeño teorema de Fermat: a^(M-2) es el inverso de a módulo primo\n    ll k = n - 1;\n    cout << f[m + k] * power(f[k], M - 2) % M * power(f[m], M - 2) % M << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Combinatoria (estrellas y barras) con factoriales e inversos modulares\n * Problema  : CSES 1716 - Distributing Apples (https://cses.fi/problemset/task/1716)\n * Entrada   : n m (niños y manzanas)\n * Salida    : formas de repartir m manzanas entre n niños, módulo 10^9+7\n * Complejidad: tiempo O(n + m), memoria O(1)\n\"\"\"\n\nM = 10**9 + 7\n\n\ndef main():\n    n, m = map(int, input().split())\n    # m manzanas (estrellas) y n-1 separadores (barras): C(m + n - 1, n - 1)\n    k = n - 1\n    num = den = 1\n    for i in range(1, k + 1):\n        num = num * (m + i) % M   # (m+1)(m+2)...(m+k)\n        den = den * i % M         # k!\n    # inverso con el pequeño teorema de Fermat\n    print(num * pow(den, M - 2, M) % M)\n\n\nmain()\n"}, {"id": "FunctionalTools-Classic-Problems-Exponentiation", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Classic Problems", "archivo": "FunctionalTools/Classic Problems/Exponentiation.cpp", "nombre": "Exponentiation", "algoritmo": "Exponenciación binaria (rápida) modular", "problema": "CSES 1095 - Exponentiation (https://cses.fi/problemset/task/1095)", "cses": "https://cses.fi/problemset/task/1095", "py_lento": false, "entrada": "n, luego n pares \"a b\"", "salida": "a^b módulo 10^9+7 para cada par (con 0^0 = 1)", "complejidad": "tiempo O(log b) por par, memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Exponenciación binaria (rápida) modular\n * Problema  : CSES 1095 - Exponentiation (https://cses.fi/problemset/task/1095)\n * Entrada   : n, luego n pares \"a b\"\n * Salida    : a^b módulo 10^9+7 para cada par (con 0^0 = 1)\n * Complejidad: tiempo O(log b) por par, memoria O(1)\n */\n\nconst ll M = 1e9 + 7;\n\n// se recorre b en binario: base se eleva al cuadrado en cada paso y se multiplica cuando el bit está encendido\nll power(ll base, ll e) {\n    ll res = 1;\n    base %= M;\n    while (e > 0) {\n        if (e & 1) res = res * base % M;\n        base = base * base % M;\n        e >>= 1;\n    }\n    return res;\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    while (n--) {\n        ll a, b;\n        cin >> a >> b;\n        cout << power(a, b) << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Exponenciación binaria (rápida) modular\n * Problema  : CSES 1095 - Exponentiation (https://cses.fi/problemset/task/1095)\n * Entrada   : n, luego n pares \"a b\"\n * Salida    : a^b módulo 10^9+7 para cada par (con 0^0 = 1)\n * Complejidad: tiempo O(log b) por par, memoria O(1)\n\"\"\"\n\nM = 10**9 + 7\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + 2 * n]))\n    # pow(a, b, M) de Python ya hace exponenciación binaria (y da 1 para 0^0)\n    print('\\n'.join(str(pow(v[k], v[k + 1], M)) for k in range(0, 2 * n, 2)))\n\n\nmain()\n"}, {"id": "FunctionalTools-Classic-Problems-Prime-Multiples", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Classic Problems", "archivo": "FunctionalTools/Classic Problems/Prime Multiples.cpp", "nombre": "Prime Multiples", "algoritmo": "Principio de inclusión-exclusión sobre subconjuntos", "problema": "CSES 2185 - Prime Multiples (https://cses.fi/problemset/task/2185)", "cses": "https://cses.fi/problemset/task/2185", "py_lento": false, "entrada": "n k, luego k primos distintos", "salida": "cuántos enteros de 1 a n son divisibles por al menos uno de los primos", "complejidad": "tiempo O(2^k · k), memoria O(k)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Principio de inclusión-exclusión sobre subconjuntos\n * Problema  : CSES 2185 - Prime Multiples (https://cses.fi/problemset/task/2185)\n * Entrada   : n k, luego k primos distintos\n * Salida    : cuántos enteros de 1 a n son divisibles por al menos uno de los primos\n * Complejidad: tiempo O(2^k · k), memoria O(k)\n */\n\nint main() {\n    fastio;\n    ll n;\n    int k;\n    cin >> n >> k;\n    vector<ll> a(k);\n    for (auto &p : a) cin >> p;\n    ll total = 0;\n    // |A1 ∪ ... ∪ Ak| = Σ (−1)^(|S|+1) · ⌊n / producto(S)⌋ sobre los subconjuntos S no vacíos\n    for (int mask = 1; mask < (1 << k); mask++) {\n        ll prod = 1;\n        bool grande = false;\n        for (int i = 0; i < k && !grande; i++)\n            if (mask >> i & 1) {\n                // si el producto pasa de n, ese término vale 0 (se evita el desbordamiento)\n                if (prod > n / a[i]) grande = true;\n                else prod *= a[i];\n            }\n        if (grande) continue;\n        if (__builtin_popcount(mask) & 1) total += n / prod;\n        else total -= n / prod;\n    }\n    cout << total << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Principio de inclusión-exclusión sobre subconjuntos\n * Problema  : CSES 2185 - Prime Multiples (https://cses.fi/problemset/task/2185)\n * Entrada   : n k, luego k primos distintos\n * Salida    : cuántos enteros de 1 a n son divisibles por al menos uno de los primos\n * Complejidad: tiempo O(número de subconjuntos con producto ≤ n), memoria igual\n\"\"\"\n\n\ndef main():\n    n, k = map(int, input().split())\n    a = list(map(int, input().split()))\n    # terms = [(producto, signo)] de los subconjuntos con producto ≤ n (los demás aportan 0)\n    terms = [(1, -1)]  # el subconjunto vacío con signo -1 para que los de tamaño 1 queden en +1\n    for p in a:\n        terms += [(q * p, -s) for q, s in terms if q * p <= n]\n    # |A1 ∪ ... ∪ Ak| = Σ (−1)^(|S|+1) · ⌊n / producto(S)⌋ sobre los S no vacíos\n    print(sum(s * (n // q) for q, s in terms[1:]))\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-BS-library", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/BS(library).cpp", "nombre": "BS(library)", "algoritmo": "Búsqueda binaria con la librería (binary_search / lower_bound)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "n target, luego n enteros ordenados", "salida": "FOUND y su índice, o NOT FOUND", "complejidad": "tiempo O(log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Búsqueda binaria con la librería (binary_search / lower_bound)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n target, luego n enteros ordenados\n * Salida    : FOUND y su índice, o NOT FOUND\n * Complejidad: tiempo O(log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n; ll target;\n    cin >> n >> target;\n    vector<ll> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // asume a[] ordenado\n    // binary_search solo responde si existe\n    bool found = binary_search(all(a), target);\n    if (found) {\n        cout << \"FOUND\\n\";\n        // posición con lower_bound:\n        // lower_bound da la primera posición con valor >= target\n        int idx = int(lower_bound(all(a), target) - a.begin());\n        cout << \"at index \" << idx << \"\\n\";\n    } else {\n        cout << \"NOT FOUND\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\nfrom bisect import bisect_left\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Búsqueda binaria con la librería (binary_search / lower_bound)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n target, luego n enteros ordenados\n * Salida    : FOUND y su índice, o NOT FOUND\n * Complejidad: tiempo O(log n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.read().split()\n    n, target = int(data[0]), int(data[1])\n    a = list(map(int, data[2:2 + n]))\n    # bisect_left da la primera posición con valor >= target\n    idx = bisect_left(a, target)\n    # el valor existe si en esa posición está justo target\n    if idx < n and a[idx] == target:\n        print(\"FOUND\")\n        print(\"at index %d\" % idx)\n    else:\n        print(\"NOT FOUND\")\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-BS", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/BS.cpp", "nombre": "BS", "algoritmo": "Búsqueda binaria manual", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "n target, luego n enteros ordenados", "salida": "FOUND at index i, o NOT FOUND", "complejidad": "tiempo O(log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Búsqueda binaria manual\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n target, luego n enteros ordenados\n * Salida    : FOUND at index i, o NOT FOUND\n * Complejidad: tiempo O(log n), memoria O(n)\n */\n\n// devuelve el índice de target en a[] o -1 si no existe\n// mitad del rango en cada paso: se descarta la mitad donde no puede estar\nint binary_search_manual(const vector<ll>& a, ll target) {\n    int lo = 0, hi = int(a.size()) - 1;\n    while (lo <= hi) {\n        // mid se calcula así para evitar overflow\n        int mid = lo + (hi - lo) / 2;\n        if (a[mid] == target) return mid;\n        if (a[mid] < target) lo = mid + 1;\n        else hi = mid - 1;\n    }\n    return -1;\n}\n\nint main() {\n    fastio;\n    int n; ll target;\n    cin >> n >> target;\n    vector<ll> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // asume a[] ordenado\n    // la búsqueda exige el arreglo ordenado\n    int idx = binary_search_manual(a, target);\n    if (idx != -1) cout << \"FOUND at index \" << idx << \"\\n\";\n    else cout << \"NOT FOUND\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Búsqueda binaria manual\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n target, luego n enteros ordenados\n * Salida    : FOUND at index i, o NOT FOUND\n * Complejidad: tiempo O(log n), memoria O(n)\n\"\"\"\n\n\n# mitad del rango en cada paso: se descarta la mitad donde no puede estar\ndef binary_search_manual(a, target):\n    lo, hi = 0, len(a) - 1\n    while lo <= hi:\n        mid = lo + (hi - lo) // 2\n        if a[mid] == target:\n            return mid\n        if a[mid] < target:\n            lo = mid + 1\n        else:\n            hi = mid - 1\n    return -1\n\n\ndef main():\n    data = sys.stdin.read().split()\n    n, target = int(data[0]), int(data[1])\n    a = list(map(int, data[2:2 + n]))\n    # la búsqueda exige el arreglo ordenado\n    idx = binary_search_manual(a, target)\n    print(\"FOUND at index %d\" % idx if idx != -1 else \"NOT FOUND\")\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-BinarySearchAnswer", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/BinarySearchAnswer.cpp", "nombre": "BinarySearchAnswer", "algoritmo": "Búsqueda binaria sobre la respuesta", "problema": "CSES 1620 - Factory Machines (https://cses.fi/problemset/task/1620)", "cses": "https://cses.fi/problemset/task/1620", "py_lento": false, "entrada": "n t, luego n tiempos k_i (una máquina produce un producto cada k_i segundos)", "salida": "mínimo tiempo para producir t productos", "complejidad": "tiempo O(n log(t · k_min)), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Búsqueda binaria sobre la respuesta\n * Problema  : CSES 1620 - Factory Machines (https://cses.fi/problemset/task/1620)\n * Entrada   : n t, luego n tiempos k_i (una máquina produce un producto cada k_i segundos)\n * Salida    : mínimo tiempo para producir t productos\n * Complejidad: tiempo O(n log(t · k_min)), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    ll t;\n    cin >> n >> t;\n    vector<ll> k(n);\n    for (auto &x : k) cin >> x;\n\n    // la respuesta es monótona: si en \"time\" alcanza, en más tiempo también\n    // cota superior: la máquina más rápida sola produce t productos en k_min * t\n    ll lo = 1, hi = *min_element(all(k)) * t;\n    // se busca el menor tiempo que alcanza\n    while (lo < hi) {\n        ll mid = lo + (hi - lo) / 2;\n        ll made = 0;\n        for (ll x : k) {\n            // cada máquina produce mid / k_i productos\n            made += mid / x;\n            if (made >= t) break;\n        }\n        // alcanza: se prueba con menos tiempo; si no, con más\n        if (made >= t) hi = mid;\n        else lo = mid + 1;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Búsqueda binaria sobre la respuesta\n * Problema  : CSES 1620 - Factory Machines (https://cses.fi/problemset/task/1620)\n * Entrada   : n t, luego n tiempos k_i (una máquina produce un producto cada k_i segundos)\n * Salida    : mínimo tiempo para producir t productos\n * Complejidad: tiempo O(n log(t · k_min)), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n, t = map(int, input().split())\n    k = list(map(int, input().split()))\n\n    # cota superior: la máquina más rápida sola produce t productos en k_min * t\n    lo, hi = 1, min(k) * t\n    # la respuesta es monótona: si en \"mid\" alcanza, en más tiempo también\n    while lo < hi:\n        mid = (lo + hi) // 2\n        # cada máquina produce mid // k_i productos\n        made = 0\n        for x in k:\n            made += mid // x\n            if made >= t:\n                break\n        # alcanza: se prueba con menos tiempo; si no, con más\n        if made >= t:\n            hi = mid\n        else:\n            lo = mid + 1\n    print(lo)\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-GrayCode", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/GrayCode.cpp", "nombre": "GrayCode", "algoritmo": "Código de Gray (i ^ (i >> 1))", "problema": "CSES 2205 - Gray Code (https://cses.fi/problemset/task/2205)", "cses": "https://cses.fi/problemset/task/2205", "py_lento": false, "entrada": "n", "salida": "los 2^n códigos de Gray de n bits, uno por línea", "complejidad": "tiempo O(2^n · n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Código de Gray (i ^ (i >> 1))\n * Problema  : CSES 2205 - Gray Code (https://cses.fi/problemset/task/2205)\n * Entrada   : n\n * Salida    : los 2^n códigos de Gray de n bits, uno por línea\n * Complejidad: tiempo O(2^n · n), memoria O(n)\n */\n\nint main(){\n    fastio;\n \n    ll n; cin >> n;\n    // hay 2^n códigos\n    for(int i = 0; i < (1<<n); ++i){\n        // código Gray del número i: i XOR (i >> 1)\n        ll gn = (i^(i >> 1));\n        // se escribe gn en binario con n bits\n        string res = \"\";\n        for(int i = 0; i < n; i++){\n            if(gn & (1 << i)) res += \"1\";\n            else res += \"0\";\n        }\n        // los bits se armaron del menos al más significativo, se invierten\n        reverse(all(res));\n        cout << res  << \"\\n\";\n    }\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Código de Gray (i ^ (i >> 1))\n * Problema  : CSES 2205 - Gray Code (https://cses.fi/problemset/task/2205)\n * Entrada   : n\n * Salida    : los 2^n códigos de Gray de n bits, uno por línea\n * Complejidad: tiempo O(2^n · n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    out = []\n    # hay 2^n códigos\n    for i in range(1 << n):\n        # código Gray del número i: i XOR (i >> 1), escrito con n bits\n        out.append(format(i ^ (i >> 1), \"0%db\" % n))\n    print(\"\\n\".join(out))\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-MatrixExponentiation", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/MatrixExponentiation.cpp", "nombre": "MatrixExponentiation", "algoritmo": "Exponenciación de matrices (Fibonacci en O(log n))", "problema": "CSES 1722 - Fibonacci Numbers (https://cses.fi/problemset/task/1722)", "cses": "https://cses.fi/problemset/task/1722", "py_lento": false, "entrada": "n", "salida": "F(n) módulo 10^9+7", "complejidad": "tiempo O(k^3 log n), k = 2, memoria O(k^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Exponenciación de matrices (Fibonacci en O(log n))\n * Problema  : CSES 1722 - Fibonacci Numbers (https://cses.fi/problemset/task/1722)\n * Entrada   : n\n * Salida    : F(n) módulo 10^9+7\n * Complejidad: tiempo O(k^3 log n), k = 2, memoria O(k^2)\n */\n\nconst ll MODM = 1000000007;  // este problema pide módulo 10^9+7\n\n// matriz cuadrada\ntypedef vector<vector<ll>> Matrix;\n\n// producto de matrices módulo MODM\nMatrix multiply(const Matrix &A, const Matrix &B) {\n    int k = A.size();\n    Matrix C(k, vector<ll>(k, 0));\n    for (int i = 0; i < k; i++)\n        for (int j = 0; j < k; j++)\n            for (int l = 0; l < k; l++)\n                C[i][j] = (C[i][j] + A[i][l] * B[l][j]) % MODM;\n    return C;\n}\n\n// exponenciación binaria: eleva la matriz en O(log e) multiplicaciones\nMatrix power(Matrix A, ll e) {\n    int k = A.size();\n    Matrix R(k, vector<ll>(k, 0));\n    for (int i = 0; i < k; i++) R[i][i] = 1;\n    while (e > 0) {\n        if (e & 1) R = multiply(R, A);\n        A = multiply(A, A);\n        e >>= 1;\n    }\n    return R;\n}\n\nint main() {\n    fastio;\n    ll n;\n    cin >> n;\n    // [F(n+1) F(n); F(n) F(n-1)] = [[1,1],[1,0]]^n\n    // matriz de Fibonacci\n    Matrix M = {{1, 1}, {1, 0}};\n    cout << power(M, n)[0][1] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Exponenciación de matrices (Fibonacci en O(log n))\n * Problema  : CSES 1722 - Fibonacci Numbers (https://cses.fi/problemset/task/1722)\n * Entrada   : n\n * Salida    : F(n) módulo 10^9+7\n * Complejidad: tiempo O(k^3 log n), k = 2, memoria O(k^2)\n\"\"\"\n\n\nMODM = 1000000007  # este problema pide módulo 10^9+7\n\n\n# producto de matrices módulo MODM\ndef multiply(A, B):\n    k = len(A)\n    return [[sum(A[i][l] * B[l][j] for l in range(k)) % MODM for j in range(k)] for i in range(k)]\n\n\n# exponenciación binaria: eleva la matriz en O(log e) multiplicaciones\ndef power(A, e):\n    k = len(A)\n    R = [[int(i == j) for j in range(k)] for i in range(k)]\n    while e > 0:\n        if e & 1:\n            R = multiply(R, A)\n        A = multiply(A, A)\n        e >>= 1\n    return R\n\n\ndef main():\n    n = int(input())\n    # matriz de Fibonacci: [F(n+1) F(n); F(n) F(n-1)] = [[1,1],[1,0]]^n\n    M = [[1, 1], [1, 0]]\n    print(power(M, n)[0][1])\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-MeetInTheMiddle", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/MeetInTheMiddle.cpp", "nombre": "MeetInTheMiddle", "algoritmo": "Meet in the middle (subconjuntos con suma x)", "problema": "CSES 1628 - Meet in the Middle (https://cses.fi/problemset/task/1628)", "cses": "https://cses.fi/problemset/task/1628", "py_lento": false, "entrada": "n x, luego n enteros", "salida": "cantidad de subconjuntos cuya suma es x", "complejidad": "tiempo O(2^(n/2) · n), memoria O(2^(n/2))", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Meet in the middle (subconjuntos con suma x)\n * Problema  : CSES 1628 - Meet in the Middle (https://cses.fi/problemset/task/1628)\n * Entrada   : n x, luego n enteros\n * Salida    : cantidad de subconjuntos cuya suma es x\n * Complejidad: tiempo O(2^(n/2) · n), memoria O(2^(n/2))\n */\n\n// todas las sumas de subconjuntos de a[l..r)\n// genera 2^(r-l) sumas duplicando la lista con cada elemento\nvector<ll> subsetSums(const vector<ll> &a, int l, int r) {\n    vector<ll> sums = {0};\n    for (int i = l; i < r; i++) {\n        int sz = sums.size();\n        for (int j = 0; j < sz; j++) sums.push_back(sums[j] + a[i]);\n    }\n    return sums;\n}\n\nint main() {\n    fastio;\n    int n;\n    ll x;\n    cin >> n >> x;\n    vector<ll> a(n);\n    for (auto &v : a) cin >> v;\n\n    // se divide el arreglo en dos mitades\n    vector<ll> L = subsetSums(a, 0, n / 2), R = subsetSums(a, n / 2, n);\n    // R ordenado para buscar con búsqueda binaria\n    sort(all(R));\n    ll count = 0;\n    for (ll s : L)\n        // para cada suma de la mitad izquierda se cuentan las de la derecha que completan x\n        count += upper_bound(all(R), x - s) - lower_bound(all(R), x - s);\n    cout << count << \"\\n\";\n    return 0;\n}\n", "python": "import sys\nfrom collections import Counter\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Meet in the middle (subconjuntos con suma x)\n * Problema  : CSES 1628 - Meet in the Middle (https://cses.fi/problemset/task/1628)\n * Entrada   : n x, luego n enteros\n * Salida    : cantidad de subconjuntos cuya suma es x\n * Complejidad: tiempo O(2^(n/2) · n), memoria O(2^(n/2))\n\"\"\"\n\n\n# genera las sumas de todos los subconjuntos duplicando la lista con cada elemento\ndef subset_sums(a):\n    sums = [0]\n    for v in a:\n        sums += [s + v for s in sums]\n    return sums\n\n\ndef main():\n    n, x = map(int, input().split())\n    a = list(map(int, input().split()))\n\n    # se divide el arreglo en dos mitades\n    L = subset_sums(a[:n // 2])\n    R = subset_sums(a[n // 2:])\n    # se cuenta cuántas veces aparece cada suma de la mitad derecha\n    cnt = Counter(R)\n    # para cada suma de la mitad izquierda se cuentan las de la derecha que completan x\n    print(sum(cnt.get(x - s, 0) for s in L))\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-ModArithmetic", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/ModArithmetic.cpp", "nombre": "ModArithmetic", "algoritmo": "Exponenciación binaria, inverso modular y nCr", "problema": "CSES 1079 - Binomial Coefficients (https://cses.fi/problemset/task/1079)", "cses": "https://cses.fi/problemset/task/1079", "py_lento": false, "entrada": "t, luego t pares \"a b\"", "salida": "C(a, b) módulo 10^9 + 7", "complejidad": "tiempo O(10^6 + t), memoria O(10^6)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 1000000007\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Exponenciación binaria, inverso modular y nCr\n * Problema  : CSES 1079 - Binomial Coefficients (https://cses.fi/problemset/task/1079)\n * Entrada   : t, luego t pares \"a b\"\n * Salida    : C(a, b) módulo 10^9 + 7\n * Complejidad: tiempo O(10^6 + t), memoria O(10^6)\n */\n\n// fact[i] = i! y inv_fact[i] = inverso de i!, ambos módulo MOD\nconst int MAXN = 1000001;\nvector<ll> fact(MAXN), inv_fact(MAXN);\n\n// a^b mod MOD en O(log b)\nll binpow(ll a, ll b) {\n    ll res = 1;\n    a %= MOD;\n    while (b > 0) {\n        if (b & 1) res = res * a % MOD;\n        a = a * a % MOD;\n        b >>= 1;\n    }\n    return res;\n}\n\n// inverso modular (MOD debe ser primo): a^(MOD-2)\nll mod_inv(ll a) {\n    return binpow(a, MOD - 2);\n}\n\n// se precalculan factoriales e inversos en O(MAXN)\nvoid precompute() {\n    fact[0] = 1;\n    for (int i = 1; i < MAXN; i++) fact[i] = fact[i - 1] * i % MOD;\n    // inverso del último factorial con Fermat\n    inv_fact[MAXN - 1] = mod_inv(fact[MAXN - 1]);\n    // los demás inversos salen de inv_fact[i-1] = inv_fact[i] * i\n    for (int i = MAXN - 1; i > 0; i--) inv_fact[i - 1] = inv_fact[i] * i % MOD;\n}\n\n// C(n, k) mod MOD\nll nCr(int n, int k) {\n    if (k < 0 || k > n) return 0;\n    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;\n}\n\nint main() {\n    fastio;\n    precompute();\n    int t; cin >> t;\n    while (t--) {\n        int a, b; cin >> a >> b;\n        cout << nCr(a, b) << \"\\n\";\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 1000000007\n\n\"\"\"\n * Algoritmo : Exponenciación binaria, inverso modular y nCr\n * Problema  : CSES 1079 - Binomial Coefficients (https://cses.fi/problemset/task/1079)\n * Entrada   : t, luego t pares \"a b\"\n * Salida    : C(a, b) módulo 10^9 + 7\n * Complejidad: tiempo O(10^6 + t), memoria O(10^6)\n\"\"\"\n\n\n# fact[i] = i! y inv_fact[i] = inverso de i!, ambos módulo MOD\nMAXN = 1000001\n\n\ndef binpow(a, b):\n    res = 1\n    a %= MOD\n    while b > 0:\n        if b & 1:\n            res = res * a % MOD\n        a = a * a % MOD\n        b >>= 1\n    return res\n\n\ndef mod_inv(a):\n    return binpow(a, MOD - 2)\n\n\ndef main():\n    # se precalculan factoriales e inversos en O(MAXN)\n    fact = [1] * MAXN\n    for i in range(1, MAXN):\n        fact[i] = fact[i - 1] * i % MOD\n    inv_fact = [1] * MAXN\n    # inverso del último factorial con Fermat\n    inv_fact[MAXN - 1] = mod_inv(fact[MAXN - 1])\n    # los demás inversos salen de inv_fact[i-1] = inv_fact[i] * i\n    for i in range(MAXN - 1, 0, -1):\n        inv_fact[i - 1] = inv_fact[i] * i % MOD\n\n    def nCr(n, k):\n        if k < 0 or k > n:\n            return 0\n        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD\n\n    t = int(input())\n    out = []\n    for _ in range(t):\n        a, b = map(int, input().split())\n        out.append(nCr(a, b))\n    print(\"\\n\".join(map(str, out)))\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-Sieve", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/Sieve.cpp", "nombre": "Sieve", "algoritmo": "Criba de Eratóstenes y criba segmentada", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "N, luego L R", "salida": "primos ≤ N y luego los primos en [L, R]", "complejidad": "tiempo O(N log log N) y O((R-L) log log R), memoria O(N + R - L)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Criba de Eratóstenes y criba segmentada\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : N, luego L R\n * Salida    : primos ≤ N y luego los primos en [L, R]\n * Complejidad: tiempo O(N log log N) y O((R-L) log log R), memoria O(N + R - L)\n */\n\n// Criba de Eratóstenes: marca en `is_prime` los primos ≤ N.\n// is_prime[x] queda en true si x es primo\nvector<bool> sieve(int N) {\n    vector<bool> is_prime(N+1, true);\n    is_prime[0] = is_prime[1] = false;\n    // solo hace falta tachar múltiplos de primos hasta sqrt(N)\n    for (int p = 2; p*p <= N; ++p) {\n        if (is_prime[p]) {\n            for (int x = p*p; x <= N; x += p)\n                is_prime[x] = false;\n        }\n    }\n    return is_prime;\n}\n\n// Criba segmentada: devuelve todos los primos en [L..R], dados los primos ≤ sqrt(R).\n// criba por segmentos: se tachan los múltiplos de los primos pequeños dentro de [L, R]\nvector<ll> segmented_sieve(ll L, ll R) {\n    ll lim = floor(sqrt(R));\n    auto base = sieve(lim);\n    vector<ll> primes;\n    for (int i = 2; i <= lim; ++i)\n        if (base[i]) primes.push_back(i);\n\n    ll sz = R - L + 1;\n    vector<bool> is_prime(sz, true);\n    if (L <= 1) {\n        for (ll x = L; x <= min(R, 1LL); ++x) is_prime[x - L] = false;\n    }\n    for (ll p : primes) {\n        // primer múltiplo de p dentro del rango (sin tachar a p mismo)\n        ll start = max(p*p, ((L + p - 1)/p)*p);\n        for (ll x = start; x <= R; x += p)\n            is_prime[x - L] = false;\n    }\n\n    vector<ll> segment;\n    for (ll i = 0; i < sz; ++i) {\n        if (is_prime[i]) segment.push_back(L + i);\n    }\n    return segment;\n}\n\nint main() {\n    fastio;\n    // Ejemplo de uso:\n    int N; \n    cin >> N;\n    auto small = sieve(N);\n    // imprime primos ≤ N\n    for (int i = 2; i <= N; ++i)\n        if (small[i]) cout << i << ' ';\n    cout << '\\n';\n\n    ll L, R;\n    cin >> L >> R;\n    auto seg = segmented_sieve(L, R);\n    // imprime primos en [L..R]\n    for (ll p : seg) cout << p << ' ';\n    cout << '\\n';\n\n    return 0;\n}\n", "python": "import sys\nimport math\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Criba de Eratóstenes y criba segmentada\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : N, luego L R\n * Salida    : primos ≤ N y luego los primos en [L, R]\n * Complejidad: tiempo O(N log log N) y O((R-L) log log R), memoria O(N + R - L)\n\"\"\"\n\n\n# is_prime[x] queda en True si x es primo\ndef sieve(N):\n    is_prime = [True] * (N + 1)\n    is_prime[0] = False\n    if N >= 1:\n        is_prime[1] = False\n    # solo hace falta tachar múltiplos de primos hasta sqrt(N)\n    p = 2\n    while p * p <= N:\n        if is_prime[p]:\n            for x in range(p * p, N + 1, p):\n                is_prime[x] = False\n        p += 1\n    return is_prime\n\n\n# criba por segmentos: se tachan los múltiplos de los primos pequeños dentro de [L, R]\ndef segmented_sieve(L, R):\n    lim = math.isqrt(R)\n    base = sieve(lim)\n    primes = [i for i in range(2, lim + 1) if base[i]]\n    is_prime = [True] * (R - L + 1)\n    for x in range(L, min(R, 1) + 1):\n        is_prime[x - L] = False\n    for p in primes:\n        # primer múltiplo de p dentro del rango (sin tachar a p mismo)\n        start = max(p * p, (L + p - 1) // p * p)\n        for x in range(start, R + 1, p):\n            is_prime[x - L] = False\n    return [L + i for i in range(R - L + 1) if is_prime[i]]\n\n\ndef main():\n    data = sys.stdin.read().split()\n    N, L, R = int(data[0]), int(data[1]), int(data[2])\n    small = sieve(N)\n    print(\" \".join(str(i) for i in range(2, N + 1) if small[i]) + \" \")\n    print(\" \".join(map(str, segmented_sieve(L, R))) + \" \")\n\n\nmain()\n"}, {"id": "FunctionalTools-Codes-TS", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/TS.cpp", "nombre": "TS", "algoritmo": "Búsqueda ternaria (máximo de una función unimodal)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "L R", "salida": "el máximo de f(x) = -(x-3)^2 + 10 en [L, R]", "complejidad": "tiempo O(log(R-L)), memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Búsqueda ternaria (máximo de una función unimodal)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : L R\n * Salida    : el máximo de f(x) = -(x-3)^2 + 10 en [L, R]\n * Complejidad: tiempo O(log(R-L)), memoria O(1)\n */\n\n// asume f es unimodal (primero crece luego decrece) en [l..r]\n// se descarta un tercio del intervalo en cada paso\nll ternary_search(int l, int r, function<ll(int)> f) {\n    while (r - l > 3) {\n        int m1 = l + (r - l) / 3;\n        int m2 = r - (r - l) / 3;\n        if (f(m1) < f(m2))\n            l = m1;\n        else\n            r = m2;\n    }\n    // al quedar pocos valores se revisan uno por uno\n    ll best = f(l);\n    for (int i = l+1; i <= r; i++)\n        best = max(best, f(i));\n    return best;\n}\n\nint main() {\n    fastio;\n    int L, R;\n    cin >> L >> R;\n    // ejemplo: f(x) = -(x-3)^2 + 10  (unimodal)\n    auto f = [&](int x){ return -(ll)(x-3)*(x-3) + 10; };\n    ll ans = ternary_search(L, R, f);\n    cout << ans << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Búsqueda ternaria (máximo de una función unimodal)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : L R\n * Salida    : el máximo de f(x) = -(x-3)^2 + 10 en [L, R]\n * Complejidad: tiempo O(log(R-L)), memoria O(1)\n\"\"\"\n\n\n# se descarta un tercio del intervalo en cada paso\ndef ternary_search(l, r, f):\n    while r - l > 3:\n        m1 = l + (r - l) // 3\n        m2 = r - (r - l) // 3\n        if f(m1) < f(m2):\n            l = m1\n        else:\n            r = m2\n    # al quedar pocos valores se revisan uno por uno\n    return max(f(i) for i in range(l, r + 1))\n\n\ndef main():\n    L, R = map(int, sys.stdin.read().split()[:2])\n    print(ternary_search(L, R, lambda x: -(x - 3) * (x - 3) + 10))\n\n\nmain()\n"}, {"id": "Probability-Algorithms-ExpectedMaximum", "carpeta": "Probability", "area": "Probabilidad", "sub": "Algorithms", "archivo": "Probability/Algorithms/ExpectedMaximum.cpp", "nombre": "ExpectedMaximum", "algoritmo": "Esperanza del máximo con P(máx ≤ m) = (m/k)^n", "problema": "CSES 1727 - Candy Lottery (https://cses.fi/problemset/task/1727)", "cses": "https://cses.fi/problemset/task/1727", "py_lento": false, "entrada": "n k", "salida": "valor esperado del máximo de n enteros al azar en [1, k], con seis decimales", "complejidad": "tiempo O(k log n), memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Esperanza del máximo con P(máx ≤ m) = (m/k)^n\n * Problema  : CSES 1727 - Candy Lottery (https://cses.fi/problemset/task/1727)\n * Entrada   : n k\n * Salida    : valor esperado del máximo de n enteros al azar en [1, k], con seis decimales\n * Complejidad: tiempo O(k log n), memoria O(1)\n */\n\nint main() {\n    fastio;\n    int n, k;\n    cin >> n >> k;\n    // el máximo es ≤ m si TODOS son ≤ m: (m/k)^n; entonces P(máx = m) = (m/k)^n − ((m−1)/k)^n\n    double res = 0;\n    for (int m = 1; m <= k; m++) res += m * (pow((double)m / k, n) - pow((double)(m - 1) / k, n));\n    precision(6);\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Esperanza del máximo con P(máx ≤ m) = (m/k)^n\n * Problema  : CSES 1727 - Candy Lottery (https://cses.fi/problemset/task/1727)\n * Entrada   : n k\n * Salida    : valor esperado del máximo de n enteros al azar en [1, k], con seis decimales\n * Complejidad: tiempo O(k log n), memoria O(1)\n\"\"\"\n\n\ndef main():\n    n, k = map(int, input().split())\n    # P(máx ≤ m) = (m/k)^n porque todos deben ser ≤ m; P(máx = m) = (m/k)^n − ((m−1)/k)^n\n    res = sum(m * ((m / k) ** n - ((m - 1) / k) ** n) for m in range(1, k + 1))\n    print(f\"{res:.6f}\")\n\n\nmain()\n"}, {"id": "Probability-Algorithms-LinearityOfExpectation", "carpeta": "Probability", "area": "Probabilidad", "sub": "Algorithms", "archivo": "Probability/Algorithms/LinearityOfExpectation.cpp", "nombre": "LinearityOfExpectation", "algoritmo": "Linealidad de la esperanza (sumar la probabilidad de cada par)", "problema": "CSES 1728 - Inversion Probability (https://cses.fi/problemset/task/1728)", "cses": "https://cses.fi/problemset/task/1728", "py_lento": false, "entrada": "n, luego r_1 … r_n (x_i es uniforme en [1, r_i])", "salida": "número esperado de inversiones, con seis decimales", "complejidad": "tiempo O(n^2 · R), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Linealidad de la esperanza (sumar la probabilidad de cada par)\n * Problema  : CSES 1728 - Inversion Probability (https://cses.fi/problemset/task/1728)\n * Entrada   : n, luego r_1 … r_n (x_i es uniforme en [1, r_i])\n * Salida    : número esperado de inversiones, con seis decimales\n * Complejidad: tiempo O(n^2 · R), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<int> r(n);\n    for (auto &x : r) cin >> x;\n    // E[inversiones] = Σ_{i<j} P(x_i > x_j): cada par es una variable 0/1 y las esperanzas se suman\n    // aunque los pares NO sean independientes entre sí\n    double res = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = i + 1; j < n; j++) {\n            // casos favorables: x_i = v y x_j < v, es decir min(v − 1, r_j) opciones para x_j\n            long long fav = 0;\n            for (int v = 1; v <= r[i]; v++) fav += min(v - 1, r[j]);\n            res += (double)fav / ((double)r[i] * r[j]);\n        }\n    precision(6);\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Linealidad de la esperanza (sumar la probabilidad de cada par)\n * Problema  : CSES 1728 - Inversion Probability (https://cses.fi/problemset/task/1728)\n * Entrada   : n, luego r_1 … r_n (x_i es uniforme en [1, r_i])\n * Salida    : número esperado de inversiones, con seis decimales\n * Complejidad: tiempo O(n^2 · R), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    r = list(map(int, input().split()))\n    # E[inversiones] = Σ_{i<j} P(x_i > x_j), aunque los pares no sean independientes\n    res = 0.0\n    for i in range(n):\n        for j in range(i + 1, n):\n            # casos favorables: x_i = v y x_j < v → min(v − 1, r_j) opciones\n            fav = sum(min(v - 1, r[j]) for v in range(1, r[i] + 1))\n            res += fav / (r[i] * r[j])\n    print(f\"{res:.6f}\")\n\n\nmain()\n"}, {"id": "Probability-Algorithms-MarkovChain", "carpeta": "Probability", "area": "Probabilidad", "sub": "Algorithms", "archivo": "Probability/Algorithms/MarkovChain.cpp", "nombre": "MarkovChain", "algoritmo": "Cadena de Markov (distribución tras k pasos) + linealidad de la esperanza", "problema": "CSES 1726 - Moving Robots (https://cses.fi/problemset/task/1726)", "cses": "https://cses.fi/problemset/task/1726", "py_lento": false, "entrada": "k", "salida": "número esperado de casillas vacías de un tablero 8×8 tras k pasos, con seis decimales", "complejidad": "tiempo O(64 · k · 64), memoria O(64 · 64)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Cadena de Markov (distribución tras k pasos) + linealidad de la esperanza\n * Problema  : CSES 1726 - Moving Robots (https://cses.fi/problemset/task/1726)\n * Entrada   : k\n * Salida    : número esperado de casillas vacías de un tablero 8×8 tras k pasos, con seis decimales\n * Complejidad: tiempo O(64 · k · 64), memoria O(64 · 64)\n */\n\nint main() {\n    fastio;\n    int k;\n    cin >> k;\n    int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};\n    // vacia[c] = probabilidad de que la casilla c quede vacía = Π sobre robots de (1 - P(robot termina en c))\n    vector<double> vacia(64, 1.0);\n    for (int start = 0; start < 64; start++) {\n        // p[c] = probabilidad de que el robot que salió de start esté en c\n        vector<double> p(64, 0.0);\n        p[start] = 1.0;\n        for (int step = 0; step < k; step++) {\n            vector<double> q(64, 0.0);\n            for (int c = 0; c < 64; c++) {\n                if (p[c] == 0) continue;\n                int x = c / 8, y = c % 8;\n                // el robot elige al azar entre las direcciones que no lo sacan del tablero\n                vector<int> vec;\n                for (int d = 0; d < 4; d++) {\n                    int a = x + dx[d], b = y + dy[d];\n                    if (a >= 0 && a < 8 && b >= 0 && b < 8) vec.push_back(a * 8 + b);\n                }\n                for (int v : vec) q[v] += p[c] / vec.size();\n            }\n            p = q;\n        }\n        // los robots se mueven de forma independiente: las probabilidades se multiplican\n        for (int c = 0; c < 64; c++) vacia[c] *= 1 - p[c];\n    }\n    // linealidad: E[vacías] = Σ P(casilla vacía)\n    double res = 0;\n    for (double v : vacia) res += v;\n    precision(6);\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Cadena de Markov (distribución tras k pasos) + linealidad de la esperanza\n * Problema  : CSES 1726 - Moving Robots (https://cses.fi/problemset/task/1726)\n * Entrada   : k\n * Salida    : número esperado de casillas vacías de un tablero 8×8 tras k pasos, con seis decimales\n * Complejidad: tiempo O(64 · k · 64), memoria O(64 · 64)\n\"\"\"\n\n\ndef main():\n    k = int(input())\n    # vecinos de cada casilla (el robot elige al azar entre los que no lo sacan del tablero)\n    nb = []\n    for c in range(64):\n        x, y = divmod(c, 8)\n        nb.append([a * 8 + b for a, b in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)) if 0 <= a < 8 and 0 <= b < 8])\n    vacia = [1.0] * 64\n    for start in range(64):\n        # p[c] = probabilidad de que el robot que salió de start esté en c\n        p = [0.0] * 64\n        p[start] = 1.0\n        for _ in range(k):\n            q = [0.0] * 64\n            for c in range(64):\n                if p[c]:\n                    share = p[c] / len(nb[c])\n                    for v in nb[c]:\n                        q[v] += share\n            p = q\n        # los robots son independientes: P(c vacía) = Π (1 - P(robot en c))\n        for c in range(64):\n            vacia[c] *= 1 - p[c]\n    # linealidad de la esperanza: E[vacías] = Σ P(casilla vacía)\n    print(f\"{sum(vacia):.6f}\")\n\n\nmain()\n"}, {"id": "Probability-Algorithms-ModularExpectation", "carpeta": "Probability", "area": "Probabilidad", "sub": "Algorithms", "archivo": "Probability/Algorithms/ModularExpectation.cpp", "nombre": "ModularExpectation", "algoritmo": "Esperanza como fracción p/q módulo primo (inversos modulares)", "problema": "Codeforces 1265E - Beautiful Mirrors (https://codeforces.com/problemset/problem/1265/E)", "cses": "https://codeforces.com/problemset/problem/1265/E", "py_lento": false, "entrada": "n, luego p_1 … p_n (el espejo i dice \"sí\" con probabilidad p_i/100)", "salida": "días esperados hasta que los n espejos digan \"sí\" seguidos, como p · q^(−1) mód 998244353", "complejidad": "tiempo O(n + log M), memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Esperanza como fracción p/q módulo primo (inversos modulares)\n * Problema  : Codeforces 1265E - Beautiful Mirrors (https://codeforces.com/problemset/problem/1265/E)\n * Entrada   : n, luego p_1 … p_n (el espejo i dice \"sí\" con probabilidad p_i/100)\n * Salida    : días esperados hasta que los n espejos digan \"sí\" seguidos, como p · q^(−1) mód 998244353\n * Complejidad: tiempo O(n + log M), memoria O(1)\n */\n\nll power(ll b, ll e) { ll r = 1; b %= MOD; for (; e; e >>= 1, b = b * b % MOD) if (e & 1) r = r * b % MOD; return r; }\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    // E = (1 + q1 + q1·q2 + … + q1⋯q_{n−1}) / (q1⋯qn), con q_i = p_i/100:\n    // el día k-ésimo de un intento solo ocurre si los k−1 anteriores dijeron \"sí\", y cada intento\n    // completo tiene éxito con probabilidad q1⋯qn\n    ll inv100 = power(100, MOD - 2), num = 0, prod = 1;\n    for (int i = 0; i < n; i++) {\n        ll p;\n        cin >> p;\n        num = (num + prod) % MOD;                 // suma 1, q1, q1·q2, ...\n        prod = prod * (p * inv100 % MOD) % MOD;   // q1⋯qi\n    }\n    // dividir módulo primo = multiplicar por el inverso (pequeño teorema de Fermat)\n    cout << num * power(prod, MOD - 2) % MOD << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Esperanza como fracción p/q módulo primo (inversos modulares)\n * Problema  : Codeforces 1265E - Beautiful Mirrors (https://codeforces.com/problemset/problem/1265/E)\n * Entrada   : n, luego p_1 … p_n (el espejo i dice \"sí\" con probabilidad p_i/100)\n * Salida    : días esperados hasta que los n espejos digan \"sí\" seguidos, como p · q^(−1) mód 998244353\n * Complejidad: tiempo O(n + log M), memoria O(1)\n\"\"\"\n\n\ndef main():\n    n = int(input())\n    ps = list(map(int, input().split()))\n    # E = (1 + q1 + q1·q2 + … + q1⋯q_{n−1}) / (q1⋯qn), con q_i = p_i/100\n    inv100 = pow(100, MOD - 2, MOD)\n    num, prod = 0, 1\n    for p in ps:\n        num = (num + prod) % MOD          # suma 1, q1, q1·q2, ...\n        prod = prod * p % MOD * inv100 % MOD\n    # dividir módulo primo = multiplicar por el inverso (Fermat)\n    print(num * pow(prod, MOD - 2, MOD) % MOD)\n\n\nmain()\n"}, {"id": "Probability-Algorithms-ProbabilityDP", "carpeta": "Probability", "area": "Probabilidad", "sub": "Algorithms", "archivo": "Probability/Algorithms/ProbabilityDP.cpp", "nombre": "ProbabilityDP", "algoritmo": "DP de probabilidades (distribución de la suma de varios dados)", "problema": "CSES 1725 - Dice Probability (https://cses.fi/problemset/task/1725)", "cses": "https://cses.fi/problemset/task/1725", "py_lento": false, "entrada": "n a b", "salida": "probabilidad de que la suma de n dados esté en [a, b], con seis decimales", "complejidad": "tiempo O(n · 6n · 6), memoria O(6n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP de probabilidades (distribución de la suma de varios dados)\n * Problema  : CSES 1725 - Dice Probability (https://cses.fi/problemset/task/1725)\n * Entrada   : n a b\n * Salida    : probabilidad de que la suma de n dados esté en [a, b], con seis decimales\n * Complejidad: tiempo O(n · 6n · 6), memoria O(6n)\n */\n\nint main() {\n    fastio;\n    int n, a, b;\n    cin >> n >> a >> b;\n    // p[s] = probabilidad de que la suma de los dados lanzados hasta ahora sea s\n    vector<double> p(6 * n + 1, 0.0);\n    p[0] = 1.0;\n    for (int d = 1; d <= n; d++) {\n        vector<double> q(6 * n + 1, 0.0);\n        // cada cara 1..6 sale con probabilidad 1/6 y suma su valor\n        for (int s = 0; s <= 6 * (d - 1); s++)\n            if (p[s] > 0)\n                for (int c = 1; c <= 6; c++) q[s + c] += p[s] / 6.0;\n        p = q;\n    }\n    double res = 0;\n    for (int s = a; s <= b; s++) res += p[s];\n    precision(6);\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de probabilidades (distribución de la suma de varios dados)\n * Problema  : CSES 1725 - Dice Probability (https://cses.fi/problemset/task/1725)\n * Entrada   : n a b\n * Salida    : probabilidad de que la suma de n dados esté en [a, b], con seis decimales\n * Complejidad: tiempo O(n · 6n · 6), memoria O(6n)\n\"\"\"\n\n\ndef main():\n    n, a, b = map(int, input().split())\n    # p[s] = probabilidad de que la suma de los dados lanzados hasta ahora sea s\n    p = [1.0]\n    for _ in range(n):\n        q = [0.0] * (len(p) + 6)\n        # cada cara 1..6 sale con probabilidad 1/6 y suma su valor\n        for s, ps in enumerate(p):\n            if ps:\n                ps /= 6\n                for c in range(1, 7):\n                    q[s + c] += ps\n        p = q\n    print(f\"{sum(p[a:b + 1]):.6f}\")\n\n\nmain()\n"}, {"id": "Probability-Classic-Problems-Bag-of-Mice", "carpeta": "Probability", "area": "Probabilidad", "sub": "Classic Problems", "archivo": "Probability/Classic Problems/Bag of Mice.cpp", "nombre": "Bag of Mice", "algoritmo": "DP de probabilidades sobre el estado (blancos, negros)", "problema": "Codeforces 148D - Bag of mice (https://codeforces.com/problemset/problem/148/D)", "cses": "https://codeforces.com/problemset/problem/148/D", "py_lento": false, "entrada": "w b (ratones blancos y negros)", "salida": "probabilidad de que gane la princesa (error ≤ 10^-9)", "complejidad": "tiempo O(w · b), memoria O(w · b)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP de probabilidades sobre el estado (blancos, negros)\n * Problema  : Codeforces 148D - Bag of mice (https://codeforces.com/problemset/problem/148/D)\n * Entrada   : w b (ratones blancos y negros)\n * Salida    : probabilidad de que gane la princesa (error ≤ 10^-9)\n * Complejidad: tiempo O(w · b), memoria O(w · b)\n */\n\nint main() {\n    fastio;\n    int W, B;\n    cin >> W >> B;\n    // P[w][b] = probabilidad de que gane la princesa si le toca sacar con w blancos y b negros\n    vector<vector<double>> P(W + 1, vector<double>(B + 1, 0.0));\n    for (int w = 1; w <= W; w++) P[w][0] = 1.0;  // solo hay blancos: gana de inmediato\n    for (int w = 1; w <= W; w++)\n        for (int b = 1; b <= B; b++) {\n            double t = w + b;\n            double res = w / t;  // saca blanco y gana\n            // si saca negro, el dragón debe sacar negro también (si saca blanco, gana él)\n            if (b >= 2) {\n                double both = (b / t) * ((b - 1) / (t - 1));\n                // luego salta un ratón al azar: blanco o negro\n                if (b >= 2 && w >= 1 && t - 2 > 0) res += both * (w / (t - 2)) * P[w - 1][b - 2];\n                if (b >= 3) res += both * ((b - 2) / (t - 2)) * P[w][b - 3];\n            }\n            P[w][b] = res;\n        }\n    precision(9);\n    cout << P[W][B] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de probabilidades sobre el estado (blancos, negros)\n * Problema  : Codeforces 148D - Bag of mice (https://codeforces.com/problemset/problem/148/D)\n * Entrada   : w b (ratones blancos y negros)\n * Salida    : probabilidad de que gane la princesa (error ≤ 10^-9)\n * Complejidad: tiempo O(w · b), memoria O(w · b)\n\"\"\"\n\n\ndef main():\n    W, B = map(int, input().split())\n    # P[w][b] = probabilidad de que gane la princesa si le toca sacar con w blancos y b negros\n    P = [[0.0] * (B + 1) for _ in range(W + 1)]\n    for w in range(1, W + 1):\n        P[w][0] = 1.0  # solo blancos: gana de inmediato\n        row, up = P[w], P[w - 1]\n        for b in range(1, B + 1):\n            t = w + b\n            res = w / t  # saca blanco y gana\n            if b >= 2:\n                # princesa y dragón sacan negro; luego salta un ratón al azar\n                both = b / t * (b - 1) / (t - 1)\n                if t > 2:\n                    res += both * w / (t - 2) * up[b - 2]\n                if b >= 3:\n                    res += both * (b - 2) / (t - 2) * row[b - 3]\n            row[b] = res\n    print(f\"{P[W][B]:.9f}\")\n\n\nmain()\n"}, {"id": "Probability-Classic-Problems-Fish", "carpeta": "Probability", "area": "Probabilidad", "sub": "Classic Problems", "archivo": "Probability/Classic Problems/Fish.cpp", "nombre": "Fish", "algoritmo": "DP de probabilidades sobre subconjuntos (bitmask)", "problema": "Codeforces 16E - Fish (https://codeforces.com/problemset/problem/16/E)", "cses": "https://codeforces.com/problemset/problem/16/E", "py_lento": false, "entrada": "n, luego la matriz a (a[i][j] = probabilidad de que i se coma a j)", "salida": "para cada pez, la probabilidad de ser el último", "complejidad": "tiempo O(2^n · n^2), memoria O(2^n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP de probabilidades sobre subconjuntos (bitmask)\n * Problema  : Codeforces 16E - Fish (https://codeforces.com/problemset/problem/16/E)\n * Entrada   : n, luego la matriz a (a[i][j] = probabilidad de que i se coma a j)\n * Salida    : para cada pez, la probabilidad de ser el último\n * Complejidad: tiempo O(2^n · n^2), memoria O(2^n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<vector<double>> a(n, vector<double>(n));\n    for (auto &row : a) for (auto &x : row) cin >> x;\n    // P[mask] = probabilidad de que en algún momento queden vivos exactamente los peces de mask\n    int full = (1 << n) - 1;\n    vector<double> P(1 << n, 0.0);\n    P[full] = 1.0;\n    // de un conjunto se pasa a uno con un pez menos: se recorre de conjuntos grandes a pequeños\n    for (int mask = full; mask > 0; mask--) {\n        if (P[mask] == 0) continue;\n        int k = __builtin_popcount(mask);\n        if (k < 2) continue;\n        double pares = k * (k - 1) / 2.0;  // cada par se encuentra con la misma probabilidad\n        for (int i = 0; i < n; i++) if (mask >> i & 1)\n            for (int j = 0; j < n; j++) if (j != i && (mask >> j & 1))\n                // se encuentran i y j (1/pares) e i se come a j (a[i][j])\n                P[mask ^ (1 << j)] += P[mask] / pares * a[i][j];\n    }\n    precision(9);\n    for (int i = 0; i < n; i++) cout << P[1 << i] << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP de probabilidades sobre subconjuntos (bitmask)\n * Problema  : Codeforces 16E - Fish (https://codeforces.com/problemset/problem/16/E)\n * Entrada   : n, luego la matriz a (a[i][j] = probabilidad de que i se coma a j)\n * Salida    : para cada pez, la probabilidad de ser el último\n * Complejidad: tiempo O(2^n · n^2), memoria O(2^n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = [list(map(float, data[1 + i * n:1 + (i + 1) * n])) for i in range(n)]\n    full = (1 << n) - 1\n    # P[mask] = probabilidad de que en algún momento queden vivos exactamente los de mask\n    P = [0.0] * (1 << n)\n    P[full] = 1.0\n    for mask in range(full, 0, -1):\n        pm = P[mask]\n        if not pm:\n            continue\n        alive = [i for i in range(n) if mask >> i & 1]\n        k = len(alive)\n        if k < 2:\n            continue\n        share = pm / (k * (k - 1) / 2)  # cada par se encuentra con la misma probabilidad\n        for j in alive:\n            # j muere si se encuentra con algún i vivo y este se lo come\n            s = 0.0\n            for i in alive:\n                s += a[i][j]\n            P[mask ^ (1 << j)] += share * s\n    print(' '.join(f\"{P[1 << i]:.9f}\" for i in range(n)))\n\n\nmain()\n"}, {"id": "Probability-Classic-Problems-Game-on-Tree", "carpeta": "Probability", "area": "Probabilidad", "sub": "Classic Problems", "archivo": "Probability/Classic Problems/Game on Tree.cpp", "nombre": "Game on Tree", "algoritmo": "Linealidad de la esperanza con indicadores (E = Σ 1 / profundidad)", "problema": "Codeforces 280C - Game on Tree (https://codeforces.com/problemset/problem/280/C)", "cses": "https://codeforces.com/problemset/problem/280/C", "py_lento": false, "entrada": "n, luego n − 1 aristas del árbol con raíz 1", "salida": "número esperado de pasos del juego (error ≤ 10^-6)", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Linealidad de la esperanza con indicadores (E = Σ 1 / profundidad)\n * Problema  : Codeforces 280C - Game on Tree (https://codeforces.com/problemset/problem/280/C)\n * Entrada   : n, luego n − 1 aristas del árbol con raíz 1\n * Salida    : número esperado de pasos del juego (error ≤ 10^-6)\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<vector<int>> g(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        g[a].push_back(b), g[b].push_back(a);\n    }\n    // v se elige (cuenta un paso) solo si se escoge antes que todos sus ancestros.\n    // Entre v y sus depth(v) − 1 ancestros, cada orden es igual de probable: P = 1 / depth(v).\n    vector<int> depth(n + 1, 0);\n    depth[1] = 1;\n    vector<int> order = {1};\n    double res = 0;\n    for (int k = 0; k < (int)order.size(); k++) {\n        int u = order[k];\n        res += 1.0 / depth[u];\n        for (int v : g[u]) if (!depth[v]) depth[v] = depth[u] + 1, order.push_back(v);\n    }\n    precision(12);\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Linealidad de la esperanza con indicadores (E = Σ 1 / profundidad)\n * Problema  : Codeforces 280C - Game on Tree (https://codeforces.com/problemset/problem/280/C)\n * Entrada   : n, luego n − 1 aristas del árbol con raíz 1\n * Salida    : número esperado de pasos del juego (error ≤ 10^-6)\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    g = [[] for _ in range(n + 1)]\n    for i in range(n - 1):\n        a, b = int(data[1 + 2 * i]), int(data[2 + 2 * i])\n        g[a].append(b)\n        g[b].append(a)\n    # v cuenta un paso solo si se escoge antes que todos sus ancestros: P = 1 / depth(v)\n    depth = [0] * (n + 1)\n    depth[1] = 1\n    order = [1]\n    for u in order:\n        for v in g[u]:\n            if not depth[v]:\n                depth[v] = depth[u] + 1\n                order.append(v)\n    print(f\"{sum(1 / depth[v] for v in range(1, n + 1)):.12f}\")\n\n\nmain()\n"}, {"id": "Probability-Classic-Problems-Ilya-and-Escalator", "carpeta": "Probability", "area": "Probabilidad", "sub": "Classic Problems", "archivo": "Probability/Classic Problems/Ilya and Escalator.cpp", "nombre": "Ilya and Escalator", "algoritmo": "DP sobre la distribución en el tiempo (proceso que avanza con probabilidad p)", "problema": "Codeforces 518D - Ilya and Escalator (https://codeforces.com/problemset/problem/518/D)", "cses": "https://codeforces.com/problemset/problem/518/D", "py_lento": false, "entrada": "n p t", "salida": "número esperado de personas en la escalera tras t segundos (error ≤ 10^-6)", "complejidad": "tiempo O(n · t), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : DP sobre la distribución en el tiempo (proceso que avanza con probabilidad p)\n * Problema  : Codeforces 518D - Ilya and Escalator (https://codeforces.com/problemset/problem/518/D)\n * Entrada   : n p t\n * Salida    : número esperado de personas en la escalera tras t segundos (error ≤ 10^-6)\n * Complejidad: tiempo O(n · t), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n, t;\n    double p;\n    cin >> n >> p >> t;\n    // d[i] = probabilidad de que haya i personas en la escalera en el segundo actual\n    vector<double> d(n + 1, 0.0);\n    d[0] = 1.0;\n    for (int s = 0; s < t; s++) {\n        vector<double> e(n + 1, 0.0);\n        for (int i = 0; i < n; i++) {\n            e[i + 1] += d[i] * p;      // el primero de la fila entra\n            e[i] += d[i] * (1 - p);    // se queda quieto\n        }\n        e[n] += d[n];                  // ya entraron todos\n        d = e;\n    }\n    double res = 0;\n    for (int i = 0; i <= n; i++) res += i * d[i];\n    precision(9);\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : DP sobre la distribución en el tiempo (proceso que avanza con probabilidad p)\n * Problema  : Codeforces 518D - Ilya and Escalator (https://codeforces.com/problemset/problem/518/D)\n * Entrada   : n p t\n * Salida    : número esperado de personas en la escalera tras t segundos (error ≤ 10^-6)\n * Complejidad: tiempo O(n · t), memoria O(n)\n\"\"\"\n\n\ndef main():\n    parts = input().split()\n    n, p, t = int(parts[0]), float(parts[1]), int(parts[2])\n    q = 1 - p\n    # d[i] = probabilidad de que haya i personas en la escalera\n    d = [1.0] + [0.0] * n\n    for _ in range(t):\n        # i personas: o ya había i y nadie entró, o había i−1 y entró uno; con n ya no cambia\n        e = [d[0] * q] + [a * q + b * p for a, b in zip(d[1:n], d[:n - 1])] + [d[n] + d[n - 1] * p] if n > 1 else [d[0] * q, d[1] + d[0] * p]\n        d = e\n    print(f\"{sum(i * x for i, x in enumerate(d)):.9f}\")\n\n\nmain()\n"}, {"id": "Probability-Classic-Problems-Journey", "carpeta": "Probability", "area": "Probabilidad", "sub": "Classic Problems", "archivo": "Probability/Classic Problems/Journey.cpp", "nombre": "Journey", "algoritmo": "Esperanza en un árbol (probabilidad de llegar a cada hoja)", "problema": "Codeforces 839C - Journey (https://codeforces.com/problemset/problem/839/C)", "cses": "https://codeforces.com/problemset/problem/839/C", "py_lento": false, "entrada": "n, luego n − 1 caminos \"u v\"", "salida": "largo esperado del viaje desde la ciudad 1 (error ≤ 10^-6)", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Esperanza en un árbol (probabilidad de llegar a cada hoja)\n * Problema  : Codeforces 839C - Journey (https://codeforces.com/problemset/problem/839/C)\n * Entrada   : n, luego n − 1 caminos \"u v\"\n * Salida    : largo esperado del viaje desde la ciudad 1 (error ≤ 10^-6)\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<vector<int>> g(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int u, v;\n        cin >> u >> v;\n        g[u].push_back(v), g[v].push_back(u);\n    }\n    // prob[v] = probabilidad de pasar por v; el caballo elige uniforme entre los hijos no visitados\n    vector<double> prob(n + 1, 0.0);\n    vector<int> depth(n + 1, 0), par(n + 1, 0);\n    prob[1] = 1.0;\n    double res = 0;\n    vector<int> order = {1};\n    for (int k = 0; k < (int)order.size(); k++) {\n        int u = order[k];\n        int hijos = g[u].size() - (u != 1);\n        if (hijos == 0) res += prob[u] * depth[u];  // el viaje termina en una hoja\n        for (int v : g[u]) if (v != par[u]) {\n            par[v] = u, depth[v] = depth[u] + 1, prob[v] = prob[u] / hijos;\n            order.push_back(v);\n        }\n    }\n    precision(12);\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Esperanza en un árbol (probabilidad de llegar a cada hoja)\n * Problema  : Codeforces 839C - Journey (https://codeforces.com/problemset/problem/839/C)\n * Entrada   : n, luego n − 1 caminos \"u v\"\n * Salida    : largo esperado del viaje desde la ciudad 1 (error ≤ 10^-6)\n * Complejidad: tiempo O(n), memoria O(n)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.buffer.read().split()\n    n = int(data[0])\n    g = [[] for _ in range(n + 1)]\n    for i in range(n - 1):\n        u, v = int(data[1 + 2 * i]), int(data[2 + 2 * i])\n        g[u].append(v)\n        g[v].append(u)\n    # prob[v] = probabilidad de pasar por v; el caballo elige uniforme entre los no visitados\n    prob = [0.0] * (n + 1)\n    depth = [0] * (n + 1)\n    par = [0] * (n + 1)\n    prob[1] = 1.0\n    res = 0.0\n    order = [1]\n    for u in order:\n        hijos = len(g[u]) - (u != 1)\n        if hijos == 0:\n            res += prob[u] * depth[u]  # el viaje termina en una hoja\n            continue\n        share = prob[u] / hijos\n        for v in g[u]:\n            if v != par[u]:\n                par[v] = u\n                depth[v] = depth[u] + 1\n                prob[v] = share\n                order.append(v)\n    print(f\"{res:.12f}\")\n\n\nmain()\n"}, {"id": "Probability-Classic-Problems-Lets-Play-Osu", "carpeta": "Probability", "area": "Probabilidad", "sub": "Classic Problems", "archivo": "Probability/Classic Problems/Lets Play Osu.cpp", "nombre": "Lets Play Osu", "algoritmo": "Esperanza de un cuadrado con linealidad ((L+1)^2 − L^2 = 2L + 1)", "problema": "Codeforces 235B - Let's Play Osu! (https://codeforces.com/problemset/problem/235/B)", "cses": "https://codeforces.com/problemset/problem/235/B", "py_lento": false, "entrada": "n, luego p_1 … p_n (probabilidad de acertar cada clic)", "salida": "puntaje esperado (suma de cuadrados de los bloques de aciertos), error ≤ 10^-6", "complejidad": "tiempo O(n), memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Esperanza de un cuadrado con linealidad ((L+1)^2 − L^2 = 2L + 1)\n * Problema  : Codeforces 235B - Let's Play Osu! (https://codeforces.com/problemset/problem/235/B)\n * Entrada   : n, luego p_1 … p_n (probabilidad de acertar cada clic)\n * Salida    : puntaje esperado (suma de cuadrados de los bloques de aciertos), error ≤ 10^-6\n * Complejidad: tiempo O(n), memoria O(1)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    // len = E[largo del bloque de aciertos que termina en el clic actual]\n    // si el clic i acierta, el bloque crece de L a L+1 y el puntaje sube (L+1)^2 − L^2 = 2L + 1\n    double len = 0, res = 0;\n    for (int i = 0; i < n; i++) {\n        double p;\n        cin >> p;\n        res += p * (2 * len + 1);   // linealidad: E[2L + 1] = 2·E[L] + 1\n        len = p * (len + 1);        // si falla, el bloque vuelve a 0\n    }\n    precision(12);\n    cout << res << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Esperanza de un cuadrado con linealidad ((L+1)^2 − L^2 = 2L + 1)\n * Problema  : Codeforces 235B - Let's Play Osu! (https://codeforces.com/problemset/problem/235/B)\n * Entrada   : n, luego p_1 … p_n (probabilidad de acertar cada clic)\n * Salida    : puntaje esperado (suma de cuadrados de los bloques de aciertos), error ≤ 10^-6\n * Complejidad: tiempo O(n), memoria O(1)\n\"\"\"\n\n\ndef main():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    # length = E[largo del bloque de aciertos que termina en el clic actual]\n    length = res = 0.0\n    for p in map(float, data[1:1 + n]):\n        res += p * (2 * length + 1)  # el puntaje sube (L+1)^2 − L^2 = 2L + 1 si acierta\n        length = p * (length + 1)    # si falla, el bloque vuelve a 0\n    print(f\"{res:.12f}\")\n\n\nmain()\n"}, {"id": "Probability-Classic-Problems-Probability-Given", "carpeta": "Probability", "area": "Probabilidad", "sub": "Classic Problems", "archivo": "Probability/Classic Problems/Probability Given.cpp", "nombre": "Probability Given", "algoritmo": "Probabilidad condicional / teorema de Bayes con DP de conteo de éxitos", "problema": "UVa 11181 - Probability|Given", "cses": "", "py_lento": false, "entrada": "varios casos \"N r\" y N probabilidades p_i; termina con \"0 0\"", "salida": "\"Case k:\" y, para cada amigo, P(compró | exactamente r compraron), con seis decimales", "complejidad": "tiempo O(N^3) por caso, memoria O(N)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Probabilidad condicional / teorema de Bayes con DP de conteo de éxitos\n * Problema  : UVa 11181 - Probability|Given\n * Entrada   : varios casos \"N r\" y N probabilidades p_i; termina con \"0 0\"\n * Salida    : \"Case k:\" y, para cada amigo, P(compró | exactamente r compraron), con seis decimales\n * Complejidad: tiempo O(N^3) por caso, memoria O(N)\n */\n\n// d[j] = P(exactamente j compran) entre los amigos indicados por usar\nvector<double> conteo(const vector<double> &p, int saltar) {\n    int n = p.size();\n    vector<double> d(n + 1, 0.0);\n    d[0] = 1.0;\n    for (int i = 0; i < n; i++) {\n        if (i == saltar) continue;\n        for (int j = n; j >= 0; j--) d[j] = d[j] * (1 - p[i]) + (j ? d[j - 1] * p[i] : 0.0);\n    }\n    return d;\n}\n\nint main() {\n    fastio;\n    int n, r, caso = 0;\n    while (cin >> n >> r && (n || r)) {\n        vector<double> p(n);\n        for (auto &x : p) cin >> x;\n        // Bayes: P(i compró | r compraron) = P(i compró y r compraron) / P(r compraron)\n        double total = conteo(p, -1)[r];\n        cout << \"Case \" << ++caso << \":\\n\";\n        precision(6);\n        for (int i = 0; i < n; i++) {\n            // i compró y entre los demás compraron exactamente r − 1 (eventos independientes)\n            double conjunta = r ? p[i] * conteo(p, i)[r - 1] : 0.0;\n            cout << conjunta / total << \"\\n\";\n        }\n    }\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Probabilidad condicional / teorema de Bayes con DP de conteo de éxitos\n * Problema  : UVa 11181 - Probability|Given\n * Entrada   : varios casos \"N r\" y N probabilidades p_i; termina con \"0 0\"\n * Salida    : \"Case k:\" y, para cada amigo, P(compró | exactamente r compraron), con seis decimales\n * Complejidad: tiempo O(N^3) por caso, memoria O(N)\n\"\"\"\n\n\ndef conteo(p, saltar):\n    \"\"\"d[j] = P(exactamente j compran) entre todos menos el amigo saltar.\"\"\"\n    d = [1.0]\n    for i, pi in enumerate(p):\n        if i != saltar:\n            d = [a * (1 - pi) + b * pi for a, b in zip(d + [0.0], [0.0] + d)]\n    return d\n\n\ndef main():\n    data = sys.stdin.read().split()\n    pos, caso, out = 0, 0, []\n    while pos + 1 < len(data):\n        n, r = int(data[pos]), int(data[pos + 1])\n        pos += 2\n        if n == 0 and r == 0:\n            break\n        p = list(map(float, data[pos:pos + n]))\n        pos += n\n        caso += 1\n        out.append(f\"Case {caso}:\")\n        # Bayes: P(i compró | r compraron) = P(i compró y r compraron) / P(r compraron)\n        total = conteo(p, -1)[r]\n        for i in range(n):\n            otros = conteo(p, i)\n            conjunta = p[i] * otros[r - 1] if r else 0.0\n            out.append(f\"{conjunta / total:.6f}\")\n    print('\\n'.join(out))\n\n\nmain()\n"}, {"id": "Probability-Classic-Problems-Serval-and-Bonus-Problem", "carpeta": "Probability", "area": "Probabilidad", "sub": "Classic Problems", "archivo": "Probability/Classic Problems/Serval and Bonus Problem.cpp", "nombre": "Serval and Bonus Problem", "algoritmo": "Probabilidad continua: reducir a órdenes relativos de puntos uniformes + DP modular", "problema": "Codeforces 1153F - Serval and Bonus Problem (https://codeforces.com/problemset/problem/1153/F)", "cses": "https://codeforces.com/problemset/problem/1153/F", "py_lento": true, "entrada": "n k l", "salida": "longitud esperada cubierta por al menos k de n segmentos al azar en [0, l], mód 998244353", "complejidad": "tiempo O(n^2), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Probabilidad continua: reducir a órdenes relativos de puntos uniformes + DP modular\n * Problema  : Codeforces 1153F - Serval and Bonus Problem (https://codeforces.com/problemset/problem/1153/F)\n * Entrada   : n k l\n * Salida    : longitud esperada cubierta por al menos k de n segmentos al azar en [0, l], mód 998244353\n * Complejidad: tiempo O(n^2), memoria O(n)\n */\n\nll power(ll b, ll e) { ll r = 1; b %= MOD; for (; e; e >>= 1, b = b * b % MOD) if (e & 1) r = r * b % MOD; return r; }\n\nint main() {\n    fastio;\n    int n, k;\n    ll l;\n    cin >> n >> k >> l;\n    // Truco: la longitud esperada cubierta = l · P(un punto x uniforme quede cubierto por ≥ k).\n    // Con 2n extremos y x, todos uniformes e independientes, cualquier orden de los 2n + 1 puntos es\n    // igual de probable: basta contar órdenes. Se recorren los puntos de izquierda a derecha:\n    // f[j][t] = formas con j segmentos abiertos, t = ya se colocó x (0/1).\n    vector<array<ll, 2>> f(n + 2, {0, 0}), g(n + 2);\n    f[0][0] = 1;\n    for (int i = 0; i < 2 * n + 1; i++) {\n        for (auto &x : g) x = {0, 0};\n        for (int j = 0; j <= n; j++)\n            for (int t = 0; t < 2; t++) {\n                ll v = f[j][t];\n                if (!v) continue;\n                if (j < n) g[j + 1][t] = (g[j + 1][t] + v) % MOD;               // abre un segmento\n                if (j > 0) g[j - 1][t] = (g[j - 1][t] + v * j) % MOD;           // cierra uno de los j abiertos\n                if (t == 0 && j >= k) g[j][1] = (g[j][1] + v) % MOD;            // aquí va x: está cubierto\n            }\n        swap(f, g);\n    }\n    // f[0][1] cuenta órdenes con segmentos sin etiqueta y extremos en orden; por cada uno hay\n    // n! · 2^n órdenes de los 2n + 1 puntos etiquetados, de un total de (2n + 1)!\n    ll num = f[0][1];\n    for (int i = 1; i <= n; i++) num = num * i % MOD * 2 % MOD;\n    ll den = 1;\n    for (int i = 1; i <= 2 * n + 1; i++) den = den * i % MOD;\n    cout << num * power(den, MOD - 2) % MOD * (l % MOD) % MOD << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Probabilidad continua: reducir a órdenes relativos de puntos uniformes + DP modular\n * Problema  : Codeforces 1153F - Serval and Bonus Problem (https://codeforces.com/problemset/problem/1153/F)\n * Entrada   : n k l\n * Salida    : longitud esperada cubierta por al menos k de n segmentos al azar en [0, l], mód 998244353\n * Complejidad: tiempo O(n^2), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n, k, l = map(int, input().split())\n    # E[longitud] = l · P(un punto x uniforme quede cubierto por ≥ k segmentos).\n    # Todos los órdenes de los 2n + 1 puntos (extremos y x) son igual de probables: se cuentan órdenes.\n    # f0[j] / f1[j] = formas con j segmentos abiertos, sin / con x ya colocado\n    f0 = [1] + [0] * n\n    f1 = [0] * (n + 1)\n    mult = list(range(n + 1))\n    for _ in range(2 * n + 1):\n        # abrir: j -> j + 1; cerrar uno de los j abiertos: j -> j − 1 (j formas)\n        g0 = [((f0[j - 1] if j else 0) + (f0[j + 1] * mult[j + 1] if j < n else 0)) % MOD for j in range(n + 1)]\n        g1 = [((f1[j - 1] if j else 0) + (f1[j + 1] * mult[j + 1] if j < n else 0) + (f0[j] if j >= k else 0)) % MOD for j in range(n + 1)]\n        f0, f1 = g0, g1\n    # cada orden contado corresponde a n! · 2^n órdenes de puntos etiquetados, de (2n + 1)! posibles\n    num = f1[0]\n    for i in range(1, n + 1):\n        num = num * i * 2 % MOD\n    den = 1\n    for i in range(1, 2 * n + 2):\n        den = den * i % MOD\n    print(num * pow(den, MOD - 2, MOD) % MOD * (l % MOD) % MOD)\n\n\nmain()\n"}, {"id": "Probability-Distributions-Binomial", "carpeta": "Probability", "area": "Probabilidad", "sub": "Distributions", "archivo": "Probability/Distributions/Binomial.cpp", "nombre": "Binomial", "algoritmo": "Distribución binomial (n ensayos de Bernoulli independientes con probabilidad p)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "n k p (n ≤ 1000, 0 ≤ k ≤ n, 0 ≤ p ≤ 1)", "salida": "P(X = k), P(X ≥ k), E[X] = np y Var(X) = np(1 − p), uno por línea con nueve decimales", "complejidad": "tiempo O(n^2), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Distribución binomial (n ensayos de Bernoulli independientes con probabilidad p)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n k p (n ≤ 1000, 0 ≤ k ≤ n, 0 ≤ p ≤ 1)\n * Salida    : P(X = k), P(X ≥ k), E[X] = np y Var(X) = np(1 − p), uno por línea con nueve decimales\n * Complejidad: tiempo O(n^2), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n, k;\n    double p;\n    cin >> n >> k >> p;\n    // d[i] = P(i éxitos en los ensayos hechos hasta ahora). Cada ensayo: éxito con p, fracaso con 1 − p.\n    // Así se arma la binomial sin calcular C(n, k) ni potencias (y sin desbordar con n grande).\n    vector<double> d(n + 1, 0.0);\n    d[0] = 1.0;\n    for (int t = 1; t <= n; t++)\n        for (int i = t; i >= 0; i--)\n            d[i] = d[i] * (1 - p) + (i ? d[i - 1] * p : 0.0);\n    // forma cerrada equivalente: P(X = k) = C(n, k) · p^k · (1 − p)^(n − k)\n    double cola = 0;\n    for (int i = k; i <= n; i++) cola += d[i];\n    precision(9);\n    cout << d[k] << \"\\n\" << cola << \"\\n\" << n * p << \"\\n\" << n * p * (1 - p) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Distribución binomial (n ensayos de Bernoulli independientes con probabilidad p)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n k p (n ≤ 1000, 0 ≤ k ≤ n, 0 ≤ p ≤ 1)\n * Salida    : P(X = k), P(X ≥ k), E[X] = np y Var(X) = np(1 − p), uno por línea con nueve decimales\n * Complejidad: tiempo O(n^2), memoria O(n)\n\"\"\"\n\n\ndef main():\n    parts = input().split()\n    n, k, p = int(parts[0]), int(parts[1]), float(parts[2])\n    q = 1 - p\n    # d[i] = P(i éxitos en los ensayos hechos hasta ahora); cada ensayo es éxito con p\n    d = [1.0]\n    for _ in range(n):\n        d = [a * q + b * p for a, b in zip(d + [0.0], [0.0] + d)]\n    # forma cerrada equivalente: P(X = k) = C(n, k) · p^k · (1 − p)^(n − k)\n    print(f\"{d[k]:.9f}\")\n    print(f\"{sum(d[k:]):.9f}\")\n    print(f\"{n * p:.9f}\")\n    print(f\"{n * p * q:.9f}\")\n\n\nmain()\n"}, {"id": "Probability-Distributions-ContinuousUniform", "carpeta": "Probability", "area": "Probabilidad", "sub": "Distributions", "archivo": "Probability/Distributions/ContinuousUniform.cpp", "nombre": "ContinuousUniform", "algoritmo": "Probabilidad continua uniforme (probabilidad geométrica: área favorable / área total)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "a b s (x uniforme en [0, a], y uniforme en [0, b], independientes; reales positivos)", "salida": "P(x + y ≤ s) con nueve decimales", "complejidad": "tiempo O(1), memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Probabilidad continua uniforme (probabilidad geométrica: área favorable / área total)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : a b s (x uniforme en [0, a], y uniforme en [0, b], independientes; reales positivos)\n * Salida    : P(x + y ≤ s) con nueve decimales\n * Complejidad: tiempo O(1), memoria O(1)\n */\n\n// área del triángulo x + y ≤ s, x, y ≥ 0 que queda a la derecha de x = c (si c ≥ s es 0)\ndouble tri(double c) { return c >= 0 ? c * c / 2 : 0; }\n\nint main() {\n    fastio;\n    double a, b, s;\n    cin >> a >> b >> s;\n    // (x, y) es un punto uniforme en el rectángulo [0, a] × [0, b] (densidad 1/(a·b)):\n    // la probabilidad de un evento es el área de su región dividida entre a·b.\n    // Área de {x + y ≤ s} dentro del rectángulo por inclusión-exclusión de triángulos:\n    double area = tri(s) - tri(s - a) - tri(s - b) + tri(s - a - b);\n    area = max(0.0, min(area, a * b));\n    precision(9);\n    cout << area / (a * b) << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Probabilidad continua uniforme (probabilidad geométrica: área favorable / área total)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : a b s (x uniforme en [0, a], y uniforme en [0, b], independientes; reales positivos)\n * Salida    : P(x + y ≤ s) con nueve decimales\n * Complejidad: tiempo O(1), memoria O(1)\n\"\"\"\n\n\ndef tri(c):\n    \"\"\"Área del triángulo {x + y ≤ c, x, y ≥ 0} (0 si c < 0).\"\"\"\n    return c * c / 2 if c > 0 else 0.0\n\n\ndef main():\n    a, b, s = map(float, input().split())\n    # (x, y) es uniforme en el rectángulo [0, a] × [0, b]: P(evento) = área(evento) / (a · b).\n    # Área de {x + y ≤ s} en el rectángulo por inclusión-exclusión de triángulos:\n    area = tri(s) - tri(s - a) - tri(s - b) + tri(s - a - b)\n    area = max(0.0, min(area, a * b))\n    print(f\"{area / (a * b):.9f}\")\n\n\nmain()\n"}, {"id": "Probability-Distributions-CouponCollector", "carpeta": "Probability", "area": "Probabilidad", "sub": "Distributions", "archivo": "Probability/Distributions/CouponCollector.cpp", "nombre": "CouponCollector", "algoritmo": "Distribución geométrica y coleccionista de cupones (E = n · H_n)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "py_lento": false, "entrada": "n t (n tipos de cupón igual de probables, t compras; n, t ≤ 1000)", "salida": "el número esperado de compras para tener los n tipos, y la probabilidad de tenerlos todos en ≤ t compras", "complejidad": "tiempo O(n · t), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n/*\n * Algoritmo : Distribución geométrica y coleccionista de cupones (E = n · H_n)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n t (n tipos de cupón igual de probables, t compras; n, t ≤ 1000)\n * Salida    : el número esperado de compras para tener los n tipos, y la probabilidad de tenerlos todos en ≤ t compras\n * Complejidad: tiempo O(n · t), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n, t;\n    cin >> n >> t;\n    // con c tipos ya vistos, cada compra trae uno nuevo con probabilidad (n − c)/n:\n    // esperar el siguiente nuevo es una geométrica de esperanza n/(n − c)\n    double E = 0;\n    for (int c = 0; c < n; c++) E += (double)n / (n - c);   // = n · (1 + 1/2 + … + 1/n)\n    // d[c] = P(haber visto exactamente c tipos tras las compras hechas): cadena de Markov en c\n    vector<double> d(n + 1, 0.0);\n    d[0] = 1.0;\n    for (int s = 0; s < t; s++)\n        for (int c = n; c >= 0; c--)\n            d[c] = d[c] * c / n + (c ? d[c - 1] * (n - c + 1) / n : 0.0);\n    precision(9);\n    cout << E << \"\\n\" << d[n] << \"\\n\";\n    return 0;\n}\n", "python": "import sys\n\ninput = sys.stdin.readline\nINF = float('inf')\nMOD = 998244353\n\n\"\"\"\n * Algoritmo : Distribución geométrica y coleccionista de cupones (E = n · H_n)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n t (n tipos de cupón igual de probables, t compras; n, t ≤ 1000)\n * Salida    : el número esperado de compras para tener los n tipos, y la probabilidad de tenerlos todos en ≤ t compras\n * Complejidad: tiempo O(n · t), memoria O(n)\n\"\"\"\n\n\ndef main():\n    n, t = map(int, input().split())\n    # con c tipos vistos, el siguiente nuevo llega tras una geométrica de esperanza n/(n − c)\n    E = sum(n / (n - c) for c in range(n))  # = n · H_n\n    # d[c] = P(haber visto exactamente c tipos): con c/n se repite uno viejo, con (n − c)/n sale uno nuevo\n    stay = [c / n for c in range(n + 1)]\n    new = [(n - c + 1) / n for c in range(n + 1)]\n    d = [1.0] + [0.0] * n\n    for _ in range(t):\n        d = [d[0] * stay[0]] + [d[c] * stay[c] + d[c - 1] * new[c] for c in range(1, n + 1)]\n    print(f\"{E:.9f}\")\n    print(f\"{d[n]:.9f}\")\n\n\nmain()\n"}];
